void add_edge(int from, int to, int cap, int cost) {
    graph[from].push_back({to, cap, cost, (int)graph[to].size()});
    graph[to].push_back({from, 0, -cost, (int)graph[from].size()-1});
}

bool bellman_ford(int s, int t) {
    fill(dist.begin(), dist.end(), INT_MAX);
    dist[s] = 0;
    bool updated;
    for (int iter = 0; iter < MAX_V; ++iter) {
        updated = false;
        for (int v = 0; v < MAX_V; ++v) {
            if (dist[v] == INT_MAX) continue;
            for (int i = 0; i < graph[v].size(); ++i) {
                Edge &e = graph[v][i];
                if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                    dist[e.to] = dist[v] + e.cost;
                    prevv[e.to] = v;
                    preve[e.to] = i;
                    updated = true;
                }
            }
        }
        if (!updated) break;
    }
    return dist[t] != INT_MAX;
}

int min_cost_flow(int s, int t) {
    int flow = 0, cost = 0;
    while (bellman_ford(s, t)) {
        int f = INT_MAX;
        for (int v = t; v != s; v = prevv[v]) {
            f = min(f, graph[prevv[v]][preve[v]].cap);
        }
        flow += f;
        cost += dist[t] * f;
        for (int v = t; v != s; v = prevv[v]) {
            Edge &e = graph[prevv[v]][preve[v]];
            e.cap -= f;
            graph[v][e.rev].cap += f;
        }
    }
    return cost;
}

