using namespace std;

using ll = long long;

struct Edge {
    int v;
    int capacity;
    int flow;
    int cost;
    Edge(int v, int cap, int fl, int cst) : v(v), capacity(cap), flow(fl), cost(cst) {}
};

vector<Edge> edgeList;
vector<vector<int>> graph;
const int MAXN = 14043;
ll distance[MAXN];
int prevNode[MAXN];
int prevEdge[MAXN];
bool inQueue[MAXN];

const ll INFL = (ll)1e18;

int S, T;

int getRemaining(int idx) {
    return edgeList[idx].capacity - edgeList[idx].flow;
}

void bellmanFord() {
    fill(distance, distance + MAXN, INFL);
    fill(prevNode, prevNode + MAXN, -1);
    fill(prevEdge, prevEdge + MAXN, -1);
    fill(inQueue, inQueue + MAXN, false);
    distance[S] = 0;
    queue<int> q;
    q.push(S);
    inQueue[S] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inQueue[u] = false;
        for (int idx : graph[u]) {
            if (getRemaining(idx) == 0) continue;
            int v = edgeList[idx].v;
            int w = edgeList[idx].cost;
            if (distance[v] > distance[u] + w) {
                distance[v] = distance[u] + w;
                prevNode[v] = u;
                prevEdge[v] = idx;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void augment() {
    bellmanFord();
    int cur = T;
    while (cur != S) {
        edgeList[prevEdge[cur]].flow++;
        edgeList[prevEdge[cur] ^ 1].flow--;
        cur = prevNode[cur];
    }
}

void addEdge(int u, int v, int cap, int cost) {
    graph[u].push_back(edgeList.size());
    edgeList.emplace_back(v, cap, 0, cost);
    graph[v].push_back(edgeList.size());
    edgeList.emplace_back(u, 0, 0, -cost);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    S = MAXN - 2;
    T = MAXN - 1;

    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        --x;
        addEdge(S, x, 1, 0);
    }

    int TMAX = 101;
    for (int t = 0; t < TMAX; t++) {
        addEdge(t * n, T, k, t * c);
    }

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        for (int t = 0; t < TMAX - 1; t++) {
            for (int j = 0; j < k; j++) {
                addEdge(u + t * n, v + (t + 1) * n, 1, d * (2 * j + 1));
            }
        }
        for (int t = 0; t < TMAX - 1; t++) {
            for (int j = 0; j < k; j++) {
                addEdge(v + t * n, u + (t + 1) * n, 1, d * (2 * j + 1));
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int t = 0; t < TMAX - 1; t++) {
            addEdge(i + t * n, i + (t + 1) * n, k, 0);
        }
    }

    ll ans = 0;
    for (int i = 0; i < k; i++) {
        augment();
        ans += distance[T];
    }

    cout << ans << '\n';
    return 0;
}

#include <iostream>
