                        q.push(e.dest);
                    }
                }
            }
        }

        if (dist[sink_node] == INF) return -1;

        int batch_flow = required_flow;
        for (int cur = sink_node; cur != source_node; cur = parent_node[cur]) {
            batch_flow = min(batch_flow, graph[parent_node[cur]][parent_link[cur]].avail);
        }
        required_flow -= batch_flow;
        total_spent += (llong)batch_flow * dist[sink_node];

        for (int cur = sink_node; cur != source_node; cur = parent_node[cur]) {
            Link& e = graph[parent_node[cur]][parent_link[cur]];
            e.avail -= batch_flow;
            graph[cur][e.inv].avail += batch_flow;
        }
    }
    return total_spent;
}

