    for (int t = 0; t <= T; ++t) {
        link(idx(1, t), dst, c * t, k);
    }

    for (int v = 1; v <= n; ++v) {
        for (int t = 0; t < T; ++t) {
            link(idx(v, t), idx(v, t + 1), 0, k);
        }
    }

    while (m--) {
        cin >> u >> v;
        for (int i = 1; i <= k; ++i) {
            for (int t = 0; t < T; ++t) {
                int w = d * (2 * i - 1);
                link(idx(u, t), idx(v, t + 1), w, 1);
                link(idx(v, t), idx(u, t + 1), w, 1);
            }
        }
    }

