    void connect(int from, int to, int cap, int cst) {
        edges[from].push_back({to, cap, cst, (int)edges[to].size()});
        edges[to].push_back({from, 0, -cst, (int)edges[from].size() - 1});
    }

    int compute(int source, int sink, int requiredFlow) {
        int result = 0;
        memset(potential, 0, sizeof(potential));
        while (requiredFlow > 0) {
            priority_queue<pii, vector<pii>, greater<pii>> pq;
            fill(distance, distance + nodeCount, INF);
            distance[source] = 0;
            pq.emplace(0, source);
