};

class MinCostMaxFlow {
public:
    static const int MAX_VERTEX = 5010;
    int vertexCount;
    vector<Arc> adjacency[MAX_VERTEX];
    int height[MAX_VERTEX];
    int shortestPath[MAX_VERTEX];
    int predecessorVertex[MAX_VERTEX], predecessorArc[MAX_VERTEX];

    void establish(int n) { vertexCount = n; }

    void insert(int src, int dst, int cap, int cst) {
        adjacency[src].push_back({dst, cap, cst, (int)adjacency[dst].size()});
        adjacency[dst].push_back({src, 0, -cst, (int)adjacency[src].size() - 1});
    }

    int optimize(int source, int sink, int demand) {
        int totalCost = 0;
        memset(height, 0, sizeof(height));
        while (demand > 0) {
            priority_queue<ip, vector<ip>, greater<ip>> pq;
            fill(shortestPath, shortestPath + vertexCount, INFINITY);
            shortestPath[source] = 0;
            pq.emplace(0, source);
            while (!pq.empty()) {
                auto [dist, u] = pq.top(); pq.pop();
                if (shortestPath[u] < dist) continue;
                for (int i = 0; i < adjacency[u].size(); ++i) {
                    auto& arc = adjacency[u][i];
                    if (arc.capacity > 0 && shortestPath[arc.destination] > shortestPath[u] + arc.weight + height[u] - height[arc.destination]) {
                        shortestPath[arc.destination] = shortestPath[u] + arc.weight + height[u] - height[arc.destination];
                        predecessorVertex[arc.destination] = u;
                        predecessorArc[arc.destination] = i;
                        pq.emplace(shortestPath[arc.destination], arc.destination);
                    }
                }
            }
            if (shortestPath[sink] == INFINITY) return -1;
            for (int i = 0; i < vertexCount; ++i) height[i] += shortestPath[i];
            int flow = demand;
            for (int v = sink; v != source; v = predecessorVertex[v])
                flow = min(flow, adjacency[predecessorVertex[v]][predecessorArc[v]].capacity);
            demand -= flow;
            totalCost += flow * height[sink];
            for (int v = sink; v != source; v = predecessorVertex[v]) {
                auto& arc = adjacency[predecessorVertex[v]][predecessorArc[v]];
                arc.capacity -= flow;
                adjacency[v][arc.complement].capacity += flow;
            }
        }
        return totalCost;
    }
};

