    int cap;
    int w;
};

vector<Edge> g[10001];
int vis[10001], cur[10001], n;
int dis[10001], pot[10001];

int addv(int c) {
    while (c--) g[n++].clear();
    return n - 1;
}

void adde(int u, int v, int c, int w) {
    g[u].push_back({v, (int)g[v].size(), c, w});
    g[v].push_back({u, (int)g[u].size() - 1, 0, -w});
}

bool dijkstra(int s, int t) {
    fill(dis, dis + n, INF);
    fill(vis, vis + n, 0);
    using pii = pair<int, int>;
    priority_queue<pii, vector<pii>, greater<pii>> q;
    q.push({dis[s] = 0, s});
    while (!q.empty()) {
        int du, u;
        tie(du, u) = q.top(); q.pop();
        if (vis[u]) continue;
        vis[u] = 1;
        for (auto& e : g[u]) {
            int v = e.to;
            int dv = du + pot[u] + e.w - pot[v];
            if (!e.cap || vis[v] || dis[v] <= dv) continue;
            q.push({dis[v] = dv, v});
        }
    }
    return vis[t];
}

bool dinic_bfs(int s, int t) {
    fill(vis, vis + n, 0);
    queue<int> q;
    q.push(s);
    vis[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : g[u]) {
            int v = e.to;
            if (vis[v] || !e.cap) continue;
            if (dis[v] != dis[u] + e.w - pot[v] + pot[u]) continue;
            vis[v] = vis[u] + 1;
            q.push(v);
        }
    }
    return vis[t];
}

int dinic_dfs(int u, int t, int f) {
    if (u == t) return f;
    int sf = 0;
    for (int& i = cur[u]; i < (int)g[u].size(); ++i) {
        auto& e = g[u][i];
        int v = e.to;
        if (!e.cap || vis[v] != vis[u] + 1) continue;
        if (dis[v] != dis[u] + e.w - pot[v] + pot[u]) continue;
        int df = dinic_dfs(v, t, min(e.cap, f));
        sf += df;
        f -= df;
        e.cap -= df;
        g[v][e.rev].cap += df;
        if (!f) break;
    }
    return sf;
}

pair<int, int> mcmf(int s, int t, int mf) {
    int sf = 0, sc = 0;
    fill(pot, pot + n, 0);
    while (dijkstra(s, t)) {
        int f = 0;
        while (dinic_bfs(s, t)) {
            fill(cur, cur + n, 0);
            int df = dinic_dfs(s, t, mf);
            mf -= df;
            f += df;
            if (!mf) break;
        }
        sf += f;
        sc += (dis[t] + pot[t]) * f;
        for (int i = 0; i < n; ++i) pot[i] += dis[i];
        if (!mf) break;
    }
    return {sf, sc};
}

