const int T = 99;
const int C = 12;
const ll INF = 0x3f3f3f3f3f3f3f3fLL;

struct Edge {
    int to, rev;
    ll flow, cap, cost;
};

struct MCF {
    int N;
    vector<vector<Edge>> g;
    vector<ll> dist, h;
    vector<int> prevv, preve;

    MCF(int n) : N(n), g(n), dist(n), h(n), prevv(n), preve(n) {}

    void addEdge(int u, int v, ll c, ll p) {
        g[u].push_back({v, (int)g[v].size(), 0, c, p});
        g[v].push_back({u, (int)g[u].size()-1, 0, 0, -p});
    }

    ll minCostFlow(int s, int t, ll& totalCost) {
        totalCost = 0;
        ll flow = 0;

        for (ll lim = 1LL << 30; lim > 0; lim >>= 1) {
            while (true) {
                fill(dist.begin(), dist.end(), INF);
                fill(prevv.begin(), prevv.end(), -1);
                dist[s] = 0;

                priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
                pq.push({0, s});

                while (!pq.empty()) {
                    auto [d, u] = pq.top(); pq.pop();
                    if (d > dist[u]) continue;
                    for (int i = 0; i < g[u].size(); ++i) {
                        auto& e = g[u][i];
                        if (e.cap - e.flow >= lim && dist[e.to] > dist[u] + h[u] - h[e.to] + e.cost) {
                            dist[e.to] = dist[u] + h[u] - h[e.to] + e.cost;
                            prevv[e.to] = u;
                            preve[e.to] = i;
                            pq.push({dist[e.to], e.to});
                        }
                    }
                }

                if (dist[t] >= INF) break;

                for (int i = 0; i < N; ++i) {
                    if (dist[i] < INF) h[i] += dist[i];
                }

                ll df = INF;
                for (int v = t; v != s; v = prevv[v]) {
                    df = min(df, g[prevv[v]][preve[v]].cap - g[prevv[v]][preve[v]].flow);
                }

                for (int v = t; v != s; v = prevv[v]) {
                    auto& e = g[prevv[v]][preve[v]];
                    e.flow += df;
                    g[v][e.rev].flow -= df;
                    totalCost += df * g[v][e.rev].cost;
                }
                flow += df;
            }
        }
        return flow;
    }
};

