            }
        }
    }

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < C; ++j) {
            int cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < T; ++t) {
                network.addEdge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                network.addEdge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
