const int T = 99;
const int C = 12;
const ll INF = 0x3f3f3f3f3f3f3f3fLL;

struct Edge {
    int to, rev;
    ll flow, cap, cost;
};

class FlowNetwork {
public:
    int n;
    vector<vector<Edge>> adj;
    vector<ll> dist, phi;
    vector<int> par;

    FlowNetwork(int size) : n(size), adj(size), dist(size), phi(size, 0), par(size) {}

    void connect(int u, int v, ll capacity, ll cost) {
        adj[u].push_back({v, (int)adj[v].size(), 0, capacity, cost});
        adj[v].push_back({u, (int)adj[u].size()-1, 0, 0, -cost});
    }

    ll solve(int s, int t, ll& totalCost) {
        totalCost = 0;
        ll totalFlow = 0;

        for (ll block = 1LL << 30; block > 0; block >>= 1) {
            while (true) {
                fill(dist.begin(), dist.end(), INF);
                fill(par.begin(), par.end(), -1);
                dist[s] = 0;

                using P = pair<ll, int>;
                priority_queue<P, vector<P>, greater<P>> pq;
                pq.emplace(0, s);

                while (!pq.empty()) {
                    auto [d, u] = pq.top(); pq.pop();
                    if (d != dist[u]) continue;
                    for (int i = 0; i < adj[u].size(); ++i) {
                        auto& e = adj[u][i];
                        if (e.cap - e.flow >= block && dist[e.to] > dist[u] + phi[u] - phi[e.to] + e.cost) {
                            dist[e.to] = dist[u] + phi[u] - phi[e.to] + e.cost;
                            par[e.to] = i;
                            pq.emplace(dist[e.to], e.to);
                        }
                    }
                }

                if (dist[t] >= INF) break;

                for (int i = 0; i < n; ++i) {
                    if (dist[i] < INF) phi[i] += dist[i];
                }

                ll df = INF;
                for (int v = t; v != s; v = adj[v][par[v]].to) {
                    df = min(df, adj[adj[v][par[v]].to][adj[v][par[v]].rev].cap - adj[adj[v][par[v]].to][adj[v][par[v]].rev].flow);
                }

                for (int v = t; v != s; v = adj[v][par[v]].to) {
                    auto& e = adj[adj[v][par[v]].to][adj[v][par[v]].rev];
                    e.flow += df;
                    adj[v][par[v]].flow -= df;
                    totalCost += df * e.cost;
                }
                totalFlow += df;
            }
        }
        return totalFlow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

