using ll = long long;
using pii = pair<int, int>;

const int T = 99;
const int C = 12;
const ll INF = 0x3f3f3f3f3f3f3f3fLL;

struct Edge {
    int to, rev;
    ll flow, cap, cost;
};

class MinCostMaxFlow {
public:
    int N;
    vector<vector<Edge>> g;
    vector<ll> dist, h;
    vector<int> prevv, preve;

    MinCostMaxFlow(int n) : N(n), g(n), dist(n), h(n, 0), prevv(n), preve(n) {}

    void add_edge(int from, int to, ll cap, ll cost) {
        g[from].push_back({to, (int)g[to].size(), 0, cap, cost});
        g[to].push_back({from, (int)g[from].size()-1, 0, 0, -cost});
    }

    ll min_cost_flow(int s, int t, ll& total_cost) {
        total_cost = 0;
        ll total_flow = 0;

        for (ll block = 1LL << 30; block > 0; block >>= 1) {
            while (true) {
                fill(dist.begin(), dist.end(), INF);
                fill(prevv.begin(), prevv.end(), -1);
                dist[s] = 0;

                priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
                pq.push({0, s});

                while (!pq.empty()) {
                    auto [d, u] = pq.top(); pq.pop();
                    if (d > dist[u]) continue;
                    for (int i = 0; i < g[u].size(); ++i) {
                        auto& e = g[u][i];
                        if (e.cap - e.flow >= block && dist[e.to] > dist[u] + h[u] - h[e.to] + e.cost) {
                            dist[e.to] = dist[u] + h[u] - h[e.to] + e.cost;
                            prevv[e.to] = u;
                            preve[e.to] = i;
                            pq.push({dist[e.to], e.to});
                        }
                    }
                }

                if (dist[t] >= INF) break;

                for (int i = 0; i < N; ++i) {
                    if (dist[i] < INF) h[i] += dist[i];
                }

                ll df = INF;
                for (int v = t; v != s; v = prevv[v]) {
                    df = min(df, g[prevv[v]][preve[v]].cap - g[prevv[v]][preve[v]].flow);
                }

                for (int v = t; v != s; v = prevv[v]) {
                    auto& e = g[prevv[v]][preve[v]];
                    e.flow += df;
                    g[v][e.rev].flow -= df;
                    total_cost += df * g[v][e.rev].cost;
                }
                total_flow += df;
            }
        }
        return total_flow;
    }
};

