        if (t > 0) {
            for (int i = 1; i <= n; ++i) {
                mcf.add_edge(i + (t - 1) * n, i + t * n, INF, c);
            }
        }
    }

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < C; ++j) {
            int cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < T; ++t) {
                mcf.add_edge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                mcf.add_edge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
            }
        }
    }

    ll price;
    ll flow = mcf.min_cost_flow(source, sink, price);
    assert(flow == k);
    cout << price << '\n';

    return 0;
}

