}

struct Edge {
    int dest, nextEdge, capacity, weight;
};

int n, m, k, v1, v2, source, sink;
int dist[MAXN];
bool inQueue[MAXN];
Edge graph[MAXN];
int adjList[MAXN], edgeCount = 1;

void insertEdge(int u, int v, int cap, int cost) {
    graph[++edgeCount] = {v, adjList[u], cap, cost};
    adjList[u] = edgeCount;
    graph[++edgeCount] = {u, adjList[v], 0, -cost};
    adjList[v] = edgeCount;
}

bool findShortestPath() {
    fill(dist, dist + sink + 1, INF);
    fill(inQueue, inQueue + sink + 1, false);
    queue<int> q;
    q.push(source);
    dist[source] = 0;
    inQueue[source] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inQueue[u] = false;

        for (int i = adjList[u]; i; i = graph[i].nextEdge) {
            int v = graph[i].dest, w = graph[i].weight;
            if (graph[i].capacity > 0 && dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return dist[sink] != INF;
}

int augment(int u, int flow, bool visited[]) {
    if (u == sink) return flow;
    visited[u] = true;
    int pushed = 0, remaining = flow;

    for (int i = adjList[u]; i; i = graph[i].nextEdge) {
        int v = graph[i].dest, cap = graph[i].capacity;
        if (visited[v] || cap == 0 || dist[v] != dist[u] + graph[i].weight) continue;
        int f = augment(v, min(remaining, cap), visited);
        if (f > 0) {
            remaining -= f;
            graph[i].capacity -= f;
            graph[i ^ 1].capacity += f;
            pushed += f;
            if (remaining == 0) break;
        }
    }
    return pushed;
}

