const int MAXN = 5000010;
const int INF = 1000000000;

inline int get_node(int x, int layer, int n) {
    return x + (layer - 1) * n;
}

inline void input(int &x) {
    x = 0;
    char c = getchar();
    bool neg = false;
    while (c < '0' || c > '9') {
        if (c == '-') neg = true;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

struct Link {
    int dest;
    int next;
    int cap;
    int cost;
};

int n, m, k, v1, v2, src, dst;
int dist[MAXN];
bool inq[MAXN];
Link edge[MAXN];
int head[MAXN], edge_num = 1;

void link(int u, int v, int c, int w) {
    edge[++edge_num] = {v, head[u], c, w};
    head[u] = edge_num;
    edge[++edge_num] = {u, head[v], 0, -w};
    head[v] = edge_num;
}

bool bfs_shortest_path() {
    fill(dist, dist + dst + 1, INF);
    fill(inq, inq + dst + 1, false);
    queue<int> q;
    q.push(src);
    dist[src] = 0;
    inq[src] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = false;

        for (int i = head[u]; i; i = edge[i].next) {
            int v = edge[i].dest, w = edge[i].cost;
            if (edge[i].cap > 0 && dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return dist[dst] != INF;
}

int dfs_flow(int u, int flow, bool visited[]) {
    if (u == dst) return flow;
    visited[u] = true;
    int pushed = 0, left = flow;

    for (int i = head[u]; i; i = edge[i].next) {
        int v = edge[i].dest, cap = edge[i].cap;
        if (visited[v] || cap == 0 || dist[v] != dist[u] + edge[i].cost) continue;
        int f = dfs_flow(v, min(left, cap), visited);
        if (f > 0) {
            left -= f;
            edge[i].cap -= f;
            edge[i ^ 1].cap += f;
            pushed += f;
            if (left == 0) break;
        }
    }
    return pushed;
}

int min_cost_flow() {
    int total = 0;
    while (bfs_shortest_path()) {
        bool visited[MAXN] = {false};
        int flow = dfs_flow(src, INF, visited);
        if (flow > 0) total += flow * dist[dst];
    }
    return total;
}

