using cost_t = llong;
const flow_t INF_FLOW = 1000000000LL;

struct MinCostMaxFlow {
    int vertex_count;
    vector<cost_t> distance, potential;
    vector<flow_t> bottleneck;
    vector<int> prev_edge, prev_vertex;
    priority_queue<pair<cost_t, int>, vector<pair<cost_t, int>>, greater<pair<cost_t, int>>> min_heap;

    struct Connection {
        int target;
        int reverse;
        flow_t flow;
        flow_t capacity;
        cost_t weight;
    };

    vector<vector<Connection>> graph;

    MinCostMaxFlow(int n) : vertex_count(n), distance(n), potential(n), bottleneck(n), prev_edge(n), prev_vertex(n), graph(n) {}

    void link(int u, int v, flow_t cap, cost_t cost) {
        graph[u].push_back({v, (int)graph[v].size(), 0, cap, cost});
        graph[v].push_back({u, (int)graph[u].size() - 1, 0, 0, -cost});
    }

    pair<flow_t, cost_t> min_cost_flow(int source, int sink) {
        flow_t total_flow = 0;
        cost_t total_cost = 0;

        while (true) {
            min_heap.emplace(0, source);
            fill(distance.begin(), distance.end(), INF_FLOW);
            distance[source] = 0;
            bottleneck[source] = INF_FLOW;

            while (!min_heap.empty()) {
                auto [dist, u] = min_heap.top();
                min_heap.pop();

                if (dist != distance[u]) continue;

                for (int idx = 0; idx < (int)graph[u].size(); ++idx) {
                    Connection &edge = graph[u][idx];
                    int v = edge.target;

                    if (edge.capacity <= edge.flow) continue;

                    cost_t new_dist = distance[u] + edge.weight + potential[u] - potential[v];
                    if (distance[v] > new_dist) {
                        distance[v] = new_dist;
                        min_heap.emplace(new_dist, v);
                        prev_vertex[v] = u;
                        prev_edge[v] = idx;
                        bottleneck[v] = min(bottleneck[u], edge.capacity - edge.flow);
                    }
                }
            }

            if (distance[sink] == INF_FLOW) break;

            for (int i = 0; i < vertex_count; ++i)
                potential[i] += distance[i];

            flow_t delta = min(bottleneck[sink], INF_FLOW - total_flow);
            total_flow += delta;

            for (int v = sink; v != source; v = prev_vertex[v]) {
                Connection &edge = graph[prev_vertex[v]][prev_edge[v]];
                edge.flow += delta;
                graph[v][edge.reverse].flow -= delta;
                total_cost += delta * edge.weight;
            }
        }

        return {total_flow, total_cost};
    }
};

