                add_bidir(node_id[b][j], node_id[a][j + 1], 1, k * D);
            }
        }
    }

    int ans = mcmf(src, sink);
    assert(flow == K);
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using u32 = unsigned int;
using u64 = unsigned long long;
using f80 = long double;
using pii = pair<int, int>;

constexpr int MAXN = 55, MAXT = 110, MAXP = MAXN * MAXT, MAXE = 5 * MAXT * MAXN * MAXN;
constexpr int INF = 1000000000;

struct Edge {
    int dest, cap, cost, next;
};

int ecnt = 1;
int head[MAXP];
Edge edges[MAXE];

int N, M, K, C, D;
int cnt[MAXN];
int node_id[MAXN][MAXT];
int src, sink, node_count;

inline void add_edge(int u, int v, int cap, int cost) {
    edges[++ecnt] = {v, cap, cost, head[u]};
    head[u] = ecnt;
}

inline void add_bidir(int u, int v, int cap, int cost) {
    add_edge(u, v, cap, cost);
    add_edge(v, u, 0, -cost);
}

bool spfa(int s, int t) {
    static int dist[MAXP];
    static bool inq[MAXP];
    static int prevv[MAXP], preve[MAXP];
    fill(dist, dist + node_count + 1, INF);
    fill(inq, inq + node_count + 1, false);
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    inq[s] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = false;
        for (int e = head[u]; e; e = edges[e].next) {
            if (edges[e].cap > 0 && dist[edges[e].dest] > dist[u] + edges[e].cost) {
                dist[edges[e].dest] = dist[u] + edges[e].cost;
                prevv[edges[e].dest] = u;
                preve[edges[e].dest] = e;
                if (!inq[edges[e].dest]) {
                    q.push(edges[e].dest);
                    inq[edges[e].dest] = true;
                }
            }
        }
    }
    return dist[t] < INF;
}

int mcmf(int s, int t) {
    int flow = 0, cost = 0;
    while (spfa(s, t)) {
        int f = INF;
        for (int v = t; v != s; v = prevv[v]) {
            f = min(f, edges[preve[v]].cap);
        }
        flow += f;
        cost += f * dist[t];
        for (int v = t; v != s; v = prevv[v]) {
            edges[preve[v]].cap -= f;
            edges[preve[v] ^ 1].cap += f;
        }
    }
    return cost;
}

int main() {
    ios::sync_with_stdio(false);
