    memset(head, 0, sizeof(head));

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= K + M + 2; ++j) {
            node_id[i][j] = ++node_count;
            if (i == 1) {
                add_bidir(node_id[i][j], sink, INF, C * (j - 1));
            }
            if (j > 1) {
                add_bidir(node_id[i][j - 1], node_id[i][j], INF, 0);
            }
        }
        if (cnt[i]) {
            add_bidir(src, node_id[i][1], cnt[i], 0);
        }
    }

    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 1; j <= K + M + 1; ++j) {
            for (int k = 1; k <= 2 * K - 1; k += 2) {
                add_bidir(node_id[a][j], node_id[b][j + 1], 1, k * D);
                add_bidir(node_id[b][j], node_id[a][j + 1], 1, k * D);
            }
        }
    }

    int ans = mcmf(src, sink);
    assert(flow == K);
    cout << ans << '\n';
    return 0;
}

