const int INF = 1000*1000*1000;

struct rib {
	int b, u, c, f;
	size_t back;
};

void add_rib (vector < vector<rib> > & g, int a, int b, int u, int c) {
	rib r1 = { b, u, c, 0, g[b].size() };
	rib r2 = { a, 0, -c, 0, g[a].size() };
	g[a].push_back (r1);
	g[b].push_back (r2);
}

int main()
{
	int N, m, k, c, d;
	scanf("%d %d %d %d %d", &N, &m, &k, &c, &d);
	int n = N * 101 + 2;
	vector < vector<rib> > g (n);
	for (int i = 0; i < k; i++) {
		int x;
		scanf("%d", &x);
		x--;
		add_rib(g, n - 2, x*101, 1, 0);
	}
	for (int i = 0; i < 101; i++)
	{
		add_rib(g, i, n-1, INF, i*c);
	}
	for (int i = 1; i < N; i++) {
		for (int j = 0; j+1 < 101; j++) {
			add_rib(g, i*101 + j, i*101 + j + 1, INF, 0);
		}
	}
	for (int i = 0; i < m; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		u--;
		v--;
		for (int j = 0; j+1 < 101; j++) {
			for (int K = 1; K <= k; K++) {
				add_rib(g, u*101 + j, v*101 + j + 1, 1, d*K*K - d*(K-1)*(K-1));
				add_rib(g, v*101 + j, u*101 + j + 1, 1, d*K*K - d*(K-1)*(K-1));
			}
		}
	}
	int s, t;
	s = n-2;
	t = n-1;
	int flow = 0, cost = 0;
	while (flow < k) {
		vector<int> id (n, 0);
		vector<int> d (n, INF);
		vector<int> q (n);
		vector<int> p (n);
		vector<size_t> p_rib (n);
		int qh=0, qt=0;
		q[qt++] = s;
		d[s] = 0;
		while (qh != qt) {
			int v = q[qh++];
			id[v] = 2;
			if (qh == n)  qh = 0;
			for (size_t i=0; i<g[v].size(); ++i) {
				rib & r = g[v][i];
				if (r.f < r.u && d[v] + r.c < d[r.b]) {
					d[r.b] = d[v] + r.c;
					if (id[r.b] == 0) {
						q[qt++] = r.b;
						if (qt == n)  qt = 0;
					}
					else if (id[r.b] == 2) {
						if (--qh == -1)  qh = n-1;
						q[qh] = r.b;
					}
					id[r.b] = 1;
					p[r.b] = v;
					p_rib[r.b] = i;
				}
			}
		}
		if (d[t] == INF)  break;
		int addflow = k - flow;
		for (int v=t; v!=s; v=p[v]) {
			int pv = p[v];  size_t pr = p_rib[v];
			addflow = min (addflow, g[pv][pr].u - g[pv][pr].f);
		}
		for (int v=t; v!=s; v=p[v]) {
			int pv = p[v];  size_t pr = p_rib[v],  r = g[pv][pr].back;
			g[pv][pr].f += addflow;
			g[v][r].f -= addflow;
			cost += g[pv][pr].c * addflow;
		}
		flow += addflow;
	}
	assert(flow == k);
	cout<<cost<<endl;

}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1000000000;

struct Edge {
    int to, cap, cost, flow;
    size_t rev;
};

void insertEdge(vector<vector<Edge>>& graph, int from, int to, int capacity, int cost) {
    Edge forward = {to, capacity, cost, 0, graph[to].size()};
    Edge backward = {from, 0, -cost, 0, graph[from].size()};
    graph[from].push_back(forward);
    graph[to].push_back(backward);
}

int main() {
    int N, m, k, c, d;
    scanf("%d %d %d %d %d", &N, &m, &k, &c, &d);
    int totalNodes = N * 101 + 2;
    vector<vector<Edge>> graph(totalNodes);

    for (int i = 0; i < k; i++) {
        int x;
        scanf("%d", &x);
        x--;
        insertEdge(graph, totalNodes - 2, x * 101, 1, 0);
    }

    for (int i = 0; i < 101; i++) {
        insertEdge(graph, i, totalNodes - 1, INF, i * c);
    }

    for (int i = 1; i < N; i++) {
        for (int j = 0; j < 100; j++) {
            insertEdge(graph, i * 101 + j, i * 101 + j + 1, INF, 0);
        }
    }

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        for (int j = 0; j < 100; j++) {
            for (int K = 1; K <= k; K++) {
                int edgeCost = d * (K * K - (K - 1) * (K - 1));
                insertEdge(graph, u * 101 + j, v * 101 + j + 1, 1, edgeCost);
                insertEdge(graph, v * 101 + j, u * 101 + j + 1, 1, edgeCost);
            }
        }
    }

    int source = totalNodes - 2;
    int sink = totalNodes - 1;
    int totalFlow = 0, totalCost = 0;

    while (totalFlow < k) {
        vector<int> dist(totalNodes, INF);
        vector<int> parent(totalNodes, -1);
        vector<size_t> parentEdgeIndex(totalNodes);
        vector<int> inQueue(totalNodes, 0);
        queue<int> q;

        dist[source] = 0;
        q.push(source);
        inQueue[source] = 1;

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            inQueue[node] = 0;

            for (size_t idx = 0; idx < graph[node].size(); idx++) {
                Edge& e = graph[node][idx];
                if (e.flow < e.cap && dist[node] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[node] + e.cost;
                    parent[e.to] = node;
                    parentEdgeIndex[e.to] = idx;
                    if (!inQueue[e.to]) {
                        q.push(e.to);
                        inQueue[e.to] = 1;
                    }
                }
            }
        }

        if (dist[sink] == INF) break;

        int augmentFlow = k - totalFlow;
        for (int v = sink; v != source; v = parent[v]) {
            int u = parent[v];
            size_t idx = parentEdgeIndex[v];
            augmentFlow = min(augmentFlow, graph[u][idx].cap - graph[u][idx].flow);
        }

        for (int v = sink; v != source; v = parent[v]) {
            int u = parent[v];
            size_t idx = parentEdgeIndex[v];
            size_t revIdx = graph[u][idx].rev;
            graph[u][idx].flow += augmentFlow;
            graph[v][revIdx].flow -= augmentFlow;
            totalCost += graph[u][idx].cost * augmentFlow;
        }

        totalFlow += augmentFlow;
    }

    assert(totalFlow == k);
    printf("%d\n", totalCost);
    return 0;
}

