    Edge backward = {src, 0, -cost, 0, adj[src].size()};
    adj[src].push_back(forward);
    adj[dest].push_back(backward);
}

int main() {
    int N, m, k, c, d;
    scanf("%d %d %d %d %d", &N, &m, &k, &c, &d);
    int nodeCount = N * 101 + 2;
    vector<vector<Edge>> graph(nodeCount);

    for (int i = 0; i < k; ++i) {
        int x;
        scanf("%d", &x);
        --x;
        addEdge(graph, nodeCount - 2, x * 101, 1, 0);
    }

    for (int i = 0; i < 101; ++i) {
        addEdge(graph, i, nodeCount - 1, INT_MAX, i * c);
    }

    for (int i = 1; i < N; ++i) {
        for (int j = 0; j < 100; ++j) {
            addEdge(graph, i * 101 + j, i * 101 + j + 1, INT_MAX, 0);
        }
    }

    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        for (int j = 0; j < 100; ++j) {
            for (int K = 1; K <= k; ++K) {
                int deltaCost = d * (K * K - (K - 1) * (K - 1));
                addEdge(graph, u * 101 + j, v * 101 + j + 1, 1, deltaCost);
                addEdge(graph, v * 101 + j, u * 101 + j + 1, 1, deltaCost);
            }
        }
    }

    int source = nodeCount - 2;
    int sink = nodeCount - 1;
    int totalFlow = 0, minCost = 0;

    while (totalFlow < k) {
        vector<int> dist(nodeCount, MAX_COST);
        vector<int> prevNode(nodeCount, -1);
        vector<size_t> prevEdge(nodeCount);
        vector<bool> inQueue(nodeCount, false);
        queue<int> q;

        dist[source] = 0;
        q.push(source);
        inQueue[source] = true;

        while (!q.empty()) {
            int cur = q.front();
            q.pop();
            inQueue[cur] = false;

            for (size_t i = 0; i < graph[cur].size(); ++i) {
                Edge& e = graph[cur][i];
                if (e.flow < e.capacity && dist[cur] + e.weight < dist[e.destination]) {
                    dist[e.destination] = dist[cur] + e.weight;
                    prevNode[e.destination] = cur;
                    prevEdge[e.destination] = i;
                    if (!inQueue[e.destination]) {
                        q.push(e.destination);
                        inQueue[e.destination] = true;
                    }
                }
            }
        }

        if (dist[sink] == MAX_COST) break;

        int flowIncrement = k - totalFlow;
        for (int v = sink; v != source; v = prevNode[v]) {
            int u = prevNode[v];
            size_t idx = prevEdge[v];
            flowIncrement = min(flowIncrement, graph[u][idx].capacity - graph[u][idx].flow);
        }

        for (int v = sink; v != source; v = prevNode[v]) {
            int u = prevNode[v];
            size_t idx = prevEdge[v];
            size_t revIdx = graph[u][idx].reverseIndex;
            graph[u][idx].flow += flowIncrement;
            graph[v][revIdx].flow -= flowIncrement;
            minCost += graph[u][idx].weight * flowIncrement;
        }

        totalFlow += flowIncrement;
    }

    if (totalFlow != k) return 1;
    printf("%d\n", minCost);
    return 0;
}

