const int INF = 1000000000;

struct Arc {
    int target;
    int limit;
    int price;
    int current;
    size_t back;
};

void link(vector<vector<Arc>>& network, int from, int to, int cap, int cost) {
    network[from].push_back({to, cap, cost, 0, network[to].size()});
    network[to].push_back({from, 0, -cost, 0, network[from].size() - 1});
}

int main() {
    int N, m, k, c, d;
    scanf("%d %d %d %d %d", &N, &m, &k, &c, &d);
    int total = N * 101 + 2;
    vector<vector<Arc>> network(total);

    for (int i = 0; i < k; i++) {
        int x;
        scanf("%d", &x);
        x--;
        link(network, total - 2, x * 101, 1, 0);
    }

    for (int i = 0; i < 101; i++) {
        link(network, i, total - 1, INF, i * c);
    }

    for (int i = 1; i < N; i++) {
        for (int j = 0; j < 100; j++) {
            link(network, i * 101 + j, i * 101 + j + 1, INF, 0);
        }
    }

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        for (int j = 0; j < 100; j++) {
            for (int K = 1; K <= k; K++) {
                int delta = d * (K * K - (K - 1) * (K - 1));
                link(network, u * 101 + j, v * 101 + j + 1, 1, delta);
                link(network, v * 101 + j, u * 101 + j + 1, 1, delta);
            }
        }
    }

    int start = total - 2, end = total - 1;
    int totalFlow = 0, totalCost = 0;

    while (totalFlow < k) {
        vector<int> distance(total, INF);
        vector<int> predecessor(total, -1);
        vector<size_t> arcIndex(total);
        vector<bool> inQueue(total, false);
        queue<int> q;

        distance[start] = 0;
        q.push(start);
        inQueue[start] = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            inQueue[u] = false;

            for (size_t i = 0; i < network[u].size(); i++) {
                Arc& arc = network[u][i];
                if (arc.current < arc.limit && distance[u] + arc.price < distance[arc.target]) {
                    distance[arc.target] = distance[u] + arc.price;
                    predecessor[arc.target] = u;
                    arcIndex[arc.target] = i;
                    if (!inQueue[arc.target]) {
                        q.push(arc.target);
                        inQueue[arc.target] = true;
                    }
                }
            }
        }

        if (distance[end] == INF) break;

        int augment = k - totalFlow;
        for (int v = end; v != start; v = predecessor[v]) {
            int u = predecessor[v];
            size_t idx = arcIndex[v];
            augment = min(augment, network[u][idx].limit - network[u][idx].current);
        }

        for (int v = end; v != start; v = predecessor[v]) {
            int u = predecessor[v];
            size_t idx = arcIndex[v];
            size_t rev = network[u][idx].back;
            network[u][idx].current += augment;
            network[v][rev].current -= augment;
            totalCost += network[u][idx].price * augment;
        }

        totalFlow += augment;
    }

    printf("%d\n", totalCost);
