                int cost = d * (K * K - (K - 1) * (K - 1));
                connectNodes(graph, u * 101 + j, v * 101 + j + 1, 1, cost);
                connectNodes(graph, v * 101 + j, u * 101 + j + 1, 1, cost);
            }
        }
    }

    int source = totalNodes - 2;
    int sink = totalNodes - 1;
    int flow = 0, cost = 0;

    while (flow < k) {
        vector<int> dist(totalNodes, INF);
        vector<int> prevNode(totalNodes, -1);
        vector<size_t> prevEdge(totalNodes);
        vector<bool> inQ(totalNodes, false);
        queue<int> q;

        dist[source] = 0;
        q.push(source);
        inQ[source] = true;

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            inQ[node] = false;

            for (size_t i = 0; i < graph[node].size(); i++) {
                Link& edge = graph[node][i];
                if (edge.usedFlow < edge.maxFlow && dist[node] + edge.unitCost < dist[edge.dest]) {
                    dist[edge.dest] = dist[node] + edge.unitCost;
                    prevNode[edge.dest] = node;
                    prevEdge[edge.dest] = i;
                    if (!inQ[edge.dest]) {
                        q.push(edge.dest);
                        inQ[edge.dest] = true;
                    }
                }
            }
        }

        if (dist[sink] == INF) break;

        int delta = k - flow;
        for (int v = sink; v != source; v = prevNode[v]) {
            int u = prevNode[v];
            size_t idx = prevEdge[v];
            delta = min(delta, graph[u][idx].maxFlow - graph[u][idx].usedFlow);
        }

        for (int v = sink; v != source; v = prevNode[v]) {
            int u = prevNode[v];
            size_t idx = prevEdge[v];
            size_t rev = graph[u][idx].reverseLink;
            graph[u][idx].usedFlow += delta;
            graph[v][rev].usedFlow -= delta;
            cost += graph[u][idx].unitCost * delta;
        }

        flow += delta;
    }

    printf("%d\n", cost);
    return 0;
}

