struct MinCostFlow {
    int nodes;
    vector<int> dist, parent_node, parent_edge, flow_limit, potential;
    struct Edge {
        int to;
        int flow;
        int capacity;
        int cost;
        int reverse_index;
    };
    vector<vector<Edge>> graph;

    MinCostFlow(int n) : nodes(n),
        dist(n), parent_node(n), parent_edge(n), flow_limit(n), potential(n),
        graph(n) {}

    void add_edge(int from, int to, int capacity, int cost) {
        Edge forward = {to, 0, capacity, cost, (int)graph[to].size()};
        Edge backward = {from, 0, 0, -cost, (int)graph[from].size()};
        graph[from].push_back(forward);
        graph[to].push_back(backward);
    }

    pii compute(int source, int sink) {
        int total_flow = 0, total_cost = 0;
        while (total_flow < INF) {
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
            pq.emplace(0, source);
            fill(all(dist), INT_MAX);
            dist[source] = 0;
            flow_limit[source] = INT_MAX;

            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d != dist[u]) continue;
                for (int i = 0; i < sz(graph[u]); ++i) {
                    auto& e = graph[u][i];
                    int v = e.to;
                    if (e.flow >= e.capacity) continue;
                    int new_dist = dist[u] + e.cost + potential[u] - potential[v];
                    if (dist[v] > new_dist) {
                        dist[v] = new_dist;
                        pq.emplace(new_dist, v);
                        parent_node[v] = u;
                        parent_edge[v] = i;
                        flow_limit[v] = min(flow_limit[u], e.capacity - e.flow);
                    }
                }
            }

            if (dist[sink] == INT_MAX) break;

            rep(i, 0, nodes) potential[i] += dist[i];
            int delta = min(flow_limit[sink], INF - total_flow);
            total_flow += delta;
            for (int v = sink; v != source; v = parent_node[v]) {
                auto& e = graph[parent_node[v]][parent_edge[v]];
                e.flow += delta;
                graph[v][e.reverse_index].flow -= delta;
                total_cost += delta * e.cost;
            }
        }
        return {total_flow, total_cost};
    }
};

