            id_map[i][j] = node_count++;
        }
    }

    int source = node_count;
    int sink = source + 1;

    memset(adjacency_list, -1, sizeof(adjacency_list));
    edge_count = 0;

    for (int i = 0; i < K; ++i) {
        insert_edge(source, id_map[positions[i]][0], 1, 0);
    }

    for (int i = 0; i < MAX_M; ++i) {
        insert_edge(id_map[0][i], sink, K, C * i);
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < MAX_M - 1; ++j) {
            insert_edge(id_map[i][j], id_map[i][j + 1], K, 0);
        }
    }

    for (int i = 0; i < m; ++i) {
        int u = connections[i].first;
        int v = connections[i].second;
        for (int j = 0; j < MAX_M - 1; ++j) {
            for (int k = 0; k < K; ++k) {
                insert_edge(id_map[u][j], id_map[v][j + 1], 1, D * (2 * k + 1));
                insert_edge(id_map[v][j], id_map[u][j + 1], 1, D * (2 * k + 1));
            }
        }
