        for (i32 x = t; x != s; x = E[pre[x] ^ 1].to) {
            E[pre[x]].cap -= f;
            E[pre[x] ^ 1].cap += f;
        }
    }
    cerr << "flow=" << flow << "\n";
    return cost;
}

