    int S = 0, T = 1;
    int total_nodes = 2 + (n + k + 1) * (n + 1);
    vector<vector<Edge>> graph(total_nodes);

    auto add_edge = [&](int from, int to, int cap, int cost) {
        graph[from].emplace_back(to, cap, cost, graph[to].size());
        graph[to].emplace_back(from, 0, -cost, graph[from].size() - 1);
    };

    for (int i = 0; i < k; ++i) {
