    }

    for (int layer = 0; layer <= n + k; ++layer) {
        add_edge(2 + layer * (n + 1), T, k, 0);
        if (layer == n + k) break;

        for (int i = 0; i < m; ++i) {
            int u = edges[i].first, v = edges[i].second;
            for (int l = k; l >= 0; --l) {
                int weight = (l * 2 + 1) * d + c;
                add_edge(u + 1 + layer * (n + 1), v + 1 + layer * (n + 1) + n, 1, weight);
                add_edge(v + 1 + layer * (n + 1), u + 1 + layer * (n + 1) + n, 1, weight);
            }
        }

        for (int i = 1; i <= n; ++i) {
            add_edge(i + 1 + layer * (n + 1), i + 1 + layer * (n + 1) + n, k, c);
        }
    }

    int total_cost = 0;
    while (true) {
        vector<int> dist(total_nodes, INT_MAX);
        vector<int> prev_node(total_nodes, -1);
        vector<int> prev_edge(total_nodes, -1);
        queue<int> q;
        vector<bool> in_queue(total_nodes, false);

        dist[S] = 0;
        q.push(S);
        in_queue[S] = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_queue[u] = false;

            for (int i = 0; i < graph[u].size(); ++i) {
                auto& e = graph[u][i];
