        for (int v = T; v != S; v = prev_node[v]) {
            int u = prev_node[v];
            int idx = prev_edge[v];
            graph[u][idx].capacity -= flow;
            graph[v][graph[u][idx].index].capacity += flow;
        }
    }

    cout << total_cost << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAX_NODES = 2000005;

struct MinCostFlow {
    struct Edge {
        int to, cap, cost, rev;
        Edge(int t, int c, int cst, int r) : to(t), cap(c), cost(cst), rev(r) {}
    };

    vector<vector<Edge>> g;
    vector<int> dist, prevv, preve;
    int n;

    MinCostFlow(int nodes) : n(nodes) {
        g.resize(n);
        dist.resize(n);
        prevv.resize(n);
        preve.resize(n);
    }

    void add_edge(int from, int to, int cap, int cost) {
        g[from].emplace_back(to, cap, cost, g[to].size());
        g[to].emplace_back(from, 0, -cost, g[from].size() - 1);
    }

    int solve(int source, int sink) {
        int total_cost = 0;
        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[source] = 0;
            bool updated = true;
            while (updated) {
                updated = false;
                for (int v = 0; v < n; ++v) {
                    if (dist[v] == INF) continue;
                    for (int i = 0; i < g[v].size(); ++i) {
                        Edge& e = g[v][i];
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                            dist[e.to] = dist[v] + e.cost;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            updated = true;
                        }
                    }
                }
            }
            if (dist[sink] == INF) break;

            int flow = INF;
            for (int v = sink; v != source; v = prevv[v]) {
                flow = min(flow, g[prevv[v]][preve[v]].cap);
            }

            total_cost += flow * dist[sink];
            for (int v = sink; v != source; v = prevv[v]) {
                Edge& e = g[prevv[v]][preve[v]];
                e.cap -= flow;
                g[v][e.rev].cap += flow;
            }
        }
        return total_cost;
    }
};

int main() {
