    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    int S = 0, T = 1;
    int total_nodes = 2 + (n + k + 1) * (n + 1);
    MinCostFlow mcf(total_nodes);

