    for (int i = 0; i < m; ++i) {
        cin >> edges[i].first >> edges[i].second;
    }

    for (int layer = 0; layer <= n + k; ++layer) {
        mcf.add_edge(2 + layer * (n + 1), T, k, 0);
        if (layer == n + k) break;

        for (int i = 0; i < m; ++i) {
            int u = edges[i].first, v = edges[i].second;
            for (int l = k; l >= 0; --l) {
                int w = (l * 2 + 1) * d + c;
                mcf.add_edge(u + 1 + layer * (n + 1), v + 1 + layer * (n + 1) + n, 1, w);
                mcf.add_edge(v + 1 + layer * (n + 1), u + 1 + layer * (n + 1) + n, 1, w);
            }
        }

        for (int i = 1; i <= n; ++i) {
            mcf.add_edge(i + 1 + layer * (n + 1), i + 1 + layer * (n + 1) + n, k, c);
