using namespace std;

const int MAXN = 2000005;

struct Edge {
    int to, cap, cost, rev;
    Edge(int t, int c, int cst, int r) : to(t), cap(c), cost(cst), rev(r) {}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    int S = 0, T = 1;
    int total_nodes = 2 + (n + k + 1) * (n + 1);
    vector<vector<Edge>> graph(total_nodes);

    auto add_edge = [&](int from, int to, int cap, int cost) {
        graph[from].emplace_back(to, cap, cost, graph[to].size());
        graph[to].emplace_back(from, 0, -cost, graph[from].size() - 1);
    };

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        add_edge(S, x + 1, 1, 0);
    }

    vector<pair<int, int>> edges(m);
    for (int i = 0; i < m; ++i) {
        cin >> edges[i].first >> edges[i].second;
    }

    for (int layer = 0; layer <= n + k; ++layer) {
        add_edge(2 + layer * (n + 1), T, k, 0);
        if (layer == n + k) break;

        for (int i = 0; i < m; ++i) {
            int u = edges[i].first, v = edges[i].second;
            for (int l = k; l >= 0; --l) {
                int w = (l * 2 + 1) * d + c;
                add_edge(u + 1 + layer * (n + 1), v + 1 + layer * (n + 1) + n, 1, w);
                add_edge(v + 1 + layer * (n + 1), u + 1 + layer * (n + 1) + n, 1, w);
            }
        }

        for (int i = 1; i <= n; ++i) {
            add_edge(i + 1 + layer * (n + 1), i + 1 + layer * (n + 1) + n, k, c);
        }
    }

    int total_cost = 0;
    while (true) {
        vector<int> dist(total_nodes, 1e9);
        vector<int> prev_node(total_nodes, -1);
        vector<int> prev_edge(total_nodes, -1);
        queue<int> q;
        vector<bool> in_queue(total_nodes, false);

        dist[S] = 0;
        q.push(S);
        in_queue[S] = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_queue[u] = false;

            for (int i = 0; i < graph[u].size(); ++i) {
                Edge& e = graph[u][i];
                if (e.cap > 0 && dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    prev_node[e.to] = u;
                    prev_edge[e.to] = i;
                    if (!in_queue[e.to]) {
                        in_queue[e.to] = true;
                        q.push(e.to);
                    }
                }
            }
        }

        if (dist[T] >= 1e9) break;

        int flow = 1e9;
        for (int v = T; v != S; v = prev_node[v]) {
            flow = min(flow, graph[prev_node[v]][prev_edge[v]].cap);
        }

        total_cost += flow * dist[T];

        for (int v = T; v != S; v = prev_node[v]) {
            int u = prev_node[v];
            int idx = prev_edge[v];
            graph[u][idx].cap -= flow;
            graph[v][graph[u][idx].rev].cap += flow;
        }
    }

    cout << total_cost << '\n';
    return 0;
}

#include<bits/stdc++.h>

using namespace std;

struct edge
{
	int y, c, f, cost;
	edge() {};
	edge(int y, int c, int f, int cost) : y(y), c(c), f(f), cost(cost) {};
};

vector<edge> e;

const int N = 14043;
vector<int> g[N];

long long ans = 0;
long long d[N];
int p[N];
int pe[N];
int inq[N];

const long long INF64 = (long long)(1e18);

int s = N - 2;
int t = N - 1;

int rem(int x)
{
	return e[x].c - e[x].f;
}

void push_flow()
{
	for(int i = 0; i < N; i++) d[i] = INF64, p[i] = -1, pe[i] = -1, inq[i] = 0;
	d[s] = 0;
	queue<int> q;
	q.push(s);
	inq[s] = 1;
	while(!q.empty())
	{
		int k = q.front();
		q.pop();
		inq[k] = 0;
		for(auto x : g[k])
		{
			if(!rem(x)) continue;
			int c = e[x].cost;
			int y = e[x].y;
			if(d[y] > d[k] + c)
			{
				d[y] = d[k] + c;
				p[y] = k;
				pe[y] = x;
				if(inq[y] == 0)
				{
					inq[y] = 1;
					q.push(y);
				}
			}
		}
	}
	int cur = t;
	while(cur != s)
	{
		e[pe[cur]].f++;
		e[pe[cur] ^ 1].f--;
		cur = p[cur];
	}
	ans += d[t];
}

void add_edge(int x, int y, int c, int cost)
{
	g[x].push_back(e.size());
	e.push_back(edge(y, c, 0, cost));
	g[y].push_back(e.size());
	e.push_back(edge(x, 0, 0, -cost));
}

