		add_edge(s, x, 1, 0);
	}
	int tt = 101;
	for(int i = 0; i < tt; i++)
		add_edge(1 + i * n, t, k, i * c);
	for(int i = 0; i < m; i++)
	{
		int x, y;
		cin >> x >> y;
		for(int i = 0; i < tt - 1; i++)
			for(int j = 0; j < k; j++)
			{
				add_edge(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
				add_edge(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
			}

 	}
 	for(int i = 0; i < n; i++)
 		for(int j = 0; j < tt - 1; j++)
 			add_edge(i + j * n, i + j * n + n, k, 0);
