using namespace std;

struct Edge {
    int dest;
    int capacity;
    int flow;
    int cost;
    Edge() : dest(0), capacity(0), flow(0), cost(0) {}
    Edge(int d, int c, int f, int cst) : dest(d), capacity(c), flow(f), cost(cst) {}
};

vector<Edge> edgeList;
const int MAX_NODES = 14043;
vector<int> graph[MAX_NODES];

long long minCost = 0;
long long distance[MAX_NODES];
int prevNode[MAX_NODES];
int prevEdge[MAX_NODES];
bool inQueue[MAX_NODES];

const long long INF = 1000000000000000000LL;

int sourceNode = MAX_NODES - 2;
int targetNode = MAX_NODES - 1;

int getRemaining(int idx) {
    return edgeList[idx].capacity - edgeList[idx].flow;
}

void computeShortestPath() {
    fill(distance, distance + MAX_NODES, INF);
    fill(prevNode, prevNode + MAX_NODES, -1);
    fill(prevEdge, prevEdge + MAX_NODES, -1);
    fill(inQueue, inQueue + MAX_NODES, false);

    distance[sourceNode] = 0;
    queue<int> q;
    q.push(sourceNode);
    inQueue[sourceNode] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQueue[u] = false;

        for (int idx : graph[u]) {
            if (getRemaining(idx) == 0) continue;
            int v = edgeList[idx].dest;
            int w = edgeList[idx].cost;
            if (distance[v] > distance[u] + w) {
                distance[v] = distance[u] + w;
                prevNode[v] = u;
                prevEdge[v] = idx;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void updateFlow() {
    int cur = targetNode;
    while (cur != sourceNode) {
        int idx = prevEdge[cur];
        edgeList[idx].flow++;
        edgeList[idx ^ 1].flow--;
        cur = prevNode[cur];
    }
    if (distance[targetNode] < INF) {
        minCost += distance[targetNode];
    }
}

void connect(int u, int v, int cap, int cst) {
    graph[u].push_back(edgeList.size());
    edgeList.emplace_back(v, cap, 0, cst);
    graph[v].push_back(edgeList.size());
    edgeList.emplace_back(u, 0, 0, -cst);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        connect(sourceNode, x, 1, 0);
    }

    const int MAX_TIME = 101;
    for (int t = 0; t < MAX_TIME; t++) {
        connect(1 + t * n, targetNode, k, t * c);
    }

    for (int i = 0; i < m; i++) {
        int x, y;
        cin >> x >> y;
        for (int t = 0; t < MAX_TIME - 1; t++) {
            for (int j = 0; j < k; j++) {
                int cost = d * (2 * j + 1);
                connect(x + t * n, y + t * n + n, 1, cost);
                connect(y + t * n, x + t * n + n, 1, cost);
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int t = 0; t < MAX_TIME - 1; t++) {
            connect(i + t * n, i + t * n + n, k, 0);
        }
    }

    for (int i = 0; i < k; i++) {
        computeShortestPath();
        updateFlow();
    }

    cout << minCost << '\n';
    return 0;
}

