using ll = long long;

struct Arc {
    int to;
    int capacity;
    int flow;
    int weight;
    Arc() : to(0), capacity(0), flow(0), weight(0) {}
    Arc(int t, int cap, int fl, int w) : to(t), capacity(cap), flow(fl), weight(w) {}
};

vector<Arc> arcs;
const int MAX_VERTICES = 14043;
vector<int> adjList[MAX_VERTICES];

ll totalExpense = 0;
ll distTo[MAX_VERTICES];
int predecessor[MAX_VERTICES];
int edgeIndex[MAX_VERTICES];
bool visited[MAX_VERTICES];

const ll BIG_NUMBER = 1000000000000000000LL;

int startVertex = MAX_VERTICES - 2;
int endVertex = MAX_VERTICES - 1;

int residual(int idx) {
    return arcs[idx].capacity - arcs[idx].flow;
}

void findPath() {
    fill(distTo, distTo + MAX_VERTICES, BIG_NUMBER);
    fill(predecessor, predecessor + MAX_VERTICES, -1);
    fill(edgeIndex, edgeIndex + MAX_VERTICES, -1);
    fill(visited, visited + MAX_VERTICES, false);

    distTo[startVertex] = 0;
    queue<int> q;
    q.push(startVertex);
    visited[startVertex] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        visited[u] = false;

        for (int idx : adjList[u]) {
            if (residual(idx) == 0) continue;
            int v = arcs[idx].to;
            int w = arcs[idx].weight;
            if (distTo[v] > distTo[u] + w) {
                distTo[v] = distTo[u] + w;
                predecessor[v] = u;
                edgeIndex[v] = idx;
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void pushFlow() {
    int cur = endVertex;
    while (cur != startVertex) {
        int idx = edgeIndex[cur];
        arcs[idx].flow++;
        arcs[idx ^ 1].flow--;
        cur = predecessor[cur];
    }
    if (distTo[endVertex] < BIG_NUMBER) {
        totalExpense += distTo[endVertex];
    }
}

void link(int u, int v, int cap, int w) {
    adjList[u].push_back(arcs.size());
    arcs.emplace_back(v, cap, 0, w);
    adjList[v].push_back(arcs.size());
    arcs.emplace_back(u, 0, 0, -w);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        link(startVertex, x, 1, 0);
    }

    const int MAX_T = 101;
    for (int t = 0; t < MAX_T; ++t) {
        link(1 + t * n, endVertex, k, t * c);
    }

    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        for (int t = 0; t < MAX_T - 1; ++t) {
            for (int j = 0; j < k; ++j) {
                int cost = d * (2 * j + 1);
                link(x + t * n, y + t * n + n, 1, cost);
                link(y + t * n, x + t * n + n, 1, cost);
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int t = 0; t < MAX_T - 1; ++t) {
            link(i + t * n, i + t * n + n, k, 0);
        }
    }

    for (int i = 0; i < k; ++i) {
        findPath();
        pushFlow();
    }

    cout << totalExpense << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Connection {
    int target;
    int maxFlow;
    int currentFlow;
    int price;
    Connection() {}
    Connection(int t, int mf, int cf, int p) : target(t), maxFlow(mf), currentFlow(cf), price(p) {}
};

vector<Connection> connections;
const int MAX_SIZE = 14043;
vector<int> neighbors[MAX_SIZE];

ll overallCost = 0;
ll shortestPathDist[MAX_SIZE];
int nodeParent[MAX_SIZE];
int edgeParent[MAX_SIZE];
bool inQueueFlag[MAX_SIZE];

const ll LARGE_INF = 1000000000000000000LL;

int sourceNode = MAX_SIZE - 2;
int destNode = MAX_SIZE - 1;

int availableCapacity(int idx) {
    return connections[idx].maxFlow - connections[idx].currentFlow;
}

void computeMinCostPath() {
    fill(shortestPathDist, shortestPathDist + MAX_SIZE, LARGE_INF);
    fill(nodeParent, nodeParent + MAX_SIZE, -1);
    fill(edgeParent, edgeParent + MAX_SIZE, -1);
    fill(inQueueFlag, inQueueFlag + MAX_SIZE, false);

    shortestPathDist[sourceNode] = 0;
    queue<int> bfsQueue;
    bfsQueue.push(sourceNode);
    inQueueFlag[sourceNode] = true;

    while (!bfsQueue.empty()) {
        int u = bfsQueue.front();
        bfsQueue.pop();
        inQueueFlag[u] = false;

        for (int idx : neighbors[u]) {
            if (availableCapacity(idx) == 0) continue;
            int v = connections[idx].target;
            int w = connections[idx].price;
            if (shortestPathDist[v] > shortestPathDist[u] + w) {
                shortestPathDist[v] = shortestPathDist[u] + w;
                nodeParent[v] = u;
                edgeParent[v] = idx;
                if (!inQueueFlag[v]) {
                    inQueueFlag[v] = true;
                    bfsQueue.push(v);
                }
            }
        }
    }
}

void adjustFlow() {
    int cur = destNode;
    while (cur != sourceNode) {
        int idx = edgeParent[cur];
        connections[idx].currentFlow++;
        connections[idx ^ 1].currentFlow--;
        cur = nodeParent[cur];
    }
    if (shortestPathDist[destNode] != LARGE_INF) {
        overallCost += shortestPathDist[destNode];
    }
}

void createLink(int u, int v, int cap, int cost) {
    neighbors[u].push_back(connections.size());
    connections.emplace_back(v, cap, 0, cost);
    neighbors[v].push_back(connections.size());
    connections.emplace_back(u, 0, 0, -cost);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        createLink(sourceNode, x, 1, 0);
    }

    const int MAX_TIME_LEVELS = 101;
    for (int t = 0; t < MAX_TIME_LEVELS; ++t) {
        createLink(1 + t * n, destNode, k, t * c);
    }

    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        for (int t = 0; t < MAX_TIME_LEVELS - 1; ++t) {
            for (int j = 0; j < k; ++j) {
                int edgeCost = d * (2 * j + 1);
                createLink(x + t * n, y + t * n + n, 1, edgeCost);
                createLink(y + t * n, x + t * n + n, 1, edgeCost);
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int t = 0; t < MAX_TIME_LEVELS - 1; ++t) {
            createLink(i + t * n, i + t * n + n, k, 0);
        }
    }

    for (int i = 0; i < k; ++i) {
        computeMinCostPath();
        adjustFlow();
    }

    cout << overallCost << '\n';
    return 0;
}

