        cin >> x;
        addConnection(sourceVertex, x, 1, 0);
    }

    const int MAX_T = 101;
    for (int t = 0; t < MAX_T; ++t) {
        addConnection(1 + t * n, targetVertex, k, t * c);
    }

    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        for (int t = 0; t < MAX_T - 1; ++t) {
            for (int j = 0; j < k; ++j) {
                int cost = d * (2 * j + 1);
                addConnection(x + t * n, y + t * n + n, 1, cost);
                addConnection(y + t * n, x + t * n + n, 1, cost);
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int t = 0; t < MAX_T - 1; ++t) {
            addConnection(i + t * n, i + t * n + n, k, 0);
        }
    }

    for (int i = 0; i < k; ++i) {
        findShortestPath();
        updateFlowAlongPath();
    }

    cout << totalCost << '\n';
    return 0;
}

