template<typename T = long long>
struct MCMFEdge
{
    using flow_type = T;

    int trg;
    T cost;
    T adjcost;
    T flow;
    T cap;
    int dual;

    MCMFEdge() = default;
    MCMFEdge(int t, T c, T cp, int d) : trg(t), cost(c), adjcost(c), flow(0), cap(cp), dual(d) {}
};

template<typename T = long long>
class MCMFGraph : public GraphBase<MCMFEdge<T> >
{
private:
    struct pqitem
    {
        int trg;
        T prio;

        pqitem() = default;
        pqitem(int t, T p) : trg(t), prio(p) {}

        bool operator<(const pqitem &b) const
        {
            return prio > b.prio;
        }
    };
public:
    using flow_type = typename MCMFEdge<T>::flow_type;
    using Edge = typename GraphBase<MCMFEdge<T> >::Edge;
    using Node = typename GraphBase<MCMFEdge<T> >::Node;

    void add(int a, int b, T cost, T cap, T rcap)
    {
        assert(a >= 0 && a < this->size() && b >= 0 && b < this->size());
        assert(cap >= 0 && rcap >= 0 && cost >= 0);
        if (a == b)
            return;
        if (cap > 0 && rcap > 0)
        {
            add(a, b, cost, cap, 0);
            add(b, a, cost, cap, 0);
        }
        else if (rcap > 0)
        {
            add(b, a, cost, rcap, 0);
        }
        else
        {
            int da = this->size(a);
            int db = this->size(b);
            this->nodes[a].edges.emplace_back(b, cost, cap, db);
            this->nodes[b].edges.emplace_back(a, -cost, 0, da);
        }
    }

    std::pair<T, T> augment(int source, int sink)
    {
        const int N = this->size();
        const T big = std::numeric_limits<T>::max();

        std::vector<T> upby(N);
        std::vector<T> prio(N, big);
        std::vector<int> preve(N);
        std::priority_queue<pqitem> q;

        prio[source] = 0;
        upby[source] = big;
        q.emplace(source, 0);
        while (!q.empty())
        {
            int cur = q.top().trg;
            T p = q.top().prio;
            q.pop();
            if (p != prio[cur])
                continue;
            for (int i = 0; i < this->size(cur); i++)
            {
                const Edge &e = this->nodes[cur].edges[i];
                assert(e.flow == e.cap || e.adjcost >= 0);
                T p2 = p + e.adjcost;
                if (e.flow < e.cap && p2 < prio[e.trg])
                {
                    prio[e.trg] = p2;
                    preve[e.trg] = e.dual;
                    upby[e.trg] = std::min(e.cap - e.flow, upby[cur]);
                    q.emplace(e.trg, p2);
                }
            }
        }

        T up = upby[sink];
        T upcost = 0;
        if (up > 0)
        {
            int cur = sink;
            while (cur != source)
            {
                Edge &ed = this->nodes[cur].edges[preve[cur]];
                Edge &e = this->nodes[ed.trg].edges[ed.dual];
                e.flow += up;
                upcost += e.cost * up;
                ed.flow -= up;
                cur = ed.trg;
            }

            for (int i = 0; i < N; i++)
            {
                for (int j = 0; j < this->size(i); j++)
                {
                    Edge &e = this->nodes[i].edges[j];
                    e.adjcost += prio[i] - prio[e.trg];
                }
            }
        }
        return std::make_pair(up, upcost);
    }

    std::pair<T, T> make_flow(int source, int sink)
    {
        for (int i = 0; i < this->size(); i++)
            for (int j = 0; j < this->size(i); j++)
            {
                Edge &e = this->nodes[i].edges[j];
                e.flow = 0;
                e.adjcost = e.cost;
            }

        T flow = 0;
        T cost = 0;
        std::pair<T, T> up;
        while ((up = augment(source, sink)).first != 0)
        {
            flow += up.first;
            cost += up.second;
        }
        return std::make_pair(flow, cost);
    }

    explicit MCMFGraph(std::size_t sz = 0) : GraphBase<MCMFEdge<T> >(sz) {}
};

int main(int argc, const char **argv)
{
    redirect(argc, argv);
    int N, M, K, C, D;
    cin >> N >> M >> K >> C >> D;
    vi a(K);
    vi starts(N);
    for (int i = 0; i < K; i++)
    {
        cin >> a[i];
        a[i]--;
        starts[a[i]]++;
    }

    int maxT = K + N + 1;
    int V = (maxT + 1) * N + 2;
    int src = V - 2;
    int sink = V - 1;
    MCMFGraph<int> g(V);
    for (int i = 0; i < N; i++)
        if (starts[i])
            g.add(src, i, 0, starts[i], 0);
    for (int t = 0; t <= maxT; t++)
        g.add(t * N, sink, 0, K, 0);
    for (int i = 0; i < N; i++)
        for (int t = 0; t < maxT; t++)
            g.add(t * N + i, (t + 1) * N + i, C, K, 0);
    for (int i = 0; i < M; i++)
    {
        int u, v;
        cin >> u >> v;
        u--;
        v--;
        for (int t = 0; t < maxT; t++)
            for (int j = 0; j < K; j++)
            {
                g.add(t * N + u, (t + 1) * N + v, C + (2 * j + 1) * D, 1, 0);
                g.add(t * N + v, (t + 1) * N + u, C + (2 * j + 1) * D, 1, 0);
            }
    }

    auto fc = g.make_flow(src, sink);
    assert(fc.first == K);
    cout << fc.second << '\n';

    return 0;
}

