#include <algorithm>
#include <climits>

using namespace std;
using llong = long long;

struct FlowEdge {
    int dest;
    llong capacity;
    llong weight;
    int reverse_index;
};

class MinCostFlow {
public:
    vector<vector<FlowEdge>> adj;
    int num_nodes;

    MinCostFlow(int n) : num_nodes(n), adj(n) {}

    void connect(int src, int dst, llong cap, llong wgt) {
        adj[src].push_back({dst, cap, wgt, (int)adj[dst].size()});
        adj[dst].push_back({src, 0, -wgt, (int)adj[src].size() - 1});
    }

    llong compute(int source, int sink, llong required_flow) {
        vector<llong> dist(num_nodes, LLONG_MAX);
        vector<llong> potential(num_nodes, 0);
        vector<int> parent_node(num_nodes);
        vector<int> parent_edge(num_nodes);

        llong total = 0;

        while (required_flow > 0) {
            fill(dist.begin(), dist.end(), LLONG_MAX);
            priority_queue<pair<llong, int>, vector<pair<llong, int>>, greater<pair<llong, int>>> heap;
            dist[source] = 0;
            heap.emplace(0, source);

            while (!heap.empty()) {
                auto [d, u] = heap.top(); heap.pop();
                if (d != dist[u]) continue;
                for (int idx = 0; idx < adj[u].size(); ++idx) {
                    auto& e = adj[u][idx];
                    if (e.capacity > 0 && dist[e.dest] > dist[u] + e.weight + potential[u] - potential[e.dest]) {
                        dist[e.dest] = dist[u] + e.weight + potential[u] - potential[e.dest];
                        parent_node[e.dest] = u;
                        parent_edge[e.dest] = idx;
                        heap.emplace(dist[e.dest], e.dest);
                    }
                }
            }

            if (dist[sink] == LLONG_MAX) return -1;
            for (int i = 0; i < num_nodes; ++i) potential[i] += dist[i];

            llong flow = required_flow;
            for (int node = sink; node != source; node = parent_node[node]) {
                flow = min(flow, adj[parent_node[node]][parent_edge[node]].capacity);
            }

            required_flow -= flow;
            total += flow * potential[sink];

            for (int node = sink; node != source; node = parent_node[node]) {
                auto& e = adj[parent_node[node]][parent_edge[node]];
                e.capacity -= flow;
                adj[node][e.reverse_index].capacity += flow;
            }
        }
        return total;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    llong N, M, K, C, D;
    cin >> N >> M >> K >> C >> D;

    vector<int> starts(K);
    for (int i = 0; i < K; ++i) {
        cin >> starts[i];
        --starts[i];
    }

    vector<int> from_nodes(M), to_nodes(M);
    for (int i = 0; i < M; ++i) {
        cin >> from_nodes[i] >> to_nodes[i];
        --from_nodes[i];
        --to_nodes[i];
    }

    MinCostFlow network(N * 101 + 2);
    int source = N * 101;
    int sink = source + 1;

    for (int i = 0; i < K; ++i) {
        network.connect(source, starts[i], 1, 0);
    }

    for (int day = 0; day <= 100; ++day) {
        network.connect(day * N, sink, K, C * day);
    }

    for (int day = 0; day < 100; ++day) {
        for (int node = 0; node < N; ++node) {
            network.connect(day * N + node, (day + 1) * N + node, K, 0);
        }
        for (int edge_idx = 0; edge_idx < M; ++edge_idx) {
            for (int k = 1; k <= K; ++k) {
                network.connect(day * N + from_nodes[edge_idx], (day + 1) * N + to_nodes[edge_idx], 1, (2 * k - 1) * D);
                network.connect(day * N + to_nodes[edge_idx], (day + 1) * N + from_nodes[edge_idx], 1, (2 * k - 1) * D);
            }
        }
    }

    cout << network.compute(source, sink, K) << '\n';
    return 0;
}

