    for (int i = 0; i < M; ++i) {
        cin >> U[i] >> V[i];
        --U[i];
        --V[i];
    }

    Network g(N * 101 + 2);
    int s = N * 101;
    int t = s + 1;

    for (int i = 0; i < K; ++i) {
        g.link(s, A[i], 1, 0);
    }

    for (int d = 0; d <= 100; ++d) {
        g.link(d * N, t, K, C * d);
    }

    for (int d = 0; d < 100; ++d) {
        for (int node = 0; node < N; ++node) {
            g.link(d * N + node, (d + 1) * N + node, K, 0);
        }
        for (int e = 0; e < M; ++e) {
            for (int k = 1; k <= K; ++k) {
                g.link(d * N + U[e], (d + 1) * N + V[e], 1, (2 * k - 1) * D);
                g.link(d * N + V[e], (d + 1) * N + U[e], 1, (2 * k - 1) * D);
            }
        }
    }

    cout << g.min_cost_flow(s, t, K) << '\n';
