    Edge(int t, int cp, int cs, int rv) : to(t), cap(cp), cost(cs), rev(rv) {}
};

vector<vector<Edge>> graph;
vector<int> dist, prevv, preve;

void add_edge(int from, int to, int cap, int cost) {
    graph[from].emplace_back(to, cap, cost, graph[to].size());
    graph[to].emplace_back(from, 0, -cost, graph[from].size() - 1);
}

pair<int, bool> spfa(int s, int t, int n) {
    fill(dist.begin(), dist.end(), 0x3f3f3f3f);
    dist[s] = 0;
    vector<bool> inq(n, false);
    queue<int> q;
    q.push(s);
    inq[s] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = false;

        for (int i = 0; i < graph[u].size(); ++i) {
            auto& e = graph[u][i];
            if (e.cap > 0 && dist[e.to] > dist[u] + e.cost) {
                dist[e.to] = dist[u] + e.cost;
                prevv[e.to] = u;
                preve[e.to] = i;
                if (!inq[e.to]) {
                    inq[e.to] = true;
                    q.push(e.to);
                }
            }
        }
    }

    if (dist[t] >= 0x3f3f3f3f) return {0, false};

    int flow = 0x3f3f3f3f;
    for (int v = t; v != s; v = prevv[v]) {
        flow = min(flow, graph[prevv[v]][preve[v]].cap);
    }

    for (int v = t; v != s; v = prevv[v]) {
        auto& e = graph[prevv[v]][preve[v]];
        e.cap -= flow;
        graph[v][e.rev].cap += flow;
    }

    return {dist[t] * flow, true};
}

