struct MinCostMaxFlow {
    struct Edge {
        int to, capacity, cost, rev;
        Edge(int t, int cap, int cst, int r) : to(t), capacity(cap), cost(cst), rev(r) {}
    };

    vector<vector<Edge>> adj;
    vector<int> dist, prevv, preve;
    int source, sink;

    MinCostMaxFlow(int n) {
        adj.resize(n);
        dist.resize(n);
        prevv.resize(n);
        preve.resize(n);
    }

    void addEdge(int u, int v, int cap, int cost) {
        adj[u].emplace_back(v, cap, cost, adj[v].size());
        adj[v].emplace_back(u, 0, -cost, adj[u].size() - 1);
    }

    pair<int, bool> spfa() {
        fill(dist.begin(), dist.end(), INF);
        dist[source] = 0;
        vector<bool> inq(adj.size(), false);
        queue<int> q;
        q.push(source);
        inq[source] = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;

            for (int i = 0; i < adj[u].size(); ++i) {
                auto& e = adj[u][i];
                if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    prevv[e.to] = u;
                    preve[e.to] = i;
                    if (!inq[e.to]) {
                        inq[e.to] = true;
                        q.push(e.to);
                    }
                }
            }
        }

        if (dist[sink] == INF) return {0, false};

        int flow = INF;
        for (int v = sink; v != source; v = prevv[v]) {
            flow = min(flow, adj[prevv[v]][preve[v]].capacity);
        }

        for (int v = sink; v != source; v = prevv[v]) {
            auto& e = adj[prevv[v]][preve[v]];
            e.capacity -= flow;
            adj[v][e.rev].capacity += flow;
        }

        return {dist[sink] * flow, true};
    }
};

