const int N = 200005;
const int INF = (1U << 31) - 1;

template <typename Flow, typename Cost>
struct MinCostMaxFlow {
    static constexpr int MAXN = 30000;
    static constexpr int MAXM = 7010010;
    int head[MAXN], inq[MAXN], prevv[MAXN], to[MAXM], nxt[MAXM], idx;
    int src, dst, nodes;
    Flow cap[MAXM];
    Cost dist[MAXN], cost[MAXM];

    void init(int n = MAXN) {
        fill(head, head + (nodes = n), -1);
        idx = 0;
    }

    void add_edge(int u, int v, Flow c, Cost w) {
        to[idx] = v;
        nxt[idx] = head[u];
        cap[idx] = c;
        cost[idx] = w;
        head[u] = idx++;
    }

    void add_bidirectional(int u, int v, Flow c, Cost w) {
        add_edge(u, v, c, w);
        add_edge(v, u, 0, -w);
    }

    bool spfa() {
        queue<int> q;
        fill(dist, dist + nodes, INF);
        dist[src] = 0;
        q.push(src);
        inq[src] = 1;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inq[u] = 0;

            for (int e = head[u]; ~e; e = nxt[e]) {
                if (cap[e] > 0) {
                    int v = to[e];
                    if (dist[u] + cost[e] < dist[v]) {
                        dist[v] = dist[u] + cost[e];
                        prevv[v] = e;
                        if (!inq[v]) {
                            q.push(v);
                            inq[v] = 1;
                        }
                    }
                }
            }
        }
        return dist[dst] != INF;
    }

    Flow total_flow;
    Cost total_cost;

    pair<Flow, Cost> compute(int s, int t) {
        src = s;
        dst = t;
        total_flow = total_cost = 0;

        while (spfa()) {
            Flow bottleneck = INF;
            int e;
            for (int v = dst; v != src; v = to[e ^ 1]) {
                e = prevv[v];
                bottleneck = min(bottleneck, cap[e]);
            }
            for (int v = dst; v != src; v = to[e ^ 1]) {
                e = prevv[v];
                cap[e] -= bottleneck;
                cap[e ^ 1] += bottleneck;
            }
            total_cost += bottleneck * dist[dst];
            total_flow += bottleneck;
        }
        return {total_flow, total_cost};
    }
};

MinCostMaxFlow<int, int> mcmf;
int n, m, k, c, d, a[N], node_id[55][2500];

int main() {
