        rep(level, 0, max_level) {
            rep(step, 1, k + 1) {
                int delta = step * step * d - (step - 1) * (step - 1) * d;
                mcmf.add_bidirectional(node_id[u][level], node_id[v][level + 1], 1, c + delta);
            }
        }
    }

    rep(i, 1, n + 1) {
        rep(level, 0, max_level) {
            mcmf.add_bidirectional(node_id[i][level], node_id[i][level + 1], INF, c);
