};

struct MCMF {
    int head[MAX_NODES], prevv[MAX_NODES], inq[MAX_NODES];
    Edge edges[MAX_EDGES];
    long long dist[MAX_NODES];
    int idx, src, dst, node_count;

    void init(int n) {
        memset(head, -1, sizeof(int) * n);
        idx = 0;
        node_count = n;
    }

    void add_edge(int u, int v, int cap, long long w) {
        edges[idx] = {v, head[u], cap, w};
        head[u] = idx++;
    }

    void add_bidirectional(int u, int v, int cap, long long w) {
        add_edge(u, v, cap, w);
        add_edge(v, u, 0, -w);
    }

    bool spfa() {
        fill(dist, dist + node_count, INF);
        queue<int> q;
        q.push(src);
        dist[src] = 0;
        inq[src] = 1;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inq[u] = 0;

            for (int e = head[u]; ~e; e = edges[e].next) {
                if (edges[e].capacity > 0) {
                    int v = edges[e].to;
                    long long nd = dist[u] + edges[e].cost;
                    if (nd < dist[v]) {
                        dist[v] = nd;
                        prevv[v] = e;
                        if (!inq[v]) {
                            q.push(v);
                            inq[v] = 1;
                        }
                    }
                }
            }
        }
        return dist[dst] != INF;
    }

    pair<int, long long> run(int s, int t) {
        src = s;
        dst = t;
        int total_flow = 0;
        long long total_cost = 0;

        while (spfa()) {
            int bottleneck = INF;
            int e;
            for (int v = dst; v != src; v = edges[e ^ 1].to) {
                e = prevv[v];
                bottleneck = min(bottleneck, edges[e].capacity);
            }
            for (int v = dst; v != src; v = edges[e ^ 1].to) {
                e = prevv[v];
                edges[e].capacity -= bottleneck;
                edges[e ^ 1].capacity += bottleneck;
            }
            total_cost += (long long)bottleneck * dist[dst];
            total_flow += bottleneck;
        }
        return MP(total_flow, total_cost);
    }
};

