};

struct MCMF {
    int n, s, t;
    vector<vector<Edge>> g;
    vector<int> prevv, preve;
    vector<ll> dist;

    MCMF(int nodes) : n(nodes), g(nodes), prevv(nodes), preve(nodes), dist(nodes) {}

    void add_edge(int from, int to, int cap, ll cost) {
        g[from].push_back({to, cap, cost, (int)g[to].size()});
        g[to].push_back({from, 0, -cost, (int)g[from].size() - 1});
    }

    pair<int, ll> min_cost_flow(int src, int dst) {
        s = src;
        t = dst;
        int flow = 0;
        ll cost = 0;

        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            bool updated = true;
            while (updated) {
                updated = false;
                for (int v = 0; v < n; ++v) {
                    if (dist[v] == INF) continue;
                    for (int i = 0; i < g[v].size(); ++i) {
                        Edge &e = g[v][i];
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                            dist[e.to] = dist[v] + e.cost;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            updated = true;
                        }
                    }
                }
            }

            if (dist[t] == INF) break;

            int f = INF;
            for (int v = t; v != s; v = prevv[v]) {
                f = min(f, g[prevv[v]][preve[v]].cap);
            }

            flow += f;
            cost += (ll)f * dist[t];

            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= f;
                g[v][e.rev].cap += f;
            }
        }

        return {flow, cost};
    }
};

