const int MAX_EDGES = 7010010;
const int INF = 0x3f3f3f3f;

struct Edge {
    int to, capacity;
    ll cost;
    int reverse_index;
};

class MinCostMaxFlow {
public:
    int node_count, source_node, sink_node;
    vector<vector<Edge>> graph;
    vector<int> previous_node, previous_edge;
    vector<ll> distances;

    MinCostMaxFlow(int n) : node_count(n), graph(n), previous_node(n), previous_edge(n), distances(n) {}

    void add_directed_edge(int from, int to, int cap, ll cost) {
        graph[from].push_back({to, cap, cost, (int)graph[to].size()});
        graph[to].push_back({from, 0, -cost, (int)graph[from].size() - 1});
    }

    void add_undirected_edge(int u, int v, int cap, ll cost) {
        add_directed_edge(u, v, cap, cost);
        add_directed_edge(v, u, cap, cost);
    }

    pair<int, ll> compute_min_cost_flow(int src, int dst) {
        source_node = src;
        sink_node = dst;
        int total_flow = 0;
        ll total_cost = 0;

        while (true) {
            fill(distances.begin(), distances.end(), INF);
            distances[src] = 0;
            bool updated = true;

            while (updated) {
                updated = false;
                for (int u = 0; u < node_count; ++u) {
                    if (distances[u] == INF) continue;
                    for (int i = 0; i < graph[u].size(); ++i) {
                        Edge &e = graph[u][i];
                        if (e.capacity > 0 && distances[e.to] > distances[u] + e.cost) {
                            distances[e.to] = distances[u] + e.cost;
                            previous_node[e.to] = u;
                            previous_edge[e.to] = i;
                            updated = true;
                        }
                    }
                }
            }

            if (distances[sink_node] == INF) break;

            int flow_amount = INF;
            for (int v = sink_node; v != source_node; v = previous_node[v]) {
                flow_amount = min(flow_amount, graph[previous_node[v]][previous_edge[v]].capacity);
            }

            total_flow += flow_amount;
            total_cost += (ll)flow_amount * distances[sink_node];

            for (int v = sink_node; v != source_node; v = previous_node[v]) {
                Edge &e = graph[previous_node[v]][previous_edge[v]];
                e.capacity -= flow_amount;
                graph[v][e.reverse_index].capacity += flow_amount;
            }
        }

        return {total_flow, total_cost};
    }
};

