struct Edge {
    int dest, cap, cost, reverse;
    Edge(int d, int c, int cst, int r) : dest(d), cap(c), cost(cst), reverse(r) {}
};

struct MinCostFlow {
    int nodeCount;
    int potential[MAXN + 5], distance[MAXN + 5], parentV[MAXN + 5], parentE[MAXN + 5];
    vector<Edge> graph[MAXN + 5];

    void setup(int n) {
        nodeCount = n;
        for (int i = 0; i <= n; ++i) graph[i].clear();
    }

    void connect(int u, int v, int capacity, int cost) {
        graph[u].emplace_back(v, capacity, cost, (int)graph[v].size());
        graph[v].emplace_back(u, 0, -cost, (int)graph[u].size() - 1);
    }

    int compute(int source, int target, int requiredFlow) {
        int totalFlow = 0, totalExpense = 0;
        memset(potential, 0, sizeof(potential));
        while (requiredFlow > 0) {
            priority_queue<PII, vector<PII>, greater<PII>> heap;
            fill(distance, distance + nodeCount + 1, INF);
            distance[source] = 0;
            heap.emplace(0, source);
            while (!heap.empty()) {
                auto [d, u] = heap.top(); heap.pop();
                if (d > distance[u]) continue;
                for (int idx = 0; idx < graph[u].size(); ++idx) {
                    auto& e = graph[u][idx];
                    if (e.cap > 0 && distance[e.dest] > distance[u] + e.cost + potential[u] - potential[e.dest]) {
                        distance[e.dest] = distance[u] + e.cost + potential[u] - potential[e.dest];
                        parentV[e.dest] = u;
                        parentE[e.dest] = idx;
                        heap.emplace(distance[e.dest], e.dest);
                    }
                }
            }
            if (distance[target] == INF) break;
            for (int i = 0; i <= nodeCount; ++i) potential[i] += distance[i];
            int augment = requiredFlow;
            for (int v = target; v != source; v = parentV[v])
                augment = min(augment, graph[parentV[v]][parentE[v]].cap);
            requiredFlow -= augment;
            totalFlow += augment;
            totalExpense += augment * potential[target];
            for (int v = target; v != source; v = parentV[v]) {
                auto& e = graph[parentV[v]][parentE[v]];
                e.cap -= augment;
                graph[v][e.reverse].cap += augment;
            }
        }
        return totalExpense;
    }
};

