#include <bits/stdc++.h>
using namespace std;
const int N = 10000010, INF = 0x3f3f3f3f;
int n, m, c, d, k, s = 0, t, ans = 0;
int cnt = 1, hed[N], to[N], nxt[N], val[N], w[N];
int dis[N], incf[N], pre[N]; bool inq[N];

void add(int x, int y, int z, int v) {
	to[++cnt] = y, nxt[cnt] = hed[x], hed[x] = cnt, val[cnt] = z, w[cnt] = v;
	to[++cnt] = x, nxt[cnt] = hed[y], hed[y] = cnt, val[cnt] = 0, w[cnt] = -v;
}
bool spfa() {
	memset(incf, 0, sizeof(incf)), memset(dis, INF, sizeof(dis));
	memset(inq, 0, sizeof(inq)); queue<int> q;
	q.push(s), incf[s] = INF, inq[s] = 1, dis[s] = 0;
	for(; !q.empty();) {
		int u = q.front(); q.pop(); inq[u] = 0;
		for(int i = hed[u]; i; i = nxt[i]) {
			if(!val[i] || dis[to[i]] <= dis[u] + w[i]) continue;
			dis[to[i]] = dis[u] + w[i];
			incf[to[i]] = min(incf[u], val[i]);
			pre[to[i]] = i; if(!inq[to[i]]) inq[to[i]] = 1, q.push(to[i]);
		}
	}
	return dis[t] != INF;
}
void update() {
	int tmp = t;
	for(; tmp != s;) {
		int i = pre[tmp];
		val[i] -= incf[t], val[i ^ 1] += incf[t], tmp = to[i ^ 1];
	}
	ans += incf[t] * dis[t];
}
int main() {
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d), t = (n + k - 1) * n + 1;
	for(int i = 1, x; i <= k; i++) scanf("%d", &x), add(s, x, 1, 0);
	for(int i = 1, x, y; i <= m; i++) {
		scanf("%d%d", &x, &y);
		for(int j = 1; j <= n + k; j++)
			for(int h = 1; h <= k; h++) {
				add(x + (j - 1) * n, y + j * n, 1, d * h * 2 - d + c);
				add(y + (j - 1) * n, x + j * n, 1, d * h * 2 - d + c);
			}
	}
	for(int i = 1; i < n + k; i++) {
		for(int j = 2; j <= n; j++)
			add(j + (i - 1) * n, j + i * n, INF, c);
		add(1 + (i - 1) * n, 1 + i * n, INF, 0);
	}
	for(; spfa();) update();
	printf("%d\n", ans);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MAXN = 10000010, INF = 0x3f3f3f3f;
int n, m, c, d, k, source = 0, sink, total_cost = 0;
int edge_cnt = 1, head[MAXN], to[MAXN], next_edge[MAXN], capacity[MAXN], cost[MAXN];
int dist[MAXN], bottleneck[MAXN], prev_edge[MAXN]; bool in_queue[MAXN];

void insert_edge(int u, int v, int cap, int w) {
	to[++edge_cnt] = v, next_edge[edge_cnt] = head[u], head[u] = edge_cnt, capacity[edge_cnt] = cap, cost[edge_cnt] = w;
	to[++edge_cnt] = u, next_edge[edge_cnt] = head[v], head[v] = edge_cnt, capacity[edge_cnt] = 0, cost[edge_cnt] = -w;
}
bool bellman_ford() {
	memset(bottleneck, 0, sizeof(bottleneck));
	memset(dist, INF, sizeof(dist));
	memset(in_queue, 0, sizeof(in_queue));
	queue<int> q;
	q.push(source);
	bottleneck[source] = INF;
	in_queue[source] = true;
	dist[source] = 0;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		in_queue[u] = false;
		for (int e = head[u]; e; e = next_edge[e]) {
			if (capacity[e] == 0 || dist[to[e]] <= dist[u] + cost[e]) continue;
			dist[to[e]] = dist[u] + cost[e];
			bottleneck[to[e]] = min(bottleneck[u], capacity[e]);
			prev_edge[to[e]] = e;
			if (!in_queue[to[e]]) {
				in_queue[to[e]] = true;
				q.push(to[e]);
			}
		}
	}
	return dist[sink] != INF;
}
void augment() {
	int flow = bottleneck[sink];
	int cur = sink;
	while (cur != source) {
		int e = prev_edge[cur];
		capacity[e] -= flow;
		capacity[e ^ 1] += flow;
		cur = to[e ^ 1];
	}
	total_cost += flow * dist[sink];
}
int main() {
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
	sink = (n + k - 1) * n + 1;
	for (int i = 1, x; i <= k; i++) {
		scanf("%d", &x);
		insert_edge(source, x, 1, 0);
	}
	for (int i = 1, u, v; i <= m; i++) {
		scanf("%d%d", &u, &v);
		for (int layer = 1; layer <= n + k; layer++) {
			for (int hop = 1; hop <= k; hop++) {
				int weight = d * hop * 2 - d + c;
				insert_edge(u + (layer - 1) * n, v + layer * n, 1, weight);
				insert_edge(v + (layer - 1) * n, u + layer * n, 1, weight);
			}
		}
	}
	for (int layer = 1; layer < n + k; layer++) {
		for (int node = 2; node <= n; node++) {
			insert_edge(node + (layer - 1) * n, node + layer * n, INF, c);
		}
		insert_edge(1 + (layer - 1) * n, 1 + layer * n, INF, 0);
	}
	while (bellman_ford()) {
		augment();
	}
	printf("%d\n", total_cost);
	return 0;
}

