void connect(int u, int v, int capacity, int weight) {
	to[++edge_idx] = v;
	next_edge[edge_idx] = first[u];
	first[u] = edge_idx;
	cap[edge_idx] = capacity;
	wgt[edge_idx] = weight;
	to[++edge_idx] = u;
	next_edge[edge_idx] = first[v];
	first[v] = edge_idx;
	cap[edge_idx] = 0;
	wgt[edge_idx] = -weight;
}
bool find_path() {
	memset(min_flow, 0, sizeof(min_flow));
	memset(dist, 0x3f, sizeof(dist));
	memset(inq, 0, sizeof(inq));
	queue<int> q;
	q.push(src);
	min_flow[src] = INF;
	dist[src] = 0;
	inq[src] = true;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		inq[u] = false;
		for (int e = first[u]; e; e = next_edge[e]) {
			if (!cap[e] || dist[to[e]] <= dist[u] + wgt[e]) continue;
			dist[to[e]] = dist[u] + wgt[e];
			min_flow[to[e]] = min(min_flow[u], cap[e]);
			parent_edge[to[e]] = e;
			if (!inq[to[e]]) {
				inq[to[e]] = true;
				q.push(to[e]);
			}
		}
	}
	return dist[dst] != INF;
}
void push_flow() {
	int f = min_flow[dst];
	int cur = dst;
	while (cur != src) {
		int e = parent_edge[cur];
		cap[e] -= f;
		cap[e ^ 1] += f;
		cur = to[e ^ 1];
	}
	min_cost += f * dist[dst];
}
