#include <bits/stdc++.h>
using namespace std;

const int MAX_NODES = 10000;
const int MAX_EDGES = 2000000;
const int INF = 0x3f3f3f3f;

int n, m, k, c, d;

struct Edge {
    int to, cap, flow, cost, next;
} edges[MAX_EDGES];

int head[MAX_NODES], edgeCount;
int dist[MAX_NODES], prevEdge[MAX_NODES];
bool inQueue[MAX_NODES];
int nodeCount;

void initialize(int totalNodes) {
    nodeCount = totalNodes;
    edgeCount = 0;
    memset(head, -1, sizeof(head));
}

void addEdge(int u, int v, int capacity, int cost) {
    edges[edgeCount] = {v, capacity, 0, cost, head[u]};
    head[u] = edgeCount++;

    edges[edgeCount] = {u, 0, 0, -cost, head[v]};
    head[v] = edgeCount++;
}

bool findShortestPath(int source, int sink) {
    fill(dist, dist + nodeCount, INF);
    fill(inQueue, inQueue + nodeCount, false);
    fill(prevEdge, prevEdge + nodeCount, -1);

    queue<int> q;
    dist[source] = 0;
    inQueue[source] = true;
    q.push(source);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inQueue[u] = false;

        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].to;
            if (edges[i].cap > edges[i].flow && dist[v] > dist[u] + edges[i].cost) {
                dist[v] = dist[u] + edges[i].cost;
                prevEdge[v] = i;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }

    return prevEdge[sink] != -1;
}

pair<int, int> minCostMaxFlow(int source, int sink) {
    int totalFlow = 0, totalCost = 0;

    while (findShortestPath(source, sink)) {
        int bottleneck = INF;
        for (int i = prevEdge[sink]; i != -1; i = prevEdge[edges[i ^ 1].to]) {
            bottleneck = min(bottleneck, edges[i].cap - edges[i].flow);
        }

        for (int i = prevEdge[sink]; i != -1; i = prevEdge[edges[i ^ 1].to]) {
            edges[i].flow += bottleneck;
            edges[i ^ 1].flow -= bottleneck;
            totalCost += edges[i].cost * bottleneck;
        }

        totalFlow += bottleneck;
    }

    return {totalFlow, totalCost};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> k >> c >> d;
