#include <bits/stdc++.h>
using namespace std;

constexpr int MAX_NODES = 10000;
constexpr int MAX_EDGES = 2000000;
constexpr int INF = 0x3f3f3f3f;

int n, m, k, c, d;

struct Edge {
    int dest, capacity, flow, weight, next;
};

Edge edges[MAX_EDGES];
int adjacency[MAX_NODES], edge_index = 0;
int distance[MAX_NODES], parent_edge[MAX_NODES];
bool in_queue[MAX_NODES];
int total_nodes;

inline void reset_graph(int nodes) {
    total_nodes = nodes;
    edge_index = 0;
    memset(adjacency, -1, sizeof(adjacency));
}

inline void insert_edge(int u, int v, int cap, int cost) {
    edges[edge_index] = {v, cap, 0, cost, adjacency[u]};
    adjacency[u] = edge_index++;

    edges[edge_index] = {u, 0, 0, -cost, adjacency[v]};
    adjacency[v] = edge_index++;
}

bool bellman_ford(int source, int sink) {
    fill(distance, distance + total_nodes, INF);
    fill(in_queue, in_queue + total_nodes, false);
    fill(parent_edge, parent_edge + total_nodes, -1);

    queue<int> q;
    distance[source] = 0;
    in_queue[source] = true;
    q.push(source);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = false;

        for (int i = adjacency[u]; i != -1; i = edges[i].next) {
            int v = edges[i].dest;
            if (edges[i].capacity > edges[i].flow && distance[v] > distance[u] + edges[i].weight) {
                distance[v] = distance[u] + edges[i].weight;
                parent_edge[v] = i;
                if (!in_queue[v]) {
                    in_queue[v] = true;
                    q.push(v);
                }
            }
        }
    }

    return parent_edge[sink] != -1;
}

int compute_min_cost_flow(int source, int sink) {
    int total_flow = 0, total_cost = 0;

    while (bellman_ford(source, sink)) {
        int bottleneck = INF;
        for (int i = parent_edge[sink]; i != -1; i = parent_edge[edges[i ^ 1].dest]) {
            bottleneck = min(bottleneck, edges[i].capacity - edges[i].flow);
        }

        for (int i = parent_edge[sink]; i != -1; i = parent_edge[edges[i ^ 1].dest]) {
            edges[i].flow += bottleneck;
            edges[i ^ 1].flow -= bottleneck;
            total_cost += edges[i].weight * bottleneck;
        }

        total_flow += bottleneck;
    }

    return total_cost;
}

