struct Edge {
    int to, capacity, flow, cost, next;
};

Edge edge_list[MAXM];
int head[MAXN], edge_counter = 0;
int dist[MAXN], prev_node[MAXN], prev_edge[MAXN];
bool visited[MAXN];
int node_count;

void setup(int n) {
    node_count = n;
    edge_counter = 0;
    memset(head, -1, sizeof(head));
}

void connect(int u, int v, int cap, int cost) {
    edge_list[edge_counter] = {v, cap, 0, cost, head[u]};
    head[u] = edge_counter++;

    edge_list[edge_counter] = {u, 0, 0, -cost, head[v]};
    head[v] = edge_counter++;
}

bool find_path(int source, int sink) {
    fill(dist, dist + node_count, INF);
    fill(visited, visited + node_count, false);
    fill(prev_node, prev_node + node_count, -1);

    queue<int> q;
    dist[source] = 0;
    visited[source] = true;
    q.push(source);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        visited[u] = false;

        for (int i = head[u]; i != -1; i = edge_list[i].next) {
            int v = edge_list[i].to;
            if (edge_list[i].capacity > edge_list[i].flow && dist[v] > dist[u] + edge_list[i].cost) {
                dist[v] = dist[u] + edge_list[i].cost;
                prev_node[v] = u;
                prev_edge[v] = i;
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }

    return prev_node[sink] != -1;
}

int calculate_min_cost(int source, int sink) {
    int total_flow = 0, total_cost = 0;

    while (find_path(source, sink)) {
        int bottleneck = INF;
        for (int v = sink; v != source; v = prev_node[v]) {
            bottleneck = min(bottleneck, edge_list[prev_edge[v]].capacity - edge_list[prev_edge[v]].flow);
        }

        for (int v = sink; v != source; v = prev_node[v]) {
            int idx = prev_edge[v];
            edge_list[idx].flow += bottleneck;
            edge_list[idx ^ 1].flow -= bottleneck;
            total_cost += edge_list[idx].cost * bottleneck;
        }

        total_flow += bottleneck;
    }

    return total_cost;
}

