	}
	while (m--) {
		scanf("%d%d", &i, &j);
		i--; j--;
		add_edge(i, j); add_edge(j, i);
	}
	t = n + k + 1;
	n_nodes = n * t + 1;
	m_edges = 0;
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			adj_node* curr;
			u = i * t + s;
			for (curr = aa[i].next; curr; curr = curr->next) {
				j = curr->node;
				v = j * t + s + 1;
				for (x = 1; x <= k; x++)
					add_link(u, v, 1, c + (x * 2 - 1) * d);
			}
		}
	}
	for (i = 0; i < n; i++) {
		for (s = 0; s < t - 1; s++) {
			u = i * t + s;
			v = u + 1;
			add_link(u, v, k, i == 0 ? 0 : c);
		}
	}
	for (h = 0; h < k; h++)
		add_link(n_nodes - 1, initials[h] * t + 0, 1, 0);
	printf("%d\n", min_cost_flow(n_nodes - 1, 0 * t + t - 1));
	return 0;
}

