constexpr int NMAX = 5005;
constexpr int INF = 1e9;

struct Edge {
    int to, rev, cap, cost;
};

struct MinCostFlow {
    int n, s, t;
    vector<vector<Edge>> g;
    vector<int> dist, prevv, preve;

    MinCostFlow(int n, int s, int t) : n(n), s(s), t(t),
        g(n), dist(n), prevv(n), preve(n) {}

    void add_edge(int from, int to, int cap, int cost) {
        g[from].push_back({to, (int)g[to].size(), cap, cost});
        g[to].push_back({from, (int)g[from].size()-1, 0, -cost});
    }

    pair<int, int> min_cost_flow() {
        int flow = 0, cost = 0;
        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            bool update = true;
            while (update) {
                update = false;
                for (int v = 0; v < n; ++v) {
                    if (dist[v] == INF) continue;
                    for (int i = 0; i < (int)g[v].size(); ++i) {
                        Edge &e = g[v][i];
                        if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                            dist[e.to] = dist[v] + e.cost;
                            prevv[e.to] = v;
                            preve[e.to] = i;
                            update = true;
                        }
                    }
                }
            }
            if (dist[t] == INF) break;

            int f = INF;
            for (int v = t; v != s; v = prevv[v])
                f = min(f, g[prevv[v]][preve[v]].cap);

            flow += f;
            cost += f * dist[t];

            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= f;
                g[v][e.rev].cap += f;
            }
        }
        return {flow, cost};
    }
};

int P(int i, int j) { return i * n + j; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m >> k >> c_val >> d_val;

    int cs = 2 * k;
    int nodes = cs * n + 2;
    int src = nodes - 2, dst = nodes - 1;

    MinCostFlow mcf(nodes, src, dst);

    for (int i = 0; i < k; i++) {
        int tp;
        cin >> tp;
        mcf.add_edge(src, P(0, tp), 1, 0);
    }

    vector<pair<int, int>> E(m);
    for (int i = 0; i < m; i++) {
        cin >> E[i].first >> E[i].second;
    }

    for (int layer = 1; layer <= cs - 1; layer++) {
        mcf.add_edge(P(layer, 1), dst, k, c_val * layer);

        for (int node = 1; node <= n; node++) {
            mcf.add_edge(P(layer - 1, node), P(layer, node), k, 0);
        }

        for (int i = 0; i < m; i++) {
            int u = E[i].first, v = E[i].second;
            for (int t_idx = 1; t_idx <= k; t_idx++) {
                int cost = (2 * t_idx - 1) * d_val;
                mcf.add_edge(P(layer - 1, u), P(layer, v), 1, cost);
                mcf.add_edge(P(layer - 1, v), P(layer, u), 1, cost);
            }
        }
    }

    cout << mcf.min_cost_flow().second << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

const int MAXN = 5005;
const int INF = 1e9;

struct Edge {
    int to, rev, capacity, cost;
};

class MinCostMaxFlow {
public:
    int n, source, sink;
    vector<vector<Edge>> graph;
    vector<int> dist, prevv, preve;

    MinCostMaxFlow(int nodes, int src, int snk) : n(nodes), source(src), sink(snk),
        graph(nodes), dist(nodes), prevv(nodes), preve(nodes) {}

    void connect(int u, int v, int cap, int cst) {
        graph[u].push_back({v, (int)graph[v].size(), cap, cst});
        graph[v].push_back({u, (int)graph[u].size()-1, 0, -cst});
    }

    pii optimize() {
        int total_flow = 0, total_cost = 0;
        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[source] = 0;
            vector<bool> inq(n, false);
            queue<int> q;
            q.push(source);
            inq[source] = true;

            while (!q.empty()) {
                int u = q.front(); q.pop();
                inq[u] = false;
                for (int i = 0; i < (int)graph[u].size(); ++i) {
                    Edge& e = graph[u][i];
                    if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost) {
                        dist[e.to] = dist[u] + e.cost;
                        prevv[e.to] = u;
                        preve[e.to] = i;
                        if (!inq[e.to]) {
                            q.push(e.to);
                            inq[e.to] = true;
                        }
                    }
                }
            }

            if (dist[sink] == INF) break;

            int flow = INF;
            for (int v = sink; v != source; v = prevv[v])
                flow = min(flow, graph[prevv[v]][preve[v]].capacity);

            total_flow += flow;
            total_cost += flow * dist[sink];

            for (int v = sink; v != source; v = prevv[v]) {
                Edge& e = graph[prevv[v]][preve[v]];
                e.capacity -= flow;
                graph[v][e.rev].capacity += flow;
            }
        }
        return {total_flow, total_cost};
    }
};

int node_index(int i, int j) { return i * n + j; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n_in, m_in, k_in, c_in, d_in;
    cin >> n_in >> m_in >> k_in >> c_in >> d_in;
    n = n_in;

    int cs = 2 * k_in;
    int total_nodes = cs * n_in + 2;
    int src = total_nodes - 2, dst = total_nodes - 1;

    MinCostMaxFlow mcmf(total_nodes, src, dst);

    for (int i = 0; i < k_in; ++i) {
        int tp;
        cin >> tp;
        mcmf.connect(src, node_index(0, tp), 1, 0);
    }

    vector<pair<int, int>> edge_list(m_in);
    for (int i = 0; i < m_in; ++i) {
        cin >> edge_list[i].first >> edge_list[i].second;
    }

    for (int layer = 1; layer <= cs - 1; ++layer) {
        mcmf.connect(node_index(layer, 1), dst, k_in, c_in * layer);

        for (int node = 1; node <= n_in; ++node) {
            mcmf.connect(node_index(layer - 1, node), node_index(layer, node), k_in, 0);
        }

        for (int i = 0; i < m_in; ++i) {
            int u = edge_list[i].first, v = edge_list[i].second;
            for (int t_idx = 1; t_idx <= k_in; ++t_idx) {
                int cost = (2 * t_idx - 1) * d_in;
                mcmf.connect(node_index(layer - 1, u), node_index(layer, v), 1, cost);
                mcmf.connect(node_index(layer - 1, v), node_index(layer, u), 1, cost);
            }
        }
    }

    cout << mcmf.optimize().second << endl;
    return 0;
}

