using namespace std;

typedef long long lint;
typedef pair<int, int> pii;

const int MAX_N = 5005;
const int MAX_M = 4 * MAX_N * (int)sqrt(MAX_N) + 10;
const int INF = 1000000000;

int N, M, K, C, D;
int S, T, NODES;
vector<int> head, next_edge;
vector<int> to, cap, cost;
int edge_id = 1;

void init_graph(int nodes) {
    NODES = nodes;
    head.assign(nodes, -1);
    next_edge.resize(MAX_M);
    to.resize(MAX_M);
    cap.resize(MAX_M);
    cost.resize(MAX_M);
}

void add_edge(int u, int v, int c, int w) {
    to[edge_id] = v;
    cap[edge_id] = c;
    cost[edge_id] = w;
    next_edge[edge_id] = head[u];
    head[u] = edge_id++;
}

void add_flow(int u, int v, int c, int w) {
    add_edge(u, v, c, w);
    add_edge(v, u, 0, -w);
}

int dist[MAX_N];
int pre[MAX_N];
bool inq[MAX_N];

bool spfa() {
    fill(dist, dist + NODES, INF);
    queue<int> q;
    q.push(S);
    dist[S] = 0;
    memset(inq, 0, sizeof(inq));
    inq[S] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inq[u] = false;

        for (int i = head[u]; ~i; i = next_edge[i]) {
            int v = to[i];
            if (cap[i] > 0 && dist[v] > dist[u] + cost[i]) {
                dist[v] = dist[u] + cost[i];
                pre[v] = i;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return dist[T] < INF;
}

pii min_cost_max_flow() {
    pii res = {0, 0};
    while (spfa()) {
        int f = INF;
        for (int x = T; x != S; x = to[pre[x] ^ 1]) {
            f = min(f, cap[pre[x]]);
        }
        for (int x = T; x != S; x = to[pre[x] ^ 1]) {
            cap[pre[x]] -= f;
            cap[pre[x] ^ 1] += f;
        }
        res.first += f;
        res.second += f * dist[T];
    }
    return res;
}

inline int idx(int i, int j) {
    return i * N + j;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M >> K >> C >> D;

    int cs = 2 * K;
    int total_nodes = cs * N + 2;
    S = total_nodes - 2;
    T = total_nodes - 1;
    init_graph(total_nodes);

    for (int i = 0; i < K; i++) {
        int tp;
        cin >> tp;
        add_flow(S, idx(0, tp), 1, 0);
    }

    vector<pair<int, int>> edges(M);
    for (int i = 0; i < M; i++) {
        cin >> edges[i].first >> edges[i].second;
    }

    for (int layer = 1; layer <= cs - 1; layer++) {
        add_flow(idx(layer, 1), T, K, C * layer);
        for (int node = 1; node <= N; node++) {
            add_flow(idx(layer - 1, node), idx(layer, node), K, 0);
        }
        for (int i = 0; i < M; i++) {
            int u = edges[i].first, v = edges[i].second;
            for (int t = 1; t <= K; t++) {
                int w = (2 * t - 1) * D;
                add_flow(idx(layer - 1, u), idx(layer, v), 1, w);
                add_flow(idx(layer - 1, v), idx(layer, u), 1, w);
            }
        }
    }

    cout << min_cost_max_flow().second << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

constexpr int MAX_N = 5005;
constexpr int MAX_E = 4 * MAX_N * (int)sqrt(MAX_N) + 100;
constexpr int INF = 1e9;

struct Edge {
    int to, cap, cost, rev;
};

struct MCMF {
    int N, S, T;
    vector<vector<Edge>> g;
    vector<int> dist, prevv, preve;

    MCMF(int n, int s, int t) : N(n), S(s), T(t),
        g(n), dist(n), prevv(n), preve(n) {}

    void link(int u, int v, int cap, int cost) {
        g[u].emplace_back(Edge{v, cap, cost, (int)g[v].size()});
        g[v].emplace_back(Edge{u, 0, -cost, (int)g[u].size() - 1});
    }

    pii solve() {
        pii result = {0, 0};
        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[S] = 0;
            vector<bool> inq(N, false);
            queue<int> q;
            q.push(S);
            inq[S] = true;

            while (!q.empty()) {
                int u = q.front(); q.pop();
                inq[u] = false;

                for (int i = 0; i < (int)g[u].size(); ++i) {
                    auto& e = g[u][i];
                    if (e.cap > 0 && dist[e.to] > dist[u] + e.cost) {
                        dist[e.to] = dist[u] + e.cost;
                        prevv[e.to] = u;
                        preve[e.to] = i;
                        if (!inq[e.to]) {
                            inq[e.to] = true;
                            q.push(e.to);
                        }
                    }
                }
            }

            if (dist[T] == INF) break;

            int flow = INF;
            for (int v = T; v != S; v = prevv[v])
                flow = min(flow, g[prevv[v]][preve[v]].cap);

            result.first += flow;
            result.second += flow * dist[T];

            for (int v = T; v != S; v = prevv[v]) {
                Edge& e = g[prevv[v]][preve[v]];
                e.cap -= flow;
                g[v][e.rev].cap += flow;
            }
        }
        return result;
    }
};

int idx(int i, int j, int n) { return i * n + j; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    int cs = 2 * k;
    int total = cs * n + 2;
    int src = total - 2, dst = total - 1;

    MCMF solver(total, src, dst);

    for (int i = 0; i < k; ++i) {
        int tp;
        cin >> tp;
        solver.link(src, idx(0, tp, n), 1, 0);
    }

    vector<pii> E(m);
    for (int i = 0; i < m; ++i) {
        cin >> E[i].first >> E[i].second;
    }

    for (int layer = 1; layer <= cs - 1; ++layer) {
        solver.link(idx(layer, 1, n), dst, k, c * layer);
        for (int node = 1; node <= n; ++node) {
            solver.link(idx(layer - 1, node, n), idx(layer, node, n), k, 0);
        }
        for (int i = 0; i < m; ++i) {
            int u = E[i].first, v = E[i].second;
            for (int t = 1; t <= k; ++t) {
                int w = (2 * t - 1) * d;
                solver.link(idx(layer - 1, u, n), idx(layer, v, n), 1, w);
                solver.link(idx(layer - 1, v, n), idx(layer, u, n), 1, w);
            }
        }
    }

    cout << solver.solve().second << endl;
    return 0;
}

