#include<bits/stdc++.h>
using namespace std;

const int maxn = 5005;
typedef int T;
const T INF = 1e9+7;
const int K = 100;

struct Edge {
    int  u , v ;
    T cap ,flow , cost;
};

struct MCMF {
    int n,m,s,t;      // Total Number of Node Including S,T
    vector<int> G[maxn];     //Graph
    vector<Edge> E;         // EdgeList
    T d[maxn];             // Distance Array of BeTmanFord
    bool inq[maxn];           // Is node in queue
    int p[maxn];
    T a[maxn];

    MCMF(int n) : n(n) {}

    void addEdge( int u , int v , T cap , T cost ){
//        cout<<u<<" "<<v<<" "<<cap<<"/"<<cost<<endl;
        E.push_back({u, v , cap , 0 , cost});       // Positive Cost
        E.push_back({v,u , 0, 0 , -cost } );        // Negative Cost
        m = (int) E.size();
        G[u].push_back(m - 2);
        G[v].push_back(m - 1);
    }

    bool BelmanFord(T &flow , T &cost ) {
        for(int i = 0; i < n ;i  ++) d[i] = INF ;
        memset(inq, 0, sizeof(inq));
        d[s] = 0; inq[s] = 1; p[s] = 0; a[s] = INF;

        queue<int> Q;
        Q.push(s);
        while(!Q.empty() ) {
            int u = Q.front(); Q.pop();
            inq[u] = 0;

            for( int i = 0 ; i < G[u].size() ; i ++ ) {
                Edge &e = E[G[u][i]];
                if( e.cap > e.flow && d[e.v] > d[u] + e.cost ) {
                    d[e.v] = d[u] + e.cost;
                    p[e.v] = G[u][i];
                    a[e.v] = min( a[u] , e.cap - e.flow );

                    if( inq[e.v ] == 0 ) {
                        Q.push(e.v);
                        inq[e.v] = 1;
                    }
                }
            }
        }

        if( d[t] == INF ) return false;     // No augmenting Path
        flow = a[t];
        cost = d[t] ;               // Unit cost
        int u = t ;
        while( u  != s ) {
            E[p[u]].flow += a[t];
            E[p[u]^1].flow -= a[t];
            u = E[p[u]].u;
        }
        return true;
    }

    pair<T,T> Mincost (int s, int t) {
        this->s=s,this->t=t;
        T Mcost = 0;
        T Flow = 0;
        T f = 0 ;    // For Each CaT , The flow
        T d = 0;      // Shortest Distance / Cost Per Flow

        while(BelmanFord(f,d)) {
            Flow += f;
            Mcost += f *d ;
        }
        return make_pair(Flow, Mcost);
    }
};

int main() {
    int n, m, k, C, D;
    cin>>n>>m>>k>>C>>D;

    MCMF solver(n*K+2);
    int source = n*K, sink = n*K+1;

    for (int i=0; i<K; i++)
        solver.addEdge(i, sink, k, C*i);


    for (int i=0; i<k; i++) {
        int x;
        cin>>x;
        x--;
        solver.addEdge(source, x*K, 1, 0);
    }

    for (int i=0; i<n; i++)
        for (int j=1; j<K; j++)
            solver.addEdge(i*K+j-1, i*K+j, k, 0);

    while (m--) {
        int u, v;
        cin>>u>>v;
        u--; v--;

        for (int j=1; j<K; j++) {
            int a = u*K+j-1, b = v*K+j;
            int c = v*K+j-1, d = u*K+j;

            for (int i=1, cc = D; i<=k; i++, cc += 2*D) {
                solver.addEdge(a, b, 1, cc);
                solver.addEdge(c, d, 1, cc);
            }
        }
    }
    auto pr = solver.Mincost(source, sink);
    cout<<pr.second<<endl;
}

#include<bits/stdc++.h>
using namespace std;

const int MAX_NODES = 5005;
using ll = long long;
const ll INF = 1000000007LL;
const int MAX_TIME = 100;

struct Edge {
    int u, v;
    ll cap, flow, cost;
};

struct MCMF {
    int n, m, s, t;
    vector<int> G[MAX_NODES];
    vector<Edge> edges;
    ll dist[MAX_NODES];
    bool inq[MAX_NODES];
    int prev_edge[MAX_NODES];
    ll min_cap[MAX_NODES];

    MCMF(int total_nodes) : n(total_nodes) {}

    void add_edge(int u, int v, ll capacity, ll expense) {
        edges.push_back({u, v, capacity, 0, expense});
        edges.push_back({v, u, 0, 0, -expense});
        m = edges.size();
        G[u].push_back(m - 2);
        G[v].push_back(m - 1);
    }

    bool bellman_ford(ll &flow_sent, ll &total_cost) {
        fill(dist, dist + n, INF);
        fill(inq, inq + n, false);
        dist[s] = 0;
        inq[s] = true;
        prev_edge[s] = 0;
        min_cap[s] = INF;

        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inq[u] = false;

            for (int idx : G[u]) {
                Edge &e = edges[idx];
                if (e.cap > e.flow && dist[e.v] > dist[u] + e.cost) {
                    dist[e.v] = dist[u] + e.cost;
                    prev_edge[e.v] = idx;
                    min_cap[e.v] = min(min_cap[u], e.cap - e.flow);
                    if (!inq[e.v]) {
                        q.push(e.v);
                        inq[e.v] = true;
                    }
                }
            }
        }

        if (dist[t] == INF) return false;
        flow_sent = min_cap[t];
        total_cost = dist[t];
        int cur = t;
        while (cur != s) {
            edges[prev_edge[cur]].flow += min_cap[t];
            edges[prev_edge[cur] ^ 1].flow -= min_cap[t];
            cur = edges[prev_edge[cur]].u;
        }
        return true;
    }

    pair<ll, ll> compute_min_cost_flow(int source, int sink) {
        s = source;
        t = sink;
        ll total_cost = 0;
        ll total_flow = 0;
        ll flow_per_iteration, cost_per_flow;

        while (bellman_ford(flow_per_iteration, cost_per_flow)) {
            total_flow += flow_per_iteration;
            total_cost += flow_per_iteration * cost_per_flow;
        }
        return {total_flow, total_cost};
    }
};

int main() {
    int n, m, k, C, D_val;
    cin >> n >> m >> k >> C >> D_val;

    MCMF solver(n * MAX_TIME + 2);
    int source = n * MAX_TIME, sink = n * MAX_TIME + 1;

    for (int t = 0; t < MAX_TIME; t++)
        solver.add_edge(t, sink, k, C * t);

    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        x--;
        solver.add_edge(source, x * MAX_TIME, 1, 0);
    }

    for (int i = 0; i < n; i++)
        for (int t = 1; t < MAX_TIME; t++)
            solver.add_edge(i * MAX_TIME + t - 1, i * MAX_TIME + t, k, 0);

    while (m--) {
        int u, v;
        cin >> u >> v;
        u--; v--;

        for (int t = 1; t < MAX_TIME; t++) {
            int from1 = u * MAX_TIME + t - 1;
            int to1 = v * MAX_TIME + t;
            int from2 = v * MAX_TIME + t - 1;
            int to2 = u * MAX_TIME + t;

            for (int j = 1, cost_val = D_val; j <= k; j++, cost_val += 2 * D_val) {
                solver.add_edge(from1, to1, 1, cost_val);
                solver.add_edge(from2, to2, 1, cost_val);
            }
        }
    }
    auto result = solver.compute_min_cost_flow(source, sink);
    cout << result.second << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

#define MAX_N 5005
using lint = long long;
const lint BIG = 1000000007LL;
const int MAX_T = 100;

struct Edge {
    int from, to;
    lint cap, flow;
    lint cost;
};

struct MinCostMaxFlow {
    int num_nodes, num_edges, src, dst;
    vector<int> adj[MAX_N];
    vector<Edge> edge_list;
    lint dist_arr[MAX_N];
    bool visited[MAX_N];
    int parent_edge[MAX_N];
    lint bottleneck[MAX_N];

    MinCostMaxFlow(int total_nodes) : num_nodes(total_nodes), num_edges(0) {}

    void connect(int u, int v, lint capacity, lint weight) {
        edge_list.push_back({u, v, capacity, 0LL, weight});
        edge_list.push_back({v, u, 0LL, 0LL, -weight});
        int idx = edge_list.size();
        adj[u].push_back(idx - 2);
        adj[v].push_back(idx - 1);
    }

    bool shortest_path(lint &flow, lint &cost_per_unit) {
        fill(dist_arr, dist_arr + num_nodes, BIG);
        fill(visited, visited + num_nodes, false);
        dist_arr[src] = 0;
        visited[src] = true;
        bottleneck[src] = BIG;
        queue<int> q;
        q.push(src);

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            visited[node] = false;

            for (int eid : adj[node]) {
                Edge &e = edge_list[eid];
                if (e.cap > e.flow && dist_arr[e.to] > dist_arr[node] + e.cost) {
                    dist_arr[e.to] = dist_arr[node] + e.cost;
                    parent_edge[e.to] = eid;
                    bottleneck[e.to] = min(bottleneck[node], e.cap - e.flow);

                    if (!visited[e.to]) {
                        q.push(e.to);
                        visited[e.to] = true;
                    }
                }
            }
        }

        if (dist_arr[dst] == BIG) return false;

        flow = bottleneck[dst];
        cost_per_unit = dist_arr[dst];
        int cur = dst;
        while (cur != src) {
            edge_list[parent_edge[cur]].flow += bottleneck[dst];
            edge_list[parent_edge[cur] ^ 1].flow -= bottleneck[dst];
            cur = edge_list[parent_edge[cur]].from;
        }
        return true;
    }

    pair<lint, lint> solve(int source, int destination) {
        src = source;
        dst = destination;
        lint total_flow = 0;
        lint min_cost = 0;
        lint f, c;

        while (shortest_path(f, c)) {
            total_flow += f;
            min_cost += f * c;
        }
        return {total_flow, min_cost};
    }
};

int main() {
    int n, m, k, C, D;
    cin >> n >> m >> k >> C >> D;

    MinCostMaxFlow g(n * MAX_T + 2);
    int src_node = n * MAX_T;
    int dst_node = n * MAX_T + 1;

    for (int t = 0; t < MAX_T; ++t)
        g.connect(t, dst_node, k, C * t);

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        --x;
        g.connect(src_node, x * MAX_T, 1, 0);
    }

    for (int i = 0; i < n; ++i)
        for (int t = 1; t < MAX_T; ++t)
            g.connect(i * MAX_T + t - 1, i * MAX_T + t, k, 0);

    while (m--) {
        int u, v;
        cin >> u >> v;
        --u, --v;

        for (int t = 1; t < MAX_T; ++t) {
            int edge1_from = u * MAX_T + t - 1;
            int edge1_to   = v * MAX_T + t;
            int edge2_from = v * MAX_T + t - 1;
            int edge2_to   = u * MAX_T + t;

            for (int idx = 1, price = D; idx <= k; ++idx, price += 2 * D) {
                g.connect(edge1_from, edge1_to, 1, price);
                g.connect(edge2_from, edge2_to, 1, price);
            }
        }
    }

    pair<lint, lint> ans = g.solve(src_node, dst_node);
    cout << ans.second << '\n';
}

#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>

using namespace std;

typedef long long lint;

const lint INF = 1000000007LL;
const int MAX_NODE = 5005;
const int MAX_TIME = 100;

struct edge_t {
    int from;
    int to;
    lint capacity;
    lint flow;
    lint cost;
};

class MCMF {
public:
    int nodes;
    vector<int> adj[MAX_NODE];
    vector<edge_t> edges;
    lint distance[MAX_NODE];
    bool inqueue[MAX_NODE];
    int prev_edge_index[MAX_NODE];
    lint min_flow_on_path[MAX_NODE];

    MCMF(int n) : nodes(n) {
        for (int i = 0; i < n; ++i) adj[i].clear();
    }

    void addEdge(int u, int v, lint cap, lint cst) {
        edges.push_back({u, v, cap, 0, cst});
        edges.push_back({v, u, 0, 0, -cst});
        int idx = edges.size() - 2;
        adj[u].push_back(idx);
        adj[v].push_back(idx + 1);
    }

    bool computePath(lint &flow_on_this_path, lint &cost_per_flow) {
        fill(distance, distance + nodes, INF);
        fill(inqueue, inqueue + nodes, false);
        distance[0] = 0; // We'll set source later
        memset(inqueue, false, sizeof(bool) * nodes);
        memset(prev_edge_index, -1, sizeof(int) * nodes);

        queue<int> q;
        q.push(0);
        distance[0] = 0;
        inqueue[0] = true;
        min_flow_on_path[0] = INF;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            inqueue[u] = false;

            for (int eidx : adj[u]) {
                edge_t &e = edges[eidx];
                if (e.capacity > e.flow && distance[e.to] > distance[u] + e.cost) {
                    distance[e.to] = distance[u] + e.cost;
                    prev_edge_index[e.to] = eidx;
                    min_flow_on_path[e.to] = min(min_flow_on_path[u], e.capacity - e.flow);
                    if (!inqueue[e.to]) {
                        q.push(e.to);
                        inqueue[e.to] = true;
                    }
                }
            }
        }

        if (distance[1] == INF) return false;

        flow_on_this_path = min_flow_on_path[1];
        cost_per_flow = distance[1];
        int cur = 1;
        while (cur != 0) {
            int eidx = prev_edge_index[cur];
            edges[eidx].flow += flow_on_this_path;
            edges[eidx ^ 1].flow -= flow_on_this_path;
            cur = edges[eidx].from;
        }
        return true;
    }

    pair<lint, lint> getMinCostFlow(int src, int dst) {
        this->nodes = this->nodes;
        int original_nodes = nodes;
        nodes = original_nodes;

        int old_src = 0, old_dst = 1;
        // Adjust node mapping: shift everything so src and dst go where expected
        for (auto &e : edges) {
            e.from = (e.from == 0 ? src : (e.from == 1 ? dst : e.from));
            e.to   = (e.to   == 0 ? src : (e.to   == 1 ? dst : e.to));
        }

        lint total_flow = 0, total_cost = 0;
        lint flow, cost;

        while (computePath(flow, cost)) {
            total_flow += flow;
            total_cost += flow * cost;
        }

        return make_pair(total_flow, total_cost);
    }
};

int main() {
    int n, m, k, C, D;
    cin >> n >> m >> k >> C >> D;

    int total_nodes = n * MAX_TIME + 2;
    MCMF solver(total_nodes);
    int source_id = n * MAX_TIME;
    int sink_id   = n * MAX_TIME + 1;

    for (int t = 0; t < MAX_TIME; ++t)
        solver.addEdge(t, sink_id, k, C * t);

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        x--;
        solver.addEdge(source_id, x * MAX_TIME, 1, 0);
    }

    for (int i = 0; i < n; ++i)
        for (int t = 1; t < MAX_TIME; ++t)
            solver.addEdge(i * MAX_TIME + t - 1, i * MAX_TIME + t, k, 0);

    while (m--) {
        int u, v;
        cin >> u >> v;
        u--; v--;

        for (int t = 1; t < MAX_TIME; ++t) {
