    for (int i = 0; i < n; ++i)
        for (int t = 1; t < MAX_T; ++t)
            g.link(i * MAX_T + t - 1, i * MAX_T + t, k, 0);

    while (m--) {
        int u, v;
        cin >> u >> v;
        --u, --v;

        for (int t = 1; t < MAX_T; ++t) {
            int a = u * MAX_T + t - 1;
            int b = v * MAX_T + t;
            int c = v * MAX_T + t - 1;
            int d = u * MAX_T + t;

            for (int i = 1, cc = D; i <= k; ++i, cc += 2 * D) {
                g.link(a, b, 1, cc);
                g.link(c, d, 1, cc);
