struct Edge {
    int y, c, v, ty;
    Edge(int _y = 0, int _c = 0, int _v = 0, int _ty = 0) : y(_y), c(_c), v(_v), ty(_ty) {}
};

vector<int> e[MAX_NODE_NUM];
Edge es[MAX_EDGE_NUM];
int en = 0, EE = 0, C_val = 0, d_val = 0;

void flow_clear(int _EE) {
    EE = _EE;
    for (int i = 0; i <= EE; ++i) e[i].clear();
    en = 0;
}

void add_edge(int x, int y, int c, int v, int _ty) {
    e[x].push_back(en);
    es[en++] = Edge(y, c, v, _ty);
    e[y].push_back(en);
    if (_ty == 1) {
        es[en++] = Edge(x, 0, -C_val + d_val, _ty);
    } else {
        es[en++] = Edge(x, 0, -v, _ty);
    }
}

int dist[MAX_NODE_NUM], prev_edge[MAX_NODE_NUM], in_queue[MAX_NODE_NUM], queue[10000000];

int min_cost_flow() {
    for (int i = 0; i <= EE; ++i) {
        dist[i] = INF;
        in_queue[i] = 0;
    }
    dist[0] = 0;
    int head = 0, tail = 0;
    queue[tail++] = 0;

    while (head < tail) {
        int x = queue[head++];
        in_queue[x] = 0;
        for (int idx : e[x]) {
            const Edge& edge = es[idx];
            if (edge.c > 0 && dist[x] + edge.v < dist[edge.y]) {
                dist[edge.y] = dist[x] + edge.v;
                prev_edge[edge.y] = idx;
                if (!in_queue[edge.y]) {
                    in_queue[edge.y] = 1;
                    queue[tail++] = edge.y;
                }
            }
        }
    }

    if (dist[EE] == INF) return -1;

    int cur = EE;
    while (cur) {
        int idx = prev_edge[cur];
        if (es[idx].ty == 1) {
            if (idx & 1) {
                es[idx].v += 2 * d_val;
                es[idx ^ 1].v -= 2 * d_val;
            } else {
                es[idx].v += 2 * d_val;
                es[idx ^ 1].v -= 2 * d_val;
            }
        }
        es[idx].c--;
        es[idx ^ 1].c++;
        cur = es[idx ^ 1].y;
    }
    return dist[EE];
}

int solve(int nn) {
    int total = 0;
    for (int i = 0; i < nn; ++i) {
        int cost = min_cost_flow();
        if (cost == -1) break;
        total += cost;
    }
    return total;
}

