    edge_list.emplace_back(dst, cap, wgt, typ);
    adj[dst].push_back(edge_list.size());
    if (typ == 1) {
        edge_list.emplace_back(src, 0, -C_value + d_value, typ);
    } else {
        edge_list.emplace_back(src, 0, -wgt, typ);
    }
}

int find_shortest_path() {
    fill(distance, distance + total_nodes, INT_MAX);
    fill(in_queue, in_queue + total_nodes, 0);
    distance[0] = 0;
    int qhead = 0, qtail = 0;
    bfs_queue[qtail++] = 0;

    while (qhead < qtail) {
        int u = bfs_queue[qhead++];
        in_queue[u] = 0;
        for (int idx : adj[u]) {
            Edge& e = edge_list[idx];
            if (e.capacity > 0 && distance[u] + e.weight < distance[e.dest]) {
                distance[e.dest] = distance[u] + e.weight;
                parent_node[e.dest] = u;
                parent_edge[e.dest] = idx;
                if (!in_queue[e.dest]) {
                    in_queue[e.dest] = 1;
                    bfs_queue[qtail++] = e.dest;
                }
            }
        }
    }

    if (distance[sink_node] == INT_MAX) return -1;

    int cur = sink_node;
    while (cur != 0) {
        int idx = parent_edge[cur];
        if (edge_list[idx].edge_type == 1) {
            if (idx & 1) {
                edge_list[idx].weight += 2 * d_value;
                edge_list[idx ^ 1].weight -= 2 * d_value;
            } else {
