                edge_list[idx ^ 1].weight -= 2 * d_value;
            }
        }
        edge_list[idx].capacity--;
        edge_list[idx ^ 1].capacity++;
        cur = parent_node[cur];
    }
    return distance[sink_node];
}

int compute_min_cost_flow(int num_paths) {
    int total_cost = 0;
    for (int i = 0; i < num_paths; ++i) {
        int cost = find_shortest_path();
        if (cost == -1) break;
        total_cost += cost;
    }
