            if (dist[v] > dist[u] + cost) {
                dist[v] = dist[u] + cost;
                prevNode[v] = u;
                prevEdge[v] = idx;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void augmentPath() {
    dijkstra();
    if (dist[dstNode] >= INF) return;

    int cur = dstNode;
    while (cur != srcNode) {
        int idx = prevEdge[cur];
        edgeList[idx].flow++;
        edgeList[idx ^ 1].flow--;
        cur = prevNode[cur];
    }
    totalCost += dist[dstNode];
}

void addEdge(int u, int v, int cap, int cost) {
    adj[u].push_back(edgeList.size());
    edgeList.emplace_back(u, v, cap, 0, cost);
    adj[v].push_back(edgeList.size());
    edgeList.emplace_back(v, u, 0, 0, -cost);
}

