    in_queue[source_node] = 1;
    flow_limit[source_node] = INF;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = 0;
        for (int idx : node_edges[u]) {
            int v = edge_list[idx].dst;
