struct Edge {
    int from, to, flow, capacity, cost;
};

vector<Edge> edges;
vector<int> node_adj[MAXN];

void connect(int u, int v, int cap, int cost) {
    edges.push_back({u, v, 0, cap, cost});
    node_adj[u].push_back(edges.size() - 1);
    edges.push_back({v, u, 0, 0, -cost});
    node_adj[v].push_back(edges.size() - 1);
}

int dist[MAXN], inq[MAXN], min_cap[MAXN], prev_edge_idx[MAXN];

pii spfa(int n) {
    fill(dist, dist + n + 2, INF);
    queue<int> q;
    q.push(src);
    dist[src] = 0;
    inq[src] = 1;
    min_cap[src] = INF;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (int idx : node_adj[u]) {
            int v = edges[idx].to;
            if (edges[idx].capacity > edges[idx].flow && dist[v] > dist[u] + edges[idx].cost) {
                dist[v] = dist[u] + edges[idx].cost;
                prev_edge_idx[v] = idx;
                min_cap[v] = min(min_cap[u], edges[idx].capacity - edges[idx].flow);
                if (!inq[v]) {
                    q.push(v);
                    inq[v] = 1;
                }
            }
        }
    }

    if (dist[dst] == INF) return {0, 0};

    int augment = min_cap[dst];
    int cur = dst;
    while (cur != src) {
        int eid = prev_edge_idx[cur];
        edges[eid].flow += augment;
        edges[eid ^ 1].flow -= augment;
        cur = edges[eid].from;
    }

    return {augment, augment * dist[dst]};
}

