struct Edge { int target, capacity, weight, next_edge; } edges[2000010];

int encode(int t, int v) { return t * n + v; }

void insert_edge(int src, int dst, int cap, int cost) {
    edges[edge_idx] = {dst, cap, cost, adj_head[src]};
    adj_head[src] = edge_idx++;
    edges[edge_idx] = {src, 0, -cost, adj_head[dst]};
    adj_head[dst] = edge_idx++;
}

bool find_min_cost_path(int source, int sink) {
    fill(shortest_dist, shortest_dist + MAXN, INF);
    bfs_queue.push(source);
    shortest_dist[source] = 0;
    while (!bfs_queue.empty()) {
        int cur = bfs_queue.front(); bfs_queue.pop();
        in_queue[cur] = 0;
        for (int i = adj_head[cur]; ~i; i = edges[i].next_edge) {
            int next_node = edges[i].target;
            if (edges[i].capacity && shortest_dist[next_node] > shortest_dist[cur] + edges[i].weight) {
                shortest_dist[next_node] = shortest_dist[cur] + edges[i].weight;
                prev_edge[next_node] = i;
                if (!in_queue[next_node]) {
                    bfs_queue.push(next_node);
                    in_queue[next_node] = 1;
                }
            }
        }
    }
    return shortest_dist[sink] < 1000000000;
}

void augment_flow(int source, int sink) {
    for (int node = sink; node != source; node = edges[prev_edge[node] ^ 1].target) {
        edges[prev_edge[node]].capacity--;
        edges[prev_edge[node] ^ 1].capacity++;
    }
    min_cost += shortest_dist[sink];
}

int main() {
    memset(adj_head, -1, sizeof(adj_head));
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m >> k >> c >> d;
    int source = 0, sink = 6000;
    for (int i = 1; i <= k; i++) {
        cin >> arrivals[i];
        insert_edge(source, encode(0, arrivals[i]), 1, 0);
    }
    for (int i = 1; i <= m; i++) {
        cin >> froms[i] >> tos[i];
    }
    for (int t = 0; t <= 100; t++) {
        for (int i = 2; i <= n; i++) {
            insert_edge(encode(t, i), encode(t + 1, i), k, c);
        }
        insert_edge(encode(t, 1), sink, k, 0);
        for (int i = 1; i <= m; i++) {
            int max_j = min(k, 25);
            for (int j = 1; j <= max_j; j++) {
                int cost = c + (2 * j - 1) * d;
                insert_edge(encode(t, froms[i]), encode(t + 1, tos[i]), 1, cost);
                insert_edge(encode(t, tos[i]), encode(t + 1, froms[i]), 1, cost);
            }
        }
    }
    while (find_min_cost_path(source, sink)) augment_flow(source, sink);
    cout << min_cost << '\n';
    return 0;
}

