#include <utility>

void answer(unsigned v)
{
    std::cout << v << '\n';
}

void solve(const std::vector<unsigned>& a)
{
    if (a.size() == 0) {
        answer(0);
        return;
    }

    auto [min_p, max_p] = std::minmax_element(a.begin(), a.end());

    unsigned base = *min_p;
    unsigned diff = *max_p - *min_p;
    unsigned half_diff = diff / 2;
    unsigned result = base + half_diff;

    answer(result);
}

