#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> a;
    if (n > 0) { int x; cin >> x; a.push_back(x); }
    if (n > 1) { int x; cin >> x; a.push_back(x); }
    if (n > 2) { int x; cin >> x; a.push_back(x); }
    if (n > 3) { int x; cin >> x; a.push_back(x); }
    if (n == 5) { int x; cin >> x; a.push_back(x); }

    sort(a.begin(), a.end());

    int t = (a[0] + a[a.size()-1]) / 2;
    int i = 0;
    while (i < (int)a.size() && a[i] <= t) i++;
    int j = (int)a.size() - 1;
    while (j >= 0 && a[j] >= t) j--;

    int candidate1 = (i < (int)a.size()) ? a[i] : a.back();
    int candidate2 = (i > 0) ? a[i-1] : a.front();
    int candidate3 = (j >= 0) ? a[j] : a.front();

    int ans;
    if (i > 0 && (abs(candidate2 - t) < abs(candidate1 - t) || 
        (abs(candidate2 - t) == abs(candidate1 - t) && candidate2 < candidate1))) {
        ans = candidate2;
    } else {
        ans = candidate1;
    }

    if (j >= 0 && abs(candidate3 - t) < abs(ans - t)) {
        ans = candidate3;
    }

    cout << ans << endl;
    return 0;
}

