			if (mask & (1 << i))
				cnt++;
		if (cnt != k) continue;
		for (int i = 0; i < n; i++)
			if (mask & (1 << i))
				ans[i] += dp[mask];
	}
	for (int i = 0; i < n; i++)
	{
		if (i) printf(" ");
		printf("%.13lf", ans[i]);
	}
