using namespace std;

using ll = long long;
using ld = long double;

const int MAXN = 20;
const int MAXMASK = 1 << MAXN;
const ld EPS = 1e-12;

ld dp[MAXMASK];
int cntBits[MAXMASK];
ld ans[MAXN];
ld prob[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    // Precompute bit counts
    for (int m = 1; m < MAXMASK; ++m) {
        cntBits[m] = cntBits[m >> 1] + (m & 1);
    }

    int n, k;
    cin >> n >> k;

    for (int i = 0; i < n; ++i) {
        cin >> prob[i];
    }

    dp[0] = 1.0L;

    for (int mask = 0; mask < MAXMASK; ++mask) {
        ld total = 0.0L;
        for (int i = 0; i < n; ++i) {
            if (!(mask & (1 << i))) {
                total += prob[i];
            }
        }

        if (total < EPS) continue;

        for (int i = 0; i < n; ++i) {
            if (!(mask & (1 << i))) {
                if (cntBits[mask] < k) {
                    ans[i] += dp[mask] * prob[i] / total;
                }
                dp[mask | (1 << i)] += dp[mask] * prob[i] / total;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        printf("%.12Lf ", (long double)ans[i]);
    }
    printf("\n");

    return 0;
}

#include <iostream>
#include <cstdio>
#include <cmath>
#include <algorithm>
using namespace std;

const int MAX_M = 1 << 20;
const double EPSILON = 1e-12;

double dp[MAX_M];
int ones[MAX_M];
double sol[22];
double pr[22];

int main() {
    // Precompute number of 1-bits
    for (int m = 1; m < MAX_M; ++m) {
        ones[m] = ones[m >> 1];
        if (m & 1) ones[m]++;
    }

    int N, K;
    cin >> N >> K;

    for (int i = 0; i < N; ++i) {
        cin >> pr[i];
    }

    dp[0] = 1.0;

    for (int mask = 0; mask < MAX_M; ++mask) {
        double sum = 0.0;
        for (int i = 0; i < N; ++i) {
            if (!(mask & (1 << i))) {
                sum += pr[i];
            }
        }

        if (sum < EPSILON) continue;

        for (int i = 0; i < N; ++i) {
            if (!(mask & (1 << i))) {
                if (ones[mask] < K) {
                    sol[i] += dp[mask] * pr[i] / sum;
                }
                dp[mask | (1 << i)] += dp[mask] * pr[i] / sum;
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        printf("%.12f", sol[i]);
        if (i != N - 1) printf(" ");
    }
    printf("\n");

    return 0;
}

