using namespace std;

using ll = long long;
using ld = long double;
using vi = vector<int>;
using pii = pair<int, int>;

const int M = 21;
const ld eps = 1e-6;

int n, k, m;
ld p[M], d[1 << M], ans[M];
int id[M];

void read() {
    cin >> m >> k;
    n = 0;
    for (int i = 0; i < m; ++i) {
        ld x;
        cin >> x;
        if (x > eps) {
            p[n] = x;
            id[n] = i;
            ans[i] = 0;
            ++n;
        } else {
            ans[i] = 0;
        }
    }
}

void solve() {
    if (k >= n) {
        for (int i = 0; i < n; ++i) ans[id[i]] = 1.0;
    } else {
        memset(d, 0, sizeof(d));
        d[0] = 1.0;

        for (int mask = 0; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) >= k) continue;
            ld sum = 0.0;
            for (int t = 0; t < n; ++t)
                if (!(mask & (1 << t))) sum += p[t];

            for (int t = 0; t < n; ++t)
                if (!(mask & (1 << t)))
                    d[mask | (1 << t)] += d[mask] * p[t] / sum;
        }

        for (int mask = 0; mask < (1 << n); ++mask) {
            if (__builtin_popcount(mask) != k) continue;
            for (int t = 0; t < n; ++t)
                if (mask & (1 << t))
                    ans[id[t]] += d[mask];
        }
    }

    for (int i = 0; i < m; ++i)
        cout << fixed << setprecision(10) << ans[i] << " \n"[i == m-1];
}

