int gcd(int a, int b) {
    while (b) { a %= b; swap(a, b); }
    return b;
}

ll gcd(ll a, ll b) {
    while (b) { a %= b; swap(a, b); }
    return b;
}

ll lcm(ll a, ll b) { return a / gcd(a, b) * b; }

ll mod_pow(ll base, ll exp, ll mod) {
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

