int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    vector<double> p(n);
    for (int i = 0; i < n; ++i) {
        scanf("%lf", &p[i]);
    }

    // Precompute binomial coefficients
    vector<vector<ld>> binom(n + 1, vector<ld>(n + 1, 0));
    binom[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        binom[i][0] = binom[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            binom[i][j] = binom[i-1][j-1] + binom[i-1][j];
        }
    }

    // Precompute subset sizes and sums
    int total_masks = 1 << n;
    vector<int> pop(total_masks, 0);
    vector<ld> ssum(total_masks, 0);
    for (int mask = 0; mask < total_masks; ++mask) {
        for (int j = 0; j < n; ++j) {
            if (mask >> j & 1) {
                pop[mask]++;
                ssum[mask] += p[j];
            }
        }
    }

    // Compute coefficients in reverse
    vector<ld> coef(k, 0);
    coef[k - 1] = 1.0L;
    for (int i = k - 2; i >= 0; --i) {
        ld val = 1.0L;
        for (int j = i + 1; j < k; ++j) {
            val -= binom[n - 1 - i][j - i] * coef[j];
        }
        coef[i] = val;
    }

    // Final computation
    for (int i = 0; i < n; ++i) {
        ld ans = 0.0L;
        if (p[i] > 0.005) {
            for (int mask = 0; mask < total_masks; ++mask) {
                if (mask >> i & 1) continue;
                if (pop[mask] >= k) continue;
                ans += coef[pop[mask]] / (1.0L - ssum[mask]);
            }
        }
        printf("%.12f ", (double)(p[i] * ans));
    }
    printf("\n");
    return 0;
}

