    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, k;
    cin >> p >> k;

    ll res = 1;

    if (k != 0) {
        // Find modular inverse of k mod p
        int invK = -1;
        for (int i = 1; i < p; ++i) {
            if ((1LL * i * k) % p == 1) {
                invK = i;
                break;
            }
        }

        // Process cycles in the mapping x -> k*x mod p
        for (int i = 1; i < p; ++i) {
            if (!visited[i]) {
                int cur = i;
