                int len = 1;

                while (!visited[(ll)k * cur % p]) {
                    cur = (ll)k * cur % p;
                    visited[cur] = true;
                    len++;
                }

                // Check if the cycle closes after len steps with multiplier = 1
                ll multiplier = 1;
                for (int j = 0; j < len; ++j) {
                    multiplier = multiplier * invK % p;
                }

                if (multiplier == 1) {
                    res = res * p % MOD;
                }
            }
        }
    } else {
        // When k == 0, multiply by p (p-1) times
        for (int i = 1; i < p; ++i) {
            res = res * p % MOD;
        }
    }

    cout << res << endl;
    return 0;
}

