        if (e & 1) res = (res * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return res;
}

class DSU {
    vector<int> par, rank;
    int components;
public:
    DSU(int n) : par(n), rank(n, 0), components(n) {
        iota(par.begin(), par.end(), 0);
    }

    int get(int x) {
        if (par[x] != x) par[x] = get(par[x]);
        return par[x];
    }

    void unite(int x, int y) {
        x = get(x); y = get(y);
        if (x == y) return;
        if (rank[x] < rank[y]) swap(x, y);
        par[y] = x;
        if (rank[x] == rank[y]) ++rank[x];
        --components;
    }

    int count_components() const { return components; }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    vector<char> vis(p, 0);
    DSU dsu(p);

    for (ll i = 0; i < p; ++i) {
        for (ll cur = i; !vis[cur]; cur = (cur * k) % p) {
            vis[cur] = 1;
            dsu.unite(i, cur);
        }
    }

    int cnt = dsu.count_components();
    if (k != 1) --cnt;

    cout << modpow(p, cnt) << '\n';

    return 0;
}

