struct UnionFind {
    vector<int> parent;
    vector<int> height;
    int numComponents;

    explicit UnionFind(int size) : parent(size), height(size, 0), numComponents(size) {
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    void connect(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (height[a] > height[b]) {
            swap(a, b);
        }
        parent[a] = b;
        if (height[a] == height[b]) ++height[b];
        --numComponents;
    }

    int getComponentCount() const { return numComponents; }
};

