using namespace std;

typedef long long LL;
const LL MOD = 1000000007LL;

LL modPow(LL base, LL exp, LL mod) {
    LL result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int findParent(vector<int>& parent, int x) {
    if (parent[x] != x) {
        parent[x] = findParent(parent, parent[x]);
    }
    return parent[x];
}

void unionSets(vector<int>& parent, vector<int>& rank, int x, int y) {
    int rootX = findParent(parent, x);
    int rootY = findParent(parent, y);

    if (rootX == rootY) return;

    if (rank[rootX] >= rank[rootY]) {
        parent[rootY] = rootX;
        rank[rootX]++;
    } else {
        parent[rootX] = rootY;
        rank[rootY]++;
    }
}

int main() {
    int P, K;
    cin >> P >> K;

    vector<int> parent(P + 1);
    vector<int> rank(P + 1, 1);

    for (int i = 1; i <= P; i++) {
        parent[i] = i;
    }

    for (int i = 1; i < P; i++) {
        LL value = (1LL * K * i) % P;
        if (value == 0) value = P;
        int root1 = findParent(parent, i);
        int root2 = findParent(parent, value);
        if (root1 != root2) {
            unionSets(parent, rank, root1, root2);
        }
    }

    set<int> groups;
    for (int i = 1; i <= P; i++) {
        groups.insert(findParent(parent, i));
    }

    LL ways = 0;
    if (K == 0) {
        ways = modPow(P, P - 1, MOD);
    } else if (K == 1) {
        ways = modPow(P, P, MOD);
    } else {
        ways = modPow(P, groups.size(), MOD);
    }

    cout << ways << endl;

    return 0;
}

