        b = (b * b) % m;
        e >>= 1;
    }
    return r;
}

struct DSU {
    vector<int> parent, rank;
    DSU(int n) {
        parent.resize(n + 1);
        rank.assign(n + 1, 0);
        for (int i = 1; i <= n; i++) parent[i] = i;
    }
    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) swap(x, y);
        parent[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int P, K;
    cin >> P >> K;

    DSU dsu(P);

    for (int i = 1; i < P; ++i) {
        ll target = (1LL * K * i) % P;
        if (target == 0) target = P;
        dsu.unite(i, (int)target);
    }

    set<int> comps;
    for (int i = 1; i <= P; ++i) {
        comps.insert(dsu.find(i));
    }

    ll ans = 0;
    if (K == 0) {
        ans = modpow(P, P - 1, MOD);
    } else if (K == 1) {
        ans = modpow(P, P, MOD);
    } else {
        ans = modpow(P, comps.size(), MOD);
    }

    cout << ans << '\n';

    return 0;
}

