const i64 MOD = 1000000007LL;

i64 binpow(i64 a, i64 b, i64 m) {
    a %= m;
    i64 res = 1;
    while (b > 0) {
        if (b & 1) res = res * a % m;
        a = a * a % m;
        b >>= 1;
    }
    return res;
}

class UnionFind {
public:
    vector<int> parent;
    vector<int> size;

    UnionFind(int n) : parent(n+1), size(n+1, 1) {
        for (int i = 1; i <= n; ++i) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void merge(int x, int y) {
        int rootX = find(x), rootY = find(y);
        if (rootX == rootY) return;

        if (size[rootX] < size[rootY]) swap(rootX, rootY);
        parent[rootY] = rootX;
        size[rootX] += size[rootY];
    }
};

int main() {
    int P, K;
    cin >> P >> K;

    UnionFind uf(P);

    for (int i = 1; i < P; ++i) {
        int val = (1LL * K * i) % P;
        if (val == 0) val = P;
        uf.merge(i, val);
    }

    set<int> roots;
    for (int i = 1; i <= P; ++i) {
        roots.insert(uf.find(i));
    }

    i64 result;
    if (K == 0) {
        result = binpow(P, P - 1, MOD);
    } else if (K == 1) {
        result = binpow(P, P, MOD);
    } else {
        result = binpow(P, (i64)roots.size(), MOD);
    }

    cout << result << endl;

    return 0;
}

