const lint MOD = 1000000007LL;

lint mod_exp(lint base, lint exp, lint mod) {
    lint res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
