    vector<int> parent(P + 1);
    for (int i = 1; i <= P; i++) parent[i] = i;

    auto find_root = [&](int x) {
        vector<int> path;
        while (parent[x] != x) {
            path.push_back(x);
            x = parent[x];
        }
        for (int node : path) parent[node] = x;
        return x;
    };

    for (int i = 1; i < P; i++) {
        lint target = (1LL * K * i) % P;
        if (target == 0) target = P;
        int root1 = find_root(i);
        int root2 = find_root((int)target);
        if (root1 != root2) {
            parent[root2] = root1;
        }
    }

    set<int> unique_roots;
    for (int i = 1; i <= P; i++) {
        unique_roots.insert(find_root(i));
    }

    lint answer;
    if (K == 0) {
        answer = mod_exp((lint)P, (lint)(P - 1), MOD);
    } else if (K == 1) {
        answer = mod_exp((lint)P, (lint)P, MOD);
    } else {
        answer = mod_exp((lint)P, (lint)unique_roots.size(), MOD);
    }

    cout << answer << endl;

    return 0;
}

