    function<int(int)> find_set = [&](int x) -> int {
        if (parent[x] != x) {
            parent[x] = find_set(parent[x]);
        }
        return parent[x];
    };

    for (int i = 1; i < P; ++i) {
        int target = (K * i) % P;
        if (target == 0) target = P;
        int root_i = find_set(i);
        int root_target = find_set(target);
        if (root_i != root_target) {
            parent[root_target] = root_i;
        }
    }

    set<int> components;
    for (int i = 1; i <= P; ++i) {
        components.insert(find_set(i));
    }

    ll final_answer;
    if (K == 0) {
        final_answer = modular_exponentiation(P, P - 1, MOD);
    } else if (K == 1) {
        final_answer = modular_exponentiation(P, P, MOD);
    } else {
        final_answer = modular_exponentiation(P, (ll)components.size(), MOD);
    }

