const long long MOD = 1000000007;

long long mod_pow(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % MOD;
        exp = exp >> 1;
        base = (base * base) % MOD;
    }
    return result;
}

int main() {
    long long p, k;
    cin >> p >> k;

    if (k == 1) {
        cout << mod_pow(p, p) << endl;
        return 0;
    }

    vector<long long> mapping(p);
    for (long long i = 1; i < p; ++i) {
        mapping[i] = (k * i) % p;
    }

    vector<int> seen(p, 0);
    int cycle_number = 0;

    for (int idx = 1; idx < p; ++idx) {
        if (seen[idx]) continue;
        int node = idx;
        while (!seen[node]) {
            seen[node] = 1;
            node = mapping[node];
        }
        cycle_number++;
    }

    cout << mod_pow(p, cycle_number) << endl;
    return 0;
}

