const long long MOD = 1000000007;

long long binpow(long long a, long long n) {
    long long res = 1;
    while (n) {
        if (n & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        n >>= 1;
    }
    return res;
}

int main() {
    long long p, k;
    cin >> p >> k;

    if (k == 1) {
        cout << binpow(p, p) << endl;
        return 0;
    }

    vector<long long> f(p);
    for (long long i = 1; i < p; ++i)
        f[i] = (k * i) % p;

    vector<int> used(p, 0);
    int comp = 0;

    for (int i = 1; i < p; ++i) {
        if (used[i]) continue;
        int j = i;
        while (!used[j]) {
            used[j] = 1;
            j = f[j];
        }
        ++comp;
    }

    cout << binpow(p, comp) << endl;
    return 0;
}

