#define mp make_pair
typedef pair < int,int> ii;
typedef vector<ii> vii;
typedef vector<ll>vl;
typedef vector<int> vi;
typedef vector<vi> vvi;
typedef tree<
int,
null_type,
less<int>,
rb_tree_tag,
tree_order_statistics_node_update>
ordered_set;
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
ll hashPrime = 1610612741;
#define mod 1000000007
ll parent[2000005];
ll rating[2000005];
ll cnt[2000005];
ll findparent(ll root){
    while(parent[root]!=root){
        root = parent[root];
    }
    return root;
}
void findunion(ll root1,ll root2){
    ll par1 = findparent(root1);
    ll par2 = findparent(root2);
    if(rating[par1]>=rating[par2]){
        parent[par2] = par1;
        rating[par1]++;
    }
    else{
        parent[par1] = par2;
        rating[par2]++;
    }
}
void ini(ll n){
    for (ll i = 0; i <= n;i++){
        parent[i] = i;
    }
}
ll modularExponentiation(ll x, ll n, ll M)
{
    if (n == 0)
        return 1;
    else if (n % 2 == 0) //n is even
        return modularExponentiation((x * x) % M, n / 2, M);
    else //n is odd
        return (x * modularExponentiation((x * x) % M, (n - 1) / 2, M)) % M; 

 } 
int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    ll i, j, k, l, n, m;
    cin >> n >> m;
    ini(n);
    if(m==0){
        cout << modularExponentiation(n, n - 1, mod) << "\n";
    }
    else if(m==1){
        cout << modularExponentiation(n, n, mod) << "\n";
    }
    else{
        for (i = 1; i < n;i++){
            ll bash = (i * m) % n;
            findunion(i, bash);
        }
        set<ll> s;
        for (i = 1; i < n;i++){
            parent[i] = findparent(i);
            s.insert(parent[i]);
        }
        ll sz = (ll)s.size();
        cout << modularExponentiation(n, sz, mod) << "\n";
    }
    return 0;
}

