/*
Codeforces Contest #334, Div. 2, Problem D:
*/

/* theprof, Dec 1, 2015 */

#include <iostream>
#include <cmath>

#define N 1000000
#define MOD 1000000007

using namespace std;

int main() {
  int p, k;
  long long i;
  long long num = 1;
  long long q;

  // read input parameters
  cin >> p >> k;

  if (k <= 1) {
    for (q=0; q<p-1+k; q++) {
      num = (num*p) % MOD;
    }
  } else {
    bool used[p]; 

    for (i=0; i<p; i++) {
      used[i] = false;
    }

    for (i=1; i<p; i++) {
      if (!used[i]) {
        num = (num*p) % MOD;
        used[i] = true;
        q = (i*k) % p;
        while (q != i) {
          used[q] = true;
          q = (q*k) % p;
        }
      }
    }
  }
  cout << num << endl;
}

