    {
        const uint64_t ans = FastPow(p, p - 1);
        ost << ans << std::endl;
        return multipleTestMode;
    }

    if (k == 1)
    {
        const uint64_t ans = FastPow(p, p);
        ost << ans << std::endl;
        return multipleTestMode;
    }

    uint64_t groups = 0;

    vector_size_t used(p + 1);
    uint64_t ans = 1;

    for (uint64_t x = 1; x < p; x++)
    {
        if (used[x])
            continue;

        groups += 1;
        ans *= p;
        ans %= Mod;

        used[x] = 1;

        uint64_t v = x;
        while (!used[v * k % p])
        {
            used[v * k % p] = 1;
            v = v * k % p;
        }
    }

    ost << ans << std::endl;

    return multipleTestMode;
}


