        groups += 1;
        ans *= p;
        ans %= Mod;

        used[x] = 1;

        uint64_t v = x;
        while (v * k % p != 0 && !used[v * k % p])
        {
            used[v * k % p] = 1;
            v = v * k % p;
        }
    }

