using namespace std;

const long long MOD = 1000000007LL;

long long mod_exp(long long base, unsigned long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    long long p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << mod_exp(p, p - 1) << '\n';
        return 0;
    }

    vector<int> parent(p);
    for (int i = 0; i < p; i++) parent[i] = i;

    function<int(int)> find_set = [&](int x) -> int {
        if (parent[x] != x) {
            parent[x] = find_set(parent[x]);
        }
        return parent[x];
    };

    auto union_sets = [&](int a, int b) {
        a = find_set(a);
        b = find_set(b);
        if (a != b) {
            parent[b] = a;
        }
    };

    int num_components = p - (k > 1);

    for (long long i = 1; i < p; i++) {
        union_sets(static_cast<int>(i), static_cast<int>((i * k) % p));
    }

    unordered_set<int> unique_roots;
    for (int i = 1; i < p; i++) {
        unique_roots.insert(find_set(i));
    }

    cout << mod_exp(p, static_cast<long long>(unique_roots.size())) << '\n';

    return 0;
}

