using namespace std;

const long long MOD = 1000000007;

long long power(long long base, long long exponent) {
    long long result = 1;
    base %= MOD;
    while (exponent > 0) {
        if (exponent % 2 == 1)
            result = (result * base) % MOD;
        base = (base * base) % MOD;
        exponent /= 2;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    long long p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << power(p, p - 1) << '\n';
        return 0;
    }

    vector<int> parent(p);
    for (int i = 0; i < p; ++i) parent[i] = i;

    function<int(int)> find = [&](int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    };

    auto join = [&](int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            parent[rootY] = rootX;
        }
    };

    int component_count = p - (k > 1);

    for (long long i = 1; i < p; ++i) {
        join(static_cast<int>(i), static_cast<int>((i * k) % p));
    }

    map<int, int> root_map;
    for (int i = 1; i < p; ++i) {
        root_map[find(i)]++;
    }

    cout << power(p, static_cast<long long>(root_map.size())) << '\n';

    return 0;
}

