    for (int i = 0; i < p; ++i) parent[i] = i;

    function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };

    auto connect = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra != rb) {
            parent[rb] = ra;
        }
    };

    int num_components = p - (k > 1);

    for (long long i = 1; i < p; ++i) {
        connect(static_cast<int>(i), static_cast<int>((i * k) % p));
    }

    unordered_map<int, int> component_map;
    for (int i = 1; i < p; ++i) {
        component_map[find(i)]++;
    }

