typedef long long ll;

int mod = 1e9 + 7;

int add(int i, int j) { return ((i += j) < mod ? i : i -= mod); }
int mult(int i, int j) { return (ll) i * j % mod; }
int pwr(int i, int k) {
    int r = 1;
    while(k) {
        if(k & 1)
            r = mult(r, i);
        i = mult(i, i);
        k >>= 1;
    }

    return r;
}

int P[1000001];
int beb(int a, int m) {
    memset(P, -1, sizeof P);
    int s = sqrt(m);
    mod = m;
    int r = 1;
    int d = pwr(a, m - 2);
    for(int i = 0; i <= s; ++i) {
        if(P[r] == -1) P[r] = i;
        r = mult(r, d);
        if(r == 1) { mod = 1e9 + 7; return i + 1; }
    }

    d = pwr(a, s);
    r = d;
    for(int i = 1; i <= s; ++i) {
        if(P[r] > -1) {
            mod = 1e9 + 7;
            return s * i + P[r];
        }

        r = mult(r, d);
    }

    return -1;
}

