}

int multiply_modulo(int a, int b) {
    return static_cast<i64>(a) * b % MOD;
}

int exponentiate(int base, int exponent) {
    int result = 1;
    while (exponent) {
        if (exponent & 1) result = multiply_modulo(result, base);
        base = multiply_modulo(base, base);
        exponent /= 2;
    }
    return result;
}

