    int current_value = 1;
    int base_inverse = exponentiate(base, modulus - 2);

    for (int step = 0; step <= block_size; ++step) {
        if (baby_step_table[current_value] == -1) {
            baby_step_table[current_value] = step;
        }
        current_value = multiply_modulo(current_value, base_inverse);
        if (current_value == 1) {
            return step + 1;
        }
    }

    int giant_step_value = exponentiate(base, block_size);
    current_value = giant_step_value;
    for (int j = 1; j <= block_size; ++j) {
        if (baby_step_table[current_value] != -1) {
            return block_size * j + baby_step_table[current_value];
