struct DSU
{
	vector<ll> parent;

	DSU(ll n)
	{
		parent = vector<ll>(n);
		for (ll i = 0LL; i < n; i++) {
			parent[i] = i;
		}
	}

	ll find_set(ll a)
	{
		if (a == parent[a]) {
			return a;
		}
		ll base = find_set(parent[a]);
		parent[a] = base;
		return base;
	}

	void union_set(ll a, ll b)
	{
		a = find_set(a);
		b = find_set(b);
		if (a != b) {
			if (rand() % 2) {
				swap(a, b);
			}
			parent[b] = a;
		}
	}
};

ll count_cycles(ll p, ll k)
{
