i64 mod_pow(i64 base, i64 exp, i64 mod) {
    i64 res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

