        return 0;
    }

    auto compute = [&](int start) -> pair<int, long long> {
        vector<bool> visited(p, false);
        int len = 0;
        long long power = 1;
        int curr = start;

        while (!visited[curr]) {
            visited[curr] = true;
            curr = (k * curr) % p;
            ++len;
            power = (power * k) % p;
        }

        return {len, power};
    };

    long long final_result = 1;
    vector<bool> global_visited(p, false);

    for (int i = 0; i < p; ++i) {
        if (global_visited[i]) continue;

        auto [cycle_len, power_val] = compute(i);

        for (int j = 0, curr = i; j < cycle_len; ++j) {
            global_visited[curr] = true;
            curr = (k * curr) % p;
        }

        if (cycle_len == 1) {
            int cnt = (k == 1) ? p : 1;
            final_result = (final_result * cnt) % MOD;
        } else {
            assert(power_val == 1);
            final_result = (final_result * p) % MOD;
