#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAXN = 1000005;
const ll MOD = 1000000007;

bool visited[MAXN];

ll modPow(ll base, int exp) {
    ll result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        exp >>= 1;
        base = (base * base) % MOD;
    }
    return result;
}

int main() {
    ll p, k;
    scanf("%lld%lld", &p, &k);

    if (k == 0) {
        printf("%lld\n", modPow(p, p - 1));
        return 0;
    }

    if (k == 1) {
        printf("%lld\n", modPow(p, p));
        return 0;
    }

    int cycles = 0;
    for (int i = 1; i < p; ++i) {
        if (visited[i]) continue;
        int current = i;
        while (!visited[current]) {
            visited[current] = true;
            current = (int)((ll)current * k % p);
        }
        ++cycles;
    }

    printf("%lld\n", modPow(p, cycles));
    return 0;
}

