const long long MOD = 1000000007LL;

long long power(long long base, int exp) {
    long long res = 1;
    while (exp) {
        if (exp & 1) res = (res * base) % MOD;
        exp >>= 1;
        base = (base * base) % MOD;
    }
    return res;
}

bool seen[1000005];

int main() {
