    cin >> p >> k;

    if (k == 0) {
        cout << power(p, p - 1) << endl;
        return 0;
    }

    if (k == 1) {
        cout << power(p, p) << endl;
        return 0;
    }

    int cycleCount = 0;
    for (int i = 1; i < p; i++) {
        if (seen[i]) continue;
        int cur = i;
        while (!seen[cur]) {
            seen[cur] = true;
            cur = (int)((long long)cur * k % p);
        }
        cycleCount++;
    }

    cout << power(p, cycleCount) << endl;
    return 0;
}

