using namespace std;

const long long MOD = 1000000007;

long long mod_exp(long long base, int exponent) {
    long long result = 1;
    while (exponent) {
        if (exponent & 1) {
            result = (result * base) % MOD;
        }
        exponent >>= 1;
        base = (base * base) % MOD;
    }
    return result;
}

bool marked[1000005];

int main() {
    long long p, k;
    scanf("%lld %lld", &p, &k);

    if (k == 0) {
        printf("%lld\n", mod_exp(p, p - 1));
        return 0;
    }

    if (k == 1) {
        printf("%lld\n", mod_exp(p, p));
        return 0;
    }

    int component_count = 0;
    memset(marked, 0, sizeof(marked));

    for (int start = 1; start < p; ++start) {
        if (marked[start]) continue;
        int node = start;
        while (!marked[node]) {
            marked[node] = true;
            node = (int)((long long)node * k % p);
        }
        ++component_count;
    }

    printf("%lld\n", mod_exp(p, component_count));
    return 0;
}

