using namespace std;

using ll = long long;
const ll MOD = 1000000007;

ll binpow(ll a, int b) {
    ll res = 1;
    while (b > 0) {
        if (b & 1) res = (res * a) % MOD;
        b >>= 1;
        a = (a * a) % MOD;
    }
    return res;
}

int main() {
    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << binpow(p, p - 1) << '\n';
        return 0;
    }

    if (k == 1) {
        cout << binpow(p, p) << '\n';
        return 0;
    }

    vector<bool> visited(p, false);
    int num_cycles = 0;

    for (int i = 1; i < p; ++i) {
        if (visited[i]) continue;
        int j = i;
        while (!visited[j]) {
            visited[j] = true;
            j = (int)((ll)j * k % p);
        }
        ++num_cycles;
    }

    cout << binpow(p, num_cycles) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using lli = long long int;
constexpr lli MOD = 1000000007;

lli mpow(lli b, int e) {
    lli r = 1;
    for (; e; e >>= 1, b = b * b % MOD)
        if (e & 1) r = r * b % MOD;
    return r;
}

int main() {
    lli p, k;
    scanf("%lld %lld", &p, &k);

    if (k == 0) {
        printf("%lld\n", mpow(p, p - 1));
        return 0;
    }

    if (k == 1) {
        printf("%lld\n", mpow(p, p));
        return 0;
    }

    vector<char> seen(p, 0);
    int groups = 0;

    for (int x = 1; x < p; ++x) {
        if (seen[x]) continue;
        int y = x;
        do {
            seen[y] = 1;
            y = (int)((lli)y * k % p);
        } while (!seen[y]);
        ++groups;
    }

    printf("%lld\n", mpow(p, groups));
    return 0;
}

