    arr.reserve(n);
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        arr.push_back(x);
    }
    int t;
    cin >> t;

    sort(arr.begin(), arr.end());

    int maxLen = 0;
    for (int start = 0; start < n; start++) {
        int remaining = t;
        int len = 0;
        for (int i = start; i < n; i++) {
            if (i == start) {
                len = 1;
                remaining -= 0;
            } else {
                int diff = arr[i] - arr[i-1];
                if (remaining < diff) break;
                remaining -= diff;
                len++;
            }
        }
        if (len > maxLen) maxLen = len;
    }

    cout << maxLen << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int solve(const vector<int>& a, int T) {
    int best = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        int rem = T;
        int cnt = 0;
        for (size_t j = i; j < a.size(); ++j) {
            if (j == i) {
                cnt = 1;
            } else {
                int gap = a[j] - a[j-1];
                if (gap > rem) break;
                rem -= gap;
                cnt++;
            }
        }
        if (cnt > best) best = cnt;
    }
    return best;
}

int main() {
    int n;
    cin >> n;
    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
    }
    int t;
    cin >> t;

    sort(arr.begin(), arr.end());

    cout << solve(arr, t) << endl;
    return 0;
}

