	for (int i = 2; i < n*n+2; ++i)
		printf("cap to %d is %d\n", i-2, cap[i][1]);*/
	printf("%d\n", edmondsKarp(2+n*n+n*n, 0, 1));
}

#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

const int NN = 202;
const int INF = 0x3f3f3f3f;

int flow[NN][NN], cap[NN][NN], pre[NN], que[NN], d[NN];

int edmondsKarp(int n, int source, int sink) {
    int p, q, t, i, j;
    while (true) {
        memset(pre, -1, sizeof(pre));
        d[source] = INF;
        p = q = 0;
        que[q++] = source;
        while (p < q && pre[sink] < 0) {
            t = que[p++];
            for (i = 0; i < n; ++i) {
                if (pre[i] < 0 && (j = cap[t][i] - flow[t][i]) > 0) {
                    pre[que[q++] = i] = t;
                    d[i] = min(d[t], j);
                }
            }
        }
        if (pre[sink] < 0) break;
        for (i = sink; i != source; i = pre[i]) {
            flow[pre[i]][i] += d[sink];
            flow[i][pre[i]] -= d[sink];
        }
    }
    int total = 0;
    for (i = 0; i < n; ++i) total += flow[source][i];
    return total;
}

