            }
        }
    }
    int zIdx = Zr*N + Zc;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            char c = GridIn[i][j];
            if (c >= '1' && c <= '9') {
                int idx = i*N + j;
                EdgeCap[0][idx + 2] = c - '0';
                for (int k = 0; k < SRows.size(); ++k) {
                    int r = SRows[k], c = SCols[k];
                    int qidx = r*N + c;
                    if (DistGrid[idx][qidx] < Infinite)
