                                add_connection(node_id[0][r][c], node_id[1][rr][cc], LARGE_VALUE);
                        }
                    }
                }
            }
        }
    }

    cout << compute_max_flow() << '\n';
}

#include <bits/stdc++.h>

using namespace std;

using PI = pair<int,int>;

const int MAX_SIZE = 11;
const int MAX_VERTICES = 1000;
const int MAX_ARCS = 100100;
const int BIG_NUMBER = (1<<29);

struct Arrow {
    int to;
    int f;
    int c;
    int nxt;
};

Arrow arcs[2*MAX_ARCS];
int adj_list[MAX_VERTICES], adj_iter[MAX_VERTICES], depth[MAX_VERTICES], dq_buf[MAX_VERTICES];
int total_arcs, vertex_count, src, dst, dq_tail, dq_head;

void net_init(int V, int s, int d){
    vertex_count=V; src=s; dst=d; total_arcs=2;
    fill(adj_list, adj_list+V+1, 0);
}
void connect(int u, int v, int cap){
    arcs[total_arcs]={v,0,cap,adj_list[u]};
    adj_list[u]=total_arcs++;
    arcs[total_arcs]={u,0,0,adj_list[v]};
    adj_list[v]=total_arcs++;
}
bool make_level(){
    fill(depth, depth+vertex_count+1, 0);
    dq_tail=dq_head=0;
    dq_buf[dq_tail++]=src;
    depth[src]=1;
    while(dq_head<dq_tail && !depth[dst]){
        int u=dq_buf[dq_head++];
        for(int e=adj_list[u]; e; e=arcs[e].nxt){
            int v=arcs[e].to;
            if(!depth[v] && arcs[e].f<arcs[e].c){
                depth[v]=depth[u]+1;
                dq_buf[dq_tail++]=v;
            }
        }
    }
    return depth[dst];
}
int push(int u, int cap){
    if(u==dst) return cap;
    for(int& e=adj_iter[u]; e; e=adj_iter[u]=arcs[e].nxt){
        int v=arcs[e].to;
        if(depth[u]<depth[v] && arcs[e].f<arcs[e].c &&
           (cap = push(v, min(cap, arcs[e].c - arcs[e].f)))){
            arcs[e].f += cap;
            arcs[e^1].f -= cap;
            return cap;
        }
    }
    return 0;
}
int flow(){
    int ans=0, del;
    while(make_level()){
        copy(adj_list, adj_list+vertex_count+1, adj_iter);
        while((del = push(src, BIG_NUMBER))) ans += del;
    }
    return ans;
}

int N;
string map1[MAX_SIZE];
string map2[MAX_SIZE];

int di[4] = {0,1,0,-1};
int dj[4] = {1,0,-1,0};

bool ok(int i, int j){
    return i>=0 && j>=0 && i<N && j<N && map1[i][j]!='Y' && map1[i][j]!='Z';
}

int dists[2][MAX_SIZE][MAX_SIZE];

void spread(int si, int sj, int which){
    fill(dists[which][0], dists[which][0]+MAX_SIZE*MAX_SIZE, 0);
    dists[which][si][sj]=1;
    queue<PI> q;
    q.emplace(si,sj);
    while(!q.empty()){
        auto [i,j]=q.front(); q.pop();
        if(which==1 && dists[0][i][j] && dists[0][i][j]<=dists[1][i][j]) continue;
        for(int k=0; k<4; ++k){
            int ni=i+di[k], nj=j+dj[k];
            if(ok(ni,nj) && !dists[which][ni][nj]){
                dists[which][ni][nj]=dists[which][i][j]+1;
                q.emplace(ni,nj);
            }
        }
    }
}

int vert[2][MAX_SIZE][MAX_SIZE];

int main(){
    ios::sync_with_stdio(0); cin.tie(0);

    int Tmax; cin >> N >> Tmax;

    int zr=0, zc=0;
    int cnt=0, s=0, t=0;

    for(int i=0; i<N; ++i){
        cin >> map1[i];
        for(int j=0; j<N; ++j){
            if(map1[i][j]=='Z'){ zr=i; zc=j; }
            else if(map1[i][j]!='Y'){ cnt++; vert[0][i][j]=cnt; }
        }
    }
    for(int i=0; i<N; ++i){
        cin >> map2[i];
        for(int j=0; j<N; ++j){
            if(map2[i][j]!='Y' && map2[i][j]!='Z'){ cnt++; vert[1][i][j]=cnt; }
        }
    }

    cnt++; s=0; t=cnt;
    net_init(cnt, s, t);

    for(int i=0; i<N; ++i){
        for(int j=0; j<N; ++j){
            if(map1[i][j]!='Z' && map1[i][j]!='Y'){
                connect(s, vert[0][i][j], map1[i][j]-'0');
                connect(vert[1][i][j], t, map2[i][j]-'0');
            }
        }
    }

    spread(zr, zc, 0);

    for(int i=0; i<N; ++i){
        for(int j=0; j<N; ++j){
            if(map1[i][j]>'0' && map1[i][j]<='9'){
                spread(i, j, 1);
                for(int ii=0; ii<N; ++ii){
                    for(int jj=0; jj<N; ++jj){
                        if(map2[ii][jj]>'0' && map2[ii][jj]<='9'){
                            if(dists[1][ii][jj] && (!dists[0][ii][jj] || dists[0][ii][jj]>=dists[1][ii][jj]) && dists[1][ii][jj]-1<=Tmax)
                                connect(vert[0][i][j], vert[1][ii][jj], BIG_NUMBER);
                        }
                    }
                }
            }
        }
    }

    cout << flow() << '\n';
}

#include <bits/stdc++.h>

using namespace std;

using ii = pair<int,int>;

constexpr int MAX_D = 11;
constexpr int MAX_N = 1000;
constexpr int MAX_E = 100100;
constexpr int MAX_FLOW_VAL = (1<<29);

struct Edge {
    int v;
    int f;
    int c;
    int next;
};

Edge E[2 * MAX_E];
int head[MAX_N], ptr[MAX_N], lvl[MAX_N], Q[MAX_N];
int num_edges, num_nodes, source, sink, qf, qb;

inline void init_graph(int n, int s, int d) {
    num_nodes = n;
    source = s;
    sink = d;
    num_edges = 2;
    memset(head, 0, sizeof(int) * (n + 1));
}

inline void add_edge(int u, int v, int cap) {
    E[num_edges] = {v, 0, cap, head[u]};
    head[u] = num_edges++;
    E[num_edges] = {u, 0, 0, head[v]};
    head[v] = num_edges++;
}

inline bool bfs_level() {
    memset(lvl, 0, sizeof(int) * (num_nodes + 1));
    qf = qb = 0;
    Q[qb++] = source;
    lvl[source] = 1;
    while (qf < qb && !lvl[sink]) {
        int u = Q[qf++];
        for (int e = head[u]; e; e = E[e].next) {
            int v = E[e].v;
            if (!lvl[v] && E[e].f < E[e].c) {
                lvl[v] = lvl[u] + 1;
                Q[qb++] = v;
            }
        }
    }
    return lvl[sink];
}

inline int dfs(int u, int f) {
    if (u == sink) return f;
    for (int &e = ptr[u]; e; e = ptr[u] = E[e].next) {
        int v = E[e].v;
        if (lvl[u] < lvl[v] && E[e].f < E[e].c &&
            (f = dfs(v, min(f, E[e].c - E[e].f)))) {
            E[e].f += f;
            E[e ^ 1].f -= f;
            return f;
        }
    }
    return 0;
}

inline int dinic() {
    int ret = 0, df;
    while (bfs_level()) {
        copy(head, head + num_nodes + 1, ptr);
        while ((df = dfs(source, MAX_FLOW_VAL))) ret += df;
    }
    return ret;
}

int R;
string B1[MAX_D], B2[MAX_D];

int DR[4] = {0, 1, 0, -1};
int DC[4] = {1, 0, -1, 0};

inline bool valid(int i, int j) {
    return i >= 0 && j >= 0 && i < R && j < R && B1[i][j] != 'Y' && B1[i][j] != 'Z';
}

int d[2][MAX_D][MAX_D];

inline void bfs_dist(int si, int sj, int idx) {
    memset(d[idx], 0, sizeof(d[idx]));
    d[idx][si][sj] = 1;
    queue<ii> q;
    q.push({si, sj});
    while (!q.empty()) {
        auto [i, j] = q.front(); q.pop();
        if (idx == 1 && d[0][i][j] && d[0][i][j] <= d[1][i][j]) continue;
        for (int k = 0; k < 4; ++k) {
            int ni = i + DR[k], nj = j + DC[k];
            if (valid(ni, nj) && !d[idx][ni][nj]) {
                d[idx][ni][nj] = d[idx][i][j] + 1;
                q.push({ni, nj});
            }
        }
    }
}

int id[2][MAX_D][MAX_D];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; cin >> R >> T;

    int zi = 0, zj = 0;
    int node_cnt = 0;

    for (int i = 0; i < R; ++i) {
        cin >> B1[i];
        for (int j = 0; j < R; ++j) {
            if (B1[i][j] == 'Z') { zi = i; zj = j; }
            else if (B1[i][j] != 'Y') {
                node_cnt++;
                id[0][i][j] = node_cnt;
            }
        }
    }

    for (int i = 0; i < R; ++i) {
        cin >> B2[i];
        for (int j = 0; j < R; ++j) {
            if (B2[i][j] != 'Y' && B2[i][j] != 'Z') {
                node_cnt++;
                id[1][i][j] = node_cnt;
            }
        }
    }

    node_cnt++;
    int src = 0, dst = node_cnt;

    init_graph(node_cnt, src, dst);

    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < R; ++j) {
            if (B1[i][j] != 'Z' && B1[i][j] != 'Y') {
                add_edge(src, id[0][i][j], B1[i][j] - '0');
                add_edge(id[1][i][j], dst, B2[i][j] - '0');
            }
        }
    }

    bfs_dist(zi, zj, 0);

    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < R; ++j) {
            if (B1[i][j] > '0' && B1[i][j] <= '9') {
                bfs_dist(i, j, 1);
                for (int ii = 0; ii < R; ++ii) {
                    for (int jj = 0; jj < R; ++jj) {
                        if (B2[ii][jj] > '0' && B2[ii][jj] <= '9') {
                            if (d[1][ii][jj] &&
                                (!d[0][ii][jj] || d[0][ii][jj] >= d[1][ii][jj]) &&
                                d[1][ii][jj] - 1 <= T) {
                                add_edge(id[0][i][j], id[1][ii][jj], MAX_FLOW_VAL);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << dinic() << '\n';
}

#include <iostream>
