    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridB[i][j] != 'Z' && gridB[i][j] != 'Y' && gridB[i][j] != '0')
                sinkPoints.emplace_back(i, j);

    int M = sourcePoints.size() + sinkPoints.size() + 2;
    dinic flow(M, 0, M - 1);

    for (int i = 0; i < sourcePoints.size(); ++i) {
        i64 capacity = gridA[sourcePoints[i].first][sourcePoints[i].second] - '0';
        flow.link(0, i + 1, capacity);
    }
    for (int i = 0; i < sinkPoints.size(); ++i) {
        i64 capacity = gridB[sinkPoints[i].first][sinkPoints[i].second] - '0';
        flow.link(sourcePoints.size() + 1 + i, M - 1, capacity);
    }

    for (int i = 0; i < sourcePoints.size(); ++i)
        for (int j = 0; j < sinkPoints.size(); ++j)
            if (can_attain(0, sourcePoints[i].first, sourcePoints[i].second, sinkPoints[j].first, sinkPoints[j].second))
                flow.link(i + 1, sourcePoints.size() + 1 + j, 10000000LL);

    cout << flow.ford_fulkerson() << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <climits>
#include <array>
using namespace std;

using i64 = long long;
using pii = pair<int, int>;

constexpr int dirX[4] = { -1, 1, 0, 0 };
constexpr int dirY[4] = { 0, 0, -1, 1 };

struct edg {
    int src;
    int dst;
    i64 limit;
    i64 used;
    edg(int a, int b, i64 c) : src(a), dst(b), limit(c), used(0) {}
};

class maxflow {
public:
    const i64 big = 1000000000000000000LL;
    int vertexCount;
    int srcNode;
    int dstNode;
    vector<edg> edgeList;
    vector<vector<int>> neighborList;
    vector<int> depth;
    vector<int> iter;
    queue<int> bfsQueue;

    maxflow(int v, int s, int t) : vertexCount(v), srcNode(s), dstNode(t) {
        neighborList.resize(v);
        depth.resize(v);
        iter.resize(v);
    }

    void addConnection(int u, int v, i64 cap) {
        edgeList.emplace_back(u, v, cap);
        edgeList.emplace_back(v, u, 0);
        neighborList[u].push_back(edgeList.size() - 2);
        neighborList[v].push_back(edgeList.size() - 1);
    }

    bool levelGraph() {
        fill(depth.begin(), depth.end(), -1);
        depth[srcNode] = 0;
        bfsQueue.push(srcNode);
        while (!bfsQueue.empty()) {
            int u = bfsQueue.front(); bfsQueue.pop();
            for (int id : neighborList[u]) {
                auto& e = edgeList[id];
                if (e.limit - e.used > 0 && depth[e.dst] == -1) {
                    depth[e.dst] = depth[u] + 1;
                    bfsQueue.push(e.dst);
                }
            }
        }
        return depth[dstNode] != -1;
    }

    i64 sendFlow(int v, i64 flowSoFar) {
        if (v == dstNode) return flowSoFar;
        for (int& i = iter[v]; i < (int)neighborList[v].size(); ++i) {
            int id = neighborList[v][i];
            auto& e = edgeList[id];
            if (depth[e.dst] == depth[v] + 1 && e.limit - e.used > 0) {
                i64 flow = sendFlow(e.dst, min(flowSoFar, e.limit - e.used));
                if (flow > 0) {
                    e.used += flow;
                    edgeList[id ^ 1].used -= flow;
                    return flow;
                }
            }
        }
        return 0;
    }

    i64 computeMaxFlow() {
        i64 result = 0;
        while (levelGraph()) {
            fill(iter.begin(), iter.end(), 0);
            i64 pushed;
            while ((pushed = sendFlow(srcNode, big)) > 0) {
                result += pushed;
            }
        }
        return result;
    }
};

int gridSize, timeBound;
string land[15];
string demand[15];
int shortestTime[15][15];

bool withinBounds(int r, int c) {
    return r >= 0 && r < gridSize && c >= 0 && c < gridSize && land[r][c] != 'Y' && land[r][c] != 'Z';
}

void expandFromZ(int startX, int startY) {
    memset(shortestTime, -1, sizeof(shortestTime));
    queue<pii> q;
    q.push({startX, startY});
    shortestTime[startX][startY] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dirX[k], ny = y + dirY[k];
            if (withinBounds(nx, ny) && shortestTime[nx][ny] == -1) {
                shortestTime[nx][ny] = shortestTime[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            if (shortestTime[i][j] == -1) shortestTime[i][j] = 1000000000;
}

int cache[65][12][12][12][12];
bool precomputed[65][12][12][12][12];

bool pathExists(int step, int r1, int c1, int r2, int c2) {
    if (shortestTime[r1][c1] < step) return false;
    if (r1 == r2 && c1 == c2) return true;
    if (step >= timeBound) return false;
    if (shortestTime[r1][c1] <= step) return false;
    if (precomputed[step][r1][c1][r2][c2]) return cache[step][r1][c1][r2][c2];
    precomputed[step][r1][c1][r2][c2] = true;
    for (int d = 0; d < 4; ++d) {
        int nr = r1 + dirX[d], nc = c1 + dirY[d];
        if (nr < 0 || nr >= gridSize || nc < 0 || nc >= gridSize) continue;
        if (land[nr][nc] == 'Y' || land[nr][nc] == 'Z') continue;
        if (pathExists(step + 1, nr, nc, r2, c2)) {
            cache[step][r1][c1][r2][c2] = 1;
            return true;
        }
    }
    cache[step][r1][c1][r2][c2] = 0;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    memset(cache, -1, sizeof(cache));
    cin >> gridSize >> timeBound;
    for (int i = 0; i < gridSize; ++i) cin >> land[i];
    for (int i = 0; i < gridSize; ++i) cin >> demand[i];

    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (land[i][j] == 'Z') {
                expandFromZ(i, j);
                goto nextStep;
            }
        }
    }
nextStep:

    vector<pii> supply, capacity;
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            if (land[i][j] != 'Z' && land[i][j] != 'Y' && land[i][j] != '0')
                supply.push_back({i, j});
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            if (demand[i][j] != 'Z' && demand[i][j] != 'Y' && demand[i][j] != '0')
                capacity.push_back({i, j});

    int nodeCount = supply.size() + capacity.size() + 2;
    maxflow solver(nodeCount, 0, nodeCount - 1);

    for (int i = 0; i < supply.size(); ++i) {
        i64 val = land[supply[i].first][supply[i].second] - '0';
        solver.addConnection(0, i + 1, val);
    }
    for (int i = 0; i < capacity.size(); ++i) {
        i64 val = demand[capacity[i].first][capacity[i].second] - '0';
        solver.addConnection(supply.size() + 1 + i, nodeCount - 1, val);
    }

    for (int i = 0; i < supply.size(); ++i)
        for (int j = 0; j < capacity.size(); ++j)
            if (pathExists(0, supply[i].first, supply[i].second, capacity[j].first, capacity[j].second))
                solver.addConnection(i + 1, supply.size() + 1 + j, 10000000LL);

    cout << solver.computeMaxFlow() << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using lint = long long;
using PII = pair<int, int>;

const int DX[4] = {0, 0, 1, -1};
const int DY[4] = {1, -1, 0, 0};

struct MaxFlow {
    struct Edge {
        int to, rev;
        lint cap;
        Edge(int t, int r, lint c) : to(t), rev(r), cap(c) {}
    };

    int N, S, T;
    vector<vector<Edge>> g;
    vector<int> level, iter;
    queue<int> q;

    MaxFlow(int n, int s, int t) : N(n), S(s), T(t) {
        g.resize(n);
        level.resize(n);
        iter.resize(n);
    }

    void add_edge(int u, int v, lint c) {
        g[u].emplace_back(v, g[v].size(), c);
        g[v].emplace_back(u, g[u].size() - 1, 0);
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[S] = 0;
        q.push(S);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : g[u]) {
                if (e.cap > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[T] != -1;
    }

    lint dfs(int u, lint f) {
        if (u == T) return f;
        for (int& i = iter[u]; i < (int)g[u].size(); ++i) {
            auto& e = g[u][i];
            if (e.cap > 0 && level[e.to] == level[u] + 1) {
                lint pushed = dfs(e.to, min(f, e.cap));
                if (pushed > 0) {
                    e.cap -= pushed;
                    g[e.to][e.rev].cap += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    lint flow() {
        lint res = 0;
        while (bfs()) {
            fill(iter.begin(), iter.end(), 0);
            lint f;
            while ((f = dfs(S, 1LL << 60)) > 0) res += f;
        }
        return res;
    }
};

int N, T;
string gridA[15], gridB[15];
int dist[15][15];

bool in_bounds(int x, int y) {
    return x >= 0 && x < N && y >= 0 && y < N && gridA[x][y] != 'Y' && gridA[x][y] != 'Z';
}

void multi_source_bfs(int sx, int sy) {
    memset(dist, -1, sizeof(dist));
    queue<PII> qu;
    qu.push({sx, sy});
    dist[sx][sy] = 0;
    while (!qu.empty()) {
        auto [x, y] = qu.front(); qu.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + DX[k], ny = y + DY[k];
            if (in_bounds(nx, ny) && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                qu.push({nx, ny});
            }
        }
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (dist[i][j] == -1) dist[i][j] = 1000000000;
}

int memo_dp[65][12][12][12][12];
bool memo_set[65][12][12][12][12];

bool can_reach(int t, int x0, int y0, int x1, int y1) {
    if (dist[x0][y0] < t) return false;
    if (x0 == x1 && y0 == y1) return true;
    if (t >= T) return false;
    if (dist[x0][y0] <= t) return false;
    if (memo_set[t][x0][y0][x1][y1]) return memo_dp[t][x0][y0][x1][y1];
    memo_set[t][x0][y0][x1][y1] = true;
    for (int d = 0; d < 4; ++d) {
        int nx = x0 + DX[d], ny = y0 + DY[d];
        if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
        if (gridA[nx][ny] == 'Y' || gridA[nx][ny] == 'Z') continue;
        if (can_reach(t + 1, nx, ny, x1, y1)) {
            memo_dp[t][x0][y0][x1][y1] = 1;
            return true;
        }
    }
    memo_dp[t][x0][y0][x1][y1] = 0;
    return false;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    memset(memo_dp, -1, sizeof(memo_dp));
    cin >> N >> T;
    for (int i = 0; i < N; ++i) cin >> gridA[i];
    for (int i = 0; i < N; ++i) cin >> gridB[i];

    bool found_z = false;
    for (int i = 0; i < N && !found_z; ++i) {
        for (int j = 0; j < N && !found_z; ++j) {
            if (gridA[i][j] == 'Z') {
                multi_source_bfs(i, j);
                found_z = true;
            }
        }
    }

    vector<PII> src, dst;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (gridA[i][j] != 'Z' && gridA[i][j] != 'Y' && gridA[i][j] != '0')
                src.emplace_back(i, j);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (gridB[i][j] != 'Z' && gridB[i][j] != 'Y' && gridB[i][j] != '0')
                dst.emplace_back(i, j);

    int V = src.size() + dst.size() + 2;
    MaxFlow mf(V, 0, V - 1);

    for (int i = 0; i < src.size(); ++i) {
        lint c = gridA[src[i].first][src[i].second] - '0';
        mf.add_edge(0, i + 1, c);
    }
    for (int i = 0; i < dst.size(); ++i) {
        lint c = gridB[dst[i].first][dst[i].second] - '0';
        mf.add_edge(src.size() + 1 + i, V - 1, c);
    }

    for (int i = 0; i < src.size(); ++i)
        for (int j = 0; j < dst.size(); ++j)
            if (can_reach(0, src[i].first, src[i].second, dst[j].first, dst[j].second))
                mf.add_edge(i + 1, src.size() + 1 + j, 10000000LL);

    cout << mf.flow() << '\n';
    return 0;
}

