const int MAXN = 300;
const int INF = 1e9;

struct edge{
    int to, rev, f, cap;
    edge(int to, int rev, int f, int cap) : to(to), rev(rev), f(f), cap(cap) {}
};
vector<edge> adj[MAXN];

void add_edge(int u, int v, int c, int rc = 0) {
    edge a(v, adj[v].size(), 0, c);
    edge b(u, adj[u].size(), 0, rc);
    adj[u].push_back(a);
    adj[v].push_back(b);
}

int dis[MAXN], ptr[MAXN], src, dst;

bool bfs() {
    memset(dis, -1, sizeof dis);
    dis[src] = 0;
    queue<int> q({src});
    while(q.size() && dis[dst] == -1) {
        int u = q.front(); q.pop();
        for(auto e : adj[u]) {
            int v = e.to;
            if(dis[v]==-1 && e.f < e.cap) {
                dis[v] = dis[u] + 1;
                q.push(v);
            }
        }
    }
    return dis[dst] != -1;
}

int dfs(int u, int f) {
    if(u == dst || !f)
           return f;
    for(int &i = ptr[u]; i < adj[u].size(); i++){
        edge &e = adj[u][i];
        int v = e.to;
        if(dis[v] != dis[u] + 1)
                continue;
        if(int df = dfs(v, min(f, e.cap - e.f))) {
            e.f += df;
            adj[v][e.rev].f -= df;
            return df;
        }
    }
    return 0;
}

int mf() {
    int res = 0;
    while(bfs()) {
        memset(ptr, 0, sizeof ptr);
        while(int df = dfs(src, INF))
            res += df;
    }
    return res;
}

