        }
    }

    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            connect(node_id(i,j), node_id(i,j)+N*N, INF);
            if (grid2[i][j]>='1' && grid2[i][j]<='9') {
                connect(node_id(i,j)+N*N, sink_node, grid2[i][j]-'0');
            }
        }
    }

    compute_times();
    for (int i=1; i<=N; ++i) {
        for (int j=1; j<=N; ++j) {
            if (grid1[i][j]>='1' && grid1[i][j]<='9') {
                explore_from(i,j);
            }
        }
    }

    cout << compute_maxflow() << '\n';
    return 0;
}

#include <iostream>
#include <cstring>
#include <queue>
#include <algorithm>
