};

struct DinicMaxFlow {
    int s, t;
    vector<Edge> e;
    vector<int> g[MAX_N];
    int d[MAX_N], p[MAX_N];

    void clear() {
        e.clear();
        for (int i = 0; i < MAX_N; ++i) g[i].clear();
    }

    void add(int u, int v, ll cap) {
        e.push_back({u, v, 0, cap});
        e.push_back({v, u, 0, 0});
        g[u].push_back(e.size() - 2);
        g[v].push_back(e.size() - 1);
    }

    bool bfs() {
        fill(d, d + MAX_N, -1);
        queue<int> q;
        q.push(s);
        d[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : g[u]) {
                Edge& ed = e[id];
                if (d[ed.v] == -1 && ed.c > ed.f) {
                    d[ed.v] = d[u] + 1;
                    q.push(ed.v);
                }
            }
        }
        return d[t] != -1;
    }

    ll dfs(int u, ll f) {
        if (u == t || f == 0) return f;
        for (int& i = p[u]; i < (int)g[u].size(); ++i) {
            int id = g[u][i];
            Edge& ed = e[id];
            if (d[ed.v] == d[u] + 1 && ed.c > ed.f) {
                ll pushed = dfs(ed.v, min(f, ed.c - ed.f));
                if (pushed > 0) {
                    ed.f += pushed;
                    e[id ^ 1].f -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll maxflow() {
        ll res = 0;
        while (bfs()) {
            fill(p, p + MAX_N, 0);
            while (ll pushed = dfs(s, INF)) {
                res += pushed;
            }
        }
        return res;
    }
};

