        for (int v : adjList[u]) {
            if (visited[v]) continue;
            visited[v] = true;
            if (rightMatch[v] == -1 || augment(rightMatch[v], adjList)) {
                leftMatch[u] = v;
                rightMatch[v] = u;
                return true;
            }
        }
        return false;
    }
};

