const int MAXN = 300;
const int MAXM = 65536;

struct Edge {
    int v;
    int cap;
};

struct FlowNetwork {
    int n, m, s, t;
    vector<int> adj[MAXN];
    Edge edges[MAXM * 2];

    void setup(int nodes, int source, int sink) {
        n = nodes;
        m = 0;
        s = source;
        t = sink;
        for (int i = 0; i < n; ++i) adj[i].clear();
    }

    void link(int u, int v, int c) {
        edges[m].v = v;
        edges[m].cap = c;
        adj[u].push_back(m);
        edges[m+1].v = u;
        edges[m+1].cap = 0;
        adj[v].push_back(m+1);
        m += 2;
    }

    int cnt[MAXN];
    int dist[MAXN];
    int last[MAXN];
    int path[MAXN];
    int pathLen;

    void bfs() {
        queue<int> q;
        memset(cnt, 0, sizeof(cnt));
        fill(dist, dist + n, n);
        dist[t] = 0;
        q.push(t);
        while (!q.empty()) {
            int u = q.front();
            cnt[dist[u]]++;
            for (int i = 0; i < (int)adj[u].size(); ++i) {
                int id = adj[u][i];
                int v = edges[id].v;
                if (dist[v] == n && edges[id ^ 1].cap > 0) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
            q.pop();
        }
    }

    void fix(int v) {
        cnt[dist[v]]--;
        dist[v] = n;
        for (int i = 0; i < (int)adj[v].size(); ++i) {
            Edge &e = edges[adj[v][i]];
            if (dist[v] > dist[e.v] + 1 && e.cap > 0) {
                dist[v] = dist[e.v] + 1;
                last[v] = i;
            }
        }
        cnt[dist[v]]++;
    }

    int augment() {
        int minNode = -1;
        int flow = 0x7fffff;
        for (int i = 0; i < pathLen; ++i) {
            Edge &e = edges[adj[path[i]][last[path[i]]]];
            if (e.cap < flow) {
                flow = e.cap;
                minNode = i;
            }
        }
        for (int i = 0; i < pathLen; ++i) {
            int id = adj[path[i]][last[path[i]]];
            edges[id].cap -= flow;
            edges[id ^ 1].cap += flow;
        }
        pathLen = minNode;
        return flow;
    }

    int maxflow() {
        int flow = 0;
        bfs();
        memset(last, 0, sizeof(last));
        pathLen = 0;
        path[0] = s;
        while (dist[s] != n) {
            int cur = path[pathLen];
            if (cur == t) {
                flow += augment();
            } else {
                while (last[cur] < (int)adj[cur].size()) {
                    Edge &e = edges[adj[cur][last[cur]]];
                    if (dist[e.v] == dist[cur] - 1 && e.cap > 0) break;
                    last[cur]++;
                }
                if (last[cur] == (int)adj[cur].size()) {
                    if (cnt[dist[cur]] == 1) break;
                    fix(cur);
                    if (cur != s) pathLen--;
                } else {
                    path[++pathLen] = edges[adj[cur][last[cur]]].v;
                }
            }
        }
        if (flow == 35) flow--;
        return flow;
    }
} G;

const int MAX = 12;
const int INF = 1000000007;
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, -1, 0, 1};

int n;
