#include <iostream>
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <climits>
#include <queue>
using namespace std;

const int INF = 10000000;
const int MAX_SIZE = 12;
const int MAX_STEPS = 62;
const int MAX_NODES = 210;
const int MAX_EDGES = 21000;

typedef struct {
    int to, cap;
} Edge;

Edge graph[MAX_EDGES];
int first_edge[MAX_NODES], edge_index = 0;

void insertEdge(int from, int to, int capacity) {
    graph[edge_index].to = to;
    graph[edge_index].cap = capacity;
    graph[edge_index].next = first_edge[from];
    first_edge[from] = edge_index++;

    graph[edge_index].to = from;
    graph[edge_index].cap = 0;
    graph[edge_index].next = first_edge[to];
    first_edge[to] = edge_index++;
}

int distance[MAX_NODES], queue_buffer[MAX_NODES * 2], arc_idx[MAX_NODES], gap_count[MAX_NODES], in_queue[MAX_NODES], parent_node[MAX_NODES];

int maxFlow(int source, int sink) {
    memset(arc_idx, -1, sizeof(arc_idx));
    memset(parent_node, -1, sizeof(parent_node));
    int queue_front = 0, queue_rear = 0;
    queue_buffer[queue_rear++] = sink;
    in_queue[sink] = 1;
    gap_count[0]++;
    distance[sink] = 0;

    while (queue_front < queue_rear) {
        int current = queue_buffer[queue_front++];
        for (int i = first_edge[current]; i != -1; i = graph[i].next) {
            int neighbor = graph[i].to;
            if (!in_queue[neighbor]) {
                queue_buffer[queue_rear++] = neighbor;
                in_queue[neighbor] = 1;
                distance[neighbor] = distance[current] + 1;
                gap_count[distance[neighbor]]++;
                arc_idx[neighbor] = first_edge[neighbor];
            }
        }
    }

    int bottleneck = INF, cur_node = source, max_flow = 0;
    parent_node[source] = source;

    while (distance[source] < sink) {
        bool augment = false;

        for (int& idx = arc_idx[cur_node]; idx != -1; idx = graph[idx].next) {
            if (graph[idx].cap && distance[graph[idx].to] + 1 == distance[cur_node]) {
                augment = true;
                bottleneck = min(bottleneck, graph[idx].cap);
                parent_node[graph[idx].to] = cur_node;
                cur_node = graph[idx].to;

                if (cur_node == sink) {
                    while (cur_node != source) {
                        cur_node = parent_node[cur_node];
                        graph[arc_idx[cur_node]].cap -= bottleneck;
                        graph[arc_idx[cur_node] ^ 1].cap += bottleneck;
                    }
                    max_flow += bottleneck;
                    bottleneck = INF;
                }
                break;
            }
        }

        if (augment) continue;

        int min_dist = sink + 1;
        for (int i = first_edge[cur_node]; i != -1; i = graph[i].next) {
            if (graph[i].cap && min_dist > distance[graph[i].to]) {
                min_dist = distance[graph[i].to];
                arc_idx[cur_node] = i;
            }
        }

        gap_count[distance[cur_node]]--;
        if (gap_count[distance[cur_node]] == 0) return max_flow;
        distance[cur_node] = min_dist + 1;
        gap_count[distance[cur_node]]++;
        cur_node = parent_node[cur_node];
    }

    return max_flow;
}

char input_grid_1[MAX_SIZE][MAX_SIZE], input_grid_2[MAX_SIZE][MAX_SIZE];
int scientific[MAX_SIZE][MAX_SIZE], capacity[MAX_SIZE][MAX_SIZE], stone_states[MAX_STEPS][MAX_SIZE][MAX_SIZE];
int reachable[MAX_STEPS][MAX_SIZE][MAX_SIZE][MAX_SIZE][MAX_SIZE];
int direction[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int size_n, time_limit;

void simulateExpansion() {
    for (int step = 1; step <= time_limit; ++step) {
        for (int row = 1; row <= size_n; ++row) {
            for (int col = 1; col <= size_n; ++col) {
                if (stone_states[step-1][row][col] == 1) {
                    stone_states[step][row][col] = 1;
                } else if (stone_states[step-1][row][col] == 2) {
                    stone_states[step][row][col] = 2;
                } else {
                    for (int d = 0; d < 4; ++d) {
                        int nr = row + direction[d][0];
                        int nc = col + direction[d][1];
                        if (nr >= 1 && nr <= size_n && nc >= 1 && nc <= size_n) {
                            if (stone_states[step-1][nr][nc] == 2) {
                                stone_states[step][row][col] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool visited_state[MAX_SIZE][MAX_SIZE];

void propagate(int start_x, int start_y, int curr_x, int curr_y, int step) {
    visited_state[curr_x][curr_y] = true;
    reachable[step][start_x][start_y][curr_x][curr_y] = 1;

    if (step >= time_limit || stone_states[step][curr_x][curr_y]) return;

    for (int d = 0; d < 4; ++d) {
        int next_x = curr_x + direction[d][0];
        int next_y = curr_y + direction[d][1];
        if (next_x >= 1 && next_x <= size_n && next_y >= 1 && next_y <= size_n && !visited_state[next_x][next_y]) {
            if (stone_states[step][next_x][next_y]) continue;
            propagate(start_x, start_y, next_x, next_y, step + 1);
        }
    }
}

int main() {
    for (int i = 0; i < 100000; ++i) {}
    scanf("%d %d", &size_n, &time_limit);

    for (int i = 1; i <= size_n; ++i) {
        scanf("%s", input_grid_1[i] + 1);
        for (int j = 1; j <= size_n; ++j) {
            if (input_grid_1[i][j] == 'Z') stone_states[0][i][j] = 2;
            else if (input_grid_1[i][j] == 'Y') stone_states[0][i][j] = 1;
            else scientific[i][j] = input_grid_1[i][j] - '0';
        }
    }

    for (int i = 1; i <= size_n; ++i) {
        scanf("%s", input_grid_2[i] + 1);
        for (int j = 1; j <= size_n; ++j) {
            if (input_grid_2[i][j] >= '0' && input_grid_2[i][j] <= '9') {
                capacity[i][j] = input_grid_2[i][j] - '0';
            }
        }
    }

    simulateExpansion();

    for (int i = 1; i <= size_n; ++i) {
        for (int j = 1; j <= size_n; ++j) {
            if (scientific[i][j]) {
                memset(visited_state, 0, sizeof(visited_state));
                propagate(i, j, i, j, 0);
            }
        }
    }

    for (int s = 1; s <= time_limit; ++s) {
        for (int a = 1; a <= size_n; ++a) {
            for (int b = 1; b <= size_n; ++b) {
                for (int c = 1; c <= size_n; ++c) {
                    for (int d = 1; d <= size_n; ++d) {
                        reachable[s][a][b][c][d] += reachable[s-1][a][b][c][d];
                    }
                }
            }
        }
    }

    int source_node = 0, sink_node = size_n * size_n * 2 + 1;
    memset(first_edge, -1, sizeof(first_edge));
    edge_index = 0;

    for (int r = 1; r <= size_n; ++r) {
        for (int c = 1; c <= size_n; ++c) {
            insertEdge(source_node, (r-1)*size_n + c, scientific[r][c]);
        }
    }

    for (int r = 1; r <= size_n; ++r) {
        for (int c = 1; c <= size_n; ++c) {
            insertEdge(size_n*size_n + (r-1)*size_n + c, sink_node, capacity[r][c]);
        }
    }

    for (int x = 1; x <= size_n; ++x) {
        for (int y = 1; y <= size_n; ++y) {
            for (int nx = 1; nx <= size_n; ++nx) {
                for (int ny = 1; ny <= size_n; ++ny) {
                    if (scientific[x][y] && capacity[nx][ny] && reachable[time_limit][x][y][nx][ny]) {
                        insertEdge((x-1)*size_n + y, size_n*size_n + (nx-1)*size_n + ny, INF);
                    }
                }
            }
        }
    }

    printf("%d\n", maxFlow(source_node, sink_node));
    return 0;
}

#include <iostream>
#include <cstring>
#include <climits>
#include <cstdio>
#include <algorithm>
using namespace std;

#define MAX_VAL 10000000
#define MAX_GRID 12
#define MAX_TIME 62
#define MAX_NODE 210
#define MAX_PATH 21000

struct Connection {
    int dest;
    int weight;
};

Connection link[MAX_PATH];
int adj_list[MAX_PATH];
int node_head[MAX_NODE];
int total_links = 0;

inline void connect(int from, int to, int cap) {
    link[total_links] = {to, cap};
    adj_list[total_links] = node_head[from];
    node_head[from] = total_links++;
    link[total_links] = {from, 0};
    adj_list[total_links] = node_head[to];
    node_head[to] = total_links++;
}

int depth[MAX_NODE], fifo[MAX_NODE * 2], pointer[MAX_NODE], bucket[MAX_NODE], queued[MAX_NODE], prev_node[MAX_NODE];

int dinic_max_flow(int s, int t) {
    memset(pointer, -1, sizeof(pointer));
    memset(prev_node, -1, sizeof(prev_node));
    int head = 0, tail = 0;
    fifo[tail++] = t;
    queued[t] = 1;
    bucket[0]++;
    depth[t] = 0;

    while (head < tail) {
        int u = fifo[head++];
        for (int e = node_head[u]; ~e; e = adj_list[e]) {
            int v = link[e].dest;
            if (!queued[v]) {
                fifo[tail++] = v;
                queued[v] = 1;
                depth[v] = depth[u] + 1;
                bucket[depth[v]]++;
                pointer[v] = node_head[v];
            }
        }
    }

    int flow = 0, min_capacity = MAX_VAL;
    int cur = s;
    prev_node[s] = s;

    while (depth[s] < t) {
        bool extended = false;
        for (int &i = pointer[cur]; ~i; i = adj_list[i]) {
            if (link[i].weight && depth[link[i].dest] + 1 == depth[cur]) {
                extended = true;
                min_capacity = min(min_capacity, link[i].weight);
                prev_node[link[i].dest] = cur;
                cur = link[i].dest;
                if (cur == t) {
                    int augment = min_capacity;
                    while (cur != s) {
                        cur = prev_node[cur];
                        link[pointer[cur]].weight -= augment;
                        link[pointer[cur]^1].weight += augment;
                    }
                    flow += augment;
                    min_capacity = MAX_VAL;
                }
                break;
            }
        }

        if (extended) continue;

        int best_dist = t + 1;
        for (int e = node_head[cur]; ~e; e = adj_list[e]) {
            if (link[e].weight && best_dist > depth[link[e].dest]) {
                best_dist = depth[link[e].dest];
                pointer[cur] = e;
            }
        }

        bucket[depth[cur]]--;
        if (!bucket[depth[cur]]) break;
        depth[cur] = best_dist + 1;
        bucket[depth[cur]]++;
        cur = prev_node[cur];
    }

    return flow;
}

char source_map[MAX_GRID][MAX_GRID], target_map[MAX_GRID][MAX_GRID];
int src_val[MAX_GRID][MAX_GRID], tgt_val[MAX_GRID][MAX_GRID], spread[MAX_TIME][MAX_GRID][MAX_GRID];
int path_dp[MAX_TIME][MAX_GRID][MAX_GRID][MAX_GRID][MAX_GRID];
int move_vec[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int grid_size, total_steps;

void process_spread() {
    for (int step = 1; step <= total_steps; step++) {
        for (int r = 1; r <= grid_size; r++) {
            for (int c = 1; c <= grid_size; c++) {
                if (spread[step-1][r][c] == 1) {
                    spread[step][r][c] = 1;
                } else if (spread[step-1][r][c] == 2) {
                    spread[step][r][c] = 2;
                } else {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + move_vec[d][0];
                        int nc = c + move_vec[d][1];
                        if (nr >= 1 && nr <= grid_size && nc >= 1 && nc <= grid_size) {
                            if (spread[step-1][nr][nc] == 2) {
                                spread[step][r][c] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool marked[MAX_GRID][MAX_GRID];

void trace(int sx, int sy, int px, int py, int step) {
    marked[px][py] = true;
    path_dp[step][sx][sy][px][py] = 1;
    if (step >= total_steps || spread[step][px][py]) return;

    for (int d = 0; d < 4; d++) {
        int nx = px + move_vec[d][0];
        int ny = py + move_vec[d][1];
        if (nx >= 1 && nx <= grid_size && ny >= 1 && ny <= grid_size && !marked[nx][ny]) {
            if (spread[step][nx][ny]) continue;
            trace(sx, sy, nx, ny, step + 1);
        }
    }
}

int main() {
    volatile int ignore = 0;
    for (int i = 0; i < 100000; i++) ignore++;

    scanf("%d %d", &grid_size, &total_steps);
    for (int i = 1; i <= grid_size; i++) {
        scanf("%s", source_map[i] + 1);
        for (int j = 1; j <= grid_size; j++) {
            if (source_map[i][j] == 'Z') spread[0][i][j] = 2;
            else if (source_map[i][j] == 'Y') spread[0][i][j] = 1;
            else src_val[i][j] = source_map[i][j] - '0';
        }
    }

    for (int i = 1; i <= grid_size; i++) {
        scanf("%s", target_map[i] + 1);
        for (int j = 1; j <= grid_size; j++) {
            if (target_map[i][j] >= '0' && target_map[i][j] <= '9') {
                tgt_val[i][j] = target_map[i][j] - '0';
            }
        }
    }

    process_spread();

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            if (src_val[i][j]) {
                memset(marked, 0, sizeof(marked));
                trace(i, j, i, j, 0);
            }
        }
    }

    for (int k = 1; k <= total_steps; k++) {
        for (int a = 1; a <= grid_size; a++) {
            for (int b = 1; b <= grid_size; b++) {
                for (int c = 1; c <= grid_size; c++) {
                    for (int d = 1; d <= grid_size; d++) {
                        path_dp[k][a][b][c][d] += path_dp[k-1][a][b][c][d];
                    }
                }
            }
        }
    }

    int src_node = 0, dst_node = grid_size * grid_size * 2 + 1;
    memset(node_head, -1, sizeof(node_head));
    total_links = 0;

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            connect(src_node, (i-1)*grid_size + j, src_val[i][j]);
        }
    }

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            connect(grid_size*grid_size + (i-1)*grid_size + j, dst_node, tgt_val[i][j]);
        }
    }

    for (int x = 1; x <= grid_size; x++) {
        for (int y = 1; y <= grid_size; y++) {
            for (int nx = 1; nx <= grid_size; nx++) {
                for (int ny = 1; ny <= grid_size; ny++) {
                    if (src_val[x][y] && tgt_val[nx][ny] && path_dp[total_steps][x][y][nx][ny]) {
                        connect((x-1)*grid_size + y, grid_size*grid_size + (nx-1)*grid_size + ny, MAX_VAL);
                    }
                }
            }
        }
    }

    printf("%d\n", dinic_max_flow(src_node, dst_node));
    return 0;
}

#include <iostream>
#include <cstdio>
#include <cstring>
#include <algorithm>
#include <queue>
#include <vector>
#include <climits>
using namespace std;

const int MAX_INF = 10000000;
const int GRID_SIZE = 12;
const int TIME_LIMIT = 62;
const int NODE_LIMIT = 210;
const int EDGE_LIMIT = 21000;

struct Edge {
    int target;
    int capacity;
};

vector<Edge> network[EDGE_LIMIT];
int adjacency[NODE_LIMIT], edge_counter = 0;

void add_connection(int from, int to, int cap) {
    network[edge_counter] = {{to, cap}};
    adjacency[edge_counter] = adjacency[from];
    adjacency[from] = edge_counter++;
    network[edge_counter] = {{from, 0}};
    adjacency[edge_counter] = adjacency[to];
    adjacency[to] = edge_counter++;
}

int level[NODE_LIMIT], que[NODE * 2], current_arc[NODE_LIMIT], count_layer[NODE_LIMIT], in_que[NODE_LIMIT], prev_node[NODE_LIMIT];

int dinic_flow(int source, int sink) {
    memset(current_arc, -1, sizeof(current_arc));
    memset(prev_node, -1, sizeof(prev_node));
    int qhead = 0, qtail = 0;
    que[qtail++] = sink;
    in_que[sink] = 1;
    count_layer[0]++;
    level[sink] = 0;

    while (qhead < qtail) {
        int u = que[qhead++];
        for (int idx = adjacency[u]; ~idx; idx = adjacency[idx]) {
            int v = network[idx].target;
            if (!in_que[v]) {
                que[qtail++] = v;
                in_que[v] = 1;
                level[v] = level[u] + 1;
                count_layer[level[v]]++;
                current_arc[v] = adjacency[v];
            }
        }
    }

    int flow = 0, min_edge = MAX_INF;
    int cur_node = source;
    prev_node[source] = source;

    while (level[source] < sink) {
        bool extended = false;
        for (int &arc = current_arc[cur_node]; ~arc; arc = adjacency[arc]) {
            if (network[arc].capacity && level[network[arc].target] + 1 == level[cur_node]) {
                extended = true;
                min_edge = min(min_edge, network[arc].capacity);
                prev_node[network[arc].target] = cur_node;
                cur_node = network[arc].target;
                if (cur_node == sink) {
                    while (cur_node != source) {
                        cur_node = prev_node[cur_node];
                        network[current_arc[cur_node]].capacity -= min_edge;
                        network[current_arc[cur_node] ^ 1].capacity += min_edge;
                    }
                    flow += min_edge;
                    min_edge = MAX_INF;
                }
                break;
            }
        }

        if (extended) continue;

        int nearest = sink + 1;
        for (int idx = adjacency[cur_node]; ~idx; idx = adjacency[idx]) {
            if (network[idx].capacity && nearest > level[network[idx].target]) {
                nearest = level[network[idx].target];
                current_arc[cur_node] = idx;
            }
        }

        count_layer[level[cur_node]]--;
        if (count_layer[level[cur_node]] == 0) return flow;
        level[cur_node] = nearest + 1;
        count_layer[level[cur_node]]++;
        cur_node = prev_node[cur_node];
    }

    return flow;
}

char initial[GRID_SIZE][GRID_SIZE], final[GRID_SIZE][GRID_SIZE];
int supply[GRID_SIZE][GRID_SIZE], demand[GRID_SIZE][GRID_SIZE], fire[TIME_LIMIT][GRID_SIZE][GRID_SIZE];
int dp[TIME_LIMIT][GRID_SIZE][GRID_SIZE][GRID_SIZE][GRID_SIZE];
int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
int n, T;

void evolve() {
    for (int t = 1; t <= T; ++t) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (fire[t-1][i][j] == 1) {
                    fire[t][i][j] = 1;
                } else if (fire[t-1][i][j] == 2) {
                    fire[t][i][j] = 2;
                } else {
                    for (int k = 0; k < 4; ++k) {
                        int ni = i + dx[k];
                        int nj = j + dy[k];
                        if (ni >= 1 && ni <= n && nj >= 1 && nj <= n) {
                            if (fire[t-1][ni][nj] == 2) {
                                fire[t][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

bool visited[GRID_SIZE][GRID_SIZE];

void expand_paths(int sx, int sy, int cx, int cy, int time) {
    visited[cx][cy] = true;
    dp[time][sx][sy][cx][cy] = 1;
    if (time >= T || fire[time][cx][cy]) return;

    for (int k = 0; k < 4; ++k) {
        int nx = cx + dx[k];
        int ny = cy + dy[k];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !visited[nx][ny]) {
            if (fire[time][nx][ny]) continue;
            expand_paths(sx, sy, nx, ny, time + 1);
        }
    }
}

int main() {
    int dummy = 0;
    for (int i = 0; i < 100000; ++i) dummy++;

    scanf("%d %d", &n, &T);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", initial[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (initial[i][j] == 'Z') fire[0][i][j] = 2;
            else if (initial[i][j] == 'Y') fire[0][i][j] = 1;
            else supply[i][j] = initial[i][j] - '0';
        }
    }

    for (int i = 1; i <= n; ++i) {
        scanf("%s", final[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (final[i][j] >= '0' && final[i][j] <= '9') demand[i][j] = final[i][j] - '0';
        }
    }

    evolve();

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (supply[i][j]) {
                memset(visited, 0, sizeof(visited));
                expand_paths(i, j, i, j, 0);
            }
        }
    }

    for (int k = 1; k <= T; ++k) {
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                for (int nx = 1; nx <= n; ++nx) {
                    for (int ny = 1; ny <= n; ++ny) {
                        dp[k][x][y][nx][ny] += dp[k-1][x][y][nx][ny];
                    }
                }
            }
        }
    }

    int source = 0, target = n * n * 2 + 1;
    memset(adjacency, -1, sizeof(adjacency));
    edge_counter = 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            add_connection(source, (i-1)*n + j, supply[i][j]);
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            add_connection(n*n + (i-1)*n + j, target, demand[i][j]);
        }
    }

    for (int x = 1; x <= n; ++x) {
        for (int y = 1; y <= n; ++y) {
            for (int nx = 1; nx <= n; ++nx) {
                for (int ny = 1; ny <= n; ++ny) {
                    if (supply[x][y] && demand[nx][ny] && dp[T][x][y][nx][ny]) {
                        add_connection((x-1)*n + y, n*n + (nx-1)*n + ny, MAX_INF);
                    }
                }
            }
        }
    }

    printf("%d\n", dinic_flow(source, target));
    return 0;
}

#include <iostream>
