        for (int di = -1; di <= 1; ++di)
            for (int dj = -1; dj <= 1; ++dj)
                if (abs(di) + abs(dj) == 1) {
                    int nx = x + di, ny = y + dj;
                    if (inside(nx, ny) && disableTime[nx][ny] == INF && scientists[nx][ny] != 'Y') {
                        disableTime[nx][ny] = disableTime[x][y] + 1;
                        q.push({nx, ny});
                    }
                }
    }
    for (int x = 0; x < rows; ++x)
        for (int y = 0; y < cols; ++y) {
            if (scientists[x][y] >= '1' && scientists[x][y] <= '9')
                connect(source, cellId(x, y), scientists[x][y] - '0');
            if (reactors[x][y] >= '1' && reactors[x][y] <= '9')
                connect(rows * rows + cellId(x, y), sink, reactors[x][y] - '0');
            for (int X = 0; X < rows; ++X)
                for (int Y = 0; Y < cols; ++Y) {
                    if (scientists[x][y] == 'Y' || scientists[x][y] == 'Z' ||
                        reactors[X][Y] == 'Y' || reactors[X][Y] == 'Z')
                        continue;
                    memset(visitedCells, 0, sizeof(visitedCells));
                    queue<tuple<int, int, int>> bq;
                    bq.emplace(x, y, 1);
                    visitedCells[x][y] = 1;
                    while (!bq.empty()) {
                        auto [cx, cy, t] = bq.front(); bq.pop();
                        if (cx == X && cy == Y) {
                            visitedCells[cx][cy] = 1;
                            break;
                        }
                        if (t >= disableTime[cx][cy] || t >= T) continue;
                        for (int di = -1; di <= 1; ++di)
                            for (int dj = -1; dj <= 1; ++dj)
                                if (abs(di) + abs(dj) == 1) {
                                    int nx = cx + di, ny = cy + dj;
                                    if (inside(nx, ny) && !visitedCells[nx][ny] &&
                                        scientists[nx][ny] != 'Y' && scientists[nx][ny] != 'Z' &&
                                        t + 1 <= disableTime[nx][ny]) {
                                        visitedCells[nx][ny] = 1;
                                        bq.emplace(nx, ny, t + 1);
                                    }
                                }
                    }
                    if (visitedCells[X][Y])
                        connect(cellId(x, y), rows * rows + cellId(X, Y), INF);
                }
        }
    cout << computeMaxFlow() << '\n';
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = 1000000009;

struct Edge {
    int u, v, f, c;
    Edge(int u, int v, int f, int c) : u(u), v(v), f(f), c(c) {}
};

int src, snk;
vector<vector<int>> gph;
vector<Edge> edg;

void link(int u, int v, int cap) {
    gph[u].push_back(edg.size());
    edg.emplace_back(u, v, 0, cap);
    gph[v].push_back(edg.size());
    edg.emplace_back(v, u, 0, 0);
}

int p[1001], d[1001];

bool levelGraph() {
    fill(d, d + 1001, -1);
    d[src] = 0;
    queue<int> q;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int id : gph[u]) {
            auto& e = edg[id];
            if (d[e.v] == -1 && e.f < e.c) {
                d[e.v] = d[u] + 1;
                q.push(e.v);
                if (e.v == snk) return true;
            }
        }
    }
    return false;
}

ll augment(int u, ll f) {
    if (u == snk || f == 0) return f;
    for (int& i = p[u]; i < (int)gph[u].size(); ++i) {
        int id = gph[u][i];
        auto& e = edg[id];
        if (d[e.v] != d[u] + 1) continue;
        ll pushed = augment(e.v, min(f, (ll)e.c - e.f));
        if (pushed) {
            e.f += pushed;
            edg[id ^ 1].f -= pushed;
            return pushed;
        }
    }
    return 0;
}

ll flow() {
    ll total = 0;
    while (levelGraph()) {
        memset(p, 0, sizeof(p));
        ll pushed;
        while ((pushed = augment(src, INF)) > 0)
            total += pushed;
    }
    return total;
}

string sci[101], rec[101];
bool connected[10][10][10][10];
int mark[101][101];
int failAt[10][10];
int n, m;

bool inGrid(int r, int c) {
    return r >= 0 && c >= 0 && r < n && c < m;
}

int node(int r, int c) {
    return 1 + m * r + c;
}

int main() {
    ios::sync_with_stdio(false);
    int T;
    cin >> n >> T;
    ++T;
    m = n;
    snk = m * m * 2 + 1;
    src = 0;
    gph.resize(m * m * 2 + 2);
    queue<pair<int, int>> q;
    for (int i = 0; i < n; ++i) cin >> sci[i];
    for (int i = 0; i < n; ++i) {
        cin >> rec[i];
        for (int j = 0; j < m; ++j) {
            failAt[i][j] = INF;
            if (rec[i][j] == 'Z') {
                q.push({i, j});
                failAt[i][j] = 1;
            }
        }
    }
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int di = -1; di <= 1; ++di)
            for (int dj = -1; dj <= 1; ++dj)
                if (abs(di) + abs(dj) == 1) {
                    int nx = x + di, ny = y + dj;
                    if (inGrid(nx, ny) && failAt[nx][ny] == INF && sci[nx][ny] != 'Y') {
                        failAt[nx][ny] = failAt[x][y] + 1;
                        q.push({nx, ny});
                    }
                }
    }
    for (int x = 0; x < n; ++x)
        for (int y = 0; y < m; ++y) {
            if (sci[x][y] >= '1' && sci[x][y] <= '9')
                link(src, node(x, y), sci[x][y] - '0');
            if (rec[x][y] >= '1' && rec[x][y] <= '9')
                link(n * n + node(x, y), snk, rec[x][y] - '0');
            for (int X = 0; X < n; ++X)
                for (int Y = 0; Y < m; ++Y) {
                    if (sci[x][y] == 'Y' || sci[x][y] == 'Z' ||
                        rec[X][Y] == 'Y' || rec[X][Y] == 'Z')
                        continue;
                    memset(mark, 0, sizeof(mark));
                    queue<tuple<int, int, int>> bq;
                    bq.emplace(x, y, 1);
                    mark[x][y] = 1;
                    while (!bq.empty()) {
                        auto [cx, cy, t] = bq.front(); bq.pop();
                        if (cx == X && cy == Y) {
                            mark[cx][cy] = 1;
                            break;
                        }
                        if (t >= failAt[cx][cy] || t >= T) continue;
                        for (int di = -1; di <= 1; ++di)
                            for (int dj = -1; dj <= 1; ++dj)
                                if (abs(di) + abs(dj) == 1) {
                                    int nx = cx + di, ny = cy + dj;
                                    if (inGrid(nx, ny) && !mark[nx][ny] &&
                                        sci[nx][ny] != 'Y' && sci[nx][ny] != 'Z' &&
                                        t + 1 <= failAt[nx][ny]) {
                                        mark[nx][ny] = 1;
                                        bq.emplace(nx, ny, t + 1);
                                    }
                                }
                    }
                    if (mark[X][Y])
                        link(node(x, y), n * n + node(X, Y), INF);
                }
        }
    cout << flow() << '\n';
}

