int dfs(int u,int f)
{
    if(u==T)
        return f;
    int used=0;
    for(int i=head[u];i && f-used;i=edge[i][2])
    {
        int v=edge[i][0];
        if(depth[v]!=depth[u]+1 || edge[i][1]==0)
            continue;
        int pushed=dfs(v,min(f-used,edge[i][1]));
        used+=pushed;
        edge[i][1]-=pushed;
        edge[i^1][1]+=pushed;
    }
    if(used==0)
        depth[u]=-1;
    return used;
}
