    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : graph[u]) {
            if (lvl[e.to] == 0 && e.cap > 0) {
                lvl[e.to] = lvl[u] + 1;
                q.push(e.to);
                if (e.to == T) return true;
            }
        }
    }
    return false;
}

int dfs_flow(int u, int flow) {
    if (u == T) return flow;
    for (auto& e : graph[u]) {
        if (e.cap > 0 && lvl[e.to] == lvl[u] + 1) {
            int pushed = dfs_flow(e.to, min(flow, e.cap));
            if (pushed) {
                e.cap -= pushed;
                graph[e.to][e.rev_idx].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

