                    if (C[i][j] - F[i][j] > 0 && H[i]==H[j]+1) {
                        int d = min(C[i][j] - F[i][j], E[i]);
                        F[i][j] += d;
                        F[j][i] -= d;
                        E[i] -= d;
                        E[j] += d;
                        f = false;
                        ff = false;
                        if (E[i] == 0) goto next;
                    }
                }
                if (H[i] != minH+1 && minH != 10000)
                    f = false, ff = false, H[i] = minH+1;
                if (f) next: break;
            }
        if (ff) break;
    }

    cout << E[0];
    return 0;
}

