            else if (c == 'Y') maze[0][i][j] = 1;
            else if (c == 'Z') maze[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= n; ++i) {
        string line;
        cin >> line;
        for (int j = 1; j <= n; ++j) {
            char c = line[j - 1];
            if (isdigit(c)) capacities[i][j] = c - '0';
        }
    }
    source = n * n * 2;
