        if (r < N - 1 && d + 1 < dists[r + 1][c] && obstacles[r + 1][c])
            q.push({d + 1, {r + 1, c}});
        if (c < N - 1 && d + 1 < dists[r][c + 1] && obstacles[r][c + 1])
            q.push({d + 1, {r, c + 1}});
    }
    int idx = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int sink_node = N * N;
            ++idx;
            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    ++sink_node;
                    if (obstacles[i][j] && obstacles[x][y] && dist(i, j, x, y) <= T)
                        connect(idx, sink_node, BIG);
                }
            }
        }
    }
    cout << max_flow() << '\n';
    return 0;
}

