}

vector<vector<int>> bfs(int st_x, int st_y, vector<string> s) {
    vector<vector<int>> res(s.size(), vector<int>(s.size(), inf));
    res[st_x][st_y] = 0;
    deque<pii> b;
    b.emplace_back(st_x, st_y);

    while(b.size()) {
        pii v = b.front();
        b.pop_front();

        for(int i = 0;i < 4;i++) {
            int x = v.f + xdir[i];
            int y = v.s + ydir[i];
            if (!check(x, y, s) || res[x][y] != inf) continue;

            res[x][y] = res[v.f][v.s] + 1;
            b.emplace_back(x, y);
        }
    }

    return res;
}


