using namespace std;

using i64 = long long;
using pii = pair<int, int>;
using grid = vector<string>;

constexpr i64 INF = (i64)1e18;
constexpr int MAXN = 1000;

const int dx[4] = {0, 0, -1, 1};
const int dy[4] = {-1, 1, 0, 0};

vector<int> g[MAXN];
bool vis[MAXN];
int mt[MAXN];

bool ok(int x, int y, const grid& a) {
    return x >= 0 && y >= 0 && x < (int)a.size() && y < (int)a.size() && a[x][y] != 'Y' && a[x][y] != 'Z';
}

vector<vector<i64>> calc_dist(int sx, int sy, const grid& a) {
    int n = a.size();
    vector<vector<i64>> dist(n, vector<i64>(n, INF));
    deque<pii> q;
    dist[sx][sy] = 0;
    q.push_back({sx, sy});
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop_front();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (!ok(nx, ny, a) || dist[nx][ny] != INF) continue;
            dist[nx][ny] = dist[x][y] + 1;
            q.push_back({nx, ny});
        }
    }
    return dist;
}

void read_and_build() {
    int N, T;
    cin >> N >> T;
    grid A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    for (int i = 0; i < N; ++i) cin >> B[i];

    int rx = -1, ry = -1;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (A[i][j] == 'Z') rx = i, ry = j;

    auto D = calc_dist(rx, ry, A);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!ok(i, j, A)) continue;
            auto D2 = calc_dist(i, j, A);
            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    if (!ok(x, y, A) ||
                        D2[x][y] > T ||
                        D2[x][y] > D[x][y])
                        continue;

                    if (D2[x][y] == D[x][y]) {
                        bool ok_flag = false;
                        for (int k = 0; k < 4; ++k) {
                            int nx = x + dx[k], ny = y + dy[k];
                            if (ok(nx, ny, A) && D2[nx][ny] < D[nx][ny]) ok_flag = true;
                        }
                        if (!ok_flag) continue;
                    }

                    int c1 = A[i][j] - '0';
                    int c2 = B[x][y] - '0';
                    for (int u = 1; u <= c1; ++u) {
                        for (int v = 1; v <= c2; ++v) {
                            int src = i * 100 + j * 10 + u;
                            int dst = x * 100 + y * 10 + v;
                            g[src].push_back(dst);
                        }
                    }
                }
            }
        }
    }
}

bool dfs(int u) {
    if (vis[u]) return false;
    vis[u] = true;
    for (int v : g[u]) {
        if (!mt[v] || dfs(mt[v])) {
            mt[v] = u;
            return true;
        }
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    read_and_build();
    int cnt = 0;
    for (int i = 0; i < MAXN; ++i) {
        fill(vis, vis + MAXN, false);
        cnt += dfs(i);
    }
    cout << cnt << '\n';
    return 0;
}

#include <iostream>
