using namespace std;

using lli = long long;
using pii = pair<int, int>;
using vs = vector<string>;

const lli INF = (lli)1e18;
const int MAX_NODE = 1000;

int DR[4] = {0, 0, -1, 1};
int DC[4] = {-1, 1, 0, 0};

vector<int> adj[MAX_NODE];
bool marker[MAX_NODE];
int link[MAX_NODE];

bool valid(int r, int c, const vs& grid) {
    int n = grid.size();
    return r >= 0 && c >= 0 && r < n && c < n && grid[r][c] != 'Y' && grid[r][c] != 'Z';
}

vector<vector<lli>> BFS(int sr, int sc, const vs& grid) {
    int n = grid.size();
    vector<vector<lli>> dist(n, vector<lli>(n, INF));
    deque<pii> dq;
    dist[sr][sc] = 0;
    dq.emplace_back(sr, sc);

    while (!dq.empty()) {
        auto [r, c] = dq.front(); dq.pop_front();
        for (int k = 0; k < 4; ++k) {
            int nr = r + DR[k], nc = c + DC[k];
            if (!valid(nr, nc, grid) || dist[nr][nc] != INF) continue;
            dist[nr][nc] = dist[r][c] + 1;
            dq.emplace_back(nr, nc);
        }
    }
    return dist;
}

void populate_graph() {
    int N, T;
    cin >> N >> T;
    vs G1(N), G2(N);
    for (int i = 0; i < N; ++i) cin >> G1[i];
    for (int i = 0; i < N; ++i) cin >> G2[i];

    int rx = -1, ry = -1;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (G1[i][j] == 'Z') rx = i, ry = j;

    auto dist_to_react = BFS(rx, ry, G1);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!valid(i, j, G1)) continue;
            auto dist_from_src = BFS(i, j, G1);

            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    if (!valid(x, y, G1)) continue;
                    if (dist_from_src[x][y] > T) continue;
                    if (dist_from_src[x][y] > dist_to_react[x][y]) continue;

                    bool special = (dist_from_src[x][y] == dist_to_react[x][y]);
                    if (special) {
                        bool escapable = false;
                        for (int d = 0; d < 4; ++d) {
                            int nx = x + DR[d], ny = y + DC[d];
                            if (valid(nx, ny, G1) && dist_from_src[nx][ny] < dist_to_react[nx][ny]) {
                                escapable = true;
                                break;
                            }
                        }
                        if (!escapable) continue;
                    }

                    int val1 = G1[i][j] - '0';
                    int val2 = G2[x][y] - '0';
                    for (int u = 1; u <= val1; ++u) {
                        for (int v = 1; v <= val2; ++v) {
                            int src = 100 * i + 10 * j + u;
                            int dst = 100 * x + 10 * y + v;
                            adj[src].push_back(dst);
                        }
                    }
                }
            }
        }
    }
}

bool match_step(int u) {
    if (marker[u]) return false;
    marker[u] = true;
    for (int v : adj[u]) {
        if (!link[v] || match_step(link[v])) {
            link[v] = u;
            return true;
        }
    }
    return false;
}

void process_and_output() {
    populate_graph();
    int count = 0;
    for (int u = 0; u < MAX_NODE; ++u) {
        fill(marker, marker + MAX_NODE, false);
        if (match_step(u)) ++count;
    }
    cout << count << '\n';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    process_and_output();
    return 0;
}

