const lli INF = (lli)1e18;
const int MAX_NODES = 1000;

const int dR[4] = {0, 0, -1, 1};
const int dC[4] = {-1, 1, 0, 0};

vector<int> graph[MAX_NODES];
bool visited[MAX_NODES];
int mate[MAX_NODES];

inline bool safe(int r, int c, const vs& grid) {
    int n = grid.size();
    return r >= 0 && c >= 0 && r < n && c < n && grid[r][c] != 'Y' && grid[r][c] != 'Z';
}

vector<vector<lli>> distance_field(int sr, int sc, const vs& grid) {
    int n = grid.size();
    vector<vector<lli>> dist(n, vector<lli>(n, INF));
    deque<pii> dq;
    dist[sr][sc] = 0;
    dq.emplace_back(sr, sc);

    while (!dq.empty()) {
        auto [r, c] = dq.front(); dq.pop_front();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dR[k], nc = c + dC[k];
            if (!safe(nr, nc, grid) || dist[nr][nc] != INF) continue;
            dist[nr][nc] = dist[r][c] + 1;
            dq.emplace_back(nr, nc);
        }
    }
    return dist;
}

void construct_graph() {
    int N, T;
    cin >> N >> T;
    vs A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    for (int i = 0; i < N; ++i) cin >> B[i];

    int rx = -1, ry = -1;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (A[i][j] == 'Z') rx = i, ry = j;

    auto dist_react = distance_field(rx, ry, A);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!safe(i, j, A)) continue;
            auto dist_src = distance_field(i, j, A);

            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    if (!safe(x, y, A)) continue;
                    if (dist_src[x][y] > T) continue;
                    if (dist_src[x][y] > dist_react[x][y]) continue;

                    bool critical = (dist_src[x][y] == dist_react[x][y]);
                    if (critical) {
                        bool able_to_escape = false;
                        for (int k = 0; k < 4; ++k) {
                            int nx = x + dR[k], ny = y + dC[k];
                            if (safe(nx, ny, A) && dist_src[nx][ny] < dist_react[nx][ny]) {
                                able_to_escape = true;
                                break;
                            }
                        }
                        if (!able_to_escape) continue;
                    }

                    int cap1 = A[i][j] - '0';
                    int cap2 = B[x][y] - '0';
                    for (int u = 1; u <= cap1; ++u) {
                        for (int v = 1; v <= cap2; ++v) {
                            int src_id = 100 * i + 10 * j + u;
                            int dst_id = 100 * x + 10 * y + v;
                            graph[src_id].push_back(dst_id);
                        }
                    }
                }
            }
        }
    }
}

bool try_augment(int u) {
    if (visited[u]) return false;
    visited[u] = true;
    for (int v : graph[u]) {
        if (!mate[v] || try_augment(mate[v])) {
            mate[v] = u;
            return true;
        }
    }
    return false;
}

void execute() {
    construct_graph();
    int matches = 0;
    for (int u = 0; u < MAX_NODES; ++u) {
        fill(visited, visited + MAX_NODES, false);
        matches += try_augment(u);
    }
    cout << matches << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    execute();
    return 0;
}

