using namespace std;
vector<int> e[2020];
int ir[20][20];
int sc[20][20];
int pc[20][20];
char s[20][20];
char p[20][20];
int dd[20][20];
int dx[5]={0,1,-1,0};
int dy[5]={1,0,0,-1};
vector<int> ns[20][20],np[20][20];
void ade(int a,int b)
{
    e[a].push_back(b);
    e[b].push_back(a);
}
int ds[2020];
int pa[2020];
int sp,pp;
bool bfs()
{
    deque<int> q;
    for(int i=1;i<=sp;i++)
    {
        if(pa[i]==0)
            ds[i]=0,q.push_back(i);
        else
            ds[i]=3010;
    }
    ds[0]=3010;
    while(!q.empty())
    {
        int u=q[0];
        q.pop_front();
        if(ds[u]<ds[0])
        {
            for(int i=0;i<e[u].size();i++)
            {
                int v=pa[e[u][i]];
                if(ds[v]>ds[u]+1)
                    ds[v]=ds[u]+1,q.push_back(v);
            }
        }
    }
    return ds[0]!=3010;
}
bool dfs(int x)
{
    if(x==0)
        return 1;
    for(int i=0;i<e[x].size();i++)
    {
        int u=pa[e[x][i]];
        if(ds[u]==ds[x]+1)
        {
            if(dfs(u))
            {
                pa[x]=e[x][i];
                pa[e[x][i]]=x;
                return 1;
            }
        }
    }
    return 0;
}
int hkp()
{
    int an=0;
    while(bfs())
    {
        for(int i=1;i<=sp;i++)
        {
            if(pa[i]==0)
                an+=dfs(i);
        }
    }
    return an;
}
int n,t;
void wk(int a,int b)
{
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=n;j++)
        {
            dd[i][j]=100000;
        }
    }
    deque<pair<int,int> > q;
    dd[a][b]=0;
    q.push_back(make_pair(a,b));
    while(!q.empty())
    {
        int x=q[0].first,y=q[0].second;
        q.pop_front();
        for(int i=0;i<np[x][y].size();i++)
            for(int j=0;j<ns[a][b].size();j++)
                ade(ns[a][b][j],np[x][y][i]);
        if(dd[x][y]==ir[x][y])
            continue;
        for(int d=0;d<4;d++)
        {
            int nx=x+dx[d];
            int ny=y+dy[d];
            if(sc[nx][ny]!=-1&&dd[nx][ny]>dd[x][y]+1&&dd[x][y]+1<=ir[nx][ny])
            {
                dd[nx][ny]=dd[x][y]+1;
                q.push_back(make_pair(nx,ny));
            }
        }
    }
}
int main()
{
    scanf("%d%d",&n,&t);
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++)
            ir[i][j]=t;
    for(int i=1;i<=n;i++)
        scanf("%s",s[i]+1);
    for(int i=1;i<=n;i++)
        scanf("%s",p[i]+1);
