    sp=1,pp=1000;
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=n;j++)
        {
            if(s[i][j]=='Z'||s[i][j]=='Y')
                sc[i][j]=-1,ir[i][j]=0;
            if(s[i][j]=='Z')
                rx=i,ry=j,ir[i][j]=0;
            if('0'<=s[i][j]&&s[i][j]<='9')
                sc[i][j]=s[i][j]-'0';
            for(int k=0;k<sc[i][j];k++)
                ns[i][j].push_back(sp++);
        }
    }
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=n;j++)
        {
            if('0'<=p[i][j]&&p[i][j]<='9')
