    X.push(x);
    Y.push(y);

    while (!X.empty()) {
        assert(!Y.empty());

        int curx = X.front();
        int cury = Y.front();

        X.pop();
        Y.pop();

        for (int k = 0; k < 4; k++) {
            int tx = curx + dx[k];
            int ty = cury + dy[k];

            if (isValid(tx, ty) && distance[tx][ty] == INF) {
                distance[tx][ty] = distance[curx][cury] + 1;
                X.push(tx);
                Y.push(ty);
            }
        }
    }
}

void runBFS(int x, int y) {
    queue <int> X, Y, lev;
    memset(visited, false, sizeof visited);

    visited[x][y] = true;
    X.push(x);
    Y.push(y);
    lev.push(0);

    while (!X.empty()) {
        assert(!Y.empty());

        int curx = X.front();
        int cury = Y.front();
