}

void bfsFromZ(int sx, int sy) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            distMap[i][j] = INF;

    queue<int> qx, qy;
    distMap[sx][sy] = 0;
    qx.push(sx);
    qy.push(sy);

    while (!qx.empty()) {
        assert(!qy.empty());
        int cx = qx.front(); qx.pop();
        int cy = qy.front(); qy.pop();

        for (int k = 0; k < 4; ++k) {
            int nx = cx + dx[k];
            int ny = cy + dy[k];
            if (valid(nx, ny) && distMap[nx][ny] == INF) {
