            computeDist2(i, j);
            for (int x = 0; x < n; ++x) {
                for (int y = 0; y < n; ++y) {
                    if (gridB[x][y] == 'Y' || distToFinish[x][y] > T) continue;
                    addEdge(u, n * n + x * n + y + 1, cap1);
                }
            }
        }
    }

    cout << max_flow() << "\n";
    return 0;
}

