		while(!Q.empty()) {
			u = Q.front();
			Q.pop();
			for(int i = l[u]; ~i; i = E[i].x) {
				v = E[i].v;
				if(d[v] == - 1 && E[i].cap) {
					d[v] = d[u] + 1;
					Q.push(v);
				}
			}
		}
		return d[sink] != -1;
	}

	int dfs(int u, int in) {
		if(u == sink)	return in;
		int flow = 0, f;
		for(int &i = cur[u]; ~i; i = E[i].x) {
			v = E[i].v;
			if(d[v] == d[u] + 1 && E[i].cap) {
				if(f=dfs(v, min(in-flow, E[i].cap))) {
					flow += f;
					E[i].cap -= f;
