					if(flow == in)	break;
				}
			}
		}
		if(flow < in)	d[u] = -1;
		return flow;
	}

	const int inf = 1e9;
	int dinic(int _src, int _sink) {
		src = _src, sink = _sink;
		int flow = 0;
		while(bfs())
			flow += dfs(src, inf);
		return flow;
	}
};

