        memset( v2, -1, sizeof(v2) );
        v1[x][y] = v2[xz][yz] = 0;

        int x1, y1;
        while( h1 < t1 ){

                while( h1 < up1 ){
                        x = q1[h1++], y = q1[h1++];
                        if( v2[x][y] >= 0 ) continue;
                        for( int i = 0; i < 4; ++i ){
                                x1 = x + dir[i][0];
                                y1 = y + dir[i][1];
                                if( inside( x1, y1 ) && v1[x1][y1] < 0 ){
                                        v1[x1][y1] = v1[x][y] + 1;
                                        if( v1[x1][y1] > T ) break;
                                        if( v2[x1][y1] >= 0 ) continue;
                                        q1[t1++] = x1, q1[t1++] = y1;

                                        if( s2[x1][y1] != '0' ){
                                                add( id[sx][sy], id[x1][y1] + cnt, 10 );
                                        }
                                }
                        }
                }
                up1 = t1;

                while( h2 < up2 ){
                        x = q2[h2++], y = q2[h2++];

                        for( int i = 0; i < 4; ++i ){
                                x1 = x + dir[i][0];
                                y1 = y + dir[i][1];
                                if( inside( x1, y1) && v2[x1][y1] < 0 ){
                                        v2[x1][y1] = v2[x][y] + 1;
                                        q2[t2++] = x1, q2[t2++] = y1;
                                }
                        }
                }
                up2 = t2;
        }
}

bool bfs()
{
        queue<int> q;
        memset( vis, 0,  sizeof(vis) );
        vis[s] = 1;

        q.push( s );
        int u, v;
        while( !q.empty() ){
                u = q.front(), q.pop();
                for( int i = h[u]; i+1; i = nxt[i] ) if( cap[i] > 0 && !vis[vv[i]]){
                        v = vv[i];
                        pre[v] = i;
                        if( v == t ) return 1;
                        vis[v] = 1, q.push( v );

                }
        }
        return 0;
}
int maxFlow()
{
        int ans = 0, mi, v;

        while( bfs() ){
                mi = 10000000;
                v = t;
                while( v - s ){
                        v = pre[v];
                        mi = min( mi, cap[v] );
                        v = vv[v^1];
                }
                ans += mi;

                v = t;
                while( v - s ){
                        v = pre[v];
                        cap[v] -= mi;
                        cap[v^1] += mi;
                        v = vv[v^1];
                }
        }
        return ans;
}
