inline long long abs_val(long long x) {
    return x < 0 ? -x : x;
}

int main() {
    #ifndef ONLINE_JUDGE
        freopen("a.in", "r", stdin);
    #endif

    cin >> A >> B >> N;

    for (long long y = 1; y <= N; ++y) {
        long long x1 = (A * y) / B;
        long long x2 = x1 + 1;

        long long err1 = abs_val(A * y - B * x1);
        long long err2 = abs_val(A * y - B * x2);

        if (numerator == 0 && denominator == 0) {
            if (err1 * y <= err2 * y) {
                numerator = x1;
                denominator = y;
            } else {
                numerator = x2;
                denominator = y;
            }
        } else {
            long long curr_err1 = err1 * denominator;
            long long curr_err2 = err2 * denominator;
            long long best_err = abs_val(A * denominator - B * numerator) * y;

            if (curr_err1 < best_err) {
                numerator = x1;
                denominator = y;
            } else if (curr_err2 < best_err) {
                numerator = x2;
                denominator = y;
            }
        }
    }

    cout << numerator << "/" << denominator << endl;
    return 0;
}

