#include <cmath>
using namespace std;

long long n, x, y;

long long gcd(long long a, long long b) {
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

struct Fraction {
    long long num, den;

    Fraction() : num(0), den(1) {}
    Fraction(long long n, long long d) : num(n), den(d) {}

    Fraction subtract(const Fraction& other) const {
        Fraction res;
        res.num = num * other.den - other.num * den;
        res.den = den * other.den;
        return res;
    }

    bool lessThan(const Fraction& other) const {
        return num * other.den < other.num * den;
    }

    void reduce() {
        long long g = gcd(abs(num), abs(den));
        if (g != 0) {
            num /= g;
            den /= g;
        }
        if (den < 0) {
            num = -num;
            den = -den;
        }
    }

    void print() const {
        cout << num << "/" << den;
    }
};

int main() {
    cin >> x >> y >> n;

    Fraction target(x, y);
    Fraction closest(50, 1);
    Fraction bestApprox;

    for (long long i = 1; i <= n; ++i) {
        long long quotient = (target.num * i) / target.den;
        long long remainder = (target.num * i) % target.den;

        if (remainder > target.den / 2) {
            quotient++;
            remainder = target.den - remainder;
        }

        Fraction candidate(remainder, i * target.den);
        candidate.reduce();

        if (candidate.lessThan(closest)) {
            closest = candidate;
            bestApprox.num = quotient;
            bestApprox.den = i;
        }
    }

    bestApprox.print();
    return 0;
}

