    long long x, y, n;
    cin >> x >> y >> n;

    auto evaluate = [](long long a, long long b, long double target) -> long double {
        if (b == 0) return 1e30;
        return abs(target - static_cast<long double>(a) / b);
    };

    long double target = static_cast<long double>(x) / y;
    pair<long long, long long> optimal = {1, 1};
    long double best_error = evaluate(1, 1, target);

    for (long long b = 1; b <= n; ++b) {
        long long a_floor = static_cast<long long>(floor(target * b));
        long long a_ceil = static_cast<long long>(ceil(target * b));

        auto try_candidate = [&](long long a) {
            long double err = evaluate(a, b, target);
            if (err < best_error) {
                best_error = err;
                optimal = {a, b};
            }
        };

        try_candidate(a_floor);
        if (a_floor != a_ceil) {
            try_candidate(a_ceil);
        }
    }

    cout << optimal.first << '/' << optimal.second;
    return 0;
}

