    int candidate = (a > b) ? a : b;
    while (true) {
        if (a % candidate == 0 && b % candidate == 0) break;
        --candidate;
    }
    return candidate;
}

double computeAbsDiff(double x, double y, double p, double q, double& numerator, double& denominator) {
    numerator = fabs(x * q - y * p);
    denominator = y * q;
    return numerator / denominator;
}

int main() {
    double x, y, n;
    double minError = DBL_MAX;
    int bestA = 0, bestB = 1;

    cin >> x >> y >> n;

    if (n > y) {
        int g = findGCD((int)x, (int)y);
        if (g != 1) {
            x /= g;
            y /= g;
        }
        cout << (int)x << "/" << (int)y << endl;
        return 0;
    }

    for (int b = (int)n; b >= 1; --b) {
        double a_candidate = (x * b) / y;
        if (a_candidate == floor(a_candidate)) {
            bestA = (int)a_candidate;
            bestB = b;
            break;
        } else {
            double num1, den1;
            double err1 = computeAbsDiff(x, y, floor(a_candidate), b, num1, den1);
            if (err1 < minError || (fabs(err1 - minError) < 1e-12 && (int)floor(a_candidate) < bestA)) {
                bestA = (int)floor(a_candidate);
                bestB = b;
                minError = err1;
            }

            double num2, den2;
            double err2 = computeAbsDiff(x, y, ceil(a_candidate), b, num2, den2);
            if (err2 < minError || (fabs(err2 - minError) < 1e-12 && (int)ceil(a_candidate) < bestA)) {
                bestA = (int)ceil(a_candidate);
                bestB = b;
                minError = err2;
            }
        }
    }

    int g = findGCD(bestA, bestB);
    if (g != 1) {
        bestA /= g;
        bestB /= g;
    }

    cout << bestA << "/" << bestB << endl;

    return 0;
}

