inline int safe_subtract(int first, int second, ll modulo) {
    if (first - second < 0) return first - second + static_cast<int>(modulo);
    return first - second;
}

inline int safe_add(int first, int second, ll modulo) {
    if (first + second >= static_cast<int>(modulo)) return first + second - static_cast<int>(modulo);
    return first + second;
}

void recursive_build(int depth, int current_number) {
    if (current_number <= input_n) {
        node_counter++;
        int temp = safe_subtract(node_counter, current_number, MOD1);
        bucket[depth - 1].push_back(temp);
        running_sum[depth - 1] = safe_add(running_sum[depth - 1], temp, MOD2);
    }
    if (depth > 6) return;
    for (int digit = 0; digit <= 9; digit++) {
        recursive_build(depth + 1, current_number * 10 + digit);
    }
}

void recursive_compute(int depth, ll current_value) {
    if (current_value > input_n) return;
    if (depth > 1) {
        if (10LL * current_value * LIMIT_MAX > input_n &&
            1LL * (current_value + 1) * LIMIT_MAX - 1 <= input_n) {
            for (int index = 0; index < 7; index++) {
                ll temp = counter_c - current_value * base10[index];
                temp %= MOD1;
