                auto it = lower_bound(bucket[index].begin(), bucket[index].end(),
                                      static_cast<int>(MOD1) - value);
                int pos = it - bucket[index].begin();
                int add_part1 = static_cast<int>(1LL * value * bucket[index].size() % MOD2);
                int add_part2 = running_sum[index];
                int combined = safe_add(add_part1, add_part2, MOD2);
                final_output = safe_add(final_output, combined, MOD2);
                int subtract_part = static_cast<int>(1LL * MOD1 * (bucket[index].size() - pos) % MOD2);
                final_output = safe_subtract(final_output, subtract_part, MOD2);
            }
            counter_c += node_counter;
            return;
        }
        counter_c++;
        int diff = static_cast<int>((counter_c - current_value) % MOD1 + MOD1) % MOD1;
        final_output = safe_add(final_output, diff, MOD2);
    }
    int start_digit = (depth == 1) ? 1 : 0;
    for (int digit = start_digit; digit <= 9; digit++) {
        recursive_compute(depth + 1, current_value * 10 + digit);
    }
}

