void solve_dfs(ll num) {
    if (num >= n) return;
    if ((num + 1) * P <= n && num * P * 10 >= n) {
        ll factor = 1;
        for (int lv = 0; lv <= LIMIT; ++lv) {
            int sz = suffixes[lv].size();
            int offset = ((idx - factor * num) % M2 + M2) % M2;
            int threshold = (M2 - offset) % M2;
            int matches = lower_bound(suffixes[lv].begin(), suffixes[lv].end(), threshold) - suffixes[lv].begin();
