const lli P1 = 1000000007LL;

class ModNum {
public:
    lli data;
    ModNum(lli v = 0) : data(v % P1) { if (data < 0) data += P1; }
    lli value() const { return data; }
};

ModNum operator+(const ModNum& a, const ModNum& b) {
    lli s = a.data + b.data;
    return s >= P1 ? ModNum(s - P1) : ModNum(s);
}

ModNum operator-(const ModNum& a, const ModNum& b) {
    lli d = a.data - b.data;
    return d < 0 ? ModNum(d + P1) : ModNum(d);
}

ModNum operator*(const ModNum& a, const ModNum& b) {
    return ModNum((a.data * b.data) % P1);
}

ModNum modpow(ModNum b, int e) {
    ModNum r(1);
    while (e > 0) {
        if (e & 1) r = r * b;
        b = b * b;
        e >>= 1;
    }
    return r;
}

const lli P2 = 998244353LL;
const lli STEP = 1000000LL;
const int LEVELS = 6;

lli limit;
lli cursor;
int total_count;
ModNum row_sum[LEVELS + 2];
vector<lli> tail_vals[LEVELS + 2];

void build_layer(int depth, lli cur) {
    lli num = ((cursor++ - cur) % P2 + P2) % P2;
    row_sum[depth] = row_sum[depth] + ModNum(num);
    tail_vals[depth].push_back(num);
    if (depth == LEVELS) return;
    for (int d = 0; d < 10; ++d)
        build_layer(depth + 1, cur * 10 + d);
}

void solve_subtree(lli cur) {
    if (cur >= limit) return;
    if ((cur + 1) * STEP <= limit && cur * STEP * 10 >= limit) {
        lli multiplier = 1;
        for (int lvl = 0; lvl <= LEVELS; ++lvl) {
            lli sz = tail_vals[lvl].size();
            lli shift = ((cursor - multiplier * cur) % P2 + P2) % P2;
            lli limit_val = (P2 - shift) % P2;
            lli matches = lower_bound(tail_vals[lvl].begin(), tail_vals[lvl].end(), limit_val) - tail_vals[lvl].begin();
            row_sum[LEVELS + 1] = row_sum[LEVELS + 1] + ModNum(sz) * ModNum(shift) + row_sum[lvl] - ModNum((sz - matches) * P2);
            multiplier *= 10;
        }
        cursor += total_count;
        return;
    }
    lli term = ((cursor++ - cur) % P2 + P2) % P2;
    row_sum[LEVELS + 1] = row_sum[LEVELS + 1] + ModNum(term);
    for (int d = 0; d < 10; ++d)
        solve_subtree(cur * 10 + d);
}

