typedef long long ll;
using namespace std;

const ll M1 = 998244353LL;
const ll M2 = 1000000007LL;
const ll B  = 1000000LL;

int N;
ll counter = 0;
ll total_ans = 0;
ll s[8];
vector<ll> v[8];

void gen(int d, ll num);
void calc(ll x);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N;
    gen(0, 0LL);
    for (int i = 0; i <= 7; ++i) sort(v[i].begin(), v[i].end());
    counter = 0;
    for (int i = 1; i <= 9; ++i) calc(i);
    cout << total_ans % M2 << '\n';
    return 0;
}

void gen(int d, ll n) {
    if (d == 7) return;
    counter++;
    ll val = ((counter - n) % M1 + M1) % M1;
    v[d].push_back(val);
    s[d] = (s[d] + val) % M2;
    for (int i = 0; i <= 9; ++i) gen(d+1, n*10 + i);
}

void calc(ll x) {
    if (x > N) return;
    if (x*B + B - 1 <= N && x*B*10 > N) {
        ll cur = counter;
        for (int i = 0, mult = 1; i <= 6; ++i, mult *= 10) {
            ll sz = v[i].size();
            ll dif = ((cur - x*mult) % M1 + M1) % M1;
            ll pos = lower_bound(v[i].begin(), v[i].end(), M1 - dif) - v[i].begin();
            total_ans = (total_ans + dif*sz + s[i]) % M2;
            total_ans = (total_ans - M1 * (sz - pos) % M2 + M2) % M2;
            counter += sz;
        }
        return;
    }
    counter++;
    ll cur_val = ((counter - x) % M1 + M1) % M1;
    total_ans = (total_ans + cur_val) % M2;
    for (int i = 0; i <= 9; ++i) calc(x*10 + i);
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;
const ll MOD_A = 998244353;
const ll MOD_B = 1000000007;
const ll BASE = 1000000;

int N;
ll global_counter = 0;
ll answer = 0;
ll partial_sums[8];
vector<ll> digit_groups[8];

void build_data(int depth, ll num);
void handle_number(ll start_val);

int main() {
    cin >> N;
    build_data(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(digit_groups[i].begin(), digit_groups[i].end());
    }
    global_counter = 0;
    for (int d = 1; d <= 9; ++d) {
        handle_number(d);
    }
    cout << answer % MOD_B << '\n';
    return 0;
}

void build_data(int depth, ll num) {
    if (depth == 7) return;
    global_counter++;
    ll computed = ((global_counter - num) % MOD_A + MOD_A) % MOD_A;
    digit_groups[depth].push_back(computed);
    partial_sums[depth] = (partial_sums[depth] + computed) % MOD_B;
    for (int digit = 0; digit <= 9; ++digit) {
        build_data(depth + 1, num * 10 + digit);
    }
}

void handle_number(ll start_val) {
    if (start_val > N) return;
    if (start_val * BASE + BASE - 1 <= N && start_val * BASE * 10 > N) {
        ll current_total = global_counter;
        for (int i = 0, multiplier = 1; i <= 6; ++i, multiplier *= 10) {
            ll size = digit_groups[i].size();
            ll diff = ((current_total - start_val * multiplier) % MOD_A + MOD_A) % MOD_A;
            ll index = lower_bound(digit_groups[i].begin(), digit_groups[i].end(), MOD_A - diff) - digit_groups[i].begin();
            answer = (answer + diff * size + partial_sums[i]) % MOD_B;
            answer = (answer - MOD_A * (size - index) % MOD_B + MOD_B) % MOD_B;
            global_counter += size;
        }
        return;
    }
    global_counter++;
    ll value = ((global_counter - start_val) % MOD_A + MOD_A) % MOD_A;
    answer = (answer + value) % MOD_B;
    for (int d = 0; d <= 9; ++d) {
        handle_number(start_val * 10 + d);
    }
}

