using i64 = long long;

const i64 MOD1 = 998244353LL;
const i64 MOD2 = 1000000007LL;
const i64 THRESHOLD = 1000000LL;

i64 N;
i64 counter = 0, temp_counter = 0, result = 0;
vector<i64> bucket[7];
i64 bucket_sum[7];

inline i64 normalize1(i64 x) {
    x %= MOD1;
    if (x < 0) x += MOD1;
    return x;
}

void traverse_first(i64 level, i64 current) {
    if (current > N) return;
    if (level > 6) return;

    ++counter;
    i64 adjusted = normalize1(counter - current);
    bucket[level].push_back(adjusted);
    bucket_sum[level] = (bucket_sum[level] + adjusted) % MOD1;

    for (i64 d = 0; d < 10; ++d) {
        traverse_first(level + 1, current * 10 + d);
    }
}

void traverse_second(i64 level, i64 current) {
    if (current > N) return;

    if (level >= 1) {
        if (current * THRESHOLD * 10 > N && current * THRESHOLD + THRESHOLD - 1 <= N) {
            for (i64 i = 0, pow10 = 1; i <= 6; ++i, pow10 *= 10) {
                i64 target = normalize1(counter - current * pow10);
                i64 pos = lower_bound(bucket[i].begin(), bucket[i].end(), MOD1 - target) - bucket[i].begin();
                result = (result + target * (i64)bucket[i].size() + bucket_sum[i] - MOD1 * (i64)(bucket[i].size() - pos)) % MOD2;
            }
            counter += temp_counter;
            return;
        }
        ++counter;
        result = (result + normalize1(counter - current)) % MOD2;
    }

    for (i64 d = (level == 0 ? 1 : 0); d < 10; ++d) {
        traverse_second(level + 1, current * 10 + d);
    }
}

