    traverse_first(0, 0);
    temp_counter = counter;
    counter = 0;

    for (int i = 0; i <= 6; ++i) {
        sort(bucket[i].begin(), bucket[i].end());
    }

    traverse_second(0, 0);
    result %= MOD2;
    if (result < 0) result += MOD2;
    cout << result << '\n';

    return 0;
}

