using namespace std;

using ll = long long;

const ll MOD_A = 998244353;
const ll MOD_B = 1000000007;
const ll LIMIT = 1000000;

ll n_val;
ll global_counter = 0, saved_counter = 0, final_answer = 0;
vector<ll> digit_buckets[7];
ll bucket_totals[7];

inline ll mod_adjust(ll x) {
    x %= MOD_A;
    return x >= 0 ? x : x + MOD_A;
}

void precompute(ll depth, ll num) {
    if (num > n_val) return;
    if (depth > 6) return;

    ++global_counter;
    ll val = mod_adjust(global_counter - num);
    digit_buckets[depth].push_back(val);
    bucket_totals[depth] = (bucket_totals[depth] + val) % MOD_A;

    for (ll d = 0; d <= 9; ++d) {
        precompute(depth + 1, num * 10 + d);
    }
}

void process(ll depth, ll num) {
    if (num > n_val) return;

    if (depth >= 1) {
        if (num * LIMIT * 10 > n_val && num * LIMIT + LIMIT - 1 <= n_val) {
            for (ll i = 0, base = 1; i <= 6; ++i, base *= 10) {
                ll needed = mod_adjust(global_counter - num * base);
                ll idx = lower_bound(digit_buckets[i].begin(), digit_buckets[i].end(), MOD_A - needed) - digit_buckets[i].begin();
                final_answer = (final_answer + needed * (ll)digit_buckets[i].size() + bucket_totals[i] - MOD_A * (ll)(digit_buckets[i].size() - idx)) % MOD_B;
            }
            global_counter += saved_counter;
            return;
        }
        ++global_counter;
        final_answer = (final_answer + mod_adjust(global_counter - num)) % MOD_B;
    }

    for (ll d = (depth == 0 ? 1 : 0); d <= 9; ++d) {
        process(depth + 1, num * 10 + d);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string input;
    cin >> input;
    n_val = 0;
    for (char c : input) {
        n_val = n_val * 10 + (c - '0');
    }

    precompute(0, 0);
    saved_counter = global_counter;
    global_counter = 0;

    for (int i = 0; i <= 6; ++i) {
        sort(digit_buckets[i].begin(), digit_buckets[i].end());
    }

    process(0, 0);
    final_answer %= MOD_B;
    if (final_answer < 0) final_answer += MOD_B;
    cout << final_answer << '\n';

    return 0;
}

