    x %= MOD_P;
    if (x < 0) x += MOD_P;
    return x;
}

i64 N, counter;
i64 cumsum[7];
int answer;
vector<int> bucket[7];

void generate(int depth, i64 val) {
    counter++;
    bucket[depth].emplace_back((int)normalize(counter - val));
    if (depth < 6) {
        for (int dig = 0; dig <= 9; ++dig) {
            generate(depth + 1, val * 10 + dig);
        }
    }
}

int query(int idx, int off) {
    auto it = lower_bound(bucket[idx].begin(), bucket[idx].end(), (int)(MOD_P - off));
    int pos = it - bucket[idx].begin();
    i64 part1 = (i64)off * (i64)bucket[idx].size();
    i64 part2 = cumsum[idx];
    i64 part3 = (i64)MOD_P * (i64)(bucket[idx].size() - pos);
    i64 val = (part1 + part2 - part3) % MOD_Q;
    if (val < 0) val += MOD_Q;
    return (int)val;
}

void search(int depth, i64 val) {
    if (val > N) return;
    if (depth >= 1) {
        if (val * BLOCK_LEN > N / 10 && val * BLOCK_LEN + BLOCK_LEN - 1 <= N) {
            int mult = 1;
            for (int k = 0; k <= 6; ++k) {
