const ll MOD1 = 998244353, MOD2 = 1000000007;

ll result, input_n, counter1, prefix_sum[7];
vector<ll> digit_vals[7];

void dfs1(int depth, ll num) {
    if (depth == 7) return;
    digit_vals[depth].emplace_back((counter1 - num + MOD1) % MOD1);
    prefix_sum[depth] = (prefix_sum[depth] + (counter1 - num + MOD1) % MOD1) % MOD2;
    ++counter1;
    for (int d = 0; d <= 9; ++d) dfs1(depth + 1, num * 10 + d);
}

bool is_valid_segment(ll prefix_val) {
    const ll BOUND = 1000000;
    return prefix_val * BOUND + 999999 <= input_n && prefix_val * BOUND * 10 > input_n;
}

ll counter2;
ll base_pow[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

void dfs2(int depth, ll current_val) {
    if (current_val > input_n) return;
    if (is_valid_segment(current_val)) {
        for (int i = 0; i <= 6; ++i) {
            ll diff = (counter2 + 1 - current_val * base_pow[i]) % MOD1;
            if (diff < 0) diff += MOD1;
            auto it = lower_bound(digit_vals[i].begin(), digit_vals[i].end(), MOD1 - diff);
            ll count = distance(it, digit_vals[i].end());
            result = (result + prefix_sum[i] + diff * (ll)digit_vals[i].size() - MOD1 * count) % MOD2;
        }
        counter2 += counter1;
    } else {
        ++counter2;
        ll diff = (counter2 - current_val) % MOD1;
        if (diff < 0) diff += MOD1;
        result = (result + diff) % MOD2;
        for (int d = (depth == 0 ? 1 : 0); d <= 9; ++d) dfs2(depth + 1, current_val * 10 + d);
    }
}

