const llong MOD1 = 998244353LL, MOD2 = 1000000007LL;

llong final_ans, max_n, counter_a, running_sum[7];
vector<llong> pattern[7];

void build_table(llong depth, llong num) {
    if (depth == 7) return;
    llong val = (counter_a - num + MOD1) % MOD1;
    pattern[depth].push_back(val);
    running_sum[depth] = (running_sum[depth] + val) % MOD2;
    ++counter_a;
    for (int digit = 0; digit <= 9; ++digit) build_table(depth + 1, num * 10 + digit);
}

bool qualifies(llong prefix) {
    const llong cutoff = 1000000LL;
    return prefix * cutoff + 999999LL <= max_n && prefix * cutoff * 10LL > max_n;
}

llong counter_b;
llong ten_powers[7] = {1LL, 10LL, 100LL, 1000LL, 10000LL, 100000LL, 1000000LL};

void traverse(llong depth, llong current) {
    if (current > max_n) return;
    if (qualifies(current)) {
        for (int i = 0; i < 7; ++i) {
            llong diff = ((counter_b + 1LL) - current * ten_powers[i]) % MOD1;
            if (diff < 0LL) diff += MOD1;
            auto iter = lower_bound(pattern[i].begin(), pattern[i].end(), MOD1 - diff);
            llong suffix_len = pattern[i].end() - iter;
            final_ans = (final_ans + running_sum[i] + diff * (llong)pattern[i].size() - MOD1 * suffix_len) % MOD2;
        }
        counter_b += counter_a;
    } else {
        ++counter_b;
        llong diff = (counter_b - current) % MOD1;
        if (diff < 0LL) diff += MOD1;
        final_ans = (final_ans + diff) % MOD2;
        llong start_digit = (depth == 0 ? 1 : 0);
        for (int digit = start_digit; digit <= 9; ++digit) traverse(depth + 1, current * 10 + digit);
    }
}

