                int idx = it - buckets[i].begin();
                result = (result + 1LL * complement * buckets[i].size() % MOD2 + bucketSums[i] - 1LL * MOD1 * (buckets[i].size() - idx) % MOD2) % MOD2;
            }
            counter += totalNodes;
            return;
        }
        ++counter;
        result = (result + mod1(counter - currentNum)) % MOD2;
    }

    for (int digit = (depth == 0); digit <= 9; ++digit) {
        query(depth + 1, currentNum * 10 + digit);
    }
}

