    if (value > limit) return;

    if (level != 0) {
        if (value * BLOCK_SIZE > limit / 10 && (value + 1) * BLOCK_SIZE - 1 <= limit) {
            for (int idx = 0, power = 1; idx <= 6; ++idx, power *= 10) {
                llong factor = (global_counter - 1LL * value * power % MOD_A + MOD_A) % MOD_A;
                auto pos = lower_bound(digit_groups[idx].begin(), digit_groups[idx].end(), MOD_A - factor);
                final_answer = (final_answer + factor * (int)digit_groups[idx].size() + group_totals[idx]) % MOD_B;
                final_answer = (final_answer - MOD_A * (digit_groups[idx].end() - pos) % MOD_B + MOD_B) % MOD_B;
