            return;
        }
        answer = (answer + (++counter - cur_val % MOD1 + MOD1) % MOD1) % MOD2;
    }

    for (int dig = (depth == 0 ? 0 : 1); dig < 10; ++dig) {
        search(cur_val * 10 + dig, depth + 1);
    }
}

