constexpr int BLOCK = 1000000, MOD1 = 998244353, MOD2 = 1000000007;
ll N;
ll cnt = 0;
vector<int> digit_vals[7];
int result = 0;
int digit_sums[7] = {};

void generate(int level, int val) {
    digit_vals[level].push_back((++cnt - val + MOD1) % MOD1);
    if (level == 6) return;
    for (int d = 0; d < 10; ++d) {
        generate(level + 1, val * 10 + d);
    }
}

void explore(ll val, int level) {
    if (val > N) return;

    if (level > 0) {
        if (val * BLOCK > N / 10 && (val + 1) * BLOCK - 1 <= N) {
            for (int i = 0, pow10 = 1; i <= 6; ++i, pow10 *= 10) {
                ll coeff = (cnt - 1LL * val * pow10 % MOD1 + MOD1) % MOD1;
                auto it = lower_bound(digit_vals[i].begin(), digit_vals[i].end(), MOD1 - coeff);
                result = (result + coeff * (int)digit_vals[i].size() + digit_sums[i]) % MOD2;
                result = (result - MOD1 * (digit_vals[i].end() - it) % MOD2 + MOD2) % MOD2;
            }
            for (int i = 0; i <= 6; ++i) cnt += digit_vals[i].size();
            return;
        }
        result = (result + (++cnt - val % MOD1 + MOD1) % MOD1) % MOD2;
    }

    for (int d = (level == 0 ? 0 : 1); d < 10; ++d) {
        explore(val * 10 + d, level + 1);
    }
}

