			if(i==n) break;
			val=nxt(val,n);
		}
		cout<<ans<<endl;
		return 0;
	}

	INT ans=0;
	INT val=1,nth=1;
	int N=n/1000000;
	while(1){
		ans=(ans+D(nth,val))%mod2;
		nth++;
		if(L[val]==L[N]){
			if(val==N){
				ans=(ans+calc(val*10,nth,n))%mod2;
				nth=NTH;
				break;
			}
			INT v=val;
			for(int i=1;i<7;i++){
				v*=10;
				INT del=D(nth-1,v);
				int N=lower_bound(s[i].begin(),s[i].end(),mod1-del)-s[i].begin();
				N=N-s[i].size();
				ans=(ans+sum[i]+1LL*N*mod1%mod2)%mod2;
				ans=(ans+mod2)%mod2;
				ans=(ans+del*s[i].size()%mod2)%mod2;
			}
			nth+=1111110;
		}
		val=nxt(val,N);
	}

	n=1;
	for(int i=1;i<L[N]+6;i++) n*=10;
	n--;
	N=n/1000000;

	val/=10;
	val++;
	while(val%10==0) val/=10;

	while(val!=1){
		ans=(ans+D(nth,val))%mod2;
		nth++;
		if(L[val]==L[N]){
			INT v=val;
			for(int i=1;i<7;i++){
				v*=10;
				INT del=D(nth-1,v);
				int N=lower_bound(s[i].begin(),s[i].end(),mod1-del)-s[i].begin();
				N=N-s[i].size();
				ans=(ans+sum[i]+1LL*N*mod1%mod2)%mod2;
				ans=(ans+mod2)%mod2;
				ans=(ans+del*s[i].size()%mod2)%mod2;
			}
			nth+=1111110;
		}
		val=nxt(val,N);
	}
	cout<<ans<<endl;
	return 0;
}

