const int mod = 998244353;

string toString(__int128_t num) {
    if (not num)
        return "0";
    string res;

    while (num) {
        res += char('0' + num % 10);
        num /= 10;
    }

    std::reverse(ALL(res));
    return res;
}

void solve(vector<int> variables, int base, __int128_t& ans) {
    int cur, until;

    vector<int> rem1, rem2;
    
    std::function<void(int)> brute = [&](int pos) {
        if (pos == until) {
            rem1.push_back(cur);
            return;
        }

        auto oldcur = cur;
        for (int t = 0; t < 10; ++t) {
            brute(pos + 1);
            cur += variables[pos];
            if (cur >= mod)
                cur -= mod;
        }
        cur = oldcur;
    };

    cur = base;
    until = SZ(variables) / 2;
    brute(0);

    rem2 = std::move(rem1);
    cur = 0;
    until = SZ(variables);
    brute(SZ(variables) / 2);

    sort(ALL(rem1));
    sort(ALL(rem2));

    int64_t totalrsum = 0;
    for (int b: rem2)
        totalrsum += b;

    int j = SZ(rem2) - 1;
    for (int a: rem1) {
        while (j >= 0 and a + rem2[j] >= mod)
            --j;

        ans += a * int64_t(SZ(rem2)) + totalrsum - (SZ(rem2) - 1 - j) * int64_t(mod);
    }
}

int64_t pw10[17];

int64_t count_with_prefix(const string& s, int64_t n, const string& n_str) {
    int64_t ans = 0;

    int64_t s_val = 0;
    for (char ch: s)
        s_val = 10 * s_val + ch - '0';
    
    for (int len = SZ(s); len <= SZ(n_str); ++len) {
        if (len < SZ(n_str))
            ans += pw10[len - SZ(s)];
        else {
            int t = strncmp(s.c_str(), n_str.c_str(), SZ(s));
            if (t < 0)
                ans += pw10[len - SZ(s)];
            else if (t == 0) {
                ans += (n + 1) - s_val * pw10[SZ(n_str) - SZ(s)];
            }
        }
    }
    return ans;
}

