    int plen = pre.size();
    int nlen = nstr.size();

    for (int len = plen; len <= nlen; ++len) {
        if (len < nlen) {
            cnt += p10[len - plen];
        } else {
            if (pre < nstr) {
                cnt += p10[len - plen];
            } else if (pre == nstr) {
                cnt += max_n - val * p10[nlen - plen] + 1;
            }
        }
    }
    return cnt;
}

