#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD1 = 998244353, MOD2 = 1000000007, BLOCK = 1000000;
vector<ll> buckets[7];
ll bucketSums[7];
ll N, counter, result;

void buildBuckets(ll cur, int depth) {
    ++counter;
    buckets[depth].push_back((counter - cur + MOD1) % MOD1);
    bucketSums[depth] = (bucketSums[depth] + buckets[depth].back()) % MOD2;
    if (depth == 6) return;
    for (int digit = 0; digit <= 9; ++digit)
        buildBuckets(cur * 10 + digit, depth + 1);
}

void processRange(ll cur) {
    if (cur > N) return;
    if (cur * BLOCK + BLOCK - 1 <= N && cur * BLOCK * 10 > N) {
        ll base = counter;
        for (int d = 0, pow10 = 1; d <= 6; ++d, pow10 *= 10) {
            ll size = buckets[d].size();
            ll diff = ((base - cur * pow10) % MOD1 + MOD1) % MOD1;
            ll idx = lower_bound(buckets[d].begin(), buckets[d].end(), MOD1 - diff) - buckets[d].begin();
            result = (result + diff * size + bucketSums[d]) % MOD2;
            result = (result - (size - idx) * MOD1 % MOD2 + MOD2) % MOD2;
            counter += size;
        }
        return;
    }
    ++counter;
    result = (result + ((counter - cur) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int digit = 0; digit <= 9; ++digit)
        processRange(cur * 10 + digit);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N;
    buildBuckets(0, 0);
    counter = 0;
    for (int i = 0; i <= 6; ++i)
        sort(buckets[i].begin(), buckets[i].end());
    for (int start = 1; start <= 9; ++start)
        processRange(start);
    cout << result << '\n';
    return 0;
}

