using namespace std;
using i64 = long long;
const i64 MOD1 = 998244353LL, MOD2 = 1000000007LL, BLOCK_SIZE = 1000000LL;
vector<i64> digitBuckets[7];
i64 bucketPrefixSums[7];
i64 totalNumbers, globalCounter, answer;

void precompute(i64 currentNumber, int digitCount) {
    ++globalCounter;
    digitBuckets[digitCount].emplace_back((globalCounter - currentNumber + MOD1) % MOD1);
    bucketPrefixSums[digitCount] = (bucketPrefixSums[digitCount] + digitBuckets[digitCount].back()) % MOD2;
    if (digitCount == 6) return;
    for (int nextDigit = 0; nextDigit <= 9; ++nextDigit)
        precompute(currentNumber * 10 + nextDigit, digitCount + 1);
}

void processSubtree(i64 currentNumber) {
    if (currentNumber > totalNumbers) return;
    if (currentNumber * BLOCK_SIZE + BLOCK_SIZE - 1 <= totalNumbers && currentNumber * BLOCK_SIZE * 10 > totalNumbers) {
        i64 offset = globalCounter;
        for (int d = 0, power = 1; d <= 6; ++d, power *= 10) {
            i64 bucketSize = digitBuckets[d].size();
            i64 delta = ((offset - currentNumber * power) % MOD1 + MOD1) % MOD1;
            i64 splitPoint = lower_bound(digitBuckets[d].begin(), digitBuckets[d].end(), MOD1 - delta) - digitBuckets[d].begin();
            answer = (answer + delta * bucketSize + bucketPrefixSums[d]) % MOD2;
            answer = (answer - (bucketSize - splitPoint) * MOD1 % MOD2 + MOD2) % MOD2;
            globalCounter += bucketSize;
        }
        return;
    }
    ++globalCounter;
    answer = (answer + ((globalCounter - currentNumber) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int nextDigit = 0; nextDigit <= 9; ++nextDigit)
        processSubtree(currentNumber * 10 + nextDigit);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> totalNumbers;
    precompute(0, 0);
    globalCounter = 0;
    for (int i = 0; i <= 6; ++i)
        sort(digitBuckets[i].begin(), digitBuckets[i].end());
    for (int firstDigit = 1; firstDigit <= 9; ++firstDigit)
        processSubtree(firstDigit);
    cout << answer << '\n';
    return 0;
}

