using ll = long long;
const ll P1 = 998244353, P2 = 1000000007, B = 1000000;
vector<ll> buckets[7];
ll bucketSum[7];
ll N, ord, res;

void dfs_build(ll cur, int depth) {
    ord++;
    buckets[depth].push_back((ord - cur + P1) % P1);
    bucketSum[depth] = (bucketSum[depth] + buckets[depth].back()) % P2;
    if (depth == 6) return;
    for (int d = 0; d <= 9; ++d) dfs_build(cur * 10 + d, depth + 1);
}

void dfs_query(ll cur) {
    if (cur > N) return;
    if (cur * B + B - 1 <= N && cur * B * 10 > N) {
        ll base = ord;
        for (int d = 0, p = 1; d <= 6; ++d, p *= 10) {
            ll sz = buckets[d].size();
            ll diff = ((base - cur * p) % P1 + P1) % P1;
            ll idx = lower_bound(buckets[d].begin(), buckets[d].end(), P1 - diff) - buckets[d].begin();
            res = (res + diff * sz + bucketSum[d]) % P2;
            res = (res - (sz - idx) * P1 % P2 + P2) % P2;
            ord += sz;
        }
        return;
    }
    ord++;
    res = (res + ((ord - cur) % P1 + P1) % P1) % P2;
    for (int d = 0; d <= 9; ++d) dfs_query(cur * 10 + d);
}

