const int MOD = 998244353, MOD2 = 1000000007;
const int MAX_N = 1000010, BLOCK = 1000000;

ll n, ans;
vector<int> buckets[7];
int bucketSums[7] = {0};
int globalCounter = 0;

inline int modVal(int x) {
    return (x < 0) ? (x + MOD) : x;
}

void buildBuckets(int depth, int suffix) {
    ++globalCounter;
    int val = modVal(globalCounter - suffix);
    buckets[depth].push_back(val);
    bucketSums[depth] = (bucketSums[depth] + val) % MOD2;
    if (depth == 6) return;
    for (int digit = 0; digit <= 9; ++digit) {
        buildBuckets(depth + 1, suffix * 10 + digit);
    }
}

void countValidNumbers(int depth, ll current) {
    if (current > n) return;
    if (current * 10 * BLOCK > n && (current + 1) * BLOCK - 1 <= n) {
        ll u = current;
        for (int i = 0; i <= 6; ++i) {
            ll w = modVal(globalCounter - u);
            ans += w * (ll)buckets[i].size() + bucketSums[i];
            ans -= (ll)(buckets[i].end() - lower_bound(buckets[i].begin(), buckets[i].end(), MOD - w)) * (ll)MOD;
            u = (u * 10) % MOD;
        }
        ans %= MOD2;
        globalCounter = (globalCounter + 1111111) % MOD2;
        return;
    }
    if (depth) {
        globalCounter = (globalCounter + 1) % MOD2;
        ans += modVal(globalCounter - (current % MOD));
    }
    for (int digit = (depth ? 0 : 1); digit <= 9; ++digit) {
        countValidNumbers(depth + 1, current * 10 + digit);
    }
}

