            auto it = lower_bound(data[d].begin(), data[d].end(), need);
            i64 idx = it - data[d].begin();
            i64 sz = data[d].size();
            i64 sum_suffix = 0;
            for (i64 j = idx; j < sz; ++j) sum_suffix = (sum_suffix + data[d][j]) % MOD2;
