        total_ans = (total_ans + ((counter2 - num) % MOD1 + MOD1) % MOD2) % MOD2;
        for (i64 digit = (depth == 0); digit <= 9; ++digit)
            traverse(depth + 1, num * 10 + digit);
    }
}

