#include <bits/stdc++.h>
using namespace std;
using i64 = long long;

const i64 MOD1 = 998244353, MOD2 = 1000000007;

i64 n, final_ans, counterA, counterB;
i64 P[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};
vector<i64> arr[7];

inline char nextByte() {
    static char buf[1000000], *s = buf, *t = buf;
    return s == t && (t = (s = buf) + fread(buf, 1, 1000000, stdin), s == t) ? EOF : *s++;
}

i64 readInt() {
    i64 x = 0;
    char c = nextByte();
    while (c < '0' || c > '9') {
        if (c == '-') x = -1;
        c = nextByte();
    }
    if (x == -1) x = 0;
    else {
        while (c >= '0' && c <= '9') {
            x = x * 10 + c - '0';
            c = nextByte();
        }
    }
    return x;
}

void printInt(i64 x) {
    if (x < 0) { putchar('-'); printInt(-x); return; }
    if (x > 9) printInt(x / 10);
    putchar(x % 10 + '0');
}

void printLine(i64 x) { printInt(x); putchar('\n'); }

bool isSpecial(i64 x) {
    return x * 1000000 + 999999 <= n && x * 10000000 > n;
}

void buildArrays(i64 depth, i64 num) {
    if (depth == 7) return;
    i64 val = (counterA - num % MOD1 + MOD1) % MOD1;
    arr[depth].push_back(val);
    counterA++;
    for (i64 digit = 0; digit <= 9; ++digit)
        buildArrays(depth + 1, num * 10 + digit);
}

void explore(i64 depth, i64 num) {
    if (num > n) return;
    if (isSpecial(num)) {
        for (i64 d = 0; d <= 6; ++d) {
            i64 target = ((counterB + 1 - num * P[d]) % MOD1 + MOD1) % MOD1;
            auto lb = lower_bound(arr[d].begin(), arr[d].end(), target);
            i64 pos = lb - arr[d].begin();
            i64 sz = arr[d].size();
            i64 suffix = 0;
            for (i64 j = pos; j < sz; ++j) suffix = (suffix + arr[d][j]) % MOD2;
            final_ans = (final_ans + suffix + target * (sz - pos) % MOD2) % MOD2;
        }
        counterB += counterA;
    } else {
        counterB++;
        final_ans = (final_ans + ((counterB - num) % MOD1 + MOD1) % MOD2) % MOD2;
        for (i64 digit = (depth == 0); digit <= 9; ++digit)
            explore(depth + 1, num * 10 + digit);
    }
}

int main() {
    n = readInt();
    buildArrays(0, 0);
    for (int i = 0; i <= 6; ++i) sort(arr[i].begin(), arr[i].end());
    counterB = -1;
    explore(0, 0);
    printLine((final_ans % MOD2 + MOD2) % MOD2);
}

