llong phase1_counter = 0;
vector<llong> seq_store[7];
llong prefix_acc[7];

void phase1(int depth, llong cur_val) {
    if (depth == 7) return;
    llong temp_val = (phase1_counter - cur_val + MOD_1) % MOD_1;
    seq_store[depth].push_back(temp_val);
    prefix_acc[depth] += temp_val;
    phase1_counter++;
    for (int d = 0; d <= 9; ++d) {
        phase1(depth + 1, cur_val * 10 + d);
    }
}

bool is_full_block(llong prefix_val) {
    const llong block_size = 1000000LL;
    return prefix_val * block_size + 999999 <= input_n && prefix_val * block_size * 10 > input_n;
}

llong phase2_counter = 0;
const llong ten_pow[7] = {1LL, 10LL, 100LL, 1000LL, 10000LL, 100000LL, 1000000LL};

void phase2(int depth, llong prefix_val) {
    if (prefix_val > input_n) return;
