            llong pos_idx = lb_it - seq_store[len].begin();
            final_ans = (final_ans + prefix_acc[len] + offset_val * (llong)seq_store[len].size() - MOD_1 * ((llong)seq_store[len].size() - pos_idx)) % MOD_2;
