const int BLOCK = 1000000;
const int MOD_A = 998244353;
const int MOD_B = 1000000007;

lli N, counter;
vector<int> groups[7];
int group_totals[7], result, grand_total;

int mod1(lli x) {
    return ((x % MOD_A) + MOD_A) % MOD_A;
}

void generate(int level, lli prefix) {
    counter++;
    groups[level].emplace_back(mod1(counter - prefix));
    if (level == 6) return;
    for (int d = 0; d <= 9; ++d) {
        generate(level + 1, prefix * 10 + d);
    }
}

void traverse(int level, lli current) {
    if (current > N) return;
    if (level >= 1) {
        if (current * BLOCK > N / 10 && (current + 1) * BLOCK - 1 <= N) {
            int factor = 1;
            for (int i = 0; i <= 6; ++i, factor *= 10) {
                int complement = mod1(counter - factor * current);
                auto lb = lower_bound(groups[i].begin(), groups[i].end(), MOD_A - complement);
                int pos = lb - groups[i].begin();
                result = (result + 1LL * complement * (int)groups[i].size() % MOD_B + group_totals[i] - 1LL * MOD_B * ((int)groups[i].size() - pos)) % MOD_B;
            }
            counter += grand_total;
            return;
        }
        counter++;
        result = (result + mod1(counter - current)) % MOD_B;
    }
    for (int d = (level == 0 ? 1 : 0); d <= 9; ++d) {
        traverse(level + 1, current * 10 + d);
    }
}

