constexpr int MOD1 = 998244353;
constexpr int MOD2 = 1000000007;

llong n, counter;
vector<int> digit_groups[7];
int prefix_sums[7], final_answer, total_nodes;

int reduce_mod1(llong x) {
    return static_cast<int>((x % MOD1 + MOD1) % MOD1);
}

void construct(int depth, llong prefix) {
    counter++;
    digit_groups[depth].push_back(reduce_mod1(counter - prefix));
    if (depth == 6) return;
    for (int digit = 0; digit <= 9; ++digit) {
        construct(depth + 1, prefix * 10 + digit);
    }
}

void evaluate(int depth, llong current) {
    if (current > n) return;
    if (depth >= 1) {
        if (current * BLOCK_SIZE > n / 10 && (current + 1) * BLOCK_SIZE - 1 <= n) {
            int power_of_ten = 1;
            for (int i = 0; i <= 6; ++i, power_of_ten *= 10) {
                int value = reduce_mod1(counter - power_of_ten * current);
                int index = lower_bound(digit_groups[i].begin(), digit_groups[i].end(), MOD1 - value) - digit_groups[i].begin();
