        counter++;
        final_answer = (final_answer + reduce_mod1(counter - current)) % MOD2;
    }
    for (int digit = (depth == 0 ? 1 : 0); digit <= 9; ++digit) {
        evaluate(depth + 1, current * 10 + digit);
    }
}

