    scanf("%lld", &n);
    power[0] = 1;
    for (int i = 1; i <= 18; i++) {
        power[i] = power[i-1] * 10 + 1;
    }
    minSteps = INT_MAX;
    search(n, 0);
    printf("%d\n", minSteps);
    return 0;
}

