#include <iostream>
#include <cstdio>
#include <algorithm>
using namespace std;

using llong = long long;

llong result = 0;

int countDigits(llong x) {
    int cnt = 0;
    while (x > 0) {
        x /= 10;
        ++cnt;
    }
    return cnt;
}

llong construct(llong x) {
    int digits = countDigits(x);
    llong cur = 0, base = 1;
    for (int i = 0; i < digits; ++i) {
        cur += base;
        base *= 10;
    }
    if (cur <= x) return cur;
    return (cur - 1) / 10;
}

llong solve(llong x) {
    if (x <= 6) return x;
    if (x <= 11) return 13 - x;

    llong base = construct(x);
    llong nextRep = base * 10 + 1;

    if (x % base == 0) {
        llong factor = x / base;
        if (x <= nextRep / 2 + base) {
            return countDigits(base) * factor;
        } else {
            llong sub = nextRep - x;
            return countDigits(nextRep) + solve(sub);
        }
    } else {
        llong lower = (x / base) * base;
        llong upper = (x / base + 1) * base;
        llong option1 = solve(lower) + solve(x - lower);
        llong option2 = countDigits(upper) + solve(upper - x);
        if (x > nextRep / 2) {
            return min(option1, option2);
        }
        return option1;
    }
}

int main() {
    llong input;
    cin >> input;
    cout << solve(input) << endl;
    return 0;
}

