const int64 BIG = 1000000000000000LL;
const int MAX_VAL = 1000010;

vector<int64> rep_ones;
int min_steps = MAX_VAL;

void recurse(int64 x, int depth) {
    if (depth >= min_steps) return;

    if (x == 0) {
        min_steps = depth;
        return;
    }

    auto it1 = lower_bound(rep_ones.begin(), rep_ones.end(), x);
    auto it2 = upper_bound(rep_ones.begin(), rep_ones.end(), x);

    if (it1 == it2) {
        --it1;
    }

    int64 base_val = *it1;
    int pos = it1 - rep_ones.begin();
    int64 diff_a = x - base_val;
    int64 diff_b = *it2 - x;

    recurse(x % base_val, depth + pos * (x / base_val));
    recurse(diff_b, depth + pos + 1);
}

