    vector<long long> A(17);
    for(int i = 1; i <= 16; ++i)
        A[i] = A[i-1] * 10 + 1;

    function<long long(int, long long)> solve = [&](int ind, long long rem) -> long long {
        if (ind == 0) return rem == 0 ? 0 : LLONG_MAX;
        if (rem < 0) rem = -rem;

        long long m = rem / A[ind];
        long long option1 = solve(ind-1, rem - m * A[ind]) + m * ind;
        long long option2 = solve(ind-1, rem - (m+1) * A[ind]) + (m + 1) * ind;
        return min(option1, option2);
    };

