using namespace std;

using ll = long long;

struct Step {
    ll value;
    int cost;
    bool operator<(const Step& other) const {
        return cost > other.cost;
    }
};

unordered_set<ll> seen;

bool is_seen(ll x) {
    return seen.find(x) != seen.end();
}

Step u_upper(ll n) {
    ll res = 0;
    int cnt = 0;
    while (res < n) {
        res = res * 10 + 1;
        ++cnt;
    }
    return {res, cnt};
}

Step u_upper(ll n, ll& res, int& cnt) {
    res = 0;
    cnt = 0;
    while (res < n) {
        res = res * 10 + 1;
        ++cnt;
    }
    return {res, cnt};
}

Step upper_bound_step(ll n) {
    ll res = 0;
    int cnt = 0;
    while (res * 10 + 1 <= n) {
        res = res * 10 + 1;
        ++cnt;
    }
    ll base = res;
    int base_cnt = cnt;
    while (res < n) {
        res += base;
        cnt += base_cnt;
    }
    return {res, cnt};
}

Step lower_bound_step(ll n) {
    ll res = 0;
    int cnt = 0;
    while (res * 10 + 1 <= n) {
        res = res * 10 + 1;
        ++cnt;
    }
    ll base = res;
    int base_cnt = cnt;
    while (res + base <= n) {
        res += base;
        cnt += base_cnt;
    }
    return {res, cnt};
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    priority_queue<Step> pq;
    pq.push({n, 0});

    while (!pq.empty()) {
        Step cur = pq.top();
        pq.pop();

        if (cur.value == 0) {
            cout << cur.cost << '\n';
            return 0;
        }

        if (is_seen(cur.value)) continue;
        seen.insert(cur.value);

        vector<Step> next_steps;
        next_steps.push_back(lower_bound_step(cur.value));
        next_steps.push_back(upper_bound_step(cur.value));
        next_steps.push_back(u_upper(cur.value));

        for (auto& ns : next_steps) {
            ns.cost += cur.cost;
            ns.value = llabs(cur.value - ns.value);
            pq.push(ns);
        }
    }

    cout << 0 << '\n';
    return 0;
}

#include <iostream>
#include <queue>
#include <unordered_set>
#include <vector>
#include <cmath>
#include <functional>

using namespace std;

using i64 = long long;

struct Node {
    i64 val;
    int steps;
    bool operator<(const Node& other) const {
        return steps > other.steps;
    }
};

unordered_set<i64> history;

bool visited(i64 x) {
    return history.find(x) != history.end();
}

Node gen_uupper(i64 n) {
    i64 x = 0;
    int k = 0;
    while (x < n) {
        x = x * 10 + 1;
        ++k;
    }
    return {x, k};
}

Node gen_upper(i64 n) {
    i64 x = 0;
    int k = 0;
    while (x * 10 + 1 <= n) {
        x = x * 10 + 1;
        ++k;
    }
    i64 base = x;
    int base_k = k;
    while (x < n) {
        x += base;
        k += base_k;
    }
    return {x, k};
}

Node gen_lower(i64 n) {
    i64 x = 0;
    int k = 0;
    while (x * 10 + 1 <= n) {
        x = x * 10 + 1;
        ++k;
    }
    i64 base = x;
    int base_k = k;
    while (x + base <= n) {
        x += base;
        k += base_k;
    }
    return {x, k};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 target;
    cin >> target;

    priority_queue<Node> heap;
    heap.push({target, 0});

    while (!heap.empty()) {
        Node cur = heap.top();
        heap.pop();

        if (cur.val == 0) {
            cout << cur.steps << '\n';
            return 0;
        }

        if (visited(cur.val)) continue;
        history.insert(cur.val);

        vector<Node> options;
        options.push_back(gen_lower(cur.val));
        options.push_back(gen_upper(cur.val));
        options.push_back(gen_uupper(cur.val));

        for (auto& opt : options) {
            opt.steps += cur.steps;
            opt.val = std::abs(cur.val - opt.val);
            heap.push(opt);
        }
    }

    cout << 0 << '\n';
    return 0;
}

