        long long cost1 = q * (idx + 1) + dp(idx - 1, x - q * cand[idx]);
        long long cost2 = r * (idx + 1) + dp(idx - 1, x - r * cand[idx]);
        return cost1 <= cost2 ? cost1 : cost2;
    };

