    if (val <= 11) return min(13 - val, val);
    if (memo.find(val) != memo.end()) return memo[val];
    i64 n = 0, limit = 1;
    while (limit < val) {
        limit *= 10;
        limit += 1;
        ++n;
    }
    if (val * 2 >= limit) {
        i64 option1 = process(limit - val) + n + 1;
        i64 base = limit / 10;
        i64 option2 = (val / base) * n + process(val % base);
        return memo[val] = min(option1, option2);
    }
    i64 base = limit / 10;
    return memo[val] = (val / base) * n + process(val % base);
}

