typedef long long ll;

int digitCount(ll x) {
    int cnt = 0;
    while (x > 0) {
        x /= 10;
        ++cnt;
    }
    return cnt;
}

ll largestRepunit(ll x) {
    int d = digitCount(x);
    ll res = 0;
    for (int i = 0; i < d; ++i) {
        res = res * 10 + 1;
    }
    if (res <= x) return res;
    return res / 10;
}

ll solve(ll x) {
    if (x <= 6) return x;
    if (x <= 11) return 13 - x;

    ll rep = largestRepunit(x);
    ll nextRep = rep * 10 + 1;

    if (x % rep == 0) {
        if (x <= nextRep / 2 + rep) {
            return digitCount(rep) * x / rep;
        }
        return digitCount(nextRep) + solve(nextRep - x);
    } else {
        ll base = (x / rep) * rep;
        ll option1 = solve(base) + solve(x - base);
        ll option2 = digitCount(nextRep) + solve(nextRep - x);
        if (x > nextRep / 2) {
            return min(option1, option2);
        }
        return option1;
    }
}

