using llong = long long;

int countDigits(llong x) {
    if (x == 0) return 1;
    int cnt = 0;
    while (x) {
        ++cnt;
        x /= 10;
    }
    return cnt;
}

llong repunit(llong n) {
    int d = countDigits(n);
    llong res = 0;
    for (int i = 0; i < d; ++i) {
        res = res * 10 + 1;
    }
    return (res <= n) ? res : res / 10;
}

llong compute(llong n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;

    llong r = repunit(n);
    llong rNext = r * 10 + 1;

    if (n % r == 0) {
        if (n <= rNext / 2 + r) {
            return countDigits(r) * n / r;
        }
        return countDigits(rNext) + compute(rNext - n);
    } else {
        llong base = (n / r) * r;
        llong val1 = compute(base) + compute(n - base);
        llong val2 = countDigits(rNext) + compute(rNext - n);
        if (n > rNext / 2) {
            return val1 < val2 ? val1 : val2;
        }
        return val1;
    }
}

