lint repunit_number(lint n) {
    int d = digit_count(n);
    lint u = 0;
    for (int i = 0; i < d; ++i) u = u * 10 + 1;
    return (u <= n) ? u : u / 10;
}

lint minimal_steps(lint n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;

    lint u = repunit_number(n);
    lint v = u * 10 + 1;

    if (n % u == 0) {
        if (n <= v / 2 + u) {
            return digit_count(u) * n / u;
        }
        return digit_count(v) + minimal_steps(v - n);
    } else {
        lint base = (n / u) * u;
        lint option1 = minimal_steps(base) + minimal_steps(n - base);
        lint option2 = digit_count(v) + minimal_steps(v - n);
        if (n > v / 2) {
            return min(option1, option2);
        }
        return option1;
    }
}

