using namespace std;

#define FOR(i,a,b) for(int i=(a); i<(b); ++i)
#define REP(i,n) FOR(i,0,n)

#define sz(s) ((int)(s).size())

typedef long long ll;

string input, output;
int n;

void finalize() {
    if (!output.empty()) {
        if (output[0] == '.') {
            output = "dot" + output.substr(1);
        }
        else if (output[0] == '@') {
            output = "at" + output.substr(1);
        }

        if (output.back() == '.') {
            output.pop_back();
            output += "dot";
        }
        else if (output.back() == '@') {
            output.pop_back();
            output += "at";
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> input;
    n = input.length();
    output = "";

    for (int i = 0; i < n; ++i) {
        if (i + 3 <= n && input.substr(i, 3) == "dot") {
            output += '.';
            i += 2;
        }
        else if (i + 2 <= n && input.substr(i, 2) == "at") {
            output += '@';
            i += 1;
        }
        else {
            output += input[i];
        }
    }

    finalize();

    int atCount = 0;
    for (char c : output) {
        if (c == '@') atCount++;
    }

    if (atCount == 1) {
        cout << output << '\n';
    }
    else {
        bool first = true;
        for (char c : output) {
            if (c == '@') {
                if (first) {
                    cout << '@';
                    first = false;
                }
                else {
                    cout << "at";
                }
            }
            else {
                cout << c;
            }
        }
        cout << '\n';
    }

    return 0;
}

