using namespace std;

#define FOR(i,a,b) for(int i=(a); i<(b); ++i)
#define REP(i,n) FOR(i,0,n)

#define sz(s) ((int)(s).size())

typedef long long ll;

string input_str, result_str;
int input_len;

void post_transform() {
    if (!result_str.empty()) {
        if (result_str[0] == '.') {
            result_str = "dot" + result_str.substr(1);
        }
        else if (result_str[0] == '@') {
            result_str = "at" + result_str.substr(1);
        }

        if (!result_str.empty() && result_str[result_str.size()-1] == '.') {
            result_str.erase(result_str.size()-1, 1);
            result_str += "dot";
        }
        else if (!result_str.empty() && result_str[result_str.size()-1] == '@') {
            result_str.erase(result_str.size()-1, 1);
            result_str += "at";
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> input_str;
    input_len = input_str.length();
    result_str = "";

    for (int i = 0; i < input_len; ++i) {
        if (i + 3 <= input_len && input_str.substr(i, 3) == "dot") {
            result_str += '.';
            i += 2;
        }
        else if (i + 2 <= input_len && input_str.substr(i, 2) == "at") {
            result_str += '@';
            i += 1;
        }
        else {
            result_str += input_str[i];
        }
    }

    post_transform();

    int at_count = 0;
    for (char c : result_str) {
        if (c == '@') ++at_count;
    }

    if (at_count == 1) {
        cout << result_str << '\n';
    }
    else {
        bool first_occurrence = true;
        for (char c : result_str) {
            if (c == '@') {
                if (first_occurrence) {
                    cout << '@';
                    first_occurrence = false;
                }
                else {
                    cout << "at";
                }
            }
            else {
                cout << c;
            }
        }
        cout << '\n';
    }

    return 0;
}

