string transformEmail(const string& s) {
    string result = s;

    // Find and replace "at" (not at beginning)
    for (int i = 1; i + 1 < (int)result.size(); ++i) {
        if (result[i] == 'a' && result[i+1] == 't') {
            result.erase(i, 2);
            result.insert(i, "@");
            break;
        }
