    // Find and replace all "dot" sequences (not at start and not at end)
    for (int i = 1; i + 2 < (int)result.size(); ++i) {
        while (i + 2 < (int)result.size() && 
               result[i] == 'd' && result[i+1] == 'o' && result[i+2] == 't') {
            if (i + 3 < (int)result.size()) {
                result.erase(i, 3);
                result.insert(i, ".");
                i += 1; // skip past the dot to avoid infinite loop
            } else {
                break;
            }
        }
    }

    return result;
}

