string transformString(const string& s) {
    if (s.empty()) return "";
    string out;
    out.reserve(s.size());
    out.push_back(s[0]);

    bool atReplaced = false;
    size_t n = s.size();
    for (size_t i = 1; i < n; ) {
        bool consumed = false;
        if (i + 1 < n && s[i] == 'a' && s[i+1] == 't') {
            if (i + 1 == n - 1) {
                out.push_back(s[i]);
                out.push_back(s[i+1]);
                i += 2;
            } else {
                if (!atReplaced) {
                    i += 2;
                    out.push_back('@');
                    atReplaced = true;
                } else {
                    out.push_back(s[i]);
                    out.push_back(s[i+1]);
                    i += 2;
                }
            }
            consumed = true;
        } else if (i + 2 < n && s[i] == 'd' && s[i+1] == 'o' && s[i+2] == 't') {
            if (i + 2 == n - 1) {
                out.push_back(s[i]);
                out.push_back(s[i+1]);
                out.push_back(s[i+2]);
                i += 3;
            } else {
                i += 3;
                out.push_back('.');
            }
            consumed = true;
        }
        if (!consumed) {
            out.push_back(s[i]);
            ++i;
        }
    }
    return out;
}

