    std::string input;
    std::cin >> input;

    std::vector<std::string> outputs;
    std::string buffer = "";
    buffer += input[0];
    outputs.push_back(buffer);

    int at_counter = 0;

    for (size_t idx = 1; idx < input.length() - 1; ++idx) {
        std::string candidate3, candidate2;

        if (idx + 2 < input.length() - 1) {
            candidate3 = input.substr(idx, 3);
        }
        if (idx + 1 < input.length() - 1) {
            candidate2 = input.substr(idx, 2);
        }

        if (candidate3 == "dot") {
            buffer += '.';
            for (auto& line : outputs) line += '.';
            idx += 2;
        } else if (candidate2 == "at") {
            at_counter++;
            for (int k = 0; k < at_counter - 1; ++k) outputs[k] += "at";
            for (int k = at_counter - 1; k < (int)outputs.size(); ++k) outputs[k] += '@';
            buffer += input[idx];
            buffer += input[idx+1];
            outputs.push_back(buffer);
            idx += 1;
        } else {
            buffer += input[idx];
            for (auto& line : outputs) line += input[idx];
        }
    }

    for (auto& line : outputs) line += input[input.length()-1];

    std::sort(outputs.begin(), outputs.end());
    std::cout << outputs[0];

    return 0;
}

