int main() {
    string s;
    cin >> s;
    int n = s.length();
    int j = 0;

    // Process character by character with lookahead
    while (j < n) {
        // Check for "dot"
        if (j + 2 < n && s.substr(j, 3) == "dot") {
            if (j == 0 || j + 3 == n) {
                cout << "dot";
                j += 3;
            } else {
                cout << '.';
                j += 3;
            }
        }
        // Check for "at"
        else if (j + 1 < n && s.substr(j, 2) == "at") {
            if (j == 0 || j + 2 == n) {
                cout << "at";
                j += 2;
            } else {
                cout << '@';
                j += 2;
            }
        }
        // Default case: print current character
        else {
            cout << s[j];
            ++j;
        }
    }
    return 0;
}

