using namespace std;

int main() {
    string s;
    cin >> s;
    string result;
    bool replaced_at = false;
    int i = 0, n = s.length();

    while (i < n) {
        // Check for "@@@" pattern (actually 'a' followed by 't')
        if (i > 0 && i + 1 < n && !replaced_at && s[i] == 'a' && s[i+1] == 't') {
            result += '@';
            replaced_at = true;
            i += 2; // consume both 'a' and 't'
        }
        // Check for ".dot" pattern (actually 'd', 'o', 't')
        else if (i > 0 && i + 2 < n && s[i] == 'd' && s[i+1] == 'o' && s[i+2] == 't') {
            result += '.';
            i += 3; // consume 'd', 'o', 't'
        }
        else {
            result += s[i];
            i += 1;
        }
    }

    cout << result << endl;
    return 0;
}

