int main() {
    char buf[2101];
    cin >> buf;
    int len = strlen(buf);

    // Process "dot" -> "."
    for (int i = 1; i < len - 3; i++) {
        if (buf[i] == 'd' && buf[i+1] == 'o' && buf[i+2] == 't') {
            buf[i] = '.';
            buf[i+1] = buf[i+2] = '\0';
            memmove(buf + i + 1, buf + i + 3, len - i - 2);
            len -= 2;
            i += 2;
        }
    }

    // Process "at" -> "@"
    for (int i = 1; i < len - 1; i++) {
        if (buf[i] == 'a' && buf[i+1] == 't') {
            buf[i] = '@';
            buf[i+1] = '\0';
            memmove(buf + i + 1, buf + i + 2, len - i - 1);
            len -= 1;
            break;
        }
    }

    // Output result
    cout << buf << endl;
    return 0;
}

