template<unsigned int N>
class Field {
    typedef unsigned int ui;
    typedef unsigned long long ull;

    inline ui pow(ui a, ui p) {
        ui r = 1, e = a;
        while (p) {
            if (p & 1) r = ((ull)r * e) % N;
            e = ((ull)e * e) % N;
            p >>= 1;
        }
        return r;
    }

    inline ui inv(ui a) {
        return pow(a, N - 2);
    }

public:
    inline Field(int x = 0) : v(x) {}

    inline Field<N> pow(int p) {
        return (*this) ^ p;
    }

    inline Field<N> operator^(int p) {
        return { (int)pow(v, (ui)p) };
    }

    inline Field<N>& operator+=(const Field<N>& o) {
        if (v + o.v >= N) v += o.v - N;
        else v += o.v;
        return *this;
    }

    inline Field<N>& operator-=(const Field<N>& o) {
        if (v < o.v) v -= o.v - N;
        else v -= o.v;
        return *this;
    }

    inline Field<N>& operator*=(const Field<N>& o) {
        v = (ull)v * o.v % N;
        return *this;
    }

    inline Field<N>& operator/=(const Field<N>& o) {
        return *this *= inv(o.v);
    }

    inline Field<N> operator+(const Field<N>& o) const {
        Field<N> r(*this);
        return r += o;
    }

    inline Field<N> operator-(const Field<N>& o) const {
        Field<N> r(*this);
        return r -= o;
    }

    inline Field<N> operator*(const Field<N>& o) const {
        Field<N> r(*this);
        return r *= o;
    }

    inline Field<N> operator/(const Field<N>& o) const {
        Field<N> r(*this);
        return r /= o;
    }

    inline Field<N> operator-() {
        if (v) return { (int)(N - v) };
        else return { 0 };
    }

    inline Field<N>& operator++() {
        ++v;
        if (v == N) v = 0;
        return *this;
    }

    inline Field<N> operator++(int) {
        Field<N> r(*this);
        ++*this;
        return r;
    }

    inline Field<N>& operator--() {
        --v;
        if (v == (unsigned int)(-1)) v = N - 1;
        return *this;
    }

    inline Field<N> operator--(int) {
        Field<N> r(*this);
        --*this;
        return r;
    }

    inline bool operator==(const Field<N>& o) const {
        return o.v == v;
    }

    inline bool operator!=(const Field<N>& o) const {
        return o.v != v;
    }

    inline explicit operator ui() const {
        return v;
    }

    inline static vector<Field<N>> fact(int t) {
        vector<Field<N>> F(t + 1, 1);
        for (int i = 2; i <= t; ++i) {
            F[i] = F[i - 1] * i;
        }
        return F;
    }

    inline static vector<Field<N>> invfact(int t) {
        vector<Field<N>> F(t + 1, 1);
        Field<N> X{ 1 };
        for (int i = 2; i <= t; ++i) {
            X = X * i;
        }
        F[t] = 1 / X;
        for (int i = t - 1; i >= 2; --i) {
            F[i] = F[i + 1] * (i + 1);
        }
        return F;
    }

private:
