template<typename T, typename F>
T bsh(T l, T h, const F& f) {
    T r = -1, m;
    while (l <= h) {
        m = (l + h) / 2;
        if (f(m)) {
            l = m + 1;
            r = m;
        } else {
            h = m - 1;
        }
    }
    return r;
}

template<typename F>
double bshd(double l, double h, const F& f, double p = 1e-9) {
    unsigned int r = 3 + (unsigned int)log2((h - l) / p);
    while (r--) {
        double m = (l + h) / 2;
        if (f(m)) {
            l = m;
        } else {
            h = m;
        }
    }
    return (l + h) / 2;
}

