using namespace std;

const int MOD = 1000000007;

int add_mod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int sub_mod(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}

int mul_mod(int a, int b) {
    return (long long)a * b % MOD;
}

int pow_mod(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = mul_mod(result, base);
        base = mul_mod(base, base);
        exp >>= 1;
    }
    return result;
}

int inv_mod(int a) {
    return pow_mod(a, MOD - 2);
}

int div_mod(int a, int b) {
    return mul_mod(a, inv_mod(b));
}

int main() {
#ifdef LOCAL
    freopen("input.in", "r", stdin);
    freopen("output.out", "w", stdout);
#endif

    int n;
    scanf("%d", &n);

    vector<vector<int>> a(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            scanf("%d", &a[i][j]);
            a[i][j] = div_mod(a[i][j], 100);
        }
    }

    struct State {
        vector<char> masks;
        int value;
    };

    vector<State> current = {{{0}, 1}};

    for (int g = 0; g < n; ++g) {
        vector<State> next;

        for (int mask = 0; mask < (1 << n); ++mask) {
            int prob = 1;
            for (int j = 0; j < n; ++j) {
                if (mask & (1 << j)) {
                    prob = mul_mod(prob, a[j][g]);
                } else {
                    prob = mul_mod(prob, sub_mod(1, a[j][g]));
                }
            }

            for (const auto& state : current) {
                vector<char> new_masks;
                for (char mask2 : state.masks) {
                    int remaining = ~mask2 & mask;
                    while (remaining) {
                        int pos = remaining & -remaining;
                        new_masks.push_back(mask2 | pos);
                        remaining ^= pos;
                    }
                }

                if (new_masks.empty()) continue;
                sort(new_masks.begin(), new_masks.end());
                new_masks.erase(unique(new_masks.begin(), new_masks.end()), new_masks.end());

                next.push_back({new_masks, mul_mod(state.value, prob)});
            }
        }

        sort(next.begin(), next.end(), [](const State& a, const State& b) {
            return a.masks < b.masks;
        });

        current.clear();
        for (int i = 0; i < (int)next.size(); ) {
            int j = i;
            int total = 0;
            while (j < (int)next.size() && next[j].masks == next[i].masks) {
                total = add_mod(total, next[j].value);
                ++j;
            }
            current.push_back({next[i].masks, total});
            i = j;
        }
    }

    int result = 0;
    for (const auto& state : current) {
        result = add_mod(result, state.value);
    }

    cout << result << "\n";
    return 0;
}

