using namespace std;

constexpr int MOD = 1000000007;

int add(int a, int b) { return (a += b) >= MOD ? a - MOD : a; }
int sub(int a, int b) { return (a -= b) < 0 ? a + MOD : a; }
int mul(long long a, long long b) { return a * b % MOD; }
int binpow(int a, int e) {
    int r = 1;
    while (e) {
        if (e & 1) r = mul(r, a);
        a = mul(a, a);
        e >>= 1;
    }
    return r;
}
int modinv(int a) { return binpow(a, MOD - 2); }
int divide(int a, int b) { return mul(a, modinv(b)); }

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

#ifdef LOCAL
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int n;
    cin >> n;

    vector<vector<int>> mat(n, vector<int>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> mat[i][j];
            mat[i][j] = divide(mat[i][j], 100);
        }

    using State = pair<vector<char>, int>;
    vector<State> dp = {{{0}, 1}};

    for (int col = 0; col < n; ++col) {
        vector<State> nxt;

        for (int bitmask = 0; bitmask < (1 << n); ++bitmask) {
            int p = 1;
            for (int i = 0; i < n; ++i)
                p = mul(p, (bitmask >> i & 1) ? mat[i][col] : sub(1, mat[i][col]));

            for (const auto& [maskvec, coef] : dp) {
                vector<char> nmasks;
                for (char base : maskvec) {
                    int rem = bitmask ^ (base & bitmask);
                    while (rem) {
                        int low = rem & -rem;
                        nmasks.push_back(base | low);
                        rem ^= low;
                    }
                }
                if (nmasks.empty()) continue;
                sort(nmasks.begin(), nmasks.end());
                nmasks.erase(unique(nmasks.begin(), nmasks.end()), nmasks.end());
                nxt.emplace_back(nmasks, mul(coef, p));
            }
        }

        sort(nxt.begin(), nxt.end());
        dp.clear();

        for (int i = 0; i < (int)nxt.size(); ) {
            int j = i;
            int sum = 0;
            while (j < (int)nxt.size() && nxt[j].first == nxt[i].first)
                sum = add(sum, nxt[j++].second);
            dp.emplace_back(nxt[i].first, sum);
            i = j;
        }
    }

    int ans = 0;
    for (const auto& [_, coef] : dp) ans = add(ans, coef);
    cout << ans << "\n";
    return 0;
}

