    if (x >= MOD) x -= MOD;
    return x;
}

int subtract(int x, int y) {
    x -= y;
    if (x < 0) x += MOD;
    return x;
}

int multiply(int x, int y) {
    return static_cast<int>(1LL * x * y % MOD);
}

int mod_exp(int base, int exp) {
    int result = 1;
    while (exp) {
        if (exp & 1) result = multiply(result, base);
        base = multiply(base, base);
        exp >>= 1;
    }
    return result;
}

int mod_inverse(int a) {
    return mod_exp(a, MOD - 2);
}

int divide_mod(int a, int b) {
    return multiply(a, mod_inverse(b));
}

int main() {
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int n;
    scanf("%d", &n);

    std::vector<std::vector<int>> grid(n, std::vector<int>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            scanf("%d", &grid[i][j]);
            grid[i][j] = divide_mod(grid[i][j], 100);
        }

    std::vector<std::pair<std::vector<char>, int>> states;
    states.reserve(1024);
    states.emplace_back(std::vector<char>{0}, 1);

    for (int col = 0; col < n; ++col) {
        std::vector<std::pair<std::vector<char>, int>> next_states;
        next_states.reserve(4096);

        for (int mask = 0; mask < (1 << n); ++mask) {
            int prob = 1;
            for (int j = 0; j < n; ++j) {
                if (mask & (1 << j))
                    prob = multiply(prob, grid[j][col]);
                else
                    prob = multiply(prob, subtract(1, grid[j][col]));
            }

            for (const auto& [old_masks, coeff] : states) {
                std::vector<char> new_masks;
                new_masks.reserve(old_masks.size() * __builtin_popcount(mask));

                for (char b : old_masks) {
                    int remaining = mask ^ (b & mask);
                    while (remaining) {
                        int bit = remaining & -remaining;
                        new_masks.push_back(b | bit);
                        remaining ^= bit;
                    }
                }

                if (new_masks.empty()) continue;

                std::sort(new_masks.begin(), new_masks.end());
                new_masks.erase(std::unique(new_masks.begin(), new_masks.end()), new_masks.end());
                next_states.emplace_back(std::move(new_masks), multiply(coeff, prob));
            }
        }

        std::sort(next_states.begin(), next_states.end(),
            [](const auto& a, const auto& b) {
                return a.first < b.first;
            });

        states.clear();
        int idx = 0;
        while (idx < (int)next_states.size()) {
            int j = idx;
            int sum_coeff = 0;
            auto& base = next_states[idx].first;
            while (j < (int)next_states.size() && next_states[j].first == base)
                sum_coeff = add(sum_coeff, next_states[j++].second);
            states.emplace_back(base, sum_coeff);
            idx = j;
        }
    }

    int result = 0;
    for (const auto& [_, coeff] : states)
        result = add(result, coeff);
    printf("%d\n", result);
    return 0;
}

