inline int add_(int x, int y) { x += y; if (x >= MOD) x -= MOD; return x; }
inline int sub_(int x, int y) { x -= y; if (x < 0) x += MOD; return x; }
inline int mul_(int64 x, int64 y) { return (x * y) % MOD; }

int binpow_(int b, int e) {
    int r = 1;
    while (e) {
        if (e & 1) r = mul_(r, b);
        b = mul_(b, b);
        e >>= 1;
    }
