#include <algorithm>
#include <memory>
#include <iomanip>
using namespace std;

using state_t = bitset<128>;

namespace detail {
    const int MOD = 1000000007;

    struct memoizer {
        unordered_map<state_t, int> mapping;
        vector<vector<int>> transitions;
        int counter = 0;

        int get_or_create(const state_t& s) {
            auto it = mapping.find(s);
            if (it != mapping.end()) return it->second;

            int id = counter++;
            mapping[s] = id;

            state_t derived[7] = {};
            for (int i = 0; i < N; ++i) {
                for (int j = 0; j < (1 << N); ++j) {
                    if (j >> i & 1) continue;
                    derived[i][j | (1 << i)] = derived[i][j] | s[j];
                }
            }

            transitions[id].resize(128);
            for (int mask = 0; mask < (1 << N); ++mask) {
                state_t curr = s;
                for (int bit = 0; bit < N; ++bit) {
                    if (mask >> bit & 1) curr |= derived[bit];
                }
                transitions[id][mask] = get_or_create(curr);
            }

            return id;
        }
    };
}

int N, P[7][7], inv100;
int dp[2][70003];

int modpow(long long base, int exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % detail::MOD;
        base = (base * base) % detail::MOD;
        exp >>= 1;
    }
    return (int)result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N;

    detail::memoizer m;
    m.transitions.resize(70003);
    state_t init;
    init.set(0);
    m.get_or_create(init);

    inv100 = modpow(100, detail::MOD - 2);

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            cin >> P[i][j];

    int cur = 0;
    fill(dp[cur], dp[cur] + 70003, 0);
    dp[cur][1] = 1;

    vector<int> probs(1 << N);

    for (int stage = 0; stage < N; ++stage) {
        for (int mask = 0; mask < (1 << N); ++mask) {
            probs[mask] = 1;
            for (int k = 0; k < N; ++k) {
                int val = (mask >> k & 1) ? P[stage][k] : (100 - P[stage][k]);
                probs[mask] = (long long)probs[mask] * inv100 % detail::MOD * val % detail::MOD;
            }
        }

        fill(dp[cur ^ 1], dp[cur ^ 1] + 70003, 0);
        for (int s = 1; s <= m.counter; ++s) {
            if (!dp[cur][s]) continue;
            for (int mask = 0; mask < (1 << N); ++mask) {
                dp[cur ^ 1][m.transitions[s][mask]] = 
                    (dp[cur ^ 1][m.transitions[s][mask]] + 
                     (long long)dp[cur][s] * probs[mask]) % detail::MOD;
            }
        }
        cur ^= 1;
    }

    state_t full;
    full.flip();
    cout << dp[cur][m.mapping[full]] << '\n';

    return 0;
}

#include <iostream>
