using namespace io;

struct ModInt {
    int val;

    ModInt() : val(0) {}
    ModInt(ll v) : val((v % MOD + MOD) % MOD) {}

    explicit operator int() const { return val; }

    ModInt& operator+=(const ModInt& o) {
        val = (val + o.val) % MOD;
        return *this;
    }

    ModInt& operator-=(const ModInt& o) {
        val = (val - o.val + MOD) % MOD;
        return *this;
    }

    ModInt& operator*=(const ModInt& o) {
        val = (ll)val * o.val % MOD;
        return *this;
    }

    ModInt& operator/=(const ModInt& o) {
        return *this *= o.inv();
    }

    ModInt operator-() const { return ModInt(-val); }

    ModInt inv() const {
        return pow(*this, MOD - 2);
    }

    static ModInt pow(ModInt base, ll exp) {
        ModInt res = 1;
        while (exp > 0) {
            if (exp & 1) res *= base;
            base *= base;
            exp >>= 1;
        }
        return res;
    }
};

using mi = ModInt;

int main() {
    setIO();

    int n;
    read(n);

    vector<vector<mi>> p(n, vector<mi>(n));
    F0R(i, n) F0R(j, n) {
        double tmp;
        read(tmp);
        p[i][j] = (int)(tmp / 100.0 * MOD + 0.5);
    }

    vector<unsigned long long> no(n, 0);
    F0R(i, n) {
        F0R(j, 1 << n) {
            if (!(j & (1 << i))) {
                no[i] |= (1ULL << j);
            }
        }
    }

    unordered_map<unsigned long long, mi> dp;
    dp[1] = 1;

    F0R(i, n) {
        unordered_map<unsigned long long, mi> new_dp;
        for (auto& [mask, prob] : dp) {
            F0R(j, 1 << n) {
                unsigned long long res = 0;
                mi cur_prob = 1;
                F0R(k, n) {
                    if (j & (1 << k)) {
                        cur_prob *= p[i][k];
                        res |= (mask & no[k]) << (1ULL << k);
                    } else {
                        cur_prob *= (1 - p[i][k]);
                    }
                }
                new_dp[res] += prob * cur_prob;
            }
        }
        dp.swap(new_dp);
    }

    writeln(dp[1ULL << ((1 << n) - 1)]);

    return 0;
}

