struct Mod {
    int v;
    Mod() : v(0) {}
    Mod(int _v) : v(norm(_v)) {}
    explicit operator int() const { return v; }

    static int norm(int x) {
        if (x < 0) x += MOD;
        if (x >= MOD) x -= MOD;
        return x;
    }

    Mod& operator+=(const Mod& o) { v = norm(v + o.v); return *this; }
    Mod& operator-=(const Mod& o) { v = norm(v - o.v); return *this; }
    Mod& operator*=(const Mod& o) { v = (int)(1LL * v * o.v % MOD); return *this; }
    Mod& operator/=(const Mod& o) { return *this *= o.inv(); }

    Mod operator-() const { return Mod(-v); }

    Mod inv() const {
        int a = v, b = MOD, x = 0, y = 1;
        while (a > 1) {
            int q = a / b;
            int t = b; b = a % b; a = q;
            t = x; x = y - q * x; y = t;
        }
        if (y < 0) y += MOD;
        return Mod(y);
    }

    friend Mod pow(Mod a, i64 e) {
        Mod res = 1;
        while (e > 0) {
            if (e & 1) res *= a;
            a *= a;
            e >>= 1;
        }
        return res;
    }

    friend Mod operator+(Mod a, const Mod& b) { return a += b; }
    friend Mod operator-(Mod a, const Mod& b) { return a -= b; }
    friend Mod operator*(Mod a, const Mod& b) { return a *= b; }
    friend Mod operator/(Mod a, const Mod& b) { return a /= b; }
};

using mi = Mod;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<mi>> prob(n, vector<mi>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            double x;
            cin >> x;
            prob[i][j] = (int)(x / 100.0 * MOD + 0.5);
        }
    }

    vector<unsigned long long> mask_for_player(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < (1 << n); ++j) {
            if (!(j & (1 << i))) {
                mask_for_player[i] |= (1ULL << j);
            }
        }
    }

    unordered_map<unsigned long long, mi> dp;
    dp[1] = mi(1);

    for (int round = 0; round < n; ++round) {
        unordered_map<unsigned long long, mi> ndp;
        for (auto& [state, cur_prob] : dp) {
            for (int outcome = 0; outcome < (1 << n); ++outcome) {
                unsigned long long next_state = 0;
                mi p = mi(1);
                for (int k = 0; k < n; ++k) {
                    if (outcome & (1 << k)) {
                        p *= prob[round][k];
                        next_state |= (state & mask_for_player[k]) << (1ULL << k);
                    } else {
                        p *= (mi(1) - prob[round][k]);
                    }
                }
                ndp[next_state] += cur_prob * p;
            }
        }
        dp = move(ndp);
    }

    cout << dp[1ULL << ((1 << n) - 1)].v << "\n";

    return 0;
}

