struct Mint {
    int x;
    Mint(int v = 0) : x(norm(v)) {}
    static int norm(int v) {
        if (v < 0) v += MOD;
        if (v >= MOD) v -= MOD;
        return v;
    }
    Mint& operator+=(const Mint& o) { x = norm(x + o.x); return *this; }
    Mint& operator-=(const Mint& o) { x = norm(x - o.x); return *this; }
    Mint& operator*=(const Mint& o) { x = (int)(1LL * x * o.x % MOD); return *this; }
