struct Mod {
    int v;
    Mod() : v(0) {}
    Mod(int x) : v(x % MOD) { if (v < 0) v += MOD; }
    explicit operator int() const { return v; }

    Mod& operator+=(const Mod& o) { v = (v + o.v) % MOD; return *this; }
