template <typename T>
T modPow(T base, T exp, T modulus) {
    T result = 1;
    base %= modulus;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exp >>= 1;
    }
    return result;
}

class StateManager {
public:
    int n;
    int stateCount;
    vector<bitset<128>> states;
    unordered_map<string, int> stateIndex;
    vector<int> maxMatchList;

    StateManager(int n) : n(n), stateCount(0) {
        bitset<128> initial;
        initial.reset();
        initial[0] = 1;
        addState(initial);
    }

    void addState(const bitset<128>& state) {
        string key;
        key.reserve(16);
        for (int i = 0; i < 16; ++i) {
            key.push_back((char)state.to_ullong());
        }
        if (!stateIndex.count(key)) {
            stateIndex[key] = stateCount;
            states.push_back(state);
            stateCount++;
        }
    }

    int getStateId(const bitset<128>& state) {
        string key;
        key.reserve(16);
        for (int i = 0; i < 16; ++i) {
            key.push_back((char)state.to_ullong());
        }
        return stateIndex[key];
    }
};

void precompute(int n, StateManager& sm) {
    int N = 1 << n;
    vector<bitset<128>> fixedSize(n + 1);
    for (int i = 0; i <= n; ++i) {
        fixedSize[i].reset();
    }

    for (int mask = 0; mask < N; ++mask) {
        int cnt = __builtin_popcount(mask);
        fixedSize[cnt].set(mask);
    }

    vector<vector<int>> nextTable(N);
    sm.maxMatchList.resize(100000, -1);

    for (int k = 0; k < sm.stateCount; ++k) {
        bitset<128> state = sm.states[k];
        vector<bitset<128>> predHall(n);

        for (int mask = 0; mask < N; ++mask) {
            if (state.test(mask)) {
                for (int i = 0; i < n; ++i) {
                    predHall[i].set(mask | (1 << i));
                }
            }
        }

        nextTable[k].resize(N);
        for (int mask = 0; mask < N; ++mask) {
            bitset<128> next = state;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    next |= predHall[i];
                }
            }
            nextTable[k][mask] = sm.getStateId(next);
        }

        for (int i = n; i >= 0; --i) {
            if ((state & fixedSize[i]).any()) {
                sm.maxMatchList[k] = i;
                break;
            }
        }
    }

    sm.transitionTable = nextTable;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n;
    m = n;

    StateManager sm(n);
    precompute(n, sm);

    vector<vector<i64>> p(n, vector<i64>(m));
    i64 inv100 = modPow<i64>(100, MOD - 2, MOD);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            i64 x;
            cin >> x;
            p[i][j] = (x * inv100) % MOD;
        }
    }

    int totalStates = sm.stateCount;
    vector<i64> prevState(totalStates, 0);
    prevState[0] = 1;

    int N = 1 << n;
    for (int col = 0; col < m; ++col) {
        vector<i64> curState(totalStates, 0);
        for (int mask = 0; mask < N; ++mask) {
            i64 prob = 1;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    prob = (prob * p[i][col]) % MOD;
                } else {
                    prob = (prob * (MOD - p[i][col])) % MOD;
                }
            }

            for (int k = 0; k < totalStates; ++k) {
                int nextIdx = sm.transitionTable[mask][k];
                curState[nextIdx] = (curState[nextIdx] + prob * prevState[k]) % MOD;
            }
        }
        prevState = curState;
    }

    i64 ans = 0;
    for (int k = 0; k < totalStates; ++k) {
        if (sm.maxMatchList[k] == n) {
            ans = (ans + prevState[k]) % MOD;
        }
    }
    cout << (ans % MOD + MOD) % MOD << '\n';

    return 0;
}

