ll mod_pow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int popcount(int x) {
    return __builtin_popcount(x);
}

class HallState {
public:
    vector<vector<int>> next_states;
    vector<int> max_matches;
    vector<unordered_set<int>> states;

    HallState(int n) : n(n), total_states(0) {
        states.resize(1 << n);
        int initial = 1;
        states[initial].insert(initial);
        add_state(initial);
    }

private:
    int n;
    int total_states;

    void add_state(int state) {
        total_states++;
    }
};

void init_transition_tables(int n, vector<vector<int>>& transition, vector<int>& max_matching) {
    int N = 1 << n;
    vector<int> size_masks(n + 1);

    for (int mask = 0; mask < N; ++mask) {
        int cnt = popcount(mask);
        size_masks[cnt] |= (1 << mask);
    }

    vector<int> all_states;
    unordered_map<int, int> state_to_idx;

    all_states.push_back(1);
    state_to_idx[1] = 0;
    int total_states = 1;

    for (int idx = 0; idx < total_states; ++idx) {
        int state = all_states[idx];
        vector<int> pred_hall(n, 0);

        for (int mask = 0; mask < N; ++mask) {
            if (state & (1 << mask)) {
                for (int i = 0; i < n; ++i) {
                    pred_hall[i] |= (1 << (mask | (1 << i)));
                }
            }
        }

        transition[idx].resize(N);
        for (int mask = 0; mask < N; ++mask) {
            int next_state = state;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    next_state |= pred_hall[i];
                }
            }

            if (!state_to_idx.count(next_state)) {
                state_to_idx[next_state] = total_states;
                all_states.push_back(next_state);
                total_states++;
            }
            transition[idx][mask] = state_to_idx[next_state];
        }

        for (int i = n; i >= 0; --i) {
            if (state & size_masks[i]) {
                max_matching[idx] = i;
                break;
            }
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n;
    m = n;

    vector<vector<int>> transition(1 << 6, vector<int>());
    vector<int> max_matching(1 << 6, 0);
    init_transition_tables(n, transition, max_matching);

    vector<vector<ll>> p(n, vector<ll>(m));
    ll inv100 = mod_pow(100, MOD - 2, MOD);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            ll val;
            cin >> val;
            p[i][j] = (val * inv100) % MOD;
        }
    }

    int total_states = max_matching.size();
    vector<ll> dp_prev(total_states, 0), dp_cur(total_states, 0);
    dp_prev[0] = 1;

    for (int j = 0; j < m; ++j) {
        fill(dp_cur.begin(), dp_cur.end(), 0);
        int N = 1 << n;

        for (int mask = 0; mask < N; ++mask) {
            ll prob = 1;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    prob = (prob * p[i][j]) % MOD;
                } else {
                    prob = (prob * ((MOD - p[i][j]) % MOD)) % MOD;
                }
            }

            for (int k = 0; k < total_states; ++k) {
                dp_cur[transition[k][mask]] = (dp_cur[transition[k][mask]] + prob * dp_prev[k]) % MOD;
            }
        }
        dp_prev = dp_cur;
    }

    ll result = 0;
    for (int k = 0; k < total_states; ++k) {
        if (max_matching[k] == n) {
            result = (result + dp_prev[k]) % MOD;
        }
    }
    cout << ((result % MOD) + MOD) % MOD << '\n';

    return 0;
}

