class DPState {
public:
    vector<vector<i64>> transition;
    vector<int> maximumMatching;
    vector<int> stateList;

    DPState() {}

    void initialize(int n) {
        stateList.clear();
        int N = 1 << n;
        stateList.push_back(1);

        vector<int> sizeMask(n + 1, 0);
        for (int mask = 0; mask < N; ++mask) {
            int cnt = countBits(mask);
            sizeMask[cnt] |= (1 << mask);
        }

        transition.resize(1000, vector<i64>(1 << 6));
        maximumMatching.assign(1000, -1);
        int totalStates = 1;

        for (int k = 0; k < totalStates; ++k) {
            int state = stateList[k];
            vector<int> predHall(n, 0);

            for (int mask = 0; mask < N; ++mask) {
                if (state & (1 << mask)) {
                    for (int i = 0; i < n; ++i) {
                        predHall[i] |= (1 << (mask | (1 << i)));
                    }
                }
            }

            for (int mask = 0; mask < N; ++mask) {
                int nextState = state;
                for (int i = 0; i < n; ++i) {
                    if (mask & (1 << i)) {
                        nextState |= predHall[i];
                    }
                }

                if (find(stateList.begin(), stateList.end(), nextState) == stateList.end()) {
                    stateList.push_back(nextState);
                    totalStates++;
                }

                transition[k][mask] = find(stateList.begin(), stateList.end(), nextState) - stateList.begin();
            }

            for (int i = n; i >= 0; --i) {
                if (state & sizeMask[i]) {
                    maximumMatching[k] = i;
                    break;
                }
            }
        }

        transition.resize(totalStates);
        maximumMatching.resize(totalStates);
    }
};

int main() {
