    m = n;

    DPState dpState;
    dpState.initialize(n);

    vector<vector<i64>> p(n, vector<i64>(m));
    i64 inv100 = modPow(100, MOD - 2, MOD);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            i64 val;
            cin >> val;
            p[i][j] = (val * inv100) % MOD;
        }
    }

    int totalStates = dpState.stateList.size();
    vector<i64> prevDP(totalStates, 0), curDP(totalStates, 0);
    prevDP[0] = 1;

    int N = 1 << n;
    for (int col = 0; col < m; ++col) {
        fill(curDP.begin(), curDP.end(), 0);

        for (int mask = 0; mask < N; ++mask) {
            i64 prob = 1;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    prob = (prob * p[i][col]) % MOD;
                } else {
                    prob = (prob * ((MOD - p[i][col]) % MOD)) % MOD;
                }
            }

            for (int k = 0; k < totalStates; ++k) {
                int nextIdx = dpState.transition[k][mask];
                curDP[nextIdx] = (curDP[nextIdx] + prob * prevDP[k]) % MOD;
            }
        }

        prevDP.swap(curDP);
    }

    i64 ans = 0;
    for (int k = 0; k < totalStates; ++k) {
        if (dpState.maximumMatching[k] == n) {
            ans = (ans + prevDP[k]) % MOD;
        }
    }

    cout << (ans % MOD + MOD) % MOD << '\n';

    return 0;
}

