int solve(int i, LL msk) {
	if (msk == 0) return 0;
	if (i == n) return 1;
	if (dp[i].count(msk)) return dp[i][msk];
	LL ret = 0;
	for (int s = 0; s < (1<<n); ++s) {
		LL p = 1;
		for (int j = 0; j < n; ++j) 
