        for (int j = 1; j <= tot; ++j) {
            int comp_id = id[(1 << n) - 1 - sta[j]];
            if (i & bin[j-1]) new_mask |= bin[comp_id - 1];
        }
        g[new_mask] = f[i];
        f[i] = 0;
    }
    a[1] = 4; a[2] = 5; a[3] = 6;
    dfs2(1, 1, 1);
    precomp();
    int res = 0;
    for (int i = 0; i < (1 << tot); ++i)
        res = (res + (i64)f[i] * g[(1 << tot) - 1 - i] % MOD) % MOD;
    printf("%d\n", (MOD + 1 - res) % MOD);
    return 0;
}

