typedef pair<ll, ll> pll;

const int MOD = 1000000007;

int n, S, cnt[250], id[250];
int f[10][250];
vector<int> vec[10];
map<pll, int> dpMemo;

int modExp(int base, int exp) {
    int res = 1;
    base %= MOD;
    while (exp) {
        if (exp & 1) res = (1LL * res * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int compute(int pos, ll state) {
    if (state == 0) return 0;
    if (pos == n) return 1;

    pll key = make_pair(pos, state);
    if (dpMemo.find(key) != dpMemo.end()) return dpMemo[key];

    S++;
    int total = 0;

    for (int mask = 1; mask < (1 << n); mask++) {
        ll nextSt = 0;
        for (int i = 0; i < vec[pos].size(); i++) {
            if (!(state & (1LL << i))) continue;
            int prev = vec[pos][i];
            for (int b = 0; b < n; b++) {
                if ((mask & (1 << b)) && !(prev & (1 << b))) {
                    nextSt |= 1LL << id[prev | (1 << b)];
                }
            }
        }
        total = (total + 1LL * f[pos][mask] * compute(pos + 1, nextSt)) % MOD;
    }

    return dpMemo[key] = total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n;
    int inv100 = modExp(100, MOD - 2);

