            int p0 = (1 + MOD - p1) % MOD;
            for (int k = 0; k < (1 << j); k++) {
                f[i][k | (1 << j)] = (1LL * f[i][k] * p1) % MOD;
                f[i][k] = (1LL * f[i][k] * p0) % MOD;
            }
        }
    }

    for (int i = 0; i < (1 << n); i++) {
        cnt[i] = cnt[i >> 1] + (i & 1);
    }

    for (int i = 0; i < (1 << n); i++) {
        vec[cnt[i]].push_back(i);
        id[i] = vec[cnt[i]].size() - 1;
    }

    cout << compute(0, 1) << endl;
    return 0;
}

