#include <bits/stdc++.h>

using namespace std;
using ll = long long;
const int MOD = 1000000007;

inline void add(int& a, int b) {
    a = (a + b) % MOD;
    if (a < 0) a += MOD;
}

int modPow(int base, int exp, int mod) {
    int result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (ll)result * base % mod;
        base = (ll)base * base % mod;
        exp >>= 1;
    }
    return result;
}

int n;
vector<vector<int>> prob;
vector<vector<int>> prod;
vector<vector<int>> popcountVec;
vector<int> indexMap;
vector<vector<ll>> transition;
unordered_map<long long, int> memo;

int solve(int pos, long long state) {
    if (state == 0) return 0;
    if (pos == n) return 1;

    long long key = (long long)pos << 32 | state;
    if (memo.count(key)) return memo[key];

    int res = 0;
    for (int mask = 1; mask < (1 << n); ++mask) {
        long long nextState = 0;
        for (int bit = 0; bit < n; ++bit) {
            if (!(state & (1LL << bit))) continue;
            int cur = popcountVec[bit];
            int remaining = mask & ~cur;
            nextState |= transition[cur][remaining];
        }
        add(res, (ll)prod[pos][mask] * solve(pos + 1, nextState) % MOD);
    }

    return memo[key] = res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    int inv100 = modPow(100, MOD - 2, MOD);

