        for (int j = 0; j < n; ++j) {
            cin >> prob[i][j];
            prob[i][j] = (ll)prob[i][j] * inv100 % MOD;
        }
    }

    prod.assign(n, vector<int>(1 << n, 1));
    for (int i = 0; i < n; ++i) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            for (int j = 0; j < n; ++j) {
                if (mask & (1 << j)) {
                    prod[i][mask] = (ll)prod[i][mask] * prob[i][j] % MOD;
                } else {
                    prod[i][mask] = (ll)prod[i][mask] * ((MOD + 1 - prob[i][j]) % MOD) % MOD;
                }
            }
        }
    }

    popcountVec.assign(n, 0);
    for (int i = 0; i < n; ++i) popcountVec[i] = 1 << i;

    indexMap.assign(1 << n, 0);
    vector<vector<int>> groups(n + 1);
    for (int mask = 0; mask < (1 << n); ++mask) {
        int cnt = __builtin_popcount(mask);
        groups[cnt].push_back(mask);
        indexMap[mask] = groups[cnt].size() - 1;
    }

    transition.assign(1 << n, vector<ll>(1 << n, 0));
    for (int mask = 0; mask < (1 << n); ++mask) {
        for (int j = 0; j < n; ++j) {
            if (!(mask & (1 << j))) {
                int nextMask = mask | (1 << j);
                int groupIdx = __builtin_popcount(mask);
                int posInGroup = indexMap[nextMask];
                transition[mask][1 << j] = 1LL << posInGroup;
            }
        }
        for (int j = 0; j < (1 << n); ++j) {
            if (j == 0) continue;
            int lowbit = j & -j;
            transition[mask][j] = transition[mask][lowbit] | transition[mask][j ^ lowbit];
        }
    }

    cout << solve(0, 1) << '\n';
    return 0;
}

