        if (exp & 1) res = (ll)res * base % mod;
        base = (ll)base * base % mod;
        exp >>= 1;
    }
    return res;
}

void add(int& a, int b) {
    a = (a + b) % MOD;
    if (a < 0) a += MOD;
}

int n;
vector<vector<int>> p;
vector<vector<int>> prod;
vector<vector<int>> groups;
vector<int> index;
vector<vector<ll>> trans;
map<pair<int, ll>, int> memo;

int solve(int pos, ll state) {
    if (state == 0) return 0;
    if (pos == n) return 1;

    auto key = make_pair(pos, state);
    if (memo.find(key) != memo.end()) return memo[key];

    int result = 0;
    for (int mask = 1; mask < (1 << n); ++mask) {
        ll next_state = 0;
        for (int k = 0; k < n; ++k) {
            if (!(state & (1LL << k))) continue;
            int cur_elem = groups[k];
            int rem = mask & ~cur_elem;
            next_state |= trans[cur_elem][rem];
        }
        add(result, (ll)prod[pos][mask] * solve(pos + 1, next_state) % MOD);
    }

    return memo[key] = result;
}

int main() {
