unordered_map<lli, int> dp_cache;

int dp(int idx, lli state) {
    if (state == 0) return 0;
    if (idx == N) return 1;

    lli key = ((lli)idx << 40) ^ state;
    if (dp_cache.find(key) != dp_cache.end()) return dp_cache[key];

    int result = 0;
    for (int mask = 1; mask < (1 << N); ++mask) {
