inline int readInt() {
    int x = 0, sign = 1;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') sign = -1;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    return x * sign;
}

ll modPow(ll base, ll exp) {
    ll result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

ll modInverse(ll a) {
    return modPow(a, MOD - 2);
}

void addMod(int& a, int b) {
    a = (a + b) % MOD;
    if (a < 0) a += MOD;
}

void subMod(int& a, int b) {
    a = (a - b + MOD) % MOD;
}

void FWT(vector<int>& a, int type) {
    int n = a.size();
    for (int len = 2; len <= n; len <<= 1) {
        for (int i = 0; i < n; i += len) {
            for (int j = 0; j < len / 2; j++) {
                int u = a[i + j];
                int v = a[i + j + len / 2];
                if (type == 1) {
                    a[i + j] = (u + v) % MOD;
                    a[i + j + len / 2] = v;
                } else {
                    a[i + j] = (u - v + MOD) % MOD;
                    a[i + j + len / 2] = v;
                }
            }
        }
    }
}

