        for (int j = 0; j < 6; j++) {
            if (m3 >> j & 1) prob = prob * p[2][j] % MOD;
            else prob = prob * (MOD + 1 - p[2][j]) % MOD;
        }

        int combinedMask = 0;
        for (int a = 0; a < 6; a++) {
            if (m1 >> a & 1) {
                for (int b = 0; b < 6; b++) {
                    if (a == b) continue;
                    if (m2 >> b & 1) {
                        for (int c = 0; c < 6; c++) {
                            if (a == c || b == c) continue;
                            if (m3 >> c & 1) {
                                int nmask = (1 << a) | (1 << b) | (1 << c);
                                combinedMask |= 1 << id[nmask];
                            }
                        }
                    }
                }
            }
        }
        addMod(X[combinedMask], (int)prob);
    }

    for (int mask = 0; mask < (1 << 18); mask++) {
        int m1 = mask & 0x3F;
        int m2 = (mask >> 6) & 0x3F;
        int m3 = (mask >> 12) & 0x3F;

        ll prob = 1;
        for (int j = 0; j < 6; j++) {
            if (m1 >> j & 1) prob = prob * p[3][j] % MOD;
            else prob = prob * (MOD + 1 - p[3][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m2 >> j & 1) prob = prob * p[4][j] % MOD;
            else prob = prob * (MOD + 1 - p[4][j]) % MOD;
        }
        for (int j = 0; j < 6; j++) {
            if (m3 >> j & 1) prob = prob * p[5][j] % MOD;
            else prob = prob * (MOD + 1 - p[5][j]) % MOD;
        }

        int combinedMask = 0;
        for (int a = 0; a < 6; a++) {
            if (m1 >> a & 1) {
                for (int b = 0; b < 6; b++) {
                    if (a == b) continue;
                    if (m2 >> b & 1) {
                        for (int c = 0; c < 6; c++) {
                            if (a == c || b == c) continue;
                            if (m3 >> c & 1) {
                                int nmask = (1 << a) | (1 << b) | (1 << c);
                                nmask ^= 0x3F;
                                combinedMask |= 1 << id[nmask];
                            }
                        }
                    }
                }
            }
        }
        addMod(Y[combinedMask], (int)prob);
    }

    FWT(X, 1);
    FWT(Y, 1);

    for (int i = 0; i < (1 << 18); i++) {
        X[i] = (int)((ll)X[i] * Y[i] % MOD);
    }

    FWT(X, -1);

    int ans = 0;
    for (int i = 1; i < (1 << 18); i++) {
        addMod(ans, X[i]);
    }

    printf("%d\n", ans);
    return 0;
}

