                                }
                            }
                        }
                    }
                }
            }

            dp[finalMask][block] = (dp[finalMask][block] + prob) % mod;
        }
    }

    for (int bit = 0; bit < 20; bit++) {
        for (int mask = 0; mask < (1 << 20); mask++) {
            if (mask & (1 << bit)) {
                dp[mask][0] = (dp[mask][0] + dp[mask ^ (1 << bit)][0]) % mod;
            }
        }
    }

