    int fullMask = (1 << 20) - 1;
    for (int mask = 0; mask < (1 << 20); mask++) {
        LL complement = dp[fullMask ^ mask][1];
        result = (result - dp[mask][0] * complement % mod + mod) % mod;
    }

    cout << result << '\n';
    return 0;
}

