int add_mod(int x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
    return x;
}

int sub_mod(int x, int y) {
    x -= y;
    if (x < 0) x += MOD;
    return x;
}

int mul_mod(long long x, long long y) {
    return (int)((x * y) % MOD);
}

unordered_map<State, int> state_to_id;
int n, state_count, trans[65536][128];

int build_state(State s) {
    auto it = state_to_id.find(s);
    if (it != state_to_id.end()) return it->second;
    int id = state_count++;
    state_to_id[s] = id;
    for (int mask = 0; mask < (1 << n); ++mask) {
        State next = s;
        for (int j = 0; j < (1 << n); ++j) {
            if (!next[j]) {
                for (int k = mask & j; k; k -= k & -k) {
                    if (s[j ^ (k & -k)]) {
                        next[j] = 1;
                        break;
                    }
                }
            }
        }
        trans[id][mask] = build_state(next);
    }
    return id;
}

