            for (int k = 0; k < n; ++k) {
                int bit = (mask >> k) & 1;
                int val = bit ? p[k][i] : sub_mod(1, p[k][i]);
                q[i][mask] = mul_mod(q[i][mask], val);
            }
        }
    }

