        for (int j = 0; j < state_count; ++j) {
            for (int mask = 0; mask < (1 << n); ++mask) {
                dp[i+1][trans[j][mask]] = add_mod(dp[i+1][trans[j][mask]], 
                                                  (int)mul_mod(dp[i][j], q[i][mask]));
            }
        }
    }

    State target;
    target.set();
    cout << dp[n][state_to_id[target]] << '\n';

    return 0;
}

