int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);

    int N;
    cin >> N;
    vector<vector<mint>> p(N, vector<mint>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            cin >> p[i][j];
            p[i][j] /= 100;
        }

    using BS = bitset<128>;
    unordered_map<BS, mint> cur, nxt;
    {
        BS b;
        b[0] = true;
        cur[b] = 1;
    }

    for (int i = 0; i < N; ++i) {
        for (const auto& kv : cur) {
            BS b = kv.first;
            vector<int> ones;
            for (int idx = 0; idx < N; ++idx)
                if (b[idx]) ones.push_back(idx);

            for (int e = 0; e < (1 << N); ++e) {
                mint pr = 1;
                for (int j = 0; j < N; ++j) {
                    if ((e >> j) & 1) pr *= p[i][j];
                    else pr *= mint(1) - p[i][j];
                }

                BS nb;
                for (int x : ones) {
                    for (int r = 0; r < N; ++r) {
                        if (((e >> r) & 1) && !((x >> r) & 1)) {
                            nb[x | (1 << r)] = true;
                        }
                    }
                }
                nxt[nb] += kv.second * pr;
            }
        }
        cur.swap(nxt);
        nxt.clear();
    }

    mint ans = 0;
    BS full;
    full.set();
    for (const auto& kv : cur)
        if (kv.first[(1 << N) - 1]) ans += kv.second;
    cout << ans << endl;
}

