class Matrix {
public:
    ll m[MAX_K][MAX_K];
    int N;

    Matrix(int n = 0) : N(n) {
        memset(m, 0, sizeof(m));
        for (int i = 0; i < N; ++i) m[i][i] = 1;
    }

    Matrix* operator*(const Matrix& b) const;
};

Matrix* Matrix::operator*(const Matrix& b) const {
    Matrix* ret = new Matrix(N);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            ll sum = 0;
            for (int k = 0; k < N; ++k) {
                sum = (sum + m[i][k] * b.m[k][j]) % MOD;
            }
            ret->m[i][j] = sum;
        }
    }
    return ret;
}

