using i64 = __int64_t;
using u64 = unsigned __int64_t;

static const i64 MOD = 1000000007LL;
static constexpr int MAX_SIZE = 31;

struct Matrix {
    i64 val[MAX_SIZE][MAX_SIZE];
    int dim;

    explicit Matrix(int n = 0) : dim(n) {
        memset(val, 0, sizeof(val));
        for (int idx = 0; idx < n; ++idx)
            val[idx][idx] = 1;
    }

    Matrix operator*(const Matrix& rhs) const {
        Matrix res(dim);
        for (int i = 0; i < dim; ++i) {
            for (int j = 0; j < dim; ++j) {
                i64 accum = 0;
                for (int l = 0; l < dim; ++l) {
                    accum = (accum + val[i][l] * rhs.val[l][j]) % MOD;
                }
                res.val[i][j] = accum;
            }
        }
        return res;
    }
};

Matrix* chain[75][MAX_SIZE];
i64 powBase[128];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 N;
    int K;
    cin >> N >> K;

    for (int i = 0; i < K; ++i) {
        chain[0][i] = new Matrix(K + 1);
        for (int j = 0; j <= K; ++j) {
            chain[0][i]->val[i][j] = 1;
        }
    }

    powBase[0] = 1;
    powBase[1] = K;
    int depth = 2;
    while (powBase[depth - 1] <= N / K) {
        powBase[depth] = powBase[depth - 1] * K;
        ++depth;
    }

    for (int level = 1; level < depth; ++level) {
        chain[level][0] = new Matrix(K + 1);
        for (int col = 1; col < K; ++col) {
            *chain[level][col] = *chain[level - 1][col - 1] * *chain[level][col - 1];
        }
        Matrix cumulative(K + 1);
        for (int r = K - 1; r >= 0; --r) {
            cumulative = cumulative * *chain[level - 1][r];
            *chain[level][r] = *chain[level][r] * cumulative;
        }
    }

    Matrix result(K + 1);
    int cnt = 0;
    for (int level = depth - 1; level >= 0; --level) {
        while (powBase[level] <= N) {
            N -= powBase[level];
            result = *chain[level][cnt] * result;
            cnt = (cnt + 1) % K;
        }
    }

    i64 answer = 0;
