    if (!n) return Matrix(K + 1, 1);

    for (int i = idx; i >= 0; --i) {
        if (n >= powers[i]) {
            Matrix tmp = solve(n % powers[i], i - 1);
            int x = n / powers[i];

            Matrix ans = baseMat[i];
            for (int j = 1; j < x; ++j) {
                ans = ans * shiftMat[K - 1];
                ans = ans * baseMat[i];
            }
            ans = ans * shiftMat[K - 1];
            ans = ans * tmp;
            ans = ans * shiftMat[x - 1];
            return ans;
        }
    }

    throw runtime_error("Unreachable");
}

