        for (int i = 0; i < d; ++i) m[i][i] = diag;
    }

    int* operator[](int i) { return m[i]; }

    Matrix operator*(const Matrix& o) const {
        Matrix res(dim, 0);
        for (int i = 0; i < dim; ++i)
            for (int k = 0; k < dim; ++k)
                if (m[i][k])
                    for (int j = 0; j < dim; ++j)
                        res.m[i][j] = (res.m[i][j] + 1LL * m[i][k] * o.m[k][j]) % MOD;
        return res;
    }

    Matrix operator+(const Matrix& o) const {
        Matrix res(dim, 0);
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                res.m[i][j] = (m[i][j] + o.m[i][j]) % MOD;
        return res;
    }

    bool operator==(const Matrix& o) const {
        if (dim != o.dim) return false;
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                if (m[i][j] != o.m[i][j]) return false;
        return true;
    }
};

Matrix fastPow(Matrix base, ll exp) {
    Matrix res(base.dim, 1);
    while (exp) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

