ll P[60];

Matrix decompose(ll n, int idx) {
    if (n == 0) return Matrix(K + 1, 1);

    for (int i = idx; i >= 0; --i) {
        if (n >= P[i]) {
            Matrix t = decompose(n % P[i], i - 1);
            int x = n / P[i];

            Matrix ans = A[i];
            for (int j = 1; j < x; ++j) {
                ans = ans * S[K - 1];
                ans = ans * A[i];
            }
            ans = ans * S[K - 1];
            ans = ans * t;
            ans = ans * S[x - 1];
            return ans;
        }
    }

    throw exception();
}

