        for (int j = 0; j <= K; ++j) base_layer[0][i][j][j] = 1;
        for (int j = 0; j <= K; ++j) base_layer[0][i][j][i] = 1;
    }

    for (int level = 1; level < (int)digits.size(); ++level) {
        prefix[level - 1][0] = base_layer[level - 1][0];
        for (int col = 1; col < K; ++col)
            prefix[level - 1][col] = multiply(prefix[level - 1][col - 1], base_layer[level - 1][col]);

        suffix[level - 1][K - 1] = base_layer[level - 1][K - 1];
        for (int col = K - 2; col >= 0; --col)
            suffix[level - 1][col] = multiply(base_layer[level - 1][col], suffix[level - 1][col + 1]);

