const int MOD = 1000000007;
const int MAX_DIM = 33;

int dim;
struct Matrix {
    ll mat[MAX_DIM][MAX_DIM];
    Matrix() { memset(mat, 0, sizeof(mat)); }

    void normalize() {
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                mat[i][j] = ((mat[i][j] % MOD) + MOD) % MOD;
    }
};

Matrix identity;
Matrix multiply(const Matrix& A, const Matrix& B) {
    Matrix C;
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            for (int k = 0; k < dim; ++k) {
                C.mat[i][j] += A.mat[i][k] * B.mat[k][j];
                if (C.mat[i][j] >= 8e18) C.mat[i][j] %= MOD;
            }
    return C;
}

Matrix matrix_pow(Matrix base, ll exp) {
    base.normalize();
    Matrix result = identity;
    while (exp) {
        if (exp & 1) result = multiply(result, base);
        base = multiply(base, base);
        exp >>= 1;
    }
    return result;
}

void init_matrix(int size) {
    dim = size;
    for (int i = 0; i < dim; ++i)
        identity.mat[i][i] = 1;
}

void read_ll(ll& x) {
    int sign = 1;
    char c;
    while (((c = getchar()) < '0' || c > '9') && c != '-');
    if (c == '-') sign = -1, x = 0;
    else x = c - '0';
    while ((c = getchar()) >= '0' && c <= '9') x = x * 10 + c - '0';
    x *= sign;
}

void read_int(int& x) {
    ll t; read_ll(t); x = t;
}

int digits[128];
int digit_count;

Matrix transform(const Matrix& M, int shift) {
    Matrix res;
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j) {
            int ni = (i == dim - 1) ? (dim - 1) : ((i + shift) % (dim - 1));
            int nj = (j == dim - 1) ? (dim - 1) : ((j + shift) % (dim - 1));
            res.mat[ni][nj] = M.mat[i][j];
        }
    return res;
}

int main() {
    ll n;
    int k;
    read_ll(n); read_int(k);
    init_matrix(k + 1);

    digit_count = 0;
    while (n) {
        digits[digit_count++] = n % k;
        n /= k;
    }

    vector<Matrix> A(digit_count);

    for (int j = 0; j <= k; ++j) {
        A[0].mat[0][j] = 1;
        A[0].mat[j][j] = 1;
    }

    for (int i = 1; i < digit_count; ++i) {
        Matrix cur = identity;
        for (int j = 0; j < k; ++j)
            cur = multiply(cur, transform(A[i-1], j));
        A[i] = cur;
    }

    int shift = 0;
    Matrix result = identity;
    for (int i = digit_count - 1; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j)
            result = multiply(result, transform(A[i], (j + shift) % k));
