    Matrix() {
        memset(data, 0, sizeof(data));
    }

    void adjust() {
        for (int i = 0; i < current_dim; ++i)
            for (int j = 0; j < current_dim; ++j)
                data[i][j] = ((data[i][j] % MOD) + MOD) % MOD;
    }
};

Matrix identity_matrix;
Matrix operator*(const Matrix& lhs, const Matrix& rhs) {
    Matrix result;
    for (int i = 0; i < current_dim; ++i)
        for (int j = 0; j < current_dim; ++j)
            for (int k = 0; k < current_dim; ++k) {
                result.data[i][j] += lhs.data[i][k] * rhs.data[k][j];
                if (result.data[i][j] >= 8e18) result.data[i][j] %= MOD;
            }
    return result;
}

Matrix fast_pow(Matrix base, ll exponent) {
    base.adjust();
    Matrix result = identity_matrix;
    while (exponent > 0) {
        if (exponent & 1) result = result * base;
        base = base * base;
        exponent >>= 1;
    }
    return result;
}

void setup_matrix(int size) {
    current_dim = size;
    for (int i = 0; i < size; ++i)
