Matrix cyclic_shift(const Matrix& M, int shift_amount) {
    Matrix shifted;
    for (int i = 0; i < current_dim; ++i)
        for (int j = 0; j < current_dim; ++j) {
            int new_i = (i == current_dim - 1) ? (current_dim - 1) : ((i + shift_amount) % (current_dim - 1));
            int new_j = (j == current_dim - 1) ? (current_dim - 1) : ((j + shift_amount) % (current_dim - 1));
            shifted.data[new_i][new_j] = M.data[i][j];
        }
    return shifted;
}

