int dim;
struct Matrix {
    i64 m[MAX_D][MAX_D];

    Matrix() {
        memset(m, 0, sizeof(m));
    }

    void mod_adjust() {
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                m[i][j] = ((m[i][j] % MOD) + MOD) % MOD;
    }
};

Matrix identity;
Matrix multiply(const Matrix& A, const Matrix& B) {
    Matrix C;
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            for (int k = 0; k < dim; ++k) {
                C.m[i][j] += A.m[i][k] * B.m[k][j];
                if (C.m[i][j] >= 8e18) C.m[i][j] %= MOD;
            }
    return C;
}

Matrix power(Matrix base, i64 exp) {
    base.mod_adjust();
    Matrix res = identity;
    while (exp) {
        if (exp & 1) res = multiply(res, base);
        base = multiply(base, base);
        exp >>= 1;
    }
    return res;
}

void init_dim(int size) {
    dim = size;
    for (int i = 0; i < size; ++i)
        identity.m[i][i] = 1;
