    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j) {
            int ni = (i == dim - 1) ? (dim - 1) : ((i + shift) % (dim - 1));
            int nj = (j == dim - 1) ? (dim - 1) : ((j + shift) % (dim - 1));
            shifted.m[ni][nj] = M.m[i][j];
        }
    return shifted;
}

