inline int subtractMod(int x, int y) {
    return (x - y + m) % m;
}

int main() {
    cin >> n >> m;

    // Extract digits in base m
    ll tempN = n;
    while (tempN > 0) {
        digits[++digitCount] = tempN % m;
        tempN /= m;
    }

    // Initialize dp for first position
    for (int i = 1; i <= m; ++i) {
        dp[1][i][i] = 1;
    }
    for (int i = 0; i <= m; ++i) {
        dp[1][0][i] = 1;
    }

    // Fill dp table
    for (int pos = 2; pos <= digitCount; ++pos) {
        for (int j = 0; j <= m; ++j) {
            dp[pos][j][j] = 1;
        }

        for (int j = 0; j < m; ++j) {
            // Reset temp matrix
            memset(temp, 0, sizeof(temp));

            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    for (int c = 0; c <= m; ++c) {
                        temp[a][c] = (temp[a][c] + 1LL * dp[pos-1][subtractMod(a, j)][subtractMod(b, j)] * dp[pos][b][c]) % MOD;
                    }
                }
            }

            // Copy temp to dp[pos]
            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    dp[pos][a][b] = temp[a][b];
                }
            }
        }
    }

    // Initialize A array
    for (int i = 0; i <= m; ++i) {
        A[i] = 1;
    }

    // Process each digit
    for (int i = 1; i <= digitCount; ++i) {
        int suffixSum = 0;
        for (int j = i + 1; j <= digitCount; ++j) {
            suffixSum = (suffixSum + digits[j]) % m;
        }

        for (int d = digits[i]; d > 0; --d) {
            int dec = (suffixSum + d) % m;
            memset(B, 0, sizeof(B));

            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    B[b] = (B[b] + 1LL * A[a] * dp[i][subtractMod(a, dec)][subtractMod(b, dec)]) % MOD;
                }
            }

            for (int a = 0; a <= m; ++a) {
                A[a] = B[a];
            }
        }
    }

    cout << A[m] << endl;
    return 0;
}

