            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    int dec_a = (a - dec + m) % m;
                    int dec_b = (b - dec + m) % m;
                    B[b] = (B[b] + 1LL * A[a] * dp[i+1][dec_a][dec_b]) % MOD;
