using ll = long long;
const int MOD = 1000000007;

int main() {
    ll n;
    int m;
    cin >> n >> m;

    vector<int> digits;
    ll temp = n;
    if (temp == 0) {
        digits.push_back(0);
    } else {
        while (temp > 0) {
            digits.push_back(temp % m);
            temp /= m;
        }
    }

    int num = digits.size();

    // dp[pos][a][b]
    vector<vector<vector<int>>> dp(num + 1, vector<vector<int>>(m + 1, vector<int>(m + 1, 0)));

    // Base case initialization
    for (int i = 1; i <= m; ++i) {
        dp[1][i][i] = 1;
    }
    for (int i = 0; i <= m; ++i) {
        dp[1][0][i] = 1;
    }

    // Fill DP table
    for (int pos = 2; pos <= num; ++pos) {
        for (int j = 0; j <= m; ++j) {
            dp[pos][j][j] = 1;
        }

        for (int j = 0; j < m; ++j) {
            vector<vector<int>> temp(m + 1, vector<int>(m + 1, 0));

            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    for (int c = 0; c <= m; ++c) {
                        int dec_a = (a - j + m) % m;
                        int dec_b = (b - j + m) % m;
                        temp[a][c] = (temp[a][c] + 1LL * dp[pos-1][dec_a][dec_b] * dp[pos][b][c]) % MOD;
                    }
                }
            }

            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    dp[pos][a][b] = temp[a][b];
                }
            }
        }
    }

    vector<int> A(m + 1, 1);
    vector<int> B(m + 1, 0);

    for (int i = 0; i < num; ++i) {
        int suffixSum = 0;
        for (int j = i + 1; j < num; ++j) {
            suffixSum = (suffixSum + digits[j]) % m;
        }

        for (int d = digits[i]; d > 0; --d) {
            int dec = (suffixSum + d) % m;
            fill(B.begin(), B.end(), 0);

            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    int dec_a = (a - dec + m) % m;
                    int dec_b = (b - dec + m) % m;
                    B[b] = (B[b] + 1LL * A[a] * dp[i+1][dec_a][dec_b]) % MOD;
                }
            }

            A = B;
        }
    }

    cout << A[m] << endl;
    return 0;
}

