using lint = long long;
constexpr lint MOD = 1000000007;

inline void mod_incr(lint &x, lint y) {
    x = (x + y) % MOD;
}

int global_dim;

struct Mat {
    lint data[33][33];
    Mat() { memset(data, 0, sizeof(data)); }

    void set_identity() {
        memset(data, 0, sizeof(data));
        for (int i = 0; i < global_dim; ++i) data[i][i] = 1;
    }

    Mat operator*(const Mat &b) const {
        Mat res;
        for (int i = 0; i < global_dim; ++i)
            for (int j = 0; j < global_dim; ++j)
                for (int k = 0; k < global_dim; ++k)
                    mod_incr(res.data[i][j], data[i][k] * b.data[k][j]);
        return res;
    }
};

lint N, K;
Mat I_ops[70];
Mat II_ops[70];
Mat R_shifts[70];
Mat C_shifts[70];

int driver() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    cin >> N >> K;
    global_dim = K + 1;

    // Build unary operation matrices
    for (int i = 0; i <= K; ++i) {
        I_ops[i].set_identity();
        if (i > 0) {
            for (int j = 0; j <= K; ++j)
                I_ops[i].data[i][j] = 1;
        }
    }

    // Build row shift matrices
    for (int i = 0; i <= K; ++i) {
        R_shifts[i].set_identity();
        if (i == 1) {
            memset(R_shifts[i].data, 0, sizeof(R_shifts[i].data));
            R_shifts[i].data[0][0] = 1;
            R_shifts[i].data[1][K] = 1;
            for (int j = 2; j <= K; ++j)
                R_shifts[i].data[j][j-1] = 1;
        } else if (i > 1) {
            R_shifts[i] = R_shifts[1] * R_shifts[i-1];
        }
    }

    // Build column shift matrices
    for (int i = 0; i <= K; ++i) {
        C_shifts[i].set_identity();
        if (i == 1) {
            memset(C_shifts[i].data, 0, sizeof(C_shifts[i].data));
            C_shifts[i].data[0][0] = 1;
            C_shifts[i].data[K][1] = 1;
            for (int j = 2; j <= K; ++j)
                C_shifts[i].data[j-1][j] = 1;
        } else if (i > 1) {
            C_shifts[i] = C_shifts[i-1] * C_shifts[1];
        }
    }

    // Build base binary matrix
    II_ops[1].set_identity();
    for (int i = 1; i <= K; ++i)
        II_ops[1] = I_ops[i] * II_ops[1];

    // Digits in base K
    vector<int> nums;
    lint x = N;
    while (x) {
        nums.push_back(x % K);
        x /= K;
    }
    reverse(nums.begin(), nums.end());

    // Build layered binary matrices
    for (int depth = 2; depth <= (int)nums.size(); ++depth) {
        II_ops[depth].set_identity();
        for (int j = 0; j < K; ++j)
            II_ops[depth] = R_shifts[j] * II_ops[depth-1] * C_shifts[j] * II_ops[depth];
    }

    Mat acc; acc.set_identity();
    int pos = 0;
    for (int idx = 0; idx < (int)nums.size(); ++idx) {
        if (idx == (int)nums.size() - 1) {
            for (int t = 0; t < nums[idx]; ++t) {
                acc = I_ops[pos % K + 1] * acc;
                ++pos;
            }
        } else {
            for (int t = 0; t < nums[idx]; ++t) {
                acc = R_shifts[pos % K] * II_ops[nums.size() - idx - 1] * C_shifts[pos % K] * acc;
                ++pos;
            }
        }
    }

    lint ans = 1;
    for (int i = 1; i <= K; ++i)
        mod_incr(ans, acc.data[i][0]);

    cout << ans << endl;
    return 0;
}

int main() {
    return driver();
}

#include <iostream>
#include <cstring>
