using i64 = long long;
const i64 MOD = 1000000007LL;

inline void accumulate(i64 &dest, i64 src) {
    dest = (dest + src) % MOD;
}

int matrix_order;

struct Matrix {
    i64 elem[33][33];

    Matrix() {
        memset(elem, 0, sizeof(elem));
    }

    void unit() {
        memset(elem, 0, sizeof(elem));
        for (int i = 0; i < matrix_order; i++) elem[i][i] = 1;
    }

    Matrix operator*(const Matrix& other) const {
        Matrix result;
        for (int i = 0; i < matrix_order; i++)
            for (int j = 0; j < matrix_order; j++)
                for (int k = 0; k < matrix_order; k++)
                    accumulate(result.elem[i][j], elem[i][k] * other.elem[k][j]);
        return result;
    }
};

i64 input_n, input_k;
Matrix unit_matrices[70];
Matrix combined_matrices[70];
Matrix row_shift_matrices[70];
Matrix col_shift_matrices[70];

int process() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> input_n >> input_k;
    matrix_order = input_k + 1;

    // Initialize unit_matrices
    for (int i = 0; i <= input_k; i++) {
        unit_matrices[i].unit();
        if (i > 0) {
            for (int j = 0; j <= input_k; j++) {
                unit_matrices[i].elem[i][j] = 1;
            }
        }
    }

    // Row shift matrices
    for (int i = 0; i <= input_k; i++) {
        row_shift_matrices[i].unit();
        if (i == 1) {
            memset(row_shift_matrices[i].elem, 0, sizeof(row_shift_matrices[i].elem));
            row_shift_matrices[i].elem[0][0] = 1;
            row_shift_matrices[i].elem[1][input_k] = 1;
            for (int j = 2; j <= input_k; j++) {
                row_shift_matrices[i].elem[j][j-1] = 1;
            }
        } else if (i > 1) {
            row_shift_matrices[i] = row_shift_matrices[1] * row_shift_matrices[i-1];
        }
    }

    // Column shift matrices
    for (int i = 0; i <= input_k; i++) {
        col_shift_matrices[i].unit();
        if (i == 1) {
            memset(col_shift_matrices[i].elem, 0, sizeof(col_shift_matrices[i].elem));
            col_shift_matrices[i].elem[0][0] = 1;
            col_shift_matrices[i].elem[input_k][1] = 1;
            for (int j = 2; j <= input_k; j++) {
                col_shift_matrices[i].elem[j-1][j] = 1;
            }
        } else if (i > 1) {
            col_shift_matrices[i] = col_shift_matrices[i-1] * col_shift_matrices[1];
        }
    }

    // Combined matrix for level 1
    combined_matrices[1].unit();
    for (int i = 1; i <= input_k; i++) {
        combined_matrices[1] = unit_matrices[i] * combined_matrices[1];
    }

    // Extract digits in base input_k
    std::vector<int> digits;
    i64 temp = input_n;
    while (temp > 0) {
        digits.push_back(temp % input_k);
        temp /= input_k;
    }
    std::reverse(digits.begin(), digits.end());

    // Build higher level combined matrices
    for (int level = 2; level <= (int)digits.size(); level++) {
        combined_matrices[level].unit();
        for (int idx = 0; idx < input_k; idx++) {
            combined_matrices[level] = row_shift_matrices[idx] * combined_matrices[level-1] * col_shift_matrices[idx] * combined_matrices[level];
        }
    }

    Matrix accumulator;
    accumulator.unit();
    int current_position = 0;

    for (int i = 0; i < (int)digits.size(); i++) {
        if (i == (int)digits.size() - 1) {
            for (int cnt = 0; cnt < digits[i]; cnt++) {
                accumulator = unit_matrices[current_position % input_k + 1] * accumulator;
                current_position++;
            }
        } else {
            for (int cnt = 0; cnt < digits[i]; cnt++) {
                accumulator = row_shift_matrices[current_position % input_k] * combined_matrices[digits.size() - i - 1] * col_shift_matrices[current_position % input_k] * accumulator;
                current_position++;
            }
        }
    }

    i64 final_answer = 1;
    for (int i = 1; i <= input_k; i++) {
        accumulate(final_answer, accumulator.elem[i][0]);
    }

    std::cout << final_answer << '\n';
    return 0;
}

