    void mod_reduce() {
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                data[i][j] = ((data[i][j] % MOD) + MOD) % MOD;
    }
};

Matrix identity_matrix() {
    Matrix res;
    for (int i = 0; i < dim; ++i) res.data[i][i] = 1;
    return res;
}

Matrix mat_mul(const Matrix& A, const Matrix& B) {
    Matrix C;
    const ll INF = 8e18;
    for (int k = 0; k < dim; ++k)
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j) {
                C.data[i][j] += A.data[i][k] * B.data[k][j];
                if (C.data[i][j] >= INF) C.data[i][j] %= MOD;
            }
    return C;
}

Matrix mat_pow(Matrix base, ll exponent) {
    base.mod_reduce();
    Matrix result = identity_matrix();
    while (exponent > 0) {
        if (exponent & 1) result = mat_mul(result, base);
        base = mat_mul(base, base);
        exponent >>= 1;
    }
    return result;
}

