int base_digits[128];
int num_digits;

Matrix cyclic_shift(const Matrix& M, int shift_amount) {
    Matrix shifted;
    for (int i = 0; i <= k_input; ++i)
        for (int j = 0; j <= k_input; ++j) {
            int ni = (i == k_input) ? k_input : (i + shift_amount) % k_input;
            int nj = (j == k_input) ? k_input : (j + shift_amount) % k_input;
            shifted.data[ni][nj] = M.data[i][j];
        }
    return shifted;
}

