};

long long n, k;

int val (long long um) {
  if (um < k) return um;
  return (um + val (um / k)) % k;
}

mat M[30], MI[30];
mat E[200][40], EI[200][40];
vec cur;

mat mult (mat m1, mat m2) {
  mat m3;
  for (int i = 0; i < k; i++) {
    for (int j = 0; j < k; j++) {
      m3.a[i][j] = 0;
      for (int l = 0; l < k; l++) {
    m3.a[i][j] += (m1.a[i][l] * m2.a[l][j]) % MOD;
      }
      m3.a[i][j] %= MOD;
    }
  }
  return m3;
}

vec mult (mat m, vec v) {
  vec v2;
  for (int i = 0; i < k; i++) {
    v2.a[i] = 0;
    for (int j = 0; j < k; j++) {
      v2.a[i] += (v.a[j] * m.a[i][j]) % MOD;
    }
    v2.a[i] %= MOD;
  }
  return v2;
}

void pre_comp() {
  for (int i = 0; i < k; i++) {
    E[0][i] = M[i];
    EI[0][i] = MI[i];
  }
  int LOG = 0;
  long long t = n;
  while (t > 0) {
    LOG++;
    t /= k;
  }
  for (int j = 1; j <= LOG; j++) {
    E[j][0] = E[j - 1][0];
    EI[j][0] = EI[j - 1][0];
    for (int l = 1; l < k; l++) {
      E[j][0] = mult (E[j - 1][l], E[j][0]);
      EI[j][0] = mult (EI[j][0], EI[j - 1][l]);
    }
