        pref[s + 1] = pref[s];
        auto cur = pref[s];
        for (int i = 1; i < K; ++i) {
            cur = shift(cur);
            pref[s + 1] = mat_mult(pref[s + 1], cur);
        }
    }
}

vector<vector<int>> solve(ll n) {
    if (n == 0) {
        vector<vector<int>> I(K + 1, vector<int>(K + 1, 0));
        for (int i = 0; i <= K; ++i) I[i][i] = 1;
        return I;
    }
    ll p = 1, d = 0;
    while (p <= n / K) { p *= K; ++d; }
    if (n == p) return pref[d];
    ll steps = n / p;
    ll rem = n - steps * p;
    auto res = solve(0);
    auto coef = pref[d];
    for (int i = 0; i < steps; ++i) {
        res = mat_mult(res, coef);
        coef = shift(coef);
    }
    auto other = solve(rem);
    for (int i = 0; i < steps; ++i) other = shift(other);
    return mat_mult(res, other);
}

