    auto coef = table[d];
    for (i64 i = 0; i < steps; ++i) {
        res = multiply(res, coef);
        coef = rotate(coef);
    }
    auto other = compute(rem);
    for (i64 i = 0; i < steps; ++i) other = rotate(other);
