const ll P = ll(1e9) + 7;

struct Matrix {
    static const int N = 33;
    int n;
    ll a[N][N];

    Matrix(int n = 0, int k = 0) : n(n) {
        memset(a, 0, sizeof(a));
        for (int i = 0; i < n; ++i) {
            a[i][i] = k;
        }
    }

    Matrix operator * (const Matrix & m) const {
        assert(n == m.n);
        Matrix res(n);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                for (int k = 0; k < n; ++k) {
                    (res.a[i][k] += a[i][j] * m.a[j][k]) %= P;
                }
            }
        }
        return res;
    }

    Matrix& operator *= (const Matrix & m) {
        return *this = *this * m;
    }

    Matrix pow(int x) const {
        Matrix res = Matrix(n, 1);
        Matrix a = *this;
        while (x) {
            if (x & 1) {
                res *= a;
            }
            a *= a;
            x /= 2;
        }
        return res;
    }

    void print() const {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                dbg("%d ", int(a[i][j]));
            }
            dbg("\n");
        }
        dbg("\n");
    }

    ll* operator[](int index) {
        return a[index];
    }

    const ll* operator[](int index) const {
        return a[index];
    }
};

