    int logN = int(log(n + 0.0) / log(k + 0.0) + 2);

    Matrix shift(k + 1, 1);
    for (int j = 0; j < k; ++j) {
        shift[j][j] = 0;
        shift[(j + 1) % k][j] = 1;
    }
    vector <Matrix> block(logN);
    block[0] = Matrix(k + 1, 1);
    for (int i = 1; i <= k; ++i) {
        block[0][0][i] = 1;
    }
    for (int i = 1; i < logN; ++i) {
        block[i] = (block[i - 1] * shift).pow(k);
    }

    int i = 0;
    ll len = 1;
    while (n / len >= k) {
        i++;
        len *= k;
    }

    Matrix m(k + 1, 1);
