        if (len <= n) {
            int x = int(n / len);
            m *= (block[i] * shift).pow(x);
            n -= len * x;
        }
        --i;
        len /= k;
    }

    ll ans = 0;
    for (int i = 0; i <= k; ++i) {
        (ans += m[i][k]) %= P;
    }
    cout << ans << endl;

