const ll MOD = 1000000007LL;

struct Mtx {
    static constexpr int MAXN = 33;
    int dim;
    ll m[MAXN][MAXN];

    Mtx(int d = 0, ll diag = 0) : dim(d) {
        memset(m, 0, sizeof(m));
        for (int i = 0; i < d; ++i) m[i][i] = diag;
    }

    Mtx operator*(const Mtx& rhs) const {
        assert(dim == rhs.dim);
        Mtx res(dim);
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                for (int p = 0; p < dim; ++p)
                    (res.m[i][p] += m[i][j] * rhs.m[j][p]) %= MOD;
        return res;
    }

    Mtx& operator*=(const Mtx& rhs) {
        return *this = (*this * rhs);
    }

    Mtx pow(int e) const {
        Mtx res(dim, 1);
        Mtx base = *this;
        while (e) {
            if (e & 1) res *= base;
            base *= base;
            e >>= 1;
        }
        return res;
    }

    void show() const {
        for (int i = 0; i < dim; ++i) {
            for (int j = 0; j < dim; ++j)
                DB1("%d ", (int)m[i][j]);
            DB1("\n");
        }
        DB1("\n");
    }

    ll* operator[](int i) { return m[i]; }
