        cout << ((1LL << N) % MOD) << '\n';
        return 0;
    }

    int depth = static_cast<int>(log(N + 0.0) / log(K + 0.0) + 2);

    Mtx trans(K + 1, 1);
    for (int j = 0; j < K; ++j) {
        trans[j][j] = 0;
        trans[(j + 1) % K][j] = 1;
    }

    vector<Mtx> pre(depth);
    pre[0] = Mtx(K + 1, 1);
    for (int i = 1; i <= K; ++i) pre[0][0][i] = 1;

    for (int i = 1; i < depth; ++i)
        pre[i] = (pre[i - 1] * trans).pow(K);

    int expIdx = 0;
    ll block = 1;
    while (N / block >= K) {
        ++expIdx;
        block *= K;
    }

    Mtx state(K + 1, 1);
    while (N) {
        if (block <= N) {
            int cnt = static_cast<int>(N / block);
            state *= (pre[expIdx] * trans).pow(cnt);
            N -= block * cnt;
        }
        --expIdx;
        block /= K;
    }

    ll total = 0;
    for (int i = 0; i <= K; ++i)
        (total += state[i][K]) %= MOD;
    cout << total << '\n';

