const ll MOD = 1000000007LL;

struct Mat {
    static constexpr int MAXDIM = 33;
    int dim;
    ll entries[MAXDIM][MAXDIM];

    Mat(int d = 0, ll diag = 0) : dim(d) {
        memset(entries, 0, sizeof(entries));
        for (int i = 0; i < d; ++i) entries[i][i] = diag;
    }

    Mat operator*(const Mat& other) const {
        assert(dim == other.dim);
        Mat res(dim);
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                for (int p = 0; p < dim; ++p)
                    (res.entries[i][p] += entries[i][j] * other.entries[j][p]) %= MOD;
        return res;
    }

    Mat& operator*=(const Mat& other) {
        return *this = (*this * other);
    }

    Mat bin_pow(int exp) const {
        Mat res(dim, 1);
        Mat base = *this;
        while (exp) {
            if (exp & 1) res *= base;
            base *= base;
            exp >>= 1;
        }
        return res;
    }

    void show() const {
        for (int i = 0; i < dim; ++i) {
            for (int j = 0; j < dim; ++j)
                printf("%d ", static_cast<int>(entries[i][j]));
            printf("\n");
        }
        printf("\n");
    }

    ll* operator[](int idx) { return entries[idx]; }
    const ll* operator[](int idx) const { return entries[idx]; }
};

