    ll N;
    int K;
    cin >> N >> K;

    if (N <= K) {
        cout << ((1LL << N) % MOD) << '\n';
        return 0;
    }

    int depth = static_cast<int>(log(N + 0.0) / log(K + 0.0) + 2);

    Mat transition(K + 1, 1);
    for (int j = 0; j < K; ++j) {
        transition[j][j] = 0;
        transition[(j + 1) % K][j] = 1;
    }

    vector<Mat> precomputed(depth);
    precomputed[0] = Mat(K + 1, 1);
    for (int i = 1; i <= K; ++i)
        precomputed[0][0][i] = 1;

    for (int i = 1; i < depth; ++i)
        precomputed[i] = (precomputed[i - 1] * transition).bin_pow(K);

    int idx = 0;
    ll block_size = 1;
    while (N / block_size >= K) {
        ++idx;
        block_size *= K;
    }

    Mat state(K + 1, 1);
    ll remaining = N;
    while (remaining > 0) {
        if (block_size <= remaining) {
            int count = static_cast<int>(remaining / block_size);
            state *= (precomputed[idx] * transition).bin_pow(count);
            remaining -= block_size * count;
        }
        --idx;
        block_size /= K;
    }

    ll sum = 0;
    for (int i = 0; i <= K; ++i)
        (sum += state[i][K]) %= MOD;
    cout << sum << '\n';

    return 0;
}

