using namespace std;

using ll = long long;
using pii = pair<int, int>;

constexpr ll MOD = 1000000007LL;

struct Matrix {
    static constexpr int MAX_SIZE = 33;
    int dimension;
    ll cells[MAX_SIZE][MAX_SIZE];

    Matrix(int d = 0, ll diag_val = 0) : dimension(d) {
        memset(cells, 0, sizeof(cells));
        for (int i = 0; i < d; ++i) cells[i][i] = diag_val;
    }

    Matrix operator*(const Matrix& other) const {
        assert(dimension == other.dimension);
        Matrix res(dimension);
        for (int i = 0; i < dimension; ++i)
            for (int j = 0; j < dimension; ++j)
                for (int k = 0; k < dimension; ++k)
                    (res.cells[i][k] += cells[i][j] * other.cells[j][k]) %= MOD;
        return res;
    }

    Matrix& operator*=(const Matrix& other) {
        return *this = (*this * other);
    }

    Matrix binary_exponentiation(int exponent) const {
        Matrix result(dimension, 1);
        Matrix base = *this;
        while (exponent) {
            if (exponent & 1) result *= base;
            base *= base;
            exponent >>= 1;
        }
        return result;
    }

    void output() const {
        for (int i = 0; i < dimension; ++i) {
            for (int j = 0; j < dimension; ++j)
                printf("%d ", (int)cells[i][j]);
            printf("\n");
        }
        printf("\n");
    }

    ll* operator[](int index) { return cells[index]; }
    const ll* operator[](int index) const { return cells[index]; }
};

int main() {
#ifdef DBG1
