    freopen(".out", "w", stdout);
    freopen(".err", "w", stderr);
#endif

    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll input_n;
    int input_k;
    cin >> input_n >> input_k;

    if (input_n <= input_k) {
        cout << ((1LL << input_n) % MOD) << '\n';
        return 0;
    }

    int depth = static_cast<int>(log(input_n + 0.0) / log(input_k + 0.0) + 2);

    Matrix T(input_k + 1, 1);
    for (int j = 0; j < input_k; ++j) {
        T[j][j] = 0;
        T[(j + 1) % input_k][j] = 1;
    }

    vector<Matrix> pre(depth);
    pre[0] = Matrix(input_k + 1, 1);
    for (int i = 1; i <= input_k; ++i)
        pre[0][0][i] = 1;

    for (int i = 1; i < depth; ++i)
        pre[i] = (pre[i - 1] * T).binary_exponentiation(input_k);

    int power_index = 0;
    ll segment_length = 1;
    while (input_n / segment_length >= input_k) {
        ++power_index;
        segment_length *= input_k;
    }

    Matrix current(input_k + 1, 1);
    ll leftover = input_n;
    while (leftover > 0) {
        if (segment_length <= leftover) {
            int times = static_cast<int>(leftover / segment_length);
            current *= (pre[power_index] * T).binary_exponentiation(times);
            leftover -= segment_length * times;
        }
        --power_index;
        segment_length /= input_k;
    }

    ll final_answer = 0;
    for (int i = 0; i <= input_k; ++i)
        (final_answer += current[i][input_k]) %= MOD;
    cout << final_answer << '\n';

    return 0;
}

#include <iostream>
#include <algorithm>
