#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

constexpr int64 P = 1000000007;

struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 x) : x(x) {
    if (x > P || x < 0) { cerr << "Invalied FiniteField!" << endl; exit(1); }
  }
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

template<typename T>
vector<vector<T>> operator*(
    const vector<vector<T>>& a1, const vector<vector<T>>& a2) {
  int n = a1.size();
  int m = a1[0].size();
  if (a2.size() != m) {
    cerr << "Matrix dimensions don't match for multiplication!" << endl;
    exit(1);
  }
  int l = a2[0].size();
  vector<vector<T>> result(n, vector<T>(l));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < l; j++) {
      for (int k = 0; k < m; k++) {
        result[i][j] += a1[i][k] * a2[k][j];
      }
    }
  }
  return result;
}

template<typename T>
vector<T> operator*(const vector<vector<T>>& matrix, const vector<T>& v) {
  int n = matrix.size();
  int m = matrix[0].size();
  if (v.size() != m) {
    cerr << "Matrix and vector dimensions don't match for multiplication!"
         << endl;
    exit(1);
  }
  vector<T> result(n);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      result[i] += matrix[i][j] * v[j];
    }
  }
  return result;
}

template<typename T>
vector<vector<T>> Make2DVector(int d1, int d2, T default_value) {
  return vector<vector<T>>(d1, vector<T>(d2, default_value));
}

template<typename T>
vector<vector<vector<T>>>
Make3DVector(int d1, int d2, int d3, T default_value) {
  return vector<vector<vector<T>>>(
      d1, vector<vector<T>>(d2, vector<T>(d3, default_value)));
}

constexpr int DEBUG = 0;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int64 n;
  int d;
  cin >> n >> d;

  auto shifts = Make3DVector<FiniteField>(d, d + 1, d + 1, 0);
  for (int k = 0; k < d; k++) {
    for (int i = 0; i < d; i++) {
      shifts[k][i][(i + k) % d] = 1;
    }
    shifts[k][d][d] = 1;
  }

  auto units = Make3DVector<FiniteField>(d, d + 1, d + 1, 0);
  for (int k = 0; k < d; k++) {
    for (int i = 0; i < d + 1; i++) {
      units[k][i][i] = 1;
    }
    for (int i = 0; i < d + 1; i++) {
      units[k][k][i] = 1;
    }
  }

  auto identity = Make2DVector<FiniteField>(d + 1, d + 1, 0);
  for (int i = 0; i < d + 1; i++) {
    identity[i][i] = 1;
  }

  map<int64, vector<vector<FiniteField>>> cache;

  function<vector<vector<FiniteField>>(int64)> find_matrix =
      [&](int64 p) -> vector<vector<FiniteField>> {
    if (cache.find(p) != cache.end()) {
      return cache.find(p) -> second;
    }

    if (p <= d) {
      auto matrix = identity;
      for (int k = 0; k < p; k++) {
        matrix = units[k] * matrix;
      }
      return matrix;
    }

    int64 child_p = d;
    while ((p + child_p - 1) / child_p > d) child_p *= d;
    auto child = find_matrix(child_p);
    auto matrix = child;
    int64 remaining_p = p;
    remaining_p -= child_p;
    for (int k = 1; k < d; k++) {
      if (remaining_p >= child_p) {
        matrix = shifts[d - k] * child * shifts[k] * matrix;
        remaining_p -= child_p;
      } else if (remaining_p > 0) {
        matrix = shifts[d - k] * find_matrix(remaining_p) * shifts[k] * matrix;
        remaining_p = 0;
      } else {
        break;
      }
    }

    cache[p] = matrix;

    return matrix;
  };

  if (DEBUG) cerr << "PHASE 1" << endl;

  auto matrix = find_matrix(n);
  if (DEBUG) cerr << "PHASE 2" << endl;

  vector<FiniteField> base_vector(d + 1);
  base_vector[d] = 1;
  auto final_vector = matrix * base_vector;
  FiniteField ans = 0;
  for (const auto& x : final_vector) ans += x;
  cout << ans.Value() << endl;
}

#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

constexpr int64 MOD = 1000000007;

class FieldElement {
 private:
  int64 val;
 public:
  FieldElement(int64 v = 0) : val(v % MOD) {
    if (val < 0) val += MOD;
    if (val >= MOD) { cerr << "FieldElement overflow!" << endl; exit(1); }
  }
  int64 get() const { return val; }
  FieldElement operator+(const FieldElement& o) const {
    return FieldElement((val + o.val) % MOD);
  }
  FieldElement operator-(const FieldElement& o) const {
    return FieldElement((val - o.val + MOD) % MOD);
  }
  FieldElement operator*(const FieldElement& o) const {
    return FieldElement((val * o.val) % MOD);
  }
  FieldElement operator/(const FieldElement& o) const {
    return (*this) * o.inverse();
  }
  FieldElement& operator+=(const FieldElement& o) {
    val = (val + o.val) % MOD;
    return *this;
  }
  FieldElement& operator-=(const FieldElement& o) {
    val = (val - o.val + MOD) % MOD;
    return *this;
  }
  FieldElement& operator*=(const FieldElement& o) {
    val = (val * o.val) % MOD;
    return *this;
  }
  FieldElement& operator/=(const FieldElement& o) {
    return (*this) *= o.inverse();
  }
  FieldElement inverse() const {
    int64 exp = MOD - 2;
    int64 base = val;
    int64 res = 1;
    while (exp) {
      if (exp & 1) res = (res * base) % MOD;
      base = (base * base) % MOD;
      exp >>= 1;
    }
    return FieldElement(res);
  }
};

template<typename T>
vector<vector<T>> matmul(const vector<vector<T>>& A, const vector<vector<T>>& B) {
  int rowsA = A.size();
  int colsA = A[0].size();
  int rowsB = B.size();
  int colsB = B[0].size();
  if (colsA != rowsB) {
    cerr << "Matrix multiplication dimension mismatch!" << endl;
    exit(1);
  }
  vector<vector<T>> result(rowsA, vector<T>(colsB, T(0)));
  for (int i = 0; i < rowsA; ++i) {
    for (int j = 0; j < colsB; ++j) {
      for (int k = 0; k < colsA; ++k) {
        result[i][j] = result[i][j] + A[i][k] * B[k][j];
      }
    }
  }
  return result;
}

template<typename T>
vector<T> matvecmul(const vector<vector<T>>& A, const vector<T>& v) {
  int rows = A.size();
  int cols = A[0].size();
  if (v.size() != cols) {
    cerr << "Matrix-vector dimension mismatch!" << endl;
    exit(1);
  }
  vector<T> result(rows, T(0));
  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      result[i] = result[i] + A[i][j] * v[j];
    }
  }
  return result;
}

template<typename T>
vector<vector<T>> make2D(int r, int c, const T& val = T()) {
  return vector<vector<T>>(r, vector<T>(c, val));
}

template<typename T>
vector<vector<vector<T>>> make3D(int d1, int d2, int d3, const T& val = T()) {
  return vector<vector<vector<T>>>(d1, vector<vector<T>>(d2, vector<T>(d3, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int64 n;
  int d;
  cin >> n >> d;

  auto shifts = make3D<FieldElement>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d; ++i) {
      shifts[k][i][(i + k) % d] = FieldElement(1);
    }
    shifts[k][d][d] = FieldElement(1);
  }

  auto units = make3D<FieldElement>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d + 1; ++i) {
      units[k][i][i] = FieldElement(1);
    }
    for (int i = 0; i < d + 1; ++i) {
      units[k][k][i] = FieldElement(1);
    }
  }

  auto I = make2D<FieldElement>(d + 1, d + 1);
  for (int i = 0; i < d + 1; ++i) {
    I[i][i] = FieldElement(1);
  }

  unordered_map<int64, vector<vector<FieldElement>>> memo;

  function<vector<vector<FieldElement>>(int64)> buildMatrix = [&](int64 p) {
    if (memo.count(p)) return memo[p];
    if (p <= d) {
      auto M = I;
      for (int k = 0; k < p; ++k) {
        M = matmul(units[k], M);
      }
      return M;
    }
    int64 block = d;
    while ((p + block - 1) / block > d) block *= d;
    auto child = buildMatrix(block);
    auto M = child;
    int64 rem = p - block;
    for (int k = 1; k < d; ++k) {
      if (rem >= block) {
        M = matmul(matmul(matmul(shifts[d - k], child), shifts[k]), M);
        rem -= block;
      } else if (rem > 0) {
        M = matmul(matmul(matmul(shifts[d - k], buildMatrix(rem)), shifts[k]), M);
        rem = 0;
      } else {
        break;
      }
    }
    return memo[p] = M;
  };

  auto M = buildMatrix(n);
  vector<FieldElement> base(d + 1);
  base[d] = FieldElement(1);
  auto resVec = matvecmul(M, base);
  FieldElement total;
  for (const auto& x : resVec) total += x;
  cout << total.get() << '\n';
}

#include <bits/stdc++.h>

using namespace std;

using i64 = long long;

const i64 MOD = 1000000007LL;

struct F {
  i64 v;
  F(i64 x = 0) : v(x % MOD) {
    if (v < 0) v += MOD;
    if (v >= MOD) { cerr << "F error\n"; exit(1); }
  }
  F operator+(const F& o) const { return F((v + o.v) % MOD); }
  F operator-(const F& o) const { return F((v - o.v + MOD) % MOD); }
  F operator*(const F& o) const { return F((v * o.v) % MOD); }
  F operator/(const F& o) const { return (*this) * o.inv(); }
  F& operator+=(const F& o) { v = (v + o.v) % MOD; return *this; }
  F& operator-=(const F& o) { v = (v - o.v + MOD) % MOD; return *this; }
  F& operator*=(const F& o) { v = (v * o.v) % MOD; return *this; }
  F& operator/=(const F& o) { return (*this) *= o.inv(); }
  F inv() const {
    i64 e = MOD - 2, b = v, r = 1;
    while (e) {
      if (e & 1) r = (r * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1;
    }
    return F(r);
  }
};

template<typename T>
