}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  i64 n;
  int d;
  cin >> n >> d;

  auto S = mat3D<F>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k)
    for (int i = 0; i < d; ++i)
      S[k][i][(i + k) % d] = F(1);
  for (int k = 0; k < d; ++k)
    S[k][d][d] = F(1);

  auto U = mat3D<F>(d, d + 1, d + 1);
  for (int k = 0; k < d; ++k) {
    for (int i = 0; i < d + 1; ++i)
      U[k][i][i] = F(1);
    for (int i = 0; i < d + 1; ++i)
      U[k][k][i] = F(1);
  }

  auto I = mat2D<F>(d + 1, d + 1);
  for (int i = 0; i < d + 1; ++i)
    I[i][i] = F(1);

  unordered_map<i64, vector<vector<F>>> dp;

  function<vector<vector<F>>(i64)> solve = [&](i64 p) -> vector<vector<F>> {
    if (dp.count(p)) return dp[p];
    if (p <= d) {
      auto M = I;
      for (int k = 0; k < p; ++k)
        M = mul(U[k], M);
      return M;
    }
    i64 block = d;
    while ((p + block - 1) / block > d) block *= d;
    auto child = solve(block);
    auto M = child;
    i64 rem = p - block;
    for (int k = 1; k < d; ++k) {
      if (rem >= block) {
        M = mul(mul(mul(S[d - k], child), S[k]), M);
        rem -= block;
      } else if (rem > 0) {
        M = mul(mul(mul(S[d - k], solve(rem)), S[k]), M);
        rem = 0;
      } else break;
    }
    return dp[p] = M;
  };

  auto M = solve(n);
  vector<F> base(d + 1);
  base[d] = F(1);
  auto ansVec = mul(M, base);
  F sum;
  for (auto& x : ansVec) sum += x;
  cout << sum.v << '\n';
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;

const ll MOD = 1000000007;

class ModInt {
 public:
  ll val;
  ModInt(ll v = 0) : val(v % MOD) {
    if (val < 0) val += MOD;
    if (val >= MOD) { cerr << "ModInt error\n"; exit(1); }
  }
  ModInt operator+(const ModInt& o) const { return ModInt((val + o.val) % MOD); }
  ModInt operator-(const ModInt& o) const { return ModInt((val - o.v + MOD) % MOD); }
  ModInt operator*(const ModInt& o) const { return ModInt((val * o.val) % MOD); }
  ModInt operator/(const ModInt& o) const { return (*this) * o.inv(); }
  ModInt& operator+=(const ModInt& o) { val = (val + o.val) % MOD; return *this; }
  ModInt& operator-=(const ModInt& o) { val = (val - o.val + MOD) % MOD; return *this; }
  ModInt& operator*=(const ModInt& o) { val = (val * o.val) % MOD; return *this; }
  ModInt& operator/=(const ModInt& o) { return (*this) *= o.inv(); }
  ModInt inv() const {
    ll e = MOD - 2, b = val, r = 1;
    while (e) {
      if (e & 1) r = (r * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1;
    }
    return ModInt(r);
  }
};

