  vector<vector<T>> C(n, vector<T>(p));
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < p; ++j)
      for (int k = 0; k < m; ++k)
        C[i][j] = C[i][j] + A[i][k] * B[k][j];
  return C;
}

