using Matrix = vector<vector<int>>;

Matrix multiply(const Matrix& A, const Matrix& B) {
    int sz = A.size();
    Matrix C(sz, vector<int>(sz, 0));
    for (int i = 0; i < sz; ++i) {
        for (int j = 0; j < sz; ++j) {
            ll cur = 0;
            for (int k = 0; k < sz; ++k) {
                if (cur > LIM) cur %= MOD;
                cur += (ll)A[i][k] * B[k][j];
            }
            C[i][j] = cur % MOD;
        }
    }
    return C;
}

Matrix identity(int sz) {
    Matrix I(sz, vector<int>(sz, 0));
    for (int i = 0; i < sz; ++i) I[i][i] = 1;
    return I;
}

void run() {
    cin >> n >> base;
    int sz = base + 1;

    vector<vector<Matrix>> mat(60, vector<Matrix>(base, Matrix(sz, vector<int>(sz, 0))));

    for (int i = 0; i < base; ++i) {
        for (int j = 0; j < sz; ++j) {
            for (int k = 0; k < sz; ++k) {
                mat[0][i][j][k] = (j == k || i == j) ? 1 : 0;
            }
        }
    }

    for (int i = 1; i < 60; ++i) {
        for (int j = 0; j < base; ++j) {
            mat[i][j] = identity(sz);
            for (int k = 0; k < base; ++k) {
                mat[i][j] = multiply(mat[i][j], mat[i-1][(j + k) % base]);
            }
        }
    }

    Matrix have = identity(sz);
