Matrix matMul(const Matrix& A, const Matrix& B) {
    int N = A.size();
    Matrix C(N, vector<int>(N, 0));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            ll sum = 0;
            for (int k = 0; k < N; ++k) {
                if (sum > LIM) sum %= MOD;
                sum += (ll)A[i][k] * B[k][j];
            }
            C[i][j] = sum % MOD;
        }
    }
    return C;
}

