        if(B[j][i] != 0) idx = j;
      }
      if(idx == -1) return (0);
      if(i != idx) {
        ret *= -1;
        swap(B[i], B[idx]);
      }
      ret *= B[i][i];
      T vv = B[i][i];
      for(int j = 0; j < width(); j++) {
        B[i][j] /= vv;
      }
      for(int j = i + 1; j < width(); j++) {
        T a = B[j][i];
        for(int k = 0; k < width(); k++) {
          B[j][k] -= B[i][k] * a;
        }
      }
    }
    return (ret);
  }

  void rot() {
      Matrix<ll> B(A.size());
      for(int i = 0; i < K; i++) {
          for(int j = 0; j < K; j++) {
              B[i][j] = A[(i+K-1)%K][(j+K-1)%K];
          }
          B[i][K] = A[(i+K-1)%K][K];
          B[K][i] = A[K][(i+K-1)%K];
          B[K][K] = A[K][K];
      }
      for(int i = 0; i < A.size(); i++) {
          for(int j = 0; j < A[0].size(); j++) {
              A[i][j] = B[i][j];
          }
