typedef long long ll;
const int MOD = 1000000007;

struct Matrix {
    int mat[33][33];
} identity, base[70], result, prefix[70], suffix[70];

ll n, k;

void printMatrix(Matrix m) {
    for (int i = 0; i <= k; ++i) {
        for (int j = 0; j <= k; ++j)
            cout << m.mat[i][j] << ' ';
        cout << '\n';
    }
    cout << '\n';
}

Matrix multiply(Matrix a, Matrix b) {
    Matrix c = identity;
    for (int k_idx = 0; k_idx <= k; ++k_idx) {
        for (int i = 0; i <= k; ++i) {
            for (int j = 0; j <= k; ++j) {
                ll temp = (static_cast<ll>(a.mat[i][k_idx]) * b.mat[k_idx][j]) % MOD;
                c.mat[i][j] = (c.mat[i][j] + temp) % MOD;
            }
        }
    }
    return c;
}

void preprocess() {
    prefix[0] = base[0];
    for (int i = 1; i < k; ++i)
        prefix[i] = multiply(prefix[i-1], base[i]);

    suffix[k-1] = base[k-1];
    for (int i = k-2; i >= 0; --i)
        suffix[i] = multiply(base[i], suffix[i+1]);

    base[0] = suffix[0];
    for (int i = 1; i < k; ++i)
        base[i] = multiply(suffix[i], prefix[i-1]);
}

void solve() {
    cin >> n >> k;
    int i, j;
    result = identity;
    for (i = 0; i < k; ++i) {
        base[i] = identity;
        for (j = 0; j <= k; ++j)
            base[i].mat[j][j] = 1;
        for (j = 0; j <= k; ++j)
            base[i].mat[j][i] = 1;
        result.mat[i][i] = 1;
    }
    result.mat[k][k] = 1;

    for (; n > 0; n /= k) {
        int digit = n % k;
        if (digit) {
            ll pos = 0, temp = n;
            while (temp) {
                pos = (pos + (temp /= k)) % k;
            }
            for (i = digit - 1; i >= 0; --i) {
                result = multiply(base[(pos + i) % k], result);
            }
        }
        preprocess();
    }

    int answer = 1;
    for (i = 0; i < k; ++i)
        answer = (answer + result.mat[k][i]) % MOD;
    cout << answer << '\n';
}

int main() {
    solve();
    return 0;
}

