Mat matMul(const Mat& A, const Mat& B) {
    Mat C = Iden;
    for (int k = 0; k <= K; ++k)
        for (int i = 0; i <= K; ++i)
            for (int j = 0; j <= K; ++j) {
                i64 val = (i64)A.data[i][k] * B.data[k][j] % MOD;
                C.data[i][j] = (C.data[i][j] + val) % MOD;
            }
    return C;
}

void precomp() {
    Pref[0] = Base[0];
    for (int i = 1; i < K; ++i) Pref[i] = matMul(Pref[i-1], Base[i]);
    Suf[K-1] = Base[K-1];
    for (int i = K-2; i >= 0; --i) Suf[i] = matMul(Base[i], Suf[i+1]);
    Base[0] = Suf[0];
    for (int i = 1; i < K; ++i) Base[i] = matMul(Suf[i], Pref[i-1]);
}

