            tmp1.m[i][j] = m[i][j];
            tmp2.m[i][j] = b.m[i][j];
        }
        FOR(i, 0, n) FOR(j, 0, n) {
            ll sum = 0;
            FOR(k, 0, n) {
                sum += (ll)tmp1.m[i][k] * tmp2.m[k][j] % MOD;
            }
            m[i][j] = (int)(sum % MOD);
        }
    }
} A[64][32], pre[64][32], suf[64][32];

ll N;
int K;

void preprocess(int idx) {
    pre[idx][1] = A[idx][0];
    FOR(j, 2, K + 1) {
        pre[idx][j] = pre[idx][j - 1];
        pre[idx][j].multiply(A[idx][j - 1]);
    }
    suf[idx][K - 1] = A[idx][K - 1];
    ROF(j, 0, K - 1) {
        suf[idx][j] = A[idx][j];
        suf[idx][j].multiply(suf[idx][j + 1]);
    }
}

int digit_sum(ll x) {
    int s = 0;
    while (x) {
        (s += x % K) %= K;
        x /= K;
    }
    return s;
}

Mat solve(ll x, int depth) {
    if (x < K) {
        Mat res = A[depth][0];
        FOR(i, 1, x) res.multiply(A[depth][i]);
        return res;
    }
    Mat res = solve(x / K, depth + 1);
    int offset = digit_sum(x / K);
    FOR(i, 0, x % K) {
        res.multiply(A[depth][(offset + i) % K]);
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> K;
    FOR(i, 0, K) {
        A[0][i].init(K + 1, 0);
        FOR(j, 0, K + 1) {
            A[0][i].m[j][j] = 1;
            A[0][i].m[j][i] = 1;
        }
    }
    for (int d = 1; (pow(K, d) - 1000) <= N; ++d) {
        preprocess(d - 1);
        FOR(x, 0, K) {
            A[d][x] = suf[d - 1][x];
            if (x > 0) A[d][x].multiply(pre[d - 1][x]);
        }
    }
    Mat ans = solve(N, 0);
    int result = 0;
    FOR(i, 0, K + 1) {
        (result += ans.m[K][i]) %= MOD;
    }
    cout << result << '\n';
    return 0;
}

