Matrix identity(int size) {
    Matrix res;
    for (int i = 0; i <= size; ++i)
        res[i][i] = 1;
    return res;
}

Matrix multiply(const Matrix& A, const Matrix& B, int size) {
    Matrix C;
    for (int i = 0; i <= size; ++i)
        for (int j = 0; j <= size; ++j)
            for (int k = 0; k <= size; ++k)
                C[i][j] = add(C[i][j], mul(A[i][k], B[k][j]));
    return C;
}

Matrix power_matrix(const Matrix& base, int exp, int size) {
    Matrix result = identity(size);
    Matrix current = base;
    while (exp > 0) {
        if (exp & 1)
            result = multiply(result, current, size);
        current = multiply(current, current, size);
        exp >>= 1;
    }
    return result;
}

