Matrix build_shifted_matrix(int depth, int shift) {
    Matrix res;
    for (int i = 0; i <= global_k; ++i)
        for (int j = 0; j <= global_k; ++j) {
            int ni = (i == global_k) ? i : (i + shift) % global_k;
            int nj = (j == global_k) ? j : (j + shift) % global_k;
            res[ni][nj] = f[depth][i][j];
        }
