int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N >> K;

    // Convert N to base-K digits
    int cnt = 0;
    ll temp = 1;
    while (temp <= N) {
        temp *= K;
        ++cnt;
    }
    temp /= K;

    vector<int> digits(cnt);
    for (int i = 0; i < cnt; ++i) {
        digits[i] = N / temp;
        N %= temp;
        temp /= K;
    }

    // Initialize matrices
    for (int i = 0; i <= K; ++i) {
        init_matrix(R[i], K + 1, K + 1);
    }
    for (int i = 0; i <= cnt; ++i) {
        for (int j = 0; j < K; ++j) {
            init_matrix(D[i][j], K + 1, K + 1);
        }
    }

    // Setup base rotation matrices R[j]
    R[0][K][K] = 1;
    R[1][K][K] = 1;
    for (int j = 0; j < K; ++j) {
        R[0][j][j] = 1;
        R[1][(j + K - 1) % K][j] = 1;
    }
    for (int j = 2; j <= K; ++j) {
        R[j] = multiply(R[j - 1], R[1]);
    }

    // Setup D matrices
    for (int j = 0; j <= K; ++j) {
        D[0][0][j][j] = 1;
        D[0][0][j][0] = 1;
    }

    for (int i = 0; i <= cnt; ++i) {
        for (int j = 1; j < K; ++j) {
            mat temp1 = multiply(R[K - j], D[i][0]);
            mat temp2 = multiply(temp1, R[j]);
            D[i][j] = multiply(D[i][j - 1], temp2);
        }
        if (i < cnt) {
            D[i + 1][0] = D[i][K - 1];
        }
    }

    // Compute answer
    mat result(1, vec(K + 1, 0));
    result[0][K] = 1;
    int current_mod = 0;

    for (int i = 0; i < cnt; ++i) {
        if (digits[i] != 0) {
            mat temp1 = multiply(R[K - current_mod], D[cnt - i - 1][digits[i] - 1]);
            mat temp2 = multiply(temp1, R[current_mod]);
            result = multiply(result, temp2);
        }
        current_mod = (current_mod + digits[i]) % K;
    }

    ll answer = 0;
    for (int i = 0; i <= K; ++i) {
        answer = (answer + result[0][i]) % MOD;
    }

    cout << answer << endl;
    return 0;
}

