    // Setup R[0], R[1]
    R[0][K][K] = R[1][K][K] = 1;
    for (int j = 0; j < K; ++j) {
        R[0][j][j] = 1;
        R[1][(j + K - 1) % K][j] = 1;
    }

    // Build R[j] for j >= 2
    for (int j = 2; j <= K; ++j) {
