    int digits = 0;
    while (power <= N / K) {
        power *= K;
        ++digits;
    }
    power *= K; // now power > N
    power /= K;

    vector<int> baseK(digits);
    for (int i = 0; i < digits; ++i) {
        baseK[i] = N / power;
        N %= power;
        power /= K;
    }

