int kb;

inline void mat_mul(Mat A,Mat B,Mat res) {
    static Mat C;
    memset(C,0,sizeof(C));
    for(int i=0;i<=kb;i++)for(int k=0;k<=kb;k++)for(int j=0;j<=kb;j++) {
        C[i][j]=(C[i][j]+(LL)A[i][k]*B[k][j])%MOD;
    }
    memcpy(res,C,sizeof(C));
}

Mat A[70][maxk],pre[maxk],suf[maxk],ans,I;
void init_I() {
    memset(I,0,sizeof(I));
    for(int i=0;i<=kb;i++)I[i][i]=1;
}

int dig[70],len;

void prepocess() {
    for(int i=0;i<kb;i++) {
        for(int j=0;j<=kb;j++) {
            A[0][i][j][j]=1;
            A[0][i][i][j]=1;
        }
    }
    for(int i=1;i<len;i++) {
        memcpy(pre[0],A[i-1][0],sizeof(A[i-1][0]));
        for(int j=1;j<kb;j++) {
            mat_mul(A[i-1][j],pre[j-1],pre[j]);
        }
        memcpy(suf[kb-1],A[i-1][kb-1],sizeof(A[i-1][kb-1]));
        for(int j=kb-2;j>=0;j--) {
            mat_mul(suf[j+1],A[i-1][j],suf[j]);
        }
        for(int j=0;j<kb;j++) {
            if(j==0) mat_mul(I,suf[j],A[i][j]);
            else mat_mul(pre[j-1],suf[j],A[i][j]);
        }
    }
}

