}

#include <bits/stdc++.h>
using namespace std;
using lint = long long;
const lint MOD = 1000000007;

struct Mat {
    int n, m;
    vector<vector<lint>> a;
    Mat(int nn = 0, int mm = 0) : n(nn), m(mm), a(nn, vector<lint>(mm, 0)) {}
    lint& operator()(int i, int j) { return a[i][j]; }
    const lint& operator()(int i, int j) const { return a[i][j]; }
    Mat operator*(const Mat& b) const {
        Mat res(n, b.m);
        for (int i = 0; i < n; ++i)
            for (int k = 0; k < m; ++k)
                for (int j = 0; j < b.m; ++j)
                    res(i, j) = (res(i, j) + a[i][k] * b.a[k][j]) % MOD;
        return res;
    }
    static Mat identity(int sz) {
        Mat I(sz, sz);
        for (int i = 0; i < sz; ++i) I(i, i) = 1;
        return I;
    }
};

Mat mpow(Mat base, int exp) {
    Mat res = Mat::identity(base.n);
    while (exp) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

Mat baseMats[65];

Mat getTrans(int i, int k) {
    return mpow(baseMats[i + k], k - i) * mpow(baseMats[i], i);
}

lint solve(lint N, lint K) {
    if (N == 0) return 1;
    vector<lint> digits;
    lint tmp = N;
    while (tmp) {
        digits.push_back(tmp % K);
        tmp /= K;
    }
    reverse(digits.begin(), digits.end());
    int D = digits.size();
    vector<Mat> T(D + 5), TPow(D + 5);
    T[0] = baseMats[K - 1];
    TPow[0] = mpow(T[0], K - 1);
    if (D > 1) {
        T[1] = getTrans(K - 1, K);
        TPow[1] = mpow(T[1], K - 1);
    }
    Mat suffix = Mat::identity(2 * K + 1);
    for (int j = 2; j <= D; ++j) {
        int idx = K - (j % K);
        if (idx == K) idx = 0;
        T[j] = getTrans(idx, K);
        suffix = suffix * TPow[j - 1];
        T[j] = T[j] * suffix;
        TPow[j] = mpow(T[j], K - 1);
    }
    int r = N % K;
    N -= r;
    lint q = 0;
    tmp = N;
    if (tmp) {
        while (tmp % K == 0) {
            ++q;
            tmp /= K;
        }
    }
    q = (K - q % K) % K;
    Mat ans = Mat::identity(2 * K + 1);
    ans = mpow(baseMats[q], r) * mpow(baseMats[q + K], max(r - q, (lint)0));
    N /= K;
    if (N == 0) {
        return (ans(2 * K, 0) + ans(0, 0)) % MOD;
    }
    --N;
    int idx = 1;
    vector<lint> num;
    while (N) {
        num.push_back(N % K);
        N /= K;
    }
    for (lint d : num) {
        if (d > 0) ans = ans * mpow(T[idx], d);
        ++idx;
    }
    ans = ans * T[1];
    return (ans(2 * K, 0) + ans(0, 0)) % MOD;
}

int main() {
    lint n, k;
    cin >> n >> k;
    for (int i = 0; i < 2 * k + 1; ++i) {
        baseMats[i] = Mat(2 * k + 1, 2 * k + 1);
        for (int j = 0; j < i; ++j) baseMats[i](0, j) = 1;
        for (int j = 0; j < 2 * k - 1; ++j) baseMats[i](j + 1, j) = 1;
        baseMats[i](2 * k, 0) = 1;
        baseMats[i](2 * k, 2 * k) = 1;
    }
    cout << solve(n, k) << '\n';
    return 0;
}

