const i64 MOD = 1000000007;

struct Matrix {
    int h, w;
    vector<vector<i64>> data;
    Matrix(int n = 0) : h(n), w(n), data(n, vector<i64>(n, 0)) {}
    Matrix(int hh, int ww) : h(hh), w(ww), data(hh, vector<i64>(ww, 0)) {}
    i64& at(int r, int c) { return data[r][c]; }
    const i64& at(int r, int c) const { return data[r][c]; }
    Matrix& operator*=(const Matrix& other) {
        assert(w == other.h);
        Matrix res(h, other.w);
        for (int i = 0; i < h; ++i)
            for (int k = 0; k < w; ++k)
                for (int j = 0; j < other.w; ++j)
                    res.data[i][j] = (res.data[i][j] + data[i][k] * other.data[k][j]) % MOD;
        *this = res;
        return *this;
    }
    Matrix operator*(const Matrix& other) const {
        Matrix res(*this);
        res *= other;
        return res;
    }
    static Matrix identity(int n) {
        Matrix I(n);
        for (int i = 0; i < n; ++i) I.at(i, i) = 1;
        return I;
    }
};

Matrix power(Matrix base, int exp) {
    Matrix result = Matrix::identity(base.h);
    while (exp > 0) {
        if (exp & 1) result = result * base;
        base = base * base;
        exp >>= 1;
    }
    return result;
}

Matrix M[65];

Matrix buildTrans(int i, int k) {
    return power(M[i + k], k - i) * power(M[i], i);
}

i64 count Ways(i64 n, i64 k) {
    if (n == 0) return 1;
    vector<i64> digits;
    i64 tmp = n;
    while (tmp > 0) {
        digits.push_back(tmp % k);
        tmp /= k;
    }
    reverse(digits.begin(), digits.end());
    int len = digits.size();
    vector<Matrix> T(len + 5), P(len + 5);
    T[0] = M[k - 1];
    P[0] = power(T[0], k - 1);
    if (len > 1) {
        T[1] = buildTrans(k - 1, k);
        P[1] = power(T[1], k - 1);
    }
    Matrix suf = Matrix::identity(2 * k + 1);
    for (int j = 2; j <= len; ++j) {
        int idx = k - j % k;
        if (idx == k) idx = 0;
        T[j] = buildTrans(idx, k);
        suf = suf * P[j - 1];
        T[j] = T[j] * suf;
        P[j] = power(T[j], k - 1);
    }
    i64 r = n % k;
    n -= r;
    i64 shift = 0;
    tmp = n;
    if (tmp > 0) {
        while (tmp % k == 0) {
            ++shift;
            tmp /= k;
        }
    }
    shift = (k - shift % k) % k;
    Matrix ans = Matrix::identity(2 * k + 1);
    ans = power(M[shift], r) * power(M[shift + k], max(r - shift, (i64)0));
    n /= k;
    if (n == 0) {
        return (ans.at(2 * k, 0) + ans.at(0, 0)) % MOD;
    }
    --n;
    vector<i64> d;
    while (n > 0) {
        d.push_back(n % k);
        n /= k;
    }
    int pos = 1;
    for (i64 dig : d) {
        if (dig > 0) ans = ans * power(T[pos], dig);
        ++pos;
    }
    ans = ans * T[1];
    return (ans.at(2 * k, 0) + ans.at(0, 0)) % MOD;
}

int main() {
    i64 N, K;
    cin >> N >> K;
    for (i64 i = 0; i < 2 * K + 1; ++i) {
        M[i] = Matrix(2 * K + 1, 2 * K + 1);
        for (i64 j = 0; j < i; ++j) M[i].at(0, j) = 1;
        for (i64 j = 0; j < 2 * K - 1; ++j) M[i].at(j + 1, j) = 1;
        M[i].at(2 * K, 0) = 1;
        M[i].at(2 * K, 2 * K) = 1;
    }
    cout << countWays(N, K) << '\n';
    return 0;
}

