const ll MOD = 1000000007LL;

struct Matrix {
    int R, C;
    vector<vector<ll>> v;
    Matrix(int n = 0) : R(n), C(n), v(n, vector<ll>(n, 0)) {}
    Matrix(int r, int c) : R(r), C(c), v(r, vector<ll>(c, 0)) {}
    ll& at(int i, int j) { return v[i][j]; }
    const ll& at(int i, int j) const { return v[i][j]; }
    Matrix operator*(const Matrix& o) const {
        Matrix res(R, o.C);
        for (int i = 0; i < R; ++i)
            for (int k = 0; k < C; ++k)
                for (int j = 0; j < o.C; ++j)
                    res.v[i][j] = (res.v[i][j] + v[i][k] * o.v[k][j]) % MOD;
        return res;
    }
    static Matrix ident(int n) {
        Matrix I(n);
        for (int i = 0; i < n; ++i) I.at(i, i) = 1;
        return I;
    }
};

Matrix pow_matrix(Matrix base, int exp) {
    Matrix res = Matrix::ident(base.R);
    while (exp > 0) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

Matrix A[65];

Matrix make_matrix(int i, int k) {
    return pow_matrix(A[i + k], k - i) * pow_matrix(A[i], i);
}

ll eval(ll N, ll K) {
    if (N == 0) return 1;
    vector<ll> digits;
    ll tmp = N;
    while (tmp) {
        digits.push_back(tmp % K);
        tmp /= K;
    }
    reverse(digits.begin(), digits.end());
    int len = digits.size();
    vector<Matrix> T(len + 5), P(len + 5);
    T[0] = A[K - 1];
    P[0] = pow_matrix(T[0], K - 1);
    if (len > 1) {
        T[1] = make_matrix(K - 1, K);
        P[1] = pow_matrix(T[1], K - 1);
    }
    Matrix suffix = Matrix::ident(2 * K + 1);
    for (int j = 2; j <= len; ++j) {
        int idx = K - (j % K);
        if (idx == K) idx = 0;
        T[j] = make_matrix(idx, K);
        suffix = suffix * P[j - 1];
        T[j] = T[j] * suffix;
        P[j] = pow_matrix(T[j], K - 1);
    }
    ll r = N % K;
    N -= r;
    ll shift = 0;
    tmp = N;
    if (tmp > 0) {
        while (tmp % K == 0) {
            ++shift;
            tmp /= K;
        }
    }
    shift = (K - shift % K) % K;
    Matrix ans = Matrix::ident(2 * K + 1);
    ans = pow_matrix(A[shift], r) * pow_matrix(A[shift + K], max(r - shift, (ll)0));
    N /= K;
    if (N == 0) {
        return (ans.at(2 * K, 0) + ans.at(0, 0)) % MOD;
    }
    --N;
    vector<ll> num;
    while (N > 0) {
        num.push_back(N % K);
        N /= K;
    }
    int pos = 1;
    for (ll d : num) {
        if (d > 0) ans = ans * pow_matrix(T[pos], d);
        ++pos;
    }
    ans = ans * T[1];
    return (ans.at(2 * K, 0) + ans.at(0, 0)) % MOD;
}

