        for (ll j = 0; j < i; ++j) A[i].at(0, j) = 1;
        for (ll j = 0; j < 2 * k - 1; ++j) A[i].at(j + 1, j) = 1;
        A[i].at(2 * k, 0) = 1;
        A[i].at(2 * k, 2 * k) = 1;
    }
    cout << eval(n, k) << '\n';
    return 0;
}

