            A[i].val[j][i] = 1;
        }
    }

    vector<Matrix> prefix(n + 2), suffix(n + 2);
    prefix[0].set_identity();
    suffix[n + 1].set_identity();

    for (; m > 0; m /= n) {
        lint u = m % n;
        if (u) {
            lint s = 0;
            for (lint v = m; v > 0; v /= n) {
                s = (s + v / n) % n;
            }
            u = (s + u - 1) % n + 1;
            for (; u != s; --u) {
                if (u <= 0) u += n;
                result = A[u] * result;
            }
        }

        for (int i = 1; i <= n; ++i) {
            prefix[i] = prefix[i - 1] * A[i];
        }
        for (int i = n; i >= 1; --i) {
            suffix[i] = A[i] * suffix[i + 1];
        }
        for (int i = 1; i <= n; ++i) {
            A[i] = suffix[i] * prefix[i - 1];
        }
    }

    int final_value = 1;
    for (int i = 1; i <= n; ++i) {
        final_value = (final_value + result.val[n + 1][i]) % MOD;
    }
    printf("%d\n", final_value);

    return 0;
}

