#include <bits/stdc++.h>
using namespace std;
#define mod 1000000007
#define N 33
#define int long long
int bin[N*2],n,m;
struct matrix{ 
    int mat[N][N];
    inline matrix operator * (const matrix &a) const {
        matrix res;
        memset(res.mat,0,sizeof(res.mat));
        for (int i=0;i<=m;++i){
            for (int j=0;j<=m;++j){
                for (int k=0;k<=m;++k){
                    res.mat[i][j]=(res.mat[i][j]+mat[i][k]*a.mat[k][j])%mod;
                }
            }
        }
        return res;
    }
}ans,P[N*2][N],S[N*2][N],A[N*2][N];
int read(){
    int x=0,f=1;
    char ch=getchar();
    while (ch<'0' || ch>'9'){
        if (ch=='-') f=-1;
        ch=getchar();
    }
    while (ch>='0' && ch<='9'){
        x=x*10+ch-'0';ch=getchar();
    }
    return x*f;
}
signed main(){
    n=read(),m=read();
    int n2=n,len=-1;
    while (n2){ 
        len++;bin[len]=n2%m;n2=n2/m;
    }
    len++;
    for (int i=0;i<=m;++i) ans.mat[0][i]=1; 
    for (int i=0;i<len;++i){
        for (int j=0;j<=m;++j) A[i][0].mat[j][j]=1;
        if (!i){ 
            for (int j=0;j<m;++j){
                A[i][j].mat[m][m]=1;
                for (int k=0;k<m;++k){
                    if (k!=j){
                        A[i][j].mat[k][k]=1;
                        continue;
                    }
                    for (int l=0;l<=m;++l) A[i][j].mat[k][l]=1;
                }
            }
        }else{
            for (int j=0;j<m;++j){
                if (!j) A[i][j]=S[i-1][0]; 
                else A[i][j]=S[i-1][j]*P[i-1][j-1];
            }
        }
        P[i][0]=A[i][0];
        for (int j=1;j<m;++j) P[i][j]=P[i][j-1]*A[i][j];
        S[i][m-1]=A[i][m-1];
        for (int j=m-2;j>=0;--j) S[i][j]=A[i][j]*S[i][j+1];
    }
    int j=0;
    for (int i=len-1;i>=0;--i){
        while (bin[i] --> 0){
            ans=ans*A[i][j];j++;if (j==m) j=0;
        }
    }
    cout<<ans.mat[0][m]<<endl;
}

