    }
}

long long recursive_compute(int current_level, int bitmask) {
    if (cache[current_level][bitmask] != -1) {
        return cache[current_level][bitmask];
    }
    if (bitmask == 0) {
        cache[current_level][bitmask] = factorial_array[n];
