        return cache[current_level][bitmask];
    }
    cache[current_level][bitmask] = 0;
    int complement = bitmask - get_lowest_bit(bitmask);
    for (int subset = complement; subset; subset = (subset - 1) & complement) {
        cache[current_level][bitmask] = (cache[current_level][bitmask] + inverse_factorial_array[bitmask - subset] * recursive_compute(current_level + 1, subset)) % p;
    }
    cache[current_level][bitmask] = (cache[current_level][bitmask] + inverse_factorial_array[bitmask] * recursive_compute(current_level + 1, 0)) % p;
