void walsh_transform(int *arr, int size, int sign) {
    for (int step = 1; step < size; step <<= 1) {
        for (int i = 0; i < size; i += (step << 1)) {
            for (int j = 0; j < step; ++j) {
                int x = arr[i + j];
                int y = (1LL * sign * arr[i + j + step]) % MOD;
                arr[i + j] = mod_add(x, y);
                arr[i + j + step] = mod_add(x, MOD - y);
            }
        }
    }
