inline int norm(int x) {
    return (x % MOD + MOD) % MOD;
}

inline void add(int &x, int y) {
    x = norm(x + y);
}

int power(int base, int exp) {
    int res = 1;
    base = norm(base);
    while (exp) {
        if (exp & 1) res = (ll)res * base % MOD;
        base = (ll)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

vector<int> fact, inv_fact;

void init_fact(int max_n) {
    fact.resize(max_n + 1);
    inv_fact.resize(max_n + 1);
    fact[0] = 1;
    for (int i = 1; i <= max_n; ++i)
        fact[i] = (ll)fact[i-1] * i % MOD;
    inv_fact[max_n] = power(fact[max_n], MOD - 2);
    for (int i = max_n - 1; i >= 0; --i)
        inv_fact[i] = (ll)inv_fact[i+1] * (i+1) % MOD;
}

void fwht(vector<int> &a, int sign) {
    int n = a.size();
    for (int len = 1; len < n; len <<= 1) {
        for (int i = 0; i < n; i += len << 1) {
            for (int j = 0; j < len; ++j) {
                int x = a[i + j];
                int y = (ll)sign * a[i + j + len] % MOD;
                a[i + j] = norm(x + y);
                a[i + j + len] = norm(x - y);
            }
        }
    }
}

