}

int64 mod_pow(int64 base, int64 exp) {
    int64 result = 1;
    base = normalize(base);
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

vector<int> factorial, inv_factorial;

void precompute_factorials(int limit) {
    factorial.resize(limit + 1);
    inv_factorial.resize(limit + 1);
    factorial[0] = 1;
