        factorial[i] = (int64)factorial[i-1] * i % MOD;
    inv_factorial[limit] = mod_pow(factorial[limit], MOD - 2);
    for (int i = limit - 1; i >= 0; --i)
        inv_factorial[i] = (int64)inv_factorial[i+1] * (i+1) % MOD;
}

void walsh_hadamard_transform(vector<int> &a, int sign) {
    int n = a.size();
    for (int len = 1; len < n; len <<= 1) {
        for (int i = 0; i < n; i += len << 1) {
            for (int j = 0; j < len; ++j) {
                int x = a[i + j];
                int y = (int64)sign * a[i + j + len] % MOD;
                a[i + j] = normalize(x + y);
                a[i + j + len] = normalize(x - y);
            }
        }
    }
}

