using namespace std;

typedef long long ll;

const int N=262144;

int L,n,k,Mo,len,bit[20],fac[N],inv[N],cnt[N],g[20][N],f[20][N],h[20],p[20];

int pwr(int x,int y) {
	int z=1;
	for(;y;y>>=1,x=(ll)x*x%Mo)
		if (y&1) z=(ll)z*x%Mo;
	return z;
}

void inc(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void dec(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void FWT(int *a,int len) {for(int i=1;i<len;i<<=1) for(int j=0;j<len;j+=i<<1) for(int k=0;k<i;k++) inc(a[j+k+i],a[j+k]);}
void IFWT(int *a,int len) {for(int i=1;i<len;i<<=1) for(int j=0;j<len;j+=i<<1) for(int k=0;k<i;k++) dec(a[j+k+i],a[j+k]);}

void get_ln(int *a,int *b,int n) {
	b[0]=0;
	fo(i,1,n) {
		b[i]=(ll)a[i]*i%Mo;
		fo(j,1,i-1) (b[i]+=Mo-(ll)b[j]*a[i-j]%Mo*j%Mo)%=Mo;
		b[i]=(ll)b[i]*pwr(i,Mo-2)%Mo;
	}
}

void get_exp(int *a,int *b,int n) {
	b[0]=1;
	fo(i,1,n) {
		b[i]=0;
		fo(j,1,i) (b[i]+=(ll)a[j]*b[i-j]%Mo*j%Mo)%=Mo;
		b[i]=(ll)b[i]*pwr(i,Mo-2)%Mo;
	}
}

