int L, n, k, Mo, len;
int bit[20], fac[N], inv[N], cnt[N];
int g[20][N], f[20][N], h[20], p[20];

int pwr(int x, int y) {
    int z = 1;
    for (; y; y >>= 1, x = (ll)x * x % Mo)
        if (y & 1) z = (ll)z * x % Mo;
    return z;
}

void add(int &x, int y) {
    x += y;
    if (x >= Mo) x -= Mo;
}

void sub(int &x, int y) {
    x -= y;
    if (x < 0) x += Mo;
}

void FWT(int *a, int len) {
    for (int i = 1; i < len; i <<= 1)
        for (int j = 0; j < len; j += i << 1)
            for (int k = 0; k < i; k++)
                add(a[j + k + i], a[j + k]);
}

void IFWT(int *a, int len) {
    for (int i = 1; i < len; i <<= 1)
        for (int j = 0; j < len; j += i << 1)
            for (int k = 0; k < i; k++)
                sub(a[j + k + i], a[j + k]);
}

void get_ln(int *a, int *b, int n) {
    b[0] = 0;
    for (int i = 1; i <= n; i++) {
        b[i] = (ll)a[i] * i % Mo;
        for (int j = 1; j < i; j++) {
            sub(b[i], (ll)b[j] * a[i - j] % Mo * j % Mo);
        }
        b[i] = (ll)b[i] * pwr(i, Mo - 2) % Mo;
    }
}

void get_exp(int *a, int *b, int n) {
    b[0] = 1;
    for (int i = 1; i <= n; i++) {
        b[i] = 0;
        for (int j = 1; j <= i; j++) {
            add(b[i], (ll)a[j] * b[i - j] % Mo * j % Mo);
        }
        b[i] = (ll)b[i] * pwr(i, Mo - 2) % Mo;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> L >> k >> Mo;
    int all = pwr(k, L);

    if (L & 1) {
        cout << all << '\n';
        return 0;
    }

    fac[0] = 1;
    for (int i = 1; i <= L; i++) fac[i] = (ll)fac[i - 1] * i % Mo;

    inv[L] = pwr(fac[L], Mo - 2);
    for (int i = L - 1; i >= 0; i--) inv[i] = (ll)inv[i + 1] * (i + 1) % Mo;

    for (int s = 1; s <= L; s++) cnt[s] = cnt[s & (s - 1)] + 1;

    n = 0;
    for (int i = 0; i <= MAX_BITS; i++) {
        if (L >> i & 1) bit[++n] = 1 << i;
    }

    len = 1 << n;

    for (int i = 0; i < len; i++) {
        int s = 0;
        for (int j = 1; j <= n; j++) {
            if (i >> (j - 1) & 1) s += bit[j];
        }
        g[cnt[i]][i] = inv[s];
    }

    for (int i = 0; i <= n; i++) FWT(g[i], len);

    for (int s = 0; s < len; s++) {
        for (int i = 0; i <= n; i++) h[i] = g[i][s];
        get_ln(h, p, n);
        for (int i = 0; i <= n; i++) p[i] = (ll)p[i] * k % Mo;
        get_exp(p, h, n);
        for (int i = 0; i <= n; i++) f[i][s] = h[i];
    }

    IFWT(f[n], len);
    int ans = (ll)f[n][len - 1] * fac[L] % Mo;
    ans = (all - ans + Mo) % Mo;
    cout << ans << '\n';

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

using ll = long long;

const int MAX_N = 262144;
const int MAX_BIT = 18;

int L, n, k, Mo, len;
vector<int> bit(20), cnt(MAX_N + 1);
vector<vector<int>> g(20, vector<int>(MAX_N)), f(20, vector<int>(MAX_N));
vector<int> h(20), p(20), fac(MAX_N), inv(MAX_N);

int mod_pow(int base, int exp) {
    int result = 1;
    base %= Mo;
    while (exp > 0) {
        if (exp & 1) result = (ll)result * base % Mo;
        base = (ll)base * base % Mo;
        exp >>= 1;
    }
    return result;
}

void add_mod(int &x, int y) {
    x = (x + y) % Mo;
    if (x < 0) x += Mo;
}

void sub_mod(int &x, int y) {
    x = (x - y + Mo) % Mo;
}

void FWT(vector<int>& a, int length) {
    for (int i = 1; i < length; i <<= 1) {
        for (int j = 0; j < length; j += i << 1) {
            for (int k = 0; k < i; k++) {
                add_mod(a[j + k + i], a[j + k]);
            }
        }
    }
}

void IFWT(vector<int>& a, int length) {
    for (int i = 1; i < length; i <<= 1) {
        for (int j = 0; j < length; j += i << 1) {
            for (int k = 0; k < i; k++) {
                sub_mod(a[j + k + i], a[j + k]);
            }
        }
    }
}

void get_log(vector<int>& a, vector<int>& b, int max_n) {
    b[0] = 0;
    for (int i = 1; i <= max_n; i++) {
        b[i] = (ll)a[i] * i % Mo;
        for (int j = 1; j < i; j++) {
            sub_mod(b[i], (ll)b[j] * a[i - j] % Mo * j % Mo);
        }
        b[i] = (ll)b[i] * mod_pow(i, Mo - 2) % Mo;
    }
}

void get_exp(vector<int>& a, vector<int>& b, int max_n) {
    b[0] = 1;
    for (int i = 1; i <= max_n; i++) {
        b[i] = 0;
        for (int j = 1; j <= i; j++) {
            add_mod(b[i], (ll)a[j] * b[i - j] % Mo * j % Mo);
        }
        b[i] = (ll)b[i] * mod_pow(i, Mo - 2) % Mo;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> L >> k >> Mo;
    int total = mod_pow(k, L);

    if (L % 2 == 1) {
        cout << total << '\n';
        return 0;
    }

    fac[0] = 1;
    for (int i = 1; i <= L; i++) {
        fac[i] = (ll)fac[i - 1] * i % Mo;
    }

    inv[L] = mod_pow(fac[L], Mo - 2);
    for (int i = L - 1; i >= 0; i--) {
        inv[i] = (ll)inv[i + 1] * (i + 1) % Mo;
    }

    for (int s = 1; s <= L; s++) {
        cnt[s] = cnt[s & (s - 1)] + 1;
    }

    n = 0;
    for (int i = 0; i <= MAX_BIT; i++) {
        if ((L >> i) & 1) {
            bit[++n] = 1 << i;
        }
    }

    len = 1 << n;

    for (int i = 0; i < len; i++) {
        int sum = 0;
        for (int j = 1; j <= n; j++) {
            if ((i >> (j - 1)) & 1) {
                sum += bit[j];
            }
        }
        g[cnt[i]][i] = inv[sum];
    }

    for (int i = 0; i <= n; i++) {
        FWT(g[i], len);
    }

    for (int s = 0; s < len; s++) {
        for (int i = 0; i <= n; i++) {
            h[i] = g[i][s];
        }
        get_log(h, p, n);
        for (int i = 0; i <= n; i++) {
            p[i] = (ll)p[i] * k % Mo;
        }
        get_exp(p, h, n);
        for (int i = 0; i <= n; i++) {
            f[i][s] = h[i];
        }
    }

    IFWT(f[n], len);
    int result = (ll)f[n][len - 1] * fac[L] % Mo;
    result = (total - result + Mo) % Mo;
    cout << result << '\n';

    return 0;
}

#include <iostream>
#include <array>
using namespace std;

using i64 = long long;

constexpr int MAX_SIZE = 262144;
constexpr int MAX_POWER = 18;

int L, n, k, Mo, total_len;
array<int, 20> bit_arr;
array<int, MAX_SIZE + 1> cnt_arr;
array<array<int, MAX_SIZE>, 20> g_arr, f_arr;
array<int, 20> h_arr, p_arr;
array<int, MAX_SIZE> fac_arr, inv_arr;

int mod_exp(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = (i64)res * base % Mo;
        base = (i64)base * base % Mo;
        exp >>= 1;
    }
    return res;
}

void add_val(int& x, int y) {
    x = (x + y) % Mo;
    if (x < 0) x += Mo;
}

void sub_val(int& x, int y) {
    x = (x - y + Mo) % Mo;
}

void forward_transform(int* arr, int sz) {
    for (int step = 1; step < sz; step <<= 1) {
        for (int start = 0; start < sz; start += step << 1) {
            for (int idx = 0; idx < step; idx++) {
                add_val(arr[start + idx + step], arr[start + idx]);
            }
        }
    }
}

void inverse_transform(int* arr, int sz) {
    for (int step = 1; step < sz; step <<= 1) {
        for (int start = 0; start < sz; start += step << 1) {
            for (int idx = 0; idx < step; idx++) {
                sub_val(arr[start + idx + step], arr[start + idx]);
            }
        }
    }
}

void log_transform(int* input, int* output, int limit) {
    output[0] = 0;
    for (int i = 1; i <= limit; ++i) {
        output[i] = (i64)input[i] * i % Mo;
        for (int j = 1; j < i; ++j) {
            sub_val(output[i], (i64)output[j] * input[i - j] % Mo * j % Mo);
        }
        output[i] = (i64)output[i] * mod_exp(i, Mo - 2) % Mo;
    }
}

void exp_transform(int* input, int* output, int limit) {
    output[0] = 1;
    for (int i = 1; i <= limit; ++i) {
        output[i] = 0;
        for (int j = 1; j <= i; ++j) {
            add_val(output[i], (i64)input[j] * output[i - j] % Mo * j % Mo);
        }
        output[i] = (i64)output[i] * mod_exp(i, Mo - 2) % Mo;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> L >> k >> Mo;
    int total = mod_exp(k, L);

    if (L & 1) {
        cout << total << '\n';
        return 0;
    }

    fac_arr[0] = 1;
    for (int i = 1; i <= L; ++i) {
        fac_arr[i] = (i64)fac_arr[i - 1] * i % Mo;
    }

    inv_arr[L] = mod_exp(fac_arr[L], Mo - 2);
    for (int i = L - 1; i >= 0; --i) {
        inv_arr[i] = (i64)inv_arr[i + 1] * (i + 1) % Mo;
    }

    for (int s = 1; s <= L; ++s) {
        cnt_arr[s] = cnt_arr[s & (s - 1)] + 1;
    }

    n = 0;
    for (int i = 0; i <= MAX_POWER; ++i) {
        if ((L >> i) & 1) {
            bit_arr[++n] = 1 << i;
        }
    }

    total_len = 1 << n;

    for (int i = 0; i < total_len; ++i) {
        int sum_bits = 0;
        for (int j = 1; j <= n; ++j) {
            if ((i >> (j - 1)) & 1) {
                sum_bits += bit_arr[j];
            }
        }
        g_arr[cnt_arr[i]][i] = inv_arr[sum_bits];
    }

    for (int i = 0; i <= n; ++i) {
        forward_transform(g_arr[i].data(), total_len);
    }

    for (int s = 0; s < total_len; ++s) {
        for (int i = 0; i <= n; ++i) {
            h_arr[i] = g_arr[i][s];
        }
        log_transform(h_arr.data(), p_arr.data(), n);
        for (int i = 0; i <= n; ++i) {
            p_arr[i] = (i64)p_arr[i] * k % Mo;
        }
        exp_transform(p_arr.data(), h_arr.data(), n);
        for (int i = 0; i <= n; ++i) {
            f_arr[i][s] = h_arr[i];
        }
    }

    inverse_transform(f_arr[n].data(), total_len);
    int answer = (i64)f_arr[n][total_len - 1] * fac_arr[L] % Mo;
    answer = (total - answer + Mo) % Mo;
    cout << answer << '\n';

    return 0;
}

