#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;

const ull INF = 17446744073709551616ULL;

ull mod, n, k;
ull dp[18][250005];
ull fac[250005], inv[250005];

inline ull qpow(ull a, ull b) {
    ull res = 1, base = a;
    while (b) {
        if (b & 1) {
            res = (res * base) % mod;
        }
        base = (base * base) % mod;
        b >>= 1;
    }
    return res;
}

inline ull comb(int a, int b) {
    if (b < 0 || b > a) return 0;
    return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
}

inline ull solve() {
    fac[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fac[i] = (fac[i - 1] * static_cast<ull>(i)) % mod;
    }
    inv[n] = qpow(fac[n], mod - 2);
    for (int i = n - 1; i >= 0; --i) {
        inv[i] = (inv[i + 1] * static_cast<ull>(i + 1)) % mod;
    }

    for (int i = 1; i <= n; ++i) {
        dp[1][i] = inv[i];
    }

    ull result = (dp[1][n] * comb(k, 1)) % mod;
    int maxIter = min(17, static_cast<int>(k));

    for (int iter = 2; iter <= maxIter; ++iter) {
        for (int mask = n; mask; mask = (mask - 1) & n) {
            if (!dp[iter - 1][mask]) continue;
            int complement = n ^ mask;
            for (int sub = complement; sub; sub = (sub - 1) & complement) {
                dp[iter][mask + sub] += dp[iter - 1][mask] * inv[sub];
                if (dp[iter][mask + sub] > INF) {
                    dp[iter][mask + sub] %= mod;
                }
            }
        }
        for (int mask = n; mask; mask = (mask - 1) & n) {
            dp[iter][mask] %= mod;
        }
        result = (result + dp[iter][n] * comb(k, iter)) % mod;
    }

    result = (result * fac[n]) % mod;
    return result;
}

int main() {
    cin >> n >> k >> mod;
    ull total = qpow(k, n);
    if (n % 2 == 0) {
        total = (total - solve() + mod) % mod;
    }
    cout << total << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using u64 = unsigned long long;

const u64 INF = 17446744073709551616ULL;

u64 mod, n, k;
vector<vector<u64>> dp;
vector<u64> fact, invFact;

u64 modPow(u64 base, u64 exp) {
    u64 res = 1;
    while (exp) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

u64 nCr(int a, int b) {
    if (b < 0 || b > a) return 0;
    return (((fact[a] * invFact[b]) % mod) * invFact[a - b]) % mod;
}

u64 compute() {
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = (fact[i - 1] * static_cast<u64>(i)) % mod;

    invFact[n] = modPow(fact[n], mod - 2);
    for (int i = n - 1; i >= 0; --i) {
        invFact[i] = (invFact[i + 1] * static_cast<u64>(i + 1)) % mod;
    }

    for (int i = 1; i <= n; ++i) dp[1][i] = invFact[i];

    u64 ans = (dp[1][n] * nCr(k, 1)) % mod;
    int limit = min(17, static_cast<int>(k));

    for (int step = 2; step <= limit; ++step) {
        for (int mask = n; mask; mask = (mask - 1) & n) {
            if (!dp[step - 1][mask]) continue;
            int rem = n ^ mask;
            for (int sub = rem; sub; sub = (sub - 1) & rem) {
                dp[step][mask | sub] += dp[step - 1][mask] * invFact[sub];
                if (dp[step][mask | sub] > INF) dp[step][mask | sub] %= mod;
            }
        }
        for (int mask = n; mask; mask = (mask - 1) & n) dp[step][mask] %= mod;
        ans = (ans + dp[step][n] * nCr(k, step)) % mod;
    }

    ans = (ans * fact[n]) % mod;
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> mod;
    fact.resize(n + 1);
    invFact.resize(n + 1);
    dp.assign(18, vector<u64>(250005, 0));

    u64 total = modPow(k, n);
    if (n % 2 == 0) {
        total = (total - compute() + mod) % mod;
    }
    cout << total << '\n';
    return 0;
}

#include <iostream>
#include <cstring>
#include <climits>
using namespace std;
using u64 = unsigned long long;

const u64 BIG_INF = 17446744073709551616ULL;

u64 MOD, N, K;
u64 D[18][250005];
u64 F[250005], I[250005];

u64 fastPow(u64 b, u64 e) {
    u64 r = 1;
    while (e) {
        if (e & 1) r = (r * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return r;
}

u64 binom(int x, int y) {
    if (y < 0 || y > x) return 0;
    return (((F[x] * I[y]) % MOD) * I[x - y]) % MOD;
}

u64 process() {
    F[0] = 1;
    for (int i = 1; i <= N; ++i) F[i] = (F[i - 1] * static_cast<u64>(i)) % MOD;

    I[N] = fastPow(F[N], MOD - 2);
    for (int i = N - 1; i >= 0; --i) I[i] = (I[i + 1] * static_cast<u64>(i + 1)) % MOD;

    for (int i = 1; i <= N; ++i) D[1][i] = I[i];

    u64 sum = (D[1][N] * binom(K, 1)) % MOD;
    int maxLvl = min(17, static_cast<int>(K));

    for (int lvl = 2; lvl <= maxLvl; ++lvl) {
        for (int s = N; s; s = (s - 1) & N) {
            if (!D[lvl - 1][s]) continue;
            int rest = N ^ s;
            for (int t = rest; t; t = (t - 1) & rest) {
                D[lvl][s | t] += D[lvl - 1][s] * I[t];
                if (D[lvl][s | t] > BIG_INF) D[lvl][s | t] %= MOD;
            }
        }
        for (int s = N; s; s = (s - 1) & N) D[lvl][s] %= MOD;
        sum = (sum + D[lvl][N] * binom(K, lvl)) % MOD;
    }

    sum = (sum * F[N]) % MOD;
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> N >> K >> MOD;
    u64 base = fastPow(K, N);
    if (N % 2 == 0) {
        base = (base - process() + MOD) % MOD;
    }
    cout << base << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;
using u64 = unsigned long long;

const u64 LIMIT = 17446744073709551616ULL;

u64 MOD, N, K;
vector<vector<u64>> memo;
vector<u64> factorial, invFact;

u64 modExp(u64 b, u64 e) {
    u64 res = 1;
    while (e > 0) {
        if (e & 1) res = (res * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return res;
}

u64 choose(int n, int r) {
    if (r < 0 || r > n) return 0;
    return (((factorial[n] * invFact[r]) % MOD) * invFact[n - r]) % MOD;
}

u64 computeAnswer() {
    factorial[0] = 1;
    for (int i = 1; i <= N; ++i) {
        factorial[i] = (factorial[i - 1] * static_cast<u64>(i)) % MOD;
    }

    invFact[N] = modExp(factorial[N], MOD - 2);
    for (int i = N - 1; i >= 0; --i) {
        invFact[i] = (invFact[i + 1] * static_cast<u64>(i + 1)) % MOD;
    }

    for (int i = 1; i <= N; ++i) {
        memo[1][i] = invFact[i];
    }

    u64 total = (memo[1][N] * choose(K, 1)) % MOD;
    int depth = min(17, static_cast<int>(K));

    for (int d = 2; d <= depth; ++d) {
        for (int mask = N; mask; mask = (mask - 1) & N) {
            if (!memo[d - 1][mask]) continue;
            int complement = N ^ mask;
            for (int subset = complement; subset; subset = (subset - 1) & complement) {
                memo[d][mask | subset] += memo[d - 1][mask] * invFact[subset];
                if (memo[d][mask | subset] > LIMIT) {
                    memo[d][mask | subset] %= MOD;
                }
            }
        }
        for (int mask = N; mask; mask = (mask - 1) & N) {
            memo[d][mask] %= MOD;
        }
        total = (total + memo[d][N] * choose(K, d)) % MOD;
    }

    total = (total * factorial[N]) % MOD;
    return total;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K >> MOD;

    factorial.resize(N + 1);
    invFact.resize(N + 1);
    memo.assign(18, vector<u64>(250005, 0));

    u64 all = modExp(K, N);
    if (N % 2 == 0) {
        all = (all - computeAnswer() + MOD) % MOD;
    }
    cout << all << '\n';

    return 0;
}

#include <iostream>
#include <vector>
#include <climits>
#include <cctype>
#include <algorithm>
using namespace std;
using u64 = unsigned long long;

const u64 THRESHOLD = 17446744073709551616ULL;

u64 MOD, N, K;
vector<vector<u64>> DP;
vector<u64> FACT, INV_FACT;

u64 power(u64 base, u64 exp) {
    u64 result = 1;
    while (exp) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

u64 combination(int total, int pick) {
    if (pick < 0 || pick > total) return 0;
    return (((FACT[total] * INV_FACT[pick]) % MOD) * INV_FACT[total - pick]) % MOD;
}

u64 calculate() {
    FACT[0] = 1;
    for (int i = 1; i <= N; ++i) {
        FACT[i] = (FACT[i - 1] * static_cast<u64>(i)) % MOD;
    }

    INV_FACT[N] = power(FACT[N], MOD - 2);
    for (int i = N - 1; i >= 0; --i) {
        INV_FACT[i] = (INV_FACT[i + 1] * static_cast<u64>(i + 1)) % MOD;
    }

    for (int i = 1; i <= N; ++i) {
        DP[1][i] = INV_FACT[i];
    }

    u64 answer = (DP[1][N] * combination(K, 1)) % MOD;
    int maxLevel = min(17, static_cast<int>(K));

    for (int level = 2; level <= maxLevel; ++level) {
        for (int mask = N; mask; mask = (mask - 1) & N) {
            if (!DP[level - 1][mask]) continue;
            int remaining = N ^ mask;
            for (int subset = remaining; subset; subset = (subset - 1) & remaining) {
                DP[level][mask | subset] += DP[level - 1][mask] * INV_FACT[subset];
                if (DP[level][mask | subset] > THRESHOLD) {
                    DP[level][mask | subset] %= MOD;
                }
            }
        }
        for (int mask = N; mask; mask = (mask - 1) & N) {
            DP[level][mask] %= MOD;
        }
        answer = (answer + DP[level][N] * combination(K, level)) % MOD;
    }

    answer = (answer * FACT[N]) % MOD;
    return answer;
