i64 mod_exp(i64 base, int exp, i64 mod) {
    i64 res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    int n, k, MO;
    read_int(n); read_int(k); read_int(MO);

    if (n & 1) {
        std::cout << mod_exp(k, n, MO) << '\n';
        return 0;
    }

    std::vector<i64> fact(n + 1), inv_fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i-1] * i % MO;

    inv_fact[n] = mod_exp(fact[n], MO - 2, MO);
    for (int i = n - 1; i >= 0; --i)
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MO;

    std::vector<int> bits;
    int t = n;
    for (int i = 0; i <= 20; ++i) {
        if (t & 1)
            bits.push_back(1 << i);
        t >>= 1;
    }

    const int N = 1 << bits.size();
    std::vector<int> S(N, 0);
    for (int msk = 0; msk < N; ++msk) {
        for (int j = 0; j < (int)bits.size(); ++j) {
            if (msk >> j & 1)
                S[msk] += bits[j];
        }
    }

    std::vector<int> next_p(N);
    for (int msk = 0; msk < N; ++msk) {
        int last_bit = -1;
        for (int j = 0; j <= 20; ++j) {
            if (msk >> j & 1)
                last_bit = j;
        }
        next_p[msk] = (1 << (last_bit + 1)) + msk;
    }

    std::vector<std::vector<i64>> dp(k + 1, std::vector<i64>(N, 0));
    dp[0][0] = 1;

    for (int step = 0; step < k; ++step) {
        for (int msk = 0; msk < N; ++msk) {
            if (!dp[step][msk]) continue;
            for (int nxt = next_p[msk]; nxt < N; nxt = (nxt + 1) | msk) {
                dp[step + 1][nxt] = (dp[step + 1][nxt] + dp[step][msk] * inv_fact[S[nxt ^ msk]]) % MO;
            }
        }
    }

    i64 result = 0;
    for (int i = 0; i <= k; ++i) {
        i64 term = dp[i][N - 1] * fact[k] % MO;
        term = term * inv_fact[k - i] % MO;
        result = (result + term) % MO;
    }
    result = result * fact[n] % MO;
    result = (mod_exp(k, n, MO) - result + MO) % MO;

    std::cout << result << '\n';
    return 0;
}

