vector<int> pow_convol(vector<int> a, int k, int p) {
    int n = a.size();
    if (k == 1) {
        return a;
    }
    else if (k & 1) {
        vector<int> r = pow_convol(a, k - 1, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - i; j++) {
                res[i + j] = (res[i + j] + (long long) r[i] * a[j]) % p;
            }
        }
        return res;
    }
    else {
        vector<int> r = pow_convol(a, k >> 1, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - i; j++) {
                res[i + j] = (res[i + j] + (long long) r[i] * r[j]) % p;
