            if (bitcount(j) == i) {
                fa[i][j] = j < sz(a) ? a[j] : 0;
            }
            else {
                fa[i][j] = 0;
            }
            fc[i][j] = 0;
        }
        transform(fa[i], n, p, 0);
    }
    FOR(i, 0, n) {
        vi va(logn);
        FOR(j, 0, logn) {
            va[j] = fa[j][i];
        }
        va = pow_convol(va, k, p);
        FOR(j, 0, logn) {
            fc[j][i] = va[j];
        }
    }
    for (int i = 0; i < logn; i++) {
        transform(fc[i], n, p, 1);
        for (int j = 0; j < n; j++) if (bitcount(j) == i) {
            res[j] = fc[i][j];
        }
    }
    return res;
}

