inline ull calc() {
    fac[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fac[i] = (fac[i - 1] * (ull)i) % mod;
    }
    inv[n] = qpow(fac[n], mod - 2);
    for (int i = n - 1; i >= 0; --i) {
        inv[i] = (inv[i + 1] * (ull)(i + 1)) % mod;
    }

    for (int i = 1; i <= n; ++i) {
