int bit[20], fac[MAX_N], inv[MAX_N], cnt[MAX_N];
int g[20][MAX_N], f[20][MAX_N];

int pwr(int x, int y) {
    int z = 1;
    for (; y; y >>= 1, x = (ll)x * x % Mo)
        if (y & 1) z = (ll)z * x % Mo;
    return z;
}

void inc(int &x, int y) { x = (x + y >= Mo) ? (x + y - Mo) : (x + y); }
void dec(int &x, int y) { x = (x - y < 0) ? (x - y + Mo) : (x - y); }

void FWT(int *a, int len) {
    for (int i = 1; i < len; i <<= 1)
        for (int j = 0; j < len; j += i << 1)
            for (int k = 0; k < i; k++)
                inc(a[j + k + i], a[j + k]);
}

void IFWT(int *a, int len) {
    for (int i = 1; i < len; i <<= 1)
        for (int j = 0; j < len; j += i << 1)
            for (int k = 0; k < i; k++)
                dec(a[j + k + i], a[j + k]);
}

ll h[20], p[20];

void get_ln() {
    p[0] = 0;
    for (int i = 1; i <= n; i++) {
        p[i] = (ll)h[i] * i % Mo;
        for (int j = 1; j < i; j++)
            p[i] = (p[i] - (ll)p[j] * h[i - j] % Mo * j % Mo + Mo) % Mo;
        p[i] = (ll)p[i] * inv[i] % Mo;
    }
    for (int i = 0; i <= n; i++) h[i] = (p[i] + Mo) % Mo;
}

void get_exp() {
    p[0] = 1;
    for (int i = 1; i <= n; i++) {
        p[i] = 0;
        for (int j = 1; j <= i; j++)
            p[i] = (p[i] + (ll)h[j] * p[i - j] % Mo * j) % Mo;
        p[i] = (ll)p[i] * inv[i] % Mo;
    }
    for (int i = 0; i <= n; i++) h[i] = p[i];
}

int main() {
    scanf("%d%d%d", &L, &k, &Mo);
    int all = pwr(k, L);
    if (L & 1) {
        printf("%d\n", all);
        return 0;
    }
    fac[0] = 1;
    for (int i = 1; i <= L; i++) fac[i] = (ll)fac[i - 1] * i % Mo;
    inv[L] = pwr(fac[L], Mo - 2);
    for (int i = L - 1; i >= 0; i--) inv[i] = (ll)inv[i + 1] * (i + 1) % Mo;
    for (int s = 1; s <= L; s++) cnt[s] = cnt[s & (s - 1)] + 1;
    n = 0;
    for (int i = 0; i < 20; i++) if (L >> i & 1) bit[++n] = 1 << i;
    len = 1 << n;
    for (int i = 0; i < len; i++) {
        int s = 0;
        for (int j = 1; j <= n; j++) if (i >> (j - 1) & 1) s += bit[j];
        g[cnt[i]][i] = inv[s];
    }
    for (int i = 2; i <= n; i++) inv[i] = (ll)(Mo - Mo / i) * inv[Mo % i] % Mo;
    for (int i = 0; i <= n; i++) FWT(g[i], len);
    for (int s = 0; s < len; s++) {
        for (int i = 0; i <= n; i++) h[i] = g[i][s];
        get_ln();
        for (int i = 0; i <= n; i++) h[i] = (ll)h[i] * k % Mo;
        get_exp();
        for (int i = 0; i <= n; i++) f[i][s] = h[i];
    }
    IFWT(f[n], len);
    int ans = (ll)f[n][len - 1] * fac[L] % Mo;
    ans = (all - ans + Mo) % Mo;
    printf("%d\n", ans);
    return 0;
}

