}

void fw_transform(vector<int>& a, int length) {
    for (int i = 1; i < length; i <<= 1) {
        for (int j = 0; j < length; j += i << 1) {
            for (int k = 0; k < i; ++k) {
                add_mod(a[j + k + i], a[j + k]);
            }
        }
    }
}

void ifw_transform(vector<int>& a, int length) {
    for (int i = 1; i < length; i <<= 1) {
        for (int j = 0; j < length; j += i << 1) {
            for (int k = 0; k < i; ++k) {
