const int MAX_LEN = 262144;

int main() {
    int L, k, mod;
    cin >> L >> k >> mod;

    auto mod_pow = [&](int base, int exp) {
        int res = 1;
        base %= mod;
        while (exp) {
            if (exp & 1) res = (i64)res * base % mod;
            base = (i64)base * base % mod;
            exp >>= 1;
        }
        return res;
    };

    int total = mod_pow(k, L);
    if (L & 1) {
        cout << total << '\n';
        return 0;
    }

    vector<int> fac(L + 1), inv(L + 1);
    fac[0] = 1;
    for (int i = 1; i <= L; ++i) fac[i] = (i64)fac[i - 1] * i % mod;
    inv[L] = mod_pow(fac[L], mod - 2);
    for (int i = L; i > 0; --i) inv[i - 1] = (i64)inv[i] * i % mod;

    vector<int> cnt(L + 1);
    for (int s = 1; s <= L; ++s) cnt[s] = cnt[s & (s - 1)] + 1;

    vector<int> bits;
    for (int i = 0; i < 20; ++i) if (L >> i & 1) bits.push_back(1 << i);
    int n = bits.size();
    int len = 1 << n;

    vector<vector<int>> g(n + 1, vector<int>(len)), f(n + 1, vector<int>(len));

    for (int mask = 0; mask < len; ++mask) {
        int sum = 0;
        for (int j = 0; j < n; ++j) if (mask >> j & 1) sum += bits[j];
        g[cnt[mask]][mask] = inv[sum];
    }

    for (int i = 2; i <= n; ++i) inv[i] = (i64)(mod - mod / i) * inv[mod % i] % mod;

    auto FWT = [&](vector<int>& a, int sz, bool inverse = false) {
        for (int step = 1; step < sz; step <<= 1) {
            for (int i = 0; i < sz; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    if (!inverse) {
                        a[i + j + step] = (a[i + j + step] + a[i + j]) % mod;
                    } else {
                        a[i + j + step] = (a[i + j + step] - a[i + j] + mod) % mod;
                    }
                }
            }
        }
    };

    for (int i = 0; i <= n; ++i) FWT(g[i], len);

    vector<i64> h(n + 1), p(n + 1);

    for (int s = 0; s < len; ++s) {
        for (int i = 0; i <= n; ++i) h[i] = g[i][s];

        // log
        p[0] = 0;
        for (int i = 1; i <= n; ++i) {
            p[i] = h[i] * i % mod;
            for (int j = 1; j < i; ++j) {
                p[i] = (p[i] - p[j] * h[i - j] % mod * j % mod + mod) % mod;
            }
            p[i] = p[i] * inv[i] % mod;
        }
        for (int i = 0; i <= n; ++i) h[i] = (p[i] + mod) % mod;

        // scale by k
        for (int i = 0; i <= n; ++i) h[i] = h[i] * k % mod;

        // exp
        p[0] = 1;
        for (int i = 1; i <= n; ++i) {
            p[i] = 0;
            for (int j = 1; j <= i; ++j) {
                p[i] = (p[i] + h[j] * p[i - j] % mod * j) % mod;
            }
            p[i] = p[i] * inv[i] % mod;
        }
        for (int i = 0; i <= n; ++i) h[i] = p[i];

        for (int i = 0; i <= n; ++i) f[i][s] = h[i];
    }

    FWT(f[n], len, true);

    int ans = (i64)f[n][len - 1] * fac[L] % mod;
    ans = (total - ans + mod) % mod;
    cout << ans << '\n';

    return 0;
}

