void init_combinatorics(int limit, LL m) {
    inv_table[0] = inv_table[1] = 1;
    fact[0] = fact[1] = 1;
    for (int i = 2; i <= limit; ++i) {
        inv_table[i] = (m - m / i) * inv_table[m % i] % m;
        fact[i] = fact[i-1] * i % m;
    }
    for (int i = 2; i <= limit; ++i) {
        inv_table[i] = inv_table[i-1] * inv_table[i] % m;
    }
}

