void comb_init(int limit, i64 mod) {
    inv_tbl[0] = inv_tbl[1] = 1;
    fact_tbl[0] = fact_tbl[1] = 1;
    for (int i = 2; i <= limit; ++i) {
        inv_tbl[i] = (mod - mod / i) * inv_tbl[mod % i] % mod;
        fact_tbl[i] = fact_tbl[i-1] * i % mod;
    }
    for (int i = 2; i <= limit; ++i) {
        inv_tbl[i] = inv_tbl[i-1] * inv_tbl[i] % mod;
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    i64 n_val, k_val, mod_val;
    std::cin >> n_val >> k_val >> mod_val;
    comb_init(n_val + 5, mod_val);

    if (n_val & 1) {
        std::cout << mod_pow(k_val, n_val, mod_val) << '\n';
        return 0;
    }

    sub_list.clear();
    for (int i = 2; i <= n_val; i += 2) {
        if ((i & n_val) == i) {
            sub_list.push_back(i);
        }
    }

    std::memset(dp_tab, 0, sizeof(dp_tab));
    dp_tab[0][n_val] = 1;
    i64 tot_ans = 0;
    int max_depth = std::min(17LL, k_val);

    for (int depth = 1; depth <= max_depth; ++depth) {
        i64 sub_sum = 0;
        for (int idx = 0; idx < (int)sub_list.size(); ++idx) {
            int curr = sub_list[idx];
            if (dp_tab[depth-1][curr] == 0) continue;

            int next_node = curr & (curr - 1);
            int diff = next_node ^ curr;

            for (int step = diff; step <= next_node; step += diff) {
                if ((step & next_node) == step) {
                    dp_tab[depth][step] = (dp_tab[depth][step] +
                        dp_tab[depth-1][curr] * fact_tbl[curr] % mod_val *
                        inv_tbl[step] % mod_val * inv_tbl[curr - step] % mod_val) % mod_val;
                }
            }
            sub_sum = (sub_sum + dp_tab[depth-1][curr]) % mod_val;
        }
        tot_ans = (tot_ans + sub_sum * inv_tbl[k_val - depth] % mod_val) % mod_val;
    }

    tot_ans = tot_ans * fact_tbl[k_val] % mod_val;
    i64 final = (mod_pow(k_val, n_val, mod_val) - tot_ans % mod_val + mod_val) % mod_val;
    std::cout << final << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 250005;
int n,kk,P;
using ll = long long;
ll qpow(ll a,ll b)
{
    ll ret = 1;
    while (b)
    {
        if (b & 1) ret = ret * a % P;
        a = a * a % P;b >>= 1;
    }
    return ret;
}
inline int lowbit(int x) {return x & -x;}
ll fac[N],inv[N],dp[26][N];
ll dfs(int cur,int msk)
{
    if (dp[cur][msk] != -1) return dp[cur][msk];
    if (!msk)
    {
        dp[cur][msk] = fac[n];
        for (int i = 1;i <= cur;i++)
            dp[cur][msk] = dp[cur][msk] * (kk - i + 1) % P;
        return dp[cur][msk];
    }
    dp[cur][msk] = 0;int tmp = msk - lowbit(msk);
    for (int i = tmp;i > 0;i = (i - 1) & tmp)
        dp[cur][msk] = (dp[cur][msk] + inv[msk - i] * dfs(cur + 1,i)) % P;
    dp[cur][msk] = (dp[cur][msk] + inv[msk] * dfs(cur + 1,0)) % P;
    return dp[cur][msk];
}
int main ()
{
    ios::sync_with_stdio(false);
    cin >> n >> kk >> P;ll ans = qpow(kk,n);
    if (n & 1) {cout << ans << endl;return 0;}
    fac[0] = 1;
    for (int i = 1;i <= n;i++) fac[i] = fac[i - 1] * i % P;
    inv[n] = qpow(fac[n],P - 2);
    for (int i = n;i > 0;--i) inv[i - 1] = inv[i] * i % P;
    memset(dp,-1,sizeof(dp));ans = (ans - dfs(0,n) + P) % P;
    cout << ans << endl;
    return 0;
}
// 非卡常做法需要用FWT
// 卡常做法: 每次强制将Ai规定为含有msk的lowbit的那一个，最后当msk=0时用排列乘回来

#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 250005;
int n, k, mod;
using ll = long long;

ll modPow(ll base, ll exp) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

inline int getLowbit(int x) { return x & -x; }

ll factorial[MAX_N], invFactorial[MAX_N];
ll memo[26][MAX_N];

ll solve(int position, int mask) {
    if (memo[position][mask] != -1) return memo[position][mask];

    if (mask == 0) {
        memo[position][mask] = factorial[n];
        for (int i = 0; i < position; ++i) {
            memo[position][mask] = (memo[position][mask] * (k - i)) % mod;
        }
        return memo[position][mask];
    }

    memo[position][mask] = 0;
    int submask = mask - getLowbit(mask);

    for (int subset = submask; subset > 0; subset = (subset - 1) & submask) {
        memo[position][mask] = (memo[position][mask] + invFactorial[mask - subset] * solve(position + 1, subset)) % mod;
    }

    memo[position][mask] = (memo[position][mask] + invFactorial[mask] * solve(position + 1, 0)) % mod;
    return memo[position][mask];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> mod;
    ll total = modPow(k, n);

    if (n % 2 == 1) {
        cout << total << '\n';
        return 0;
    }

    factorial[0] = 1;
    for (int i = 1; i <= n; ++i) factorial[i] = factorial[i-1] * i % mod;

    invFactorial[n] = modPow(factorial[n], mod - 2);
    for (int i = n; i >= 1; --i) {
        invFactorial[i-1] = invFactorial[i] * i % mod;
    }

    memset(memo, -1, sizeof(memo));
    ll subtract = solve(0, n);
    ll result = (total - subtract + mod) % mod;
    cout << result << '\n';

    return 0;
}

