vector<u64> fact, inv_fact;

u64 mod_pow(u64 base, u64 exp, u64 mod) {
    u64 result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

u64 binom(int a, int b) {
    if (b < 0 || b > a) return 0;
    u64 res = fact[a];
    res = (res * inv_fact[b]) % MOD;
    res = (res * inv_fact[a - b]) % MOD;
    return res;
}

u64 compute_dp() {
    fact.assign(max(N, K) + 2, 0);
    inv_fact.assign(max(N, K) + 2, 0);
    fact[0] = 1;
    for (u64 i = 1; i <= max(N, K); ++i) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    inv_fact[max(N, K)] = mod_pow(fact[max(N, K)], MOD - 2, MOD);
    for (int i = max(N, K) - 1; i >= 0; --i) {
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD;
    }

    int T = min(18, static_cast<int>(K));
    DP.assign(T + 1, vector<u64>(300005, 0));

    for (u64 i = 1; i <= N; ++i) {
        DP[1][i] = inv_fact[i];
    }

    u64 answer = (DP[1][N] * binom(K, 1)) % MOD;

    for (int stage = 2; stage <= T; ++stage) {
        for (u64 mask = N; mask; mask = (mask - 1) & N) {
            if (!DP[stage - 1][mask]) continue;
            u64 complement = N ^ mask;
            for (u64 submask = complement; submask > mask; submask = (submask - 1) & complement) {
                DP[stage][mask ^ submask] += DP[stage - 1][mask] * inv_fact[submask];
                if (DP[stage][mask ^ submask] > INF) {
                    DP[stage][mask ^ submask] %= MOD;
                }
            }
        }
        for (u64 mask = N; mask; mask = (mask - 1) & N) {
            if (DP[stage][mask] >= MOD) {
                DP[stage][mask] %= MOD;
            }
        }
        u64 contribution = DP[stage][N] * binom(K, stage);
        contribution %= MOD;
        contribution = (contribution * fact[stage]) % MOD;
        answer = (answer + contribution) % MOD;
    }
    answer = (answer * fact[N]) % MOD;
    return answer;
}

int main() {
    cin >> N >> K >> MOD;
    u64 total = mod_pow(K, N, MOD);
    if (N % 2 == 0) {
        total = (total - compute_dp() + MOD) % MOD;
    }
