using namespace std;
using u64 = unsigned long long;

const u64 INF = 18446744073709551615ULL;
u64 MOD, N, K;
vector<vector<u64>> dp;
vector<u64> factorial;
vector<u64> inv_factorial;

u64 mod_exp(u64 base, u64 exp, u64 mod) {
    u64 result = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

u64 choose(int n, int r) {
    if (r < 0 || r > n) return 0;
    u64 res = factorial[n];
    res = (res * inv_factorial[r]) % MOD;
    res = (res * inv_factorial[n - r]) % MOD;
    return res;
}

u64 solve() {
    int max_val = max(N, K);
    factorial.assign(max_val + 1, 0);
    inv_factorial.assign(max_val + 1, 0);
    factorial[0] = 1;
    for (int i = 1; i <= max_val; ++i) {
        factorial[i] = (factorial[i - 1] * i) % MOD;
    }
    inv_factorial[max_val] = mod_exp(factorial[max_val], MOD - 2, MOD);
    for (int i = max_val - 1; i >= 0; --i) {
        inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % MOD;
    }

    int max_stage = min(18, static_cast<int>(K));
    dp.assign(max_stage + 1, vector<u64>(300005, 0));

    for (u64 i = 1; i <= N; ++i) dp[1][i] = inv_factorial[i];

    u64 result = (dp[1][N] * choose(K, 1)) % MOD;

    for (int stage = 2; stage <= max_stage; ++stage) {
        for (u64 mask = N; mask > 0; mask = (mask - 1) & N) {
            if (dp[stage - 1][mask] == 0) continue;
            u64 rem = N ^ mask;
            for (u64 sub = rem; sub > mask; sub = (sub - 1) & rem) {
                dp[stage][mask ^ sub] += dp[stage - 1][mask] * inv_factorial[sub];
                if (dp[stage][mask ^ sub] > INF) dp[stage][mask ^ sub] %= MOD;
            }
        }
        for (u64 mask = N; mask > 0; mask = (mask - 1) & N) {
            if (dp[stage][mask] >= MOD) dp[stage][mask] %= MOD;
        }
        u64 term = dp[stage][N] * choose(K, stage) % MOD;
        term = (term * factorial[stage]) % MOD;
        result = (result + term >= MOD) ? result + term - MOD : result + term;
    }
    result = (result * factorial[N]) % MOD;
    return result;
}

int main() {
    cin >> N >> K >> MOD;
    u64 full = mod_exp(K, N, MOD);
    if ((N & 1) == 0) {
        full = (full - solve() + MOD) % MOD;
    }
    cout << full << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ULL = unsigned long long;

constexpr ULL MAX_INF = (1ULL << 63);

ULL mod_val, n_val, k_val;
vector<vector<ULL>> memo;
vector<ULL> factorial_array;
vector<ULL> inv_factorial_array;

ULL binary_pow(ULL base, ULL exp, ULL m) {
    ULL result = 1;
    base %= m;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % m;
        base = (base * base) % m;
        exp >>= 1;
    }
    return result;
}

ULL binomial_coefficient(int upper, int lower) {
    if (lower < 0 || lower > upper) return 0;
    ULL result = factorial_array[upper];
    result = (result * inv_factorial_array[lower]) % mod_val;
    result = (result * inv_factorial_array[upper - lower]) % mod_val;
    return result;
}

ULL compute_dp_table() {
    const ULL max_param = max(n_val, k_val);
    factorial_array.assign(max_param + 1, 0);
    inv_factorial_array.assign(max_param + 1, 0);
    factorial_array[0] = 1;
    for (ULL idx = 1; idx <= max_param; ++idx) {
        factorial_array[idx] = (factorial_array[idx - 1] * idx) % mod_val;
    }
    inv_factorial_array[max_param] = binary_pow(factorial_array[max_param], mod_val - 2, mod_val);
    for (int idx = max_param - 1; idx >= 0; --idx) {
        inv_factorial_array[idx] = (inv_factorial_array[idx + 1] * (idx + 1)) % mod_val;
    }

    const int stages = min(18, static_cast<int>(k_val));
    memo.assign(stages + 1, vector<ULL>(300005, 0));

    for (ULL i = 1; i <= n_val; ++i) {
        memo[1][i] = inv_factorial_array[i];
    }

    ULL total = (memo[1][n_val] * binomial_coefficient(k_val, 1)) % mod_val;

    for (int stage = 2; stage <= stages; ++stage) {
        for (ULL subset = n_val; subset > 0; subset = (subset - 1) & n_val) {
            if (!memo[stage - 1][subset]) continue;
            ULL complement = n_val ^ subset;
            for (ULL subset2 = complement; subset2 > subset; subset2 = (subset2 - 1) & complement) {
                memo[stage][subset ^ subset2] += memo[stage - 1][subset] * inv_factorial_array[subset2];
                if (memo[stage][subset ^ subset2] > MAX_INF) {
                    memo[stage][subset ^ subset2] %= mod_val;
                }
            }
        }
        for (ULL subset = n_val; subset > 0; subset = (subset - 1) & n_val) {
            if (memo[stage][subset] >= mod_val) {
                memo[stage][subset] %= mod_val;
            }
        }
        ULL term = memo[stage][n_val] * binomial_coefficient(k_val, stage);
        term %= mod_val;
        term = (term * factorial_array[stage]) % mod_val;
        total = (total + term >= mod_val) ? (total + term - mod_val) : (total + term);
    }

    total = (total * factorial_array[n_val]) % mod_val;
    return total;
}

int main() {
    cin >> n_val >> k_val >> mod_val;
    ULL base_power = binary_pow(k_val, n_val, mod_val);
    if ((n_val % 2) == 0) {
        ULL sub = compute_dp_table();
        base_power = (base_power - sub + mod_val) % mod_val;
    }
