ll a[18][MAX_N], b[MAX_N];

ll mod_pow(ll base, ll exp) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> mod;

    if (n & 1) {
        cout << mod_pow(k, n);
        return 0;
