    fac[0] = 1;
    for (i = 1; i <= n; ++i) {
        fac[i] = fac[i-1] * i % mod;
    }

    inv[n] = mod_pow(fac[n], mod - 2);
    for (i = n - 1; i >= 0; --i) {
        inv[i] = inv[i+1] * (i+1) % mod;
    }

    n >>= 1;

    for (i = 0; i <= n; ++i) {
        int pop = __builtin_popcount(i);
        a[pop][i] = inv[i * 2];
    }

    for (i = 0; i < MAX_P; ++i) {
        for (j = 0; j < MAX_P; ++j) {
            for (u = 0; u < (1 << MAX_P); ++u) {
                if (u & (1 << j)) {
                    a[i][u] = (a[i][u] + a[i][u ^ (1 << j)]) % mod;
                }
            }
        }
    }

    for (i = 0; i < MAX_P; ++i) {
        for (u = 0; u < (1 << MAX_P); ++u) {
            a[i][u] %= mod;
            if (a[i][u] < 0) a[i][u] += mod;
        }
    }

    int pn = __builtin_popcount(n);

    for (i = 0; i < (1 << MAX_P); ++i) {
        memset(dp, 0, sizeof(dp));
        dp[0][0] = 1;

        for (j = 1; j <= k; ++j) {
            for (u = 0; u <= 17; ++u) {
                for (v = 0; u + v <= 17; ++v) {
                    dp[j][u + v] = (dp[j][u + v] + a[u][i] * dp[j-1][v]) % mod;
                }
            }
            for (v = 0; v <= 17; ++v) {
                dp[j][v] %= mod;
                if (dp[j][v] < 0) dp[j][v] += mod;
            }
        }
        b[i] = dp[k][pn];
    }

    for (i = 0; i < MAX_P; ++i) {
        for (j = 0; j < (1 << MAX_P); ++j) {
            if (j & (1 << i)) {
                b[j] = (b[j] - b[j ^ (1 << i)] + mod) % mod;
            }
        }
    }

    ll ans = (mod_pow(k, n * 2) - (b[n] * fac[n * 2]) % mod + mod) % mod;
    cout << ans << '\n';

    return 0;
}

