    for (i = n - 1; i >= 0; --i) {
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
    }

    n >>= 1;

    for (i = 0; i <= n; ++i) {
        int cnt = __builtin_popcount(i);
        f[cnt][i] = inv_fact[i << 1];
