        for (int mask = 0; mask < (1 << MAX_BITS); ++mask) {
            if (mask >> bit & 1) {
                f[0][mask] = (f[0][mask] + f[0][mask ^ (1 << bit)]) % MOD;
            }
        }
    }

    for (int bit = 1; bit < MAX_BITS; ++bit) {
        for (int mask = 0; mask < (1 << MAX_BITS); ++mask) {
            f[bit][mask] = f[0][mask];
        }
    }

    for (int bit = 0; bit < MAX_BITS; ++bit) {
