void addPoly(int *dest, const int *src) {
    for (int i = 0; i <= N; ++i) {
        dest[i] = (dest[i] + src[i]) % MOD;
        if (dest[i] < 0) dest[i] += MOD;
    }
}

void subPoly(int *dest, const int *src) {
    for (int i = 0; i <= N; ++i) {
        dest[i] = (dest[i] - src[i]) % MOD;
        if (dest[i] < 0) dest[i] += MOD;
    }
}

