#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MAXN = 1000010;
int n, K, MOD;
ll fact[MAXN], invFact[MAXN];
ll dp[MAXN], tmp[MAXN];

ll modPow(ll base, ll exp) {
    ll result = 1 % MOD;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

ll modInverse(ll x) {
    return modPow(x, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> K >> MOD;

    fact[0] = 1;
    for (int i = 1; i < MAXN; ++i) {
        fact[i] = fact[i-1] * i % MOD;
    }

    invFact[MAXN-1] = modInverse(fact[MAXN-1]);
    for (int i = MAXN-2; i >= 0; --i) {
        invFact[i] = invFact[i+1] * (i+1) % MOD;
    }

    ll answer = modPow(K, n);

    if (n % 2 == 0) {
        fill(dp, dp + MAXN, 0);
        dp[n] = fact[n];

        for (int round = 1; round <= K; ++round) {
            fill(tmp, tmp + MAXN, 0);

            for (int mask = n; mask; mask = (mask - 1) & n) {
                if (dp[mask] == 0) continue;

                for (int sub = mask; (sub << 1) >= mask; sub = (sub - 1) & mask) {
                    tmp[mask ^ sub] = (tmp[mask ^ sub] + dp[mask] * invFact[sub]) % MOD;
                }
            }

            copy(tmp, tmp + MAXN, dp);

            ll contrib = dp[0];
            for (int i = 0; i < round; ++i) {
                contrib = contrib * (K - i) % MOD;
            }
            answer = (answer - contrib + MOD) % MOD;
        }
    }

    cout << answer % MOD << '\n';
}

