ll binPow(ll a, int b, int p) {
    if (b == 0)
        return 1;
    ll x = binPow(a, b / 2, p);
    x *= x;
    x %= p;
    if (b & 1) {
        x *= a;
        x %= p;
    }
    return x;
}

