#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <map>

using namespace std;

using ll = long long;

ll mod_pow(ll base, int exp, int mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) 
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, p;
    cin >> n >> k >> p;

    if (n % 2 == 1) {
        cout << mod_pow(k, n, p) << '\n';
        return 0;
    }

    vector<ll> fact(n + 1), rfact(n + 1);
    fact[0] = 1;
    rfact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i-1] * i % p;
        rfact[i] = mod_pow(fact[i], p-2, p);
    }

    vector<vector<ll>> g(n + 1, vector<ll>(17, 0));
    g[0][0] = 1;

    for (int mask = 1; mask <= n; ++mask) {
        if ((mask & n) != mask) continue;

        vector<int> bits;
        for (int j = 0; j < 18; ++j) {
            if (mask & (1 << j)) 
                bits.push_back(j);
        }

        if (bits.empty()) continue;

        // Count subsets
        int total_subsets = 1 << bits.size();
        for (int subset = 1; subset < total_subsets; ++subset) {
            int l = 0;
            for (int j = 0; j < (int)bits.size(); ++j) {
                if (subset & (1 << j)) {
                    l ^= (1 << bits[j]);
                }
            }
            for (int i = 1; i < 17; ++i) {
                g[mask][i] = (g[mask][i] + rfact[l] * g[mask ^ l][i-1]) % p;
            }
        }
    }

    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j < 17; ++j) {
            g[i][j] %= p;
            if (g[i][j] < 0) g[i][j] += p;
        }
    }

    ll ans = 0;
    int upper = min(16, k);
    for (int i = 1; i <= upper; ++i) {
        ll term = fact[n] * g[n][i] % p;
        term = term * fact[k] % p;
        term = term * rfact[k - i] % p;
        ans = (ans + term) % p;
    }

    ans = (mod_pow(k, n, p) - ans + p) % p;
    cout << ans << '\n';

    return 0;
}

#include <bits/stdc++.h>

using namespace std;
using lint = long long;

lint mod_exp(lint base, lint exp, lint mod) {
    lint res = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, p;
    cin >> n >> k >> p;

    // Handle odd case directly
    if (n & 1) {
        cout << mod_exp(k, n, p) << '\n';
        return 0;
    }

    vector<lint> fact(n + 1), inv_fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) {
        fact[i] = fact[i-1] * i % p;
    }
    inv_fact[n] = mod_exp(fact[n], p - 2, p);
    for (int i = n; i >= 1; --i) {
        inv_fact[i-1] = inv_fact[i] * i % p;
    }

    // DP table: dp[mask][t] represents count of ways to partition mask into exactly t non-empty subsets
    vector<vector<lint>> dp(1 << 18, vector<lint>(17, 0));
    dp[0][0] = 1;

    for (int mask = 1; mask <= n; ++mask) {
        if ((mask & n) != mask) continue;

        vector<int> bits;
        for (int b = 0; b < 18; ++b) {
            if (mask & (1 << b)) {
                bits.push_back(b);
            }
        }

        // Iterate over all non-empty subsets
        int total_subsets = 1 << bits.size();
        for (int sub = 1; sub < total_subsets; ++sub) {
            int l = 0;
            for (int j = 0; j < (int)bits.size(); ++j) {
                if (sub & (1 << j)) {
                    l ^= (1 << bits[j]);
                }
            }

            lint coef = inv_fact[l];
            for (int t = 1; t <= 16; ++t) {
                dp[mask][t] = (dp[mask][t] + coef * dp[mask ^ l][t-1]) % p;
            }
        }
    }

    lint ans = 0;
    for (int t = 1; t <= min(16, k); ++t) {
        lint term = fact[n] * dp[n][t] % p;
        term = term * fact[k] % p;
        term = term * inv_fact[k - t] % p;
        ans = (ans + term) % p;
    }
    ans = (mod_exp(k, n, p) - ans + p) % p;
    cout << ans << '\n';

    return 0;
}

