ll mod_pow(ll base, int exp, int mod) {
    ll res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, p;
    cin >> n >> k >> p;

    if (n & 1) {
        cout << mod_pow(k, n, p) << '\n';
        return 0;
    }

    vector<ll> fact(n + 1), inv_fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i-1] * i % p;
    inv_fact[n] = mod_pow(fact[n], p-2, p);
    for (int i = n; i > 0; --i)
        inv_fact[i-1] = inv_fact[i] * i % p;

    vector<vector<ll>> dp(1 << 18, vector<ll>(17, 0));
    dp[0][0] = 1;

    for (int m = 1; m <= n; ++m) {
        if ((m & n) != m) continue;

        vector<int> ones;
        for (int b = 0; b < 18; ++b)
            if (m & (1 << b)) ones.push_back(b);

        if (ones.empty()) continue;

        int ssz = ones.size();
        for (int mask = 1; mask < (1 << ssz); ++mask) {
            int l = 0;
            for (int b = 0; b < ssz; ++b)
                if (mask & (1 << b)) l ^= (1 << ones[b]);

            ll w = inv_fact[l];
            for (int t = 1; t <= 16; ++t)
                dp[m][t] = (dp[m][t] + w * dp[m ^ l][t-1]) % p;
        }
    }

    for (int i = 0; i <= n; ++i)
        for (int t = 0; t < 17; ++t)
            dp[i][t] = (dp[i][t] % p + p) % p;

    ll total = 0;
    for (int t = 1; t <= min(16, k); ++t) {
        ll cur = fact[n] * dp[n][t] % p;
        cur = cur * fact[k] % p;
        cur = cur * inv_fact[k - t] % p;
        total = (total + cur) % p;
    }

    ll all = mod_pow(k, n, p);
    ll res = (all - total + p) % p;
    cout << res << '\n';

    return 0;
}

