#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 250010;
long long factorial[MAX_N], inverse[MAX_N];
long long dp[30][MAX_N];
int popcountArr[MAX_N];
long long n, m, modulus;

long long binomial(int n, int m) {
    return factorial[n] * inverse[n - m] % modulus * inverse[m] % modulus;
}

void accumulateMod(long long &x, long long y) {
    x = (x + y) % modulus;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> modulus;

    factorial[0] = inverse[0] = inverse[1] = factorial[1] = 1;
    for (int i = 2; i <= n; i++) {
        int r = modulus / i;
        int x = modulus - i * r;
        factorial[i] = factorial[i - 1] * i % modulus;
        inverse[i] = modulus - (1LL * r * inverse[x]) % modulus;
    }

    for (int i = 2; i <= n; i++) {
        inverse[i] = inverse[i - 1] * inverse[i] % modulus;
    }

    long long result = 1;
    for (int i = 1; i <= n; i++) {
        result = result * m % modulus;
    }

    for (int i = 1; i <= n; i++) {
        popcountArr[i] = popcountArr[i >> 1] + (i & 1);
    }

    if (n & 1) {
        cout << result << '\n';
        return 0;
    }

    dp[0][0] = 1;
    int maxBit = min<int>(popcountArr[n], m);

    for (int i = 0; i < maxBit; i++) {
        for (int j = 0; j <= n; j++) {
            if (!dp[i][j]) continue;
            int complement = n ^ j;
            for (int k = complement; k > j; k = (k - 1) & complement) {
                int combined = k | j;
                accumulateMod(dp[i + 1][combined], dp[i][j] * inverse[k] % modulus);
            }
        }
    }

    for (int i = 1; i <= m; i++) {
        long long term = dp[i][n] * factorial[m] % modulus;
        term = term * inverse[m - i] % modulus;
        term = term * factorial[n] % modulus;
        result = (result - term % modulus + modulus) % modulus;
    }

    cout << result << '\n';
    return 0;
}

