ll precomputeFactorial(int limit, ll mod) {
    vector<ll> f(limit + 1);
    f[0] = 1;
    for (int i = 1; i <= limit; ++i)
        f[i] = f[i - 1] * i % mod;
    return f[limit];
}

ll modInverse(ll a, ll mod) {
    ll b = a, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= mod;
    if (u < 0) u += mod;
    return u;
}

ll extendedModInverseArray(int limit, ll mod) {
    vector<ll> inv(limit + 1);
    inv[1] = 1;
    for (int i = 2; i <= limit; ++i)
        inv[i] = mod - (mod / i) * inv[mod % i] % mod;
    for (int i = 1; i <= limit; ++i)
        inv[i] = inv[i - 1] * inv[i] % mod;
    return inv[limit];
}

int popcount(int x) {
    int cnt = 0;
    while (x) {
        cnt += x & 1;
        x >>= 1;
    }
    return cnt;
}

