    vector<ll> fac(n + 1), inv(n + 1);
    fac[0] = inv[0] = inv[1] = fac[1] = 1;

    for (int i = 2; i <= n; ++i) {
        ll r = mod / i;
        ll x = mod - i * r;
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = (mod - r * inv[x] % mod) % mod;
    }

    for (int i = 2; i <= n; ++i) {
        inv[i] = inv[i - 1] * inv[i] % mod;
    }

    ll totalWays = 1;
    for (int i = 1; i <= n; ++i)
        totalWays = totalWays * m % mod;

    vector<int> pc(n + 1);
    pc[0] = 0;
    for (int i = 1; i <= n; ++i)
        pc[i] = pc[i >> 1] + (i & 1);

    if (n & 1) {
        cout << totalWays << '\n';
        return 0;
    }

    vector<vector<ll>> dp(pc[n] + 2, vector<ll>(n + 1, 0));
