        for (int j = 0; j <= n; ++j) {
            if (!dp[i][j]) continue;
            int mask = n ^ j;
            for (int k = mask; k > j; k = (k - 1) & mask) {
                int state = k | j;
                dp[i + 1][state] = (dp[i + 1][state] + dp[i][j] * inv[k] % mod) % mod;
            }
        }
    }

