        ll subtract = dp[i][n];
        subtract = subtract * fac[m] % mod;
        subtract = subtract * inv[m - i] % mod;
        subtract = subtract * fac[n] % mod;
        totalWays = (totalWays - subtract % mod + mod) % mod;
    }

    cout << totalWays << '\n';
    return 0;
}

