        ll r = mod / i;
        ll x = (mod - i * r) % mod;
        factorial[i] = factorial[i - 1] * i % mod;
        inv_factorial[i] = (mod - r * inv_factorial[x] % mod) % mod;
    }

    for (int i = 2; i <= n; ++i) {
        inv_factorial[i] = inv_factorial[i - 1] * inv_factorial[i] % mod;
    }

    ll all_assignments = 1;
    for (int i = 0; i < n; ++i)
        all_assignments = (all_assignments * (m % mod)) % mod;

