            for (int subset = remainder; subset > state; subset = (subset - 1) & remainder) {
                int new_state = subset | state;
                dp[depth + 1][new_state] = (dp[depth + 1][new_state] + dp[depth][state] * inv_factorial[subset] % mod) % mod;
            }
        }
    }

