        ll contrib = dp[i][n];
        contrib = contrib * factorial[m] % mod;
        contrib = contrib * inv_factorial[m - i] % mod;
        contrib = contrib * factorial[n] % mod;
        all_assignments = (all_assignments - contrib % mod + mod) % mod;
    }

    cout << all_assignments << '\n';
    return 0;
}

