int solve(int use,int S){
	if(f[use][S]!=-1)return f[use][S];
	int ret=0;
	if(!S){
		int ret=fac[n];
		for(int i=1;i<=use;++i)
			ret=1LL*ret*(k-i+1)%Mod;
//		cerr<<"!S "<<use<<" "<<S<<": "<<ret<<endl;
		return f[use][S]=ret;
	}
	if(use>k)return 0;
	int lbit=S&(-S);
	int U=S-lbit;
	for(int T=U;;T=(T-1)&U){
//		cerr<<"? "<<S<<" "<<T<<" "<<lbit<<endl;
		ret=(1LL*dfac[S-T]*solve(use+1,T)+ret)%Mod;	
		if(!T)break;
	}
