            for (int j = 0; j <= min(i, m); ++j) {
                dpW2[i][j] = dpW2[i-1][j];
                dpS2[i][j] = dpS2[i-1][j];
                for (int k = 1; k <= j; ++k) {
                    int ni = max(0, i - k - 1);
                    int nj = j - k;
                    lint termW = dpW[k] * dpW2[ni][nj] % MOD * C[j][k] % MOD;
                    lint termS = ((dpS[k] * dpW2[ni][nj] % MOD) + (dpW[k] * dpS2[ni][nj] % MOD)) % MOD * C[j][k] % MOD;
                    add_mod(dpW2[i][j], termW);
                    add_mod(dpS2[i][j], termS);
                }
            }
        }
