int MOD;

inline int normalize(int x) {
    return (x % MOD + MOD) % MOD;
}

inline void increment(int& x, int y) {
    x = normalize(x + y);
}

int mod_exp(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (1LL * result * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

vector<int> factorial, inv_factorial;

void precompute(int size) {
    factorial.resize(size + 1);
    inv_factorial.resize(size + 1);
    factorial[0] = 1;
    for (int i = 1; i <= size; ++i) {
        factorial[i] = (1LL * factorial[i - 1] * i) % MOD;
    }
    inv_factorial[size] = mod_exp(factorial[size], MOD - 2);
    for (int i = size; i >= 1; --i) {
        inv_factorial[i - 1] = (1LL * inv_factorial[i] * i) % MOD;
    }
}

int binomial(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    return (1LL * factorial[n] * inv_factorial[k] % MOD) * inv_factorial[n - k] % MOD;
}

int triangular_number(int x) {
    return x * (x + 1) / 2;
}

int G_func(int n, int m) {
    return binomial(m + n - 1, n - 1);
}

