int binom[N][N];

void calc() {
    binom[0][0] = 1;
    for (int i = 1; i < N; ++i) {
        binom[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            binom[i][j] = add(binom[i - 1][j], binom[i - 1][j - 1]);
    }
}

int main() {
    int n, m;
    rd(n, m, mod);
    calc();
    blok[0] = 1;
    for (int x = 1; x <= m; ++x) {
        for (int i = 1; i <= x; ++i) {
            int coef = mul(blok[i - 1], mul(blok[x - i], binom[x - 1][i - 1]));
            ckadd(blok[x], coef);
            ckadd(sum[x], mul(add(c2(i - 1), c2(x - i)), coef));
            ckadd(sum[x], mul(sum[i - 1], mul(coef, x + 1)));
            ckadd(sum[x], mul(sum[x - i], mul(coef, x + 1)));
        }
        ckmul(blok[x], x + 1);
    }
    ways[0][0] = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            for (int sz = 1; sz <= i; ++sz) {
                int coef = mul(blok[sz], binom[m - i + sz][sz]);
                ckadd(ways[i][j], mul(ways[i - sz][j - 1], coef));
                ckadd(dp[i][j], mul(ways[i - sz][j - 1], mul(sum[sz], binom[m - i + sz][sz])));
                ckadd(dp[i][j], mul(dp[i - sz][j - 1], coef));
            }
        }
    }
    int ans = 0;
    for (int i = 1; i <= m; ++i) {
        int zero = n - m;
        int lef = zero - (i - 1);
        if (lef >= 0)
            ckadd(ans, mul(dp[m][i], binom[i + 1 + lef - 1][lef]));
    }
    printf("%d\n", ans);
    return 0;
}

