const int maxn = 510;
int n, m, P, C[maxn][maxn], f1[maxn], f2[maxn][maxn], g1[maxn], g2[maxn][maxn];

int main() {
    scanf("%d %d %d", &n, &m, &P);
    for (int i = 0; i <= n; i++) {
        for (int j = C[i][0] = 1; j <= i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
        }
    }
    for (int i = f1[0] = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            f1[i] = (f1[i] + 1LL * f1[j - 1] * f1[i - j] % P * C[i - 1][j - 1]) % P;
            int t = (1LL * f1[j - 1] * g1[i - j] + 1LL * g1[j - 1] * f1[i - j]) % P
                * (i + 1) % P;
            g1[i] = (g1[i] + (1LL * f1[j - 1] * f1[i - j] % P * (C[j][2] +
                C[i - j + 1][2]) % P + t) % P * C[i - 1][j - 1]) % P;
        }
        f1[i] = 1LL * (i + 1) * f1[i] % P;
    }
    f2[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= min(i, m); j++) {
            f2[i][j] = f2[i - 1][j], g2[i][j] = g2[i - 1][j];
            for (int k = 1; k <= j; k++) {
                f2[i][j] = (f2[i][j] + 1LL * (i - k ? f2[i - k - 1][j - k] : 1) *
                    f1[k] % P * C[j][k]) % P;
                g2[i][j] = (g2[i][j] + (1LL * (i - k ? f2[i - k - 1][j - k] : 1) *
                    g1[k] + 1LL * (i - k ? g2[i - k - 1][j - k] : 0) * f1[k])
                    % P * C[j][k]) % P;
            }
        }
    }
    printf("%d\n", g2[n][m]);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 510;
int nodes, edges, mod;
int comb[MAX_SIZE][MAX_SIZE], f_single[MAX_SIZE], g_single[MAX_SIZE];
int f_dp[MAX_SIZE][MAX_SIZE], g_dp[MAX_SIZE][MAX_SIZE];

int main() {
    scanf("%d %d %d", &nodes, &edges, &mod);

    // Compute binomial coefficients
    for (int i = 0; i <= nodes; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % mod;
        }
    }

    // Single tree calculations
    f_single[0] = 1;
    for (int i = 1; i <= nodes; ++i) {
        for (int j = 1; j <= i; ++j) {
            long long term = (long long)f_single[j-1] * f_single[i-j] % mod;
            term = term * comb[i-1][j-1] % mod;
            f_single[i] = (f_single[i] + term) % mod;

            long long cross = ((long long)f_single[j-1] * g_single[i-j] + 
                              (long long)g_single[j-1] * f_single[i-j]) % mod;
            cross = cross * (i + 1) % mod;

            long long base = (long long)f_single[j-1] * f_single[i-j] % mod;
            base = base * (comb[j][2] + comb[i-j+1][2]) % mod;

            long long add = (base + cross) % mod;
            add = add * comb[i-1][j-1] % mod;

            g_single[i] = (g_single[i] + add) % mod;
        }
        f_single[i] = (long long)(i + 1) * f_single[i] % mod;
    }

    // DP initialization
    f_dp[0][0] = 1;

    // DP computation
    for (int i = 1; i <= nodes; ++i) {
        for (int j = 0; j <= min(i, edges); ++j) {
            f_dp[i][j] = f_dp[i-1][j];
            g_dp[i][j] = g_dp[i-1][j];

            for (int k = 1; k <= j; ++k) {
                int prev_f = (i - k) ? f_dp[i-k-1][j-k] : 1;
                int prev_g = (i - k) ? g_dp[i-k-1][j-k] : 0;

                long long term_f = (long long)prev_f * f_single[k] % mod;
                term_f = term_f * comb[j][k] % mod;
                f_dp[i][j] = (f_dp[i][j] + term_f) % mod;

                long long term_g = ((long long)prev_f * g_single[k] + 
                                   (long long)prev_g * f_single[k]) % mod;
                term_g = term_g * comb[j][k] % mod;
                g_dp[i][j] = (g_dp[i][j] + term_g) % mod;
            }
        }
    }

    printf("%d\n", g_dp[nodes][edges]);
    return 0;
}

