inline void add(int &a, int b) {
    a = (a + b) % P;
}

int main() {
    cin >> n >> m >> P;

    // Pascal's triangle
    for (int i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % P;
        }
    }

    // f1[i] - count of ordered trees
    f1[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            long long cur = (long long)f1[j-1] * f1[i-j] % P;
            cur = cur * C[i-1][j-1] % P;
            add(f1[i], cur);

            long long t = ((long long)f1[j-1] * g1[i-j] + 
                          (long long)g1[j-1] * f1[i-j]) % P;
            t = t * (i + 1) % P;

            long long term = (long long)f1[j-1] * f1[i-j] % P;
            term = term * ((long long)C[j][2] + C[i-j+1][2]) % P;
            term = (term + t) % P;
            term = term * C[i-1][j-1] % P;

            add(g1[i], term);
        }
        f1[i] = (long long)(i + 1) * f1[i] % P;
    }

    // DP base case
    f2[0][0] = 1;

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= min(i, m); j++) {
            f2[i][j] = f2[i-1][j];
            g2[i][j] = g2[i-1][j];

            for (int k = 1; k <= j; k++) {
                int pf = (i != k) ? f2[i-k-1][j-k] : 1;
                int pg = (i != k) ? g2[i-k-1][j-k] : 0;

                long long ft = (long long)pf * f1[k] % P * C[j][k] % P;
                add(f2[i][j], ft);

                long long gt = ((long long)pf * g1[k] + (long long)pg * f1[k]) % P;
                gt = gt * C[j][k] % P;
                add(g2[i][j], gt);
            }
        }
    }

    cout << g2[n][m] << endl;
    return 0;
}

