int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> P;

    // Pascal's triangle
    vector<vector<int>> C(n + 2, vector<int>(n + 2, 0));
    for (int i = 0; i <= n + 1; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = C[i-1][j-1] + C[i-1][j];
            if (C[i][j] >= P) C[i][j] -= P;
        }
    }

    vector<int> cnt(m + 1, 0);
    vector<int> dp1(m + 1, 0);
    cnt[0] = 1;

    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < i; ++j) {
            int term = mul(dp1[j], cnt[i - j - 1]);
            add(term, mul(dp1[i - j - 1], cnt[j]));
            term = mul(term, j + 1);
            int comb = (j * (j + 1LL) / 2) % P;
            add(term, mul(mul(cnt[i - j - 1], cnt[j]), comb));
            term = mul(term, C[i-1][j]);
            add(dp1[i], term);

            int cnt_term = C[i-1][j];
            cnt_term = mul(cnt_term, cnt[j]);
            cnt_term = mul(cnt_term, cnt[i - j - 1]);
            cnt_term = mul(cnt_term, j + 1);
            add(cnt[i], cnt_term);
        }
        add(cnt[i], cnt[i]);
        add(dp1[i], dp1[i]);
    }

    vector<vector<int>> dp2(n + 2, vector<int>(m + 1, 0));
    vector<vector<int>> dp3(n + 2, vector<int>(m + 1, 0));
    dp2[0][0] = 1;
    dp3[0][0] = 0;

    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int k = 0; k <= m; ++k) {
                if (j + k > m || i + k + 1 > n + 1) continue;
                int val2 = dp2[i][j];
                val2 = mul(val2, C[m - j][k]);
                val2 = mul(val2, cnt[k]);

                int val3 = dp3[i][j];
                val3 = mul(val3, cnt[k]);
                add(val3, mul(dp1[k], dp2[i][j]));
                val3 = mul(val3, C[m - j][k]);

                add(dp2[i + k + 1][j + k], val2);
                add(dp3[i + k + 1][j + k], val3);
            }
        }
    }

    cout << dp3[n + 1][m] << "\n";
