    C[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= n; j++) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }

    V<mint> g(n + 1);
    for (int i = 0; i <= n; i++) {
        g[i] = i * (i + 1) / 2;
    }

    using P = pair<mint, mint>;
    V<P> f(n + 1); // (pattern, sum of maddness of all pattern)
    f[0] = {1, 0};

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            // j, (i - 1 - j)
            mint z = f[j].first * f[i - 1 - j].first * C[i - 1][j];
            f[i].first += z * mint(i + 1);
            f[i].second += z * (g[j] + g[i - 1 - j]);
            f[i].second += (f[i - 1 - j].first * f[j].second + f[j].first * f[i - 1 - j].second) * C[i - 1][j] * mint(i + 1);
        }
    }


    for (int i = 0; i <= n; i++) {
        dbg(i, f[i].first.val(), f[i].second.val(), g[i].val());
    }

    // 0  : empty
    // 1~n: ???
    // n+1: empty

    VV<P> dp(n + 2, V<P>(m + 1));
    dp[0][0] = {1, 0};
    for (int l = 0; l <= n; l++) {
        for (int r = l + 1; r <= n + 1; r++) {
            int di = r - l - 1;
            for (int i = 0; i + di <= m; i++) {
                // dp[l][i] -> dp[r][i + di]
                mint z = dp[l][i].first * f[di].first;
                dp[r][i + di].first += z * C[i + di][di];
                dp[r][i + di].second += (dp[l][i].second * f[di].first + dp[l][i].first * f[di].second) * C[i + di][di];
            }
        }
    }

    dbg(dp[n + 1][m].first.val(), dp[n + 1][m].second.val());

    pr.writeln(dp[n + 1][m].second.val());
    return 0;
}

