Scanner sc = Scanner(stdin);
Printer pr = Printer(stdout);

int main() {
    int n, m, mod;
    sc.read(n, m, mod);

    VV<static_modint<1000000007>> C(n + 1, V<static_modint<1000000007>>(n + 1));
    C[0][0] = static_modint<1000000007>::raw(1);
    for (int i = 1; i <= n; i++) {
        C[i][0] = static_modint<1000000007>::raw(1);
        for (int j = 1; j <= n; j++) {
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
        }
    }

    V<static_modint<1000000007>> g(n + 1);
    for (int i = 0; i <= n; i++) {
        g[i] = static_modint<1000000007>::raw(i * (i + 1) / 2);
    }

    using P = pair<static_modint<1000000007>, static_modint<1000000007>>;
    V<P> f(n + 1);
    f[0] = {static_modint<1000000007>::raw(1), static_modint<1000000007>::raw(0)};

    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            static_modint<1000000007> z = f[j].first * f[i - 1 - j].first * C[i - 1][j];
            f[i].first += z * static_modint<1000000007>::raw(i + 1);
            f[i].second += z * (g[j] + g[i - 1 - j]);
            f[i].second += (f[i - 1 - j].first * f[j].second + f[j].first * f[i - 1 - j].second) * C[i - 1][j] * static_modint<1000000007>::raw(i + 1);
        }
    }

    VV<P> dp(n + 2, V<P>(m + 1));
    dp[0][0] = {static_modint<1000000007>::raw(1), static_modint<1000000007>::raw(0)};
    for (int l = 0; l <= n; l++) {
        for (int r = l + 1; r <= n + 1; r++) {
            int di = r - l - 1;
            for (int i = 0; i + di <= m; i++) {
                static_modint<1000000007> z = dp[l][i].first * f[di].first;
                dp[r][i + di].first += z * C[i + di][di];
                dp[r][i + di].second += (dp[l][i].second * f[di].first + dp[l][i].first * f[di].second) * C[i + di][di];
            }
        }
    }

    pr.writeln(dp[n + 1][m].second.val());
    return 0;
}

