#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;
using vi = vector<int>;

const int N = 509;
int mod;

inline int add(int a, int b) {
    a += b;
    if (a >= mod) a -= mod;
    return a;
}

inline int mul(int a, int b) {
    return (ll)a * b % mod;
}

int C[N][N], f[N], g[N];
int dp[N][N], dp2[N][N];

int main() {
    int n, m;
    scanf("%d%d%d", &n, &m, &mod);

    // Precompute binomial coefficients
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 0; j < i; ++j) {
            C[i][j+1] = add(C[i-1][j+1], C[i-1][j]);
        }
    }

    // Base cases for f and g
    f[0] = 1;
    g[0] = 0;

    // Compute f[i] and g[i] for i from 1 to m
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int term1 = mul(mul(C[i-1][j-1], i+1), mul(f[j-1], f[i-j]));
            f[i] = add(f[i], term1);

            int term2 = mul(mul(C[i-1][j-1], i+1), add(mul(f[j-1], g[i-j]), mul(g[j-1], f[i-j])));
            int term3 = mul(mul(C[i-1][j-1], (j-1)*j/2 + (i-j+1)*(i-j)/2), mul(f[j-1], f[i-j]));
            g[i] = add(g[i], add(term2, term3));
        }
    }

    ++n;
    dp[0][0] = 1;
    dp2[0][0] = 0;

    // DP transitions
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int k = 0; j + k <= m && i + k + 1 <= n; ++k) {
                int coef = mul(dp[i][j], f[k]);
                coef = mul(coef, C[j+k][j]);
                dp[i+k+1][j+k] = add(dp[i+k+1][j+k], coef);

                int val = add(mul(dp2[i][j], f[k]), mul(dp[i][j], g[k]));
                val = mul(C[j+k][j], val);
                dp2[i+k+1][j+k] = add(dp2[i+k+1][j+k], val);
            }
        }
    }

    printf("%d\n", dp2[n][m]);
    return 0;
}

