    f[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            f[i] = (f[i] + (ll)f[i-1-j] * f[j] % mod * (i+1) % mod * C[i-1][j] % mod) % mod;
        }
