            ll term1 = (ll)f[j] * f[i-1-j] % mod * C[i-1][j] % mod;
            ll term2 = (ll)(j+1) * j / 2;
            ll term3 = (ll)(i-1-j) * (i-j) / 2;
            h[i] = (h[i] + term1 * ((term2 + term3) % mod)) % mod;

            h[i] = (h[i] + (ll)C[i-1][j] * (i+1) % mod * f[i-1-j] % mod * h[j]) % mod;
            h[i] = (h[i] + (ll)C[i-1][j] * (i+1) % mod * f[j] % mod * h[i-1-j]) % mod;
