#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MAX_N = 505;

int n, m, MOD;
int comb[MAX_N][MAX_N];
int f[MAX_N], g[MAX_N];
int dp_f[MAX_N][MAX_N], dp_g[MAX_N][MAX_N];

inline void mod_add(int &x, int y) {
    x = (x + y) % MOD;
    if (x < 0) x += MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> MOD;

    // Precompute binomial coefficients
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            comb[i][j] = (comb[i-1][j] + comb[i-1][j-1]) % MOD;
        }
    }

    f[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            ll term1 = (ll)f[j-1] * f[i-j] % MOD;
            term1 = term1 * comb[i-1][j-1] % MOD;
            term1 = term1 * (i + 1) % MOD;
            mod_add(f[i], (int)term1);

            ll term2 = (ll)g[j-1] * f[i-j] % MOD;
            term2 = term2 * comb[i-1][j-1] % MOD;
            term2 = term2 * (i + 1) % MOD;
            mod_add(g[i], (int)term2);

            ll term3 = (ll)g[i-j] * f[j-1] % MOD;
            term3 = term3 * comb[i-1][j-1] % MOD;
            term3 = term3 * (i + 1) % MOD;
            mod_add(g[i], (int)term3);

            int sum_abs = 0;
            for (int k = 1; k <= i; ++k) {
                int diff = k - j;
                sum_abs += (diff >= 0) ? diff : -diff;
            }
            ll term4 = (ll)f[j-1] * f[i-j] % MOD;
            term4 = term4 * comb[i-1][j-1] % MOD;
            term4 = term4 * sum_abs % MOD;
            mod_add(g[i], (int)term4);
        }
    }

    dp_f[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (j == i) {
                dp_f[i][j] = f[i];
                dp_g[i][j] = g[i];
                continue;
            }
            dp_f[i][j] = dp_f[i-1][j];
            dp_g[i][j] = dp_g[i-1][j];
            for (int k = 1; k <= j; ++k) {
                ll term1 = (ll)dp_f[i-k-1][j-k] * f[k] % MOD;
                term1 = term1 * comb[j][k] % MOD;
                mod_add(dp_f[i][j], (int)term1);

                ll term2 = (ll)dp_f[i-k-1][j-k] * g[k] % MOD;
                term2 = term2 * comb[j][k] % MOD;
                mod_add(dp_g[i][j], (int)term2);

                ll term3 = (ll)dp_g[i-k-1][j-k] * f[k] % MOD;
                term3 = term3 * comb[j][k] % MOD;
                mod_add(dp_g[i][j], (int)term3);
            }
        }
    }

    cout << dp_g[n][m] << '\n';
    return 0;
}

