            g[i] = (g[i] + term2) % mod;

            int term3 = (int)(((long long)g[i-j] * f[j-1] % mod) * C[i-1][j-1] % mod * (i + 1) % mod);
            g[i] = (g[i] + term3) % mod;

            int sum_abs = 0;
            for (int k = 1; k <= i; ++k) {
                sum_abs = (sum_abs + abs(k - j)) % mod;
            }
            int term4 = (int)(((long long)f[j-1] * f[i-j] % mod) * C[i-1][j-1] % mod * sum_abs % mod);
            g[i] = (g[i] + term4) % mod;
        }
    }

    vector<vector<int>> dp_f(n + 1, vector<int>(n + 1, 0));
    vector<vector<int>> dp_g(n + 1, vector<int>(n + 1, 0));
    dp_f[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (j == i) {
                dp_f[i][j] = f[i];
                dp_g[i][j] = g[i];
                continue;
            }
            dp_f[i][j] = dp_f[i-1][j];
            dp_g[i][j] = dp_g[i-1][j];
            for (int k = 1; k <= j; ++k) {
                int term1 = (int)(((long long)dp_f[i-k-1][j-k] * f[k] % mod) * C[j][k] % mod);
                dp_f[i][j] = (dp_f[i][j] + term1) % mod;

                int term2 = (int)(((long long)dp_f[i-k-1][j-k] * g[k] % mod) * C[j][k] % mod);
                dp_g[i][j] = (dp_g[i][j] + term2) % mod;

                int term3 = (int)(((long long)dp_g[i-k-1][j-k] * f[k] % mod) * C[j][k] % mod);
                dp_g[i][j] = (dp_g[i][j] + term3) % mod;
            }
        }
    }

    cout << ((dp_g[n][m] % mod) + mod) % mod << endl;
    return 0;
}

