    f[0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            auto safe_mod = [&](long long x) -> int {
                x %= mod;
                return x >= 0 ? x : x + mod;
            };

            long long t1 = safe_mod(1LL * f[j-1] * f[i-j] % mod * C[i-1][j-1] % mod * (i + 1));
            f[i] = safe_mod(f[i] + t1);

            long long t2 = safe_mod(1LL * g[j-1] * f[i-j] % mod * C[i-1][j-1] % mod * (i + 1));
            g[i] = safe_mod(g[i] + t2);

            long long t3 = safe_mod(1LL * g[i-j] * f[j-1] % mod * C[i-1][j-1] % mod * (i + 1));
            g[i] = safe_mod(g[i] + t3);

            int sum_abs = 0;
            for (int k = 1; k <= i; ++k) {
                sum_abs = (sum_abs + abs(k - j)) % mod;
            }
            long long t4 = safe_mod(1LL * f[j-1] * f[i-j] % mod * C[i-1][j-1] % mod * sum_abs);
            g[i] = safe_mod(g[i] + t4);
        }
    }

    vector<vector<int>> dp_f(n + 1, vector<int>(n + 1, 0));
    vector<vector<int>> dp_g(n + 1, vector<int>(n + 1, 0));
    dp_f[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (j == i) {
                dp_f[i][j] = f[i];
                dp_g[i][j] = g[i];
                continue;
            }
            dp_f[i][j] = dp_f[i-1][j];
            dp_g[i][j] = dp_g[i-1][j];
            for (int k = 1; k <= j; ++k) {
                auto safe_mod = [&](long long x) -> int {
                    x %= mod;
                    return x >= 0 ? x : x + mod;
                };

                long long t1 = safe_mod(1LL * dp_f[i-k-1][j-k] * f[k] % mod * C[j][k]);
                dp_f[i][j] = safe_mod(dp_f[i][j] + t1);

                long long t2 = safe_mod(1LL * dp_f[i-k-1][j-k] * g[k] % mod * C[j][k]);
                dp_g[i][j] = safe_mod(dp_g[i][j] + t2);

                long long t3 = safe_mod(1LL * dp_g[i-k-1][j-k] * f[k] % mod * C[j][k]);
                dp_g[i][j] = safe_mod(dp_g[i][j] + t3);
