struct modinfo{uint mod, root;};
template<modinfo const&ref>
struct modular{
	static constexpr uint const &mod = ref.mod;
	static modular root(){ return modular(ref.root); }
	uint v;
	modular(ll vv = 0){ s(vv % mod + mod); }
	modular& s(uint vv){
		v = vv < mod ? vv : vv - mod;
		return *this;
	}
	modular operator-() const{ return modular() - *this; }
	modular& operator+=(const modular& rhs){ return s(v + rhs.v); }
	modular& operator-=(const modular& rhs){ return s(v + mod - rhs.v); }
	modular& operator*=(const modular& rhs){
		v = ull(v) * rhs.v % mod;
		return *this;
	}
	modular& operator/=(const modular& rhs){ return *this *= rhs.inv(); }
	modular operator+(const modular& rhs) const{ return modular(*this) += rhs; }
	modular operator-(const modular& rhs) const{ return modular(*this) -= rhs; }
	modular operator*(const modular& rhs) const{ return modular(*this) *= rhs; }
	modular operator/(const modular& rhs) const{ return modular(*this) /= rhs; }
	modular pow(int n) const{
		modular res(1), x(*this);
		while(n){
			if(n & 1) res *= x;
			x *= x;
			n >>= 1;
		}
		return res;
	}
	modular inv() const{ return pow(mod - 2); }
	friend modular operator+(int x, const modular& y){ return modular(x) + y; }
	friend modular operator-(int x, const modular& y){ return modular(x) - y; }
	friend modular operator*(int x, const modular& y){ return modular(x) * y; }
	friend modular operator/(int x, const modular& y){ return modular(x) / y; }
	friend ostream& operator<<(ostream& os, const modular& m){ return os << m.v; }
	friend istream& operator>>(istream& is, modular& m){ ll x; is >> x; m = modular(x); return is; }
	bool operator<(const modular& r) const{ return v < r.v; }
	bool operator==(const modular& r) const{ return v == r.v; }
	bool operator!=(const modular& r) const{ return v != r.v; }
	explicit operator bool() const{ return v; }
};

modinfo base{998244353, 3};
using mint = modular<base>;

const int VMAX = 10010;
mint FACT[VMAX], FINV[VMAX], INVS[VMAX];
void INIT_FACT(){
	FACT[0] = 1;
	FOR(i, 1, VMAX){
		FACT[i] = FACT[i - 1] * i;
	}
	FINV[VMAX - 1] = FACT[VMAX - 1].inv();
	for(int i = VMAX - 2; i >= 0; --i){
		FINV[i] = FINV[i + 1] * (i + 1);
	}
	for(int i = VMAX - 1; i >= 1; --i){
		INVS[i] = FINV[i] * FACT[i - 1];
	}
}
mint CHOOSE(int n, int k){
	return FACT[n] * FINV[n - k] * FINV[k];
}
mint BINOM(int a, int b){
	return FACT[a + b] * FINV[a] * FINV[b];
}
mint CATALAN(int n){
	return BINOM(n, n) - (n - 1 >= 0 ? BINOM(n - 1, n + 1) : 0);
}

void SOLVE(){
	int n, m; cin >> n >> m >> base.mod;
	INIT_FACT();

	mint ans;
	FOR(len, 1, m){
		mint f = mint(len + 1).pow(len) * len / (n - len) * FINV[len];
		REP(i, m - len){
			int j = i + len;
			mint g = mint(n - len).pow(i) * FINV[i];
			mint h = (n - j) * mint(n + 1).pow(m - 1 - j) * FACT[j];
			ans += f * g * h;
		}
	}
	ans *= mint(2).pow(m - 1) * (n + 1 - m);
	PRINT(ans);
}

signed main(){
	cin.tie(0);
	ios::sync_with_stdio(0);
	cout << fixed << setprecision(20);

	SOLVE();
}

