#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, mod;
    cin >> n >> m >> mod;

    const int N = 510;
    vector<vector<int>> C(N, vector<int>(N, 0));
    vector<vector<pair<int, int>>> dp(N, vector<pair<int, int>>(N, {0, 0}));

    // Precompute binomial coefficients
    for (int i = 0; i < N; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = C[i-1][j] + C[i-1][j-1];
            if (C[i][j] >= mod) C[i][j] -= mod;
        }
    }

    auto add = [&](int a, int b) -> int {
        a += b;
        if (a >= mod) a -= mod;
        return a;
    };

    auto mul_pair = [&](const pair<int, int>& a, const pair<int, int>& b) -> pair<int, int> {
        long long f = (1LL * a.first * b.first) % mod;
        long long s = (1LL * a.first * b.second + 1LL * a.second * b.first) % mod;
        return {(int)f, (int)s};
    };

    auto sum_range = [](int l, int r) -> int {
        return (l + r) * (r - l + 1) / 2;
    };

    for (int i = 0; i <= n; ++i) {
        dp[i][0] = {1, 0};
        for (int j = 1; j <= min(i, m); ++j) {
            if (i != j) {
                for (int k = 1; k <= i; ++k) {
                    auto term = mul_pair(mul_pair(dp[k-1][k-1], dp[i-k][j-k+1]), {C[j][k-1], 0});
                    dp[i][j].first = add(dp[i][j].first, term.first);
                    dp[i][j].second = add(dp[i][j].second, term.second);
                }
            } else {
                for (int k = 1; k <= i; ++k) {
                    int val = (i + 1) * (k * k - sum_range(1, k) + sum_range(k+1, i) - k * (i - k));
                    auto term = mul_pair(mul_pair(mul_pair(dp[k-1][k-1], dp[i-k][i-k]), {C[i-1][k-1], 0}), {val % mod, 0});
                    dp[i][j].first = add(dp[i][j].first, term.first);
                    dp[i][j].second = add(dp[i][j].second, term.second);
                }
            }
        }
    }

    cout << dp[n][m].second << '\n';
    return 0;
}

