int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, mod;
    cin >> n >> m >> mod;

    const int N = 510;
    int C[N][N];
    int dp_f[N][N], dp_s[N][N];

    for (int i = 0; i < N; ++i) {
        fill(C[i], C[i] + N, 0);
        fill(dp_f[i], dp_f[i] + N, 0);
        fill(dp_s[i], dp_s[i] + N, 0);
    }

    for (int i = 0; i < N; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = C[i-1][j] + C[i-1][j-1];
            if (C[i][j] >= mod) C[i][j] -= mod;
        }
    }

    auto add_mod = [&](int a, int b) -> int {
        a += b;
        return a >= mod ? a - mod : a;
    };

    dp_f[0][0] = 1;
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= min(i, m); ++j) {
            if (j == 0) {
                dp_f[i][j] = 1;
                dp_s[i][j] = 0;
                continue;
            }

            if (i != j) {
                for (int k = 1; k <= i; ++k) {
                    int f1 = dp_f[k-1][k-1], s1 = dp_s[k-1][k-1];
                    int f2 = dp_f[i-k][j-k+1], s2 = dp_s[i-k][j-k+1];
                    int c = C[j][k-1];
                    int nf = (long long)f1 * f2 % mod * c % mod;
                    int ns = ((long long)f1 * s2 + (long long)s1 * f2) % mod * c % mod;
                    dp_f[i][j] = add_mod(dp_f[i][j], nf);
                    dp_s[i][j] = add_mod(dp_s[i][j], ns);
                }
            } else {
                for (int k = 1; k <= i; ++k) {
                    int f1 = dp_f[k-1][k-1], s1 = dp_s[k-1][k-1];
                    int f2 = dp_f[i-k][i-k], s2 = dp_s[i-k][i-k];
                    int c = C[i-1][k-1];
                    int sum1 = k * (k + 1) / 2;
                    int sum2 = (k + 1 + i) * (i - k) / 2;
                    int val = (i + 1) * (k * k - sum1 + sum2 - k * (i - k));
                    val %= mod;
                    if (val < 0) val += mod;
                    int nf = (long long)f1 * f2 % mod * c % mod * val % mod;
                    int ns = (((long long)f1 * s2 + (long long)s1 * f2) % mod * c % mod * val + (long long)f1 * f2 % mod * c % mod * k % mod) % mod;
                    dp_f[i][j] = add_mod(dp_f[i][j], nf);
                    dp_s[i][j] = add_mod(dp_s[i][j], ns);
                }
            }
        }
    }

    cout << dp_s[n][m] << '\n';
    return 0;
}

