struct ModFast {
    u64 mod, inv;
    void setup(u64 m) {
        mod = m;
        inv = (u64)((u128(1) << 64) / m);
    }
    u64 reduce(u64 a) const {
        u64 q = (u64)((u128(inv) * a) >> 64);
        u64 r = a - q * mod;
        return r >= mod ? r - mod : r;
    }
};

const int MAX = 505;
int MOD;
int C[MAX][MAX], f[MAX], g[MAX];
int d1[MAX][MAX], d2[MAX][MAX];

inline void add(int& x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
}

inline i64 tri(int x) { return 1LL * x * (x + 1) / 2; }

int main() {
