    ModFast M;
    M.setup(MOD);

    for (int i = 0; i < MAX; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = C[i - 1][j - 1];
            add(C[i][j], C[i - 1][j]);
        }
    }

    g[0] = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int tmp = C[i - 1][j - 1];
            u64 coef = M.reduce(M.reduce((u64)g[j - 1] * g[i - j]) * tmp);
            u64 term1 = M.reduce((u64)f[j - 1] * g[i - j] + (u64)g[j - 1] * f[i - j]);
            term1 = M.reduce(term1 * (i + 1));
            term1 = M.reduce(term1 * tmp);
            add(f[i], M.reduce(term1));
            add(f[i], M.reduce((tri(j - 1) + tri(i - j)) * coef));
            add(g[i], M.reduce(coef * (i + 1)));
        }
    }

    d2[0][0] = 1;
    for (int i = 0; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            add(d1[i + 1][j], d1[i][j]);
            add(d2[i + 1][j], d2[i][j]);
            for (int k = 1; i + k <= n && j + k <= m; ++k) {
                int tmp = C[j + k][j];
                add(d1[i + k + 1][j + k], M.reduce(M.reduce((u64)tmp * d1[i][j]) * g[k]));
                add(d1[i + k + 1][j + k], M.reduce(M.reduce((u64)tmp * d2[i][j]) * f[k]));
                add(d2[i + k + 1][j + k], M.reduce(M.reduce((u64)tmp * d2[i][j]) * g[k]));
