    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    return x;
}

struct ModReduction {
    u64 modulus, multiplier;
    void configure(u64 m) {
        modulus = m;
        multiplier = (u64)((u128(1) << 64) / m);
    }
    u64 apply(u64 x) const {
        u64 q = (u64)((u128(multiplier) * x) >> 64);
        u64 r = x - q * modulus;
        return r >= modulus ? r - modulus : r;
    }
};

const int MAX_SIZE = 505;
int MOD;
int binom[MAX_SIZE][MAX_SIZE];
int func_f[MAX_SIZE], func_g[MAX_SIZE];
int table1[MAX_SIZE][MAX_SIZE], table2[MAX_SIZE][MAX_SIZE];

inline void modular_add(int& target, int delta) {
    target += delta;
    if (target >= MOD) target -= MOD;
}

inline i64 triangular(int n) { return 1LL * n * (n + 1) / 2; }

int main() {
    int N = next_int(), M = next_int();
    MOD = next_int();
    ModReduction mr;
    mr.configure(MOD);

    for (int i = 0; i < MAX_SIZE; ++i) {
        binom[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            binom[i][j] = binom[i - 1][j - 1];
            modular_add(binom[i][j], binom[i - 1][j]);
        }
    }

    func_g[0] = 1;
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= i; ++j) {
            int comb = binom[i - 1][j - 1];
            u64 coef = mr.apply(mr.apply((u64)func_g[j - 1] * func_g[i - j]) * comb);
            u64 part1 = mr.apply((u64)func_f[j - 1] * func_g[i - j] + (u64)func_g[j - 1] * func_f[i - j]);
            part1 = mr.apply(part1 * (i + 1));
            part1 = mr.apply(part1 * comb);
            modular_add(func_f[i], mr.apply(part1));
            modular_add(func_f[i], mr.apply((triangular(j - 1) + triangular(i - j)) * coef));
            modular_add(func_g[i], mr.apply(coef * (i + 1)));
        }
    }

    table2[0][0] = 1;
    for (int i = 0; i <= N; ++i) {
        for (int j = 0; j <= M; ++j) {
            modular_add(table1[i + 1][j], table1[i][j]);
            modular_add(table2[i + 1][j], table2[i][j]);
            for (int k = 1; i + k <= N && j + k <= M; ++k) {
                int comb = binom[j + k][j];
                modular_add(table1[i + k + 1][j + k], mr.apply(mr.apply((u64)comb * table1[i][j]) * func_g[k]));
                modular_add(table1[i + k + 1][j + k], mr.apply(mr.apply((u64)comb * table2[i][j]) * func_f[k]));
                modular_add(table2[i + k + 1][j + k], mr.apply(mr.apply((u64)comb * table2[i][j]) * func_g[k]));
            }
        }
    }

    printf("%d\n", table1[N + 1][M]);
    return 0;
}

