    }
    auto fpow = [&](ll x, ll k) -> ll {
        ll res = 1, base = x % P;
        while (k) {
            if (k & 1) res = res * base % P;
            base = base * base % P;
            k >>= 1;
        }
        return res;
    };
    for (ll i = 1; i <= n + 1; ++i) {
        inv[i] = fpow(fac[i], P - 2);
    }

    auto C = [&](ll x, ll y) -> ll {
        if (x < y) return 0;
        return fac[x] * inv[y] % P * inv[x - y] % P;
    };

