    for (ll i = 1; i <= m; ++i) {
        for (ll j = 0; j < i; ++j) {
            ll term = f[j] * f[i - 1 - j] % P * C(i - 1, j) % P;
            f[i] = (f[i] + term) % P;

            ll inner = ((g[j] * f[i - 1 - j] % P + f[j] * g[i - 1 - j] % P) * (i + 1) % P 
                       + f[j] * f[i - 1 - j] % P * (S(j) + S(i - 1 - j)) % P) % P;
            g[i] = (g[i] + inner * C(i - 1, j) % P) % P;
        }
        f[i] = f[i] * (i + 1) % P;
    }

    vector<vector<ll>> F(m + 1, vector<ll>(n + 1, 0));
    vector<vector<ll>> G(m + 1, vector<ll>(n + 1, 0));

    F[0][0] = 1;
    for (ll j = 0; j <= n; ++j) F[0][j] = 1;

    for (ll i = 1; i <= m; ++i) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for (ll j = i + 1; j <= n; ++j) {
            F[i][j] = F[i][j-1];
            G[i][j] = G[i][j-1];
            for (ll l = 1; l <= i; ++l) {
                if (j - 1 - l >= 0) {
                    F[i][j] = (F[i][j] + F[i-l][j-1-l] * f[l] % P * C(i, l) % P) % P;
                    G[i][j] = (G[i][j] + (G[i-l][j-1-l] * f[l] % P + F[i-l][j-1-l] * g[l] % P) * C(i, l) % P) % P;
                }
            }
        }
