long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    long long n = readInt(), m = readInt(), P = readInt();

    vector<long long> fac(n + 2), inv(n + 2);
    fac[0] = inv[0] = 1;
    for (long long i = 1; i <= n + 1; ++i) {
        fac[i] = (fac[i-1] * i) % P;
    }
    for (long long i = 1; i <= n + 1; ++i) {
        inv[i] = modPow(fac[i], P - 2, P);
    }

    auto comb = [&](long long x, long long y) -> long long {
        if (x < y) return 0;
        return (fac[x] * inv[y] % P) * inv[x - y] % P;
    };

