    for (long long i = 1; i <= m; ++i) {
        for (long long j = 0; j < i; ++j) {
            long long base = f[j] * f[i - 1 - j] % P * comb(i - 1, j) % P;
            f[i] = (f[i] + base) % P;

            long long part1 = (g[j] * f[i - 1 - j] % P + f[j] * g[i - 1 - j] % P) * (i + 1) % P;
            long long part2 = f[j] * f[i - 1 - j] % P * (tri(j) + tri(i - 1 - j)) % P;
            long long inner = (part1 + part2) % P * comb(i - 1, j) % P;
            g[i] = (g[i] + inner) % P;
        }
        f[i] = f[i] * (i + 1) % P;
    }

    vector<vector<long long>> F(m + 1, vector<long long>(n + 1, 0));
    vector<vector<long long>> G(m + 1, vector<long long>(n + 1, 0));

    F[0][0] = 1;
    for (long long j = 0; j <= n; ++j) F[0][j] = 1;

    for (long long i = 1; i <= m; ++i) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for (long long j = i + 1; j <= n; ++j) {
            F[i][j] = F[i][j-1];
            G[i][j] = G[i][j-1];
            for (long long l = 1; l <= i; ++l) {
                if (j - 1 - l >= 0) {
                    F[i][j] = (F[i][j] + F[i-l][j-1-l] * f[l] % P * comb(i, l) % P) % P;
                    long long temp = (G[i-l][j-1-l] * f[l] % P + F[i-l][j-1-l] * g[l] % P) % P;
                    G[i][j] = (G[i][j] + temp * comb(i, l) % P) % P;
                }
            }
        }
    }

    cout << G[m][n] << endl;
    return 0;
}

