        x = x * 10 + ch - '0';
        ch = getchar();
    }
    return x * f;
}

inline ll mod_mul(ll a, ll b, ll mod) {
    return (a % mod) * (b % mod) % mod;
}

inline ll mod_pow(ll base, ll exp, ll mod) {
    ll res = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) res = mod_mul(res, base, mod);
        base = mod_mul(base, base, mod);
        exp >>= 1;
    }
    return res;
}

int main() {
    ll n = read(), m = read(), P = read();

    vector<ll> fac(n + 2), inv(n + 2);
    fac[0] = inv[0] = 1;

    for (ll i = 1; i <= n + 1; ++i) {
        fac[i] = mod_mul(fac[i-1], i, P);
    }

    for (ll i = 1; i <= n + 1; ++i) {
        inv[i] = mod_pow(fac[i], P - 2, P);
    }

    auto C = [&](ll x, ll y) -> ll {
        if (x < y) return 0;
        return mod_mul(mod_mul(fac[x], inv[y], P), inv[x - y], P);
    };

    auto S = [](ll x) -> ll {
        return x * (x + 1) / 2;
    };

    vector<ll> f(m + 1, 0), g(m + 1, 0);
    f[0] = 1;

    for (ll i = 1; i <= m; ++i) {
        for (ll j = 0; j < i; ++j) {
            ll term1 = mod_mul(f[j], f[i - 1 - j], P);
            term1 = mod_mul(term1, C(i - 1, j), P);
            f[i] = (f[i] + term1) % P;

            ll part1 = (mod_mul(g[j], f[i - 1 - j], P) + mod_mul(f[j], g[i - 1 - j], P)) % P;
            part1 = mod_mul(part1, i + 1, P);
            ll part2 = mod_mul(f[j], f[i - 1 - j], P);
            part2 = mod_mul(part2, (S(j) + S(i - 1 - j)) % P, P);
            ll inner = (part1 + part2) % P;
            inner = mod_mul(inner, C(i - 1, j), P);
            g[i] = (g[i] + inner) % P;
        }
        f[i] = mod_mul(f[i], i + 1, P);
    }

    vector<vector<ll>> F(m + 1, vector<ll>(n + 1, 0));
    vector<vector<ll>> G(m + 1, vector<ll>(n + 1, 0));

    F[0][0] = 1;
    for (ll j = 0; j <= n; ++j) F[0][j] = 1;

    for (ll i = 1; i <= m; ++i) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for (ll j = i + 1; j <= n; ++j) {
            F[i][j] = F[i][j-1];
            G[i][j] = G[i][j-1];
            for (ll l = 1; l <= i; ++l) {
                if (j - 1 - l >= 0) {
                    ll termF = mod_mul(F[i-l][j-1-l], f[l], P);
                    termF = mod_mul(termF, C(i, l), P);
                    F[i][j] = (F[i][j] + termF) % P;

                    ll termG1 = mod_mul(G[i-l][j-1-l], f[l], P);
                    ll termG2 = mod_mul(F[i-l][j-1-l], g[l], P);
                    ll innerG = (termG1 + termG2) % P;
                    innerG = mod_mul(innerG, C(i, l), P);
                    G[i][j] = (G[i][j] + innerG) % P;
                }
            }
        }
    }

    cout << G[m][n] << endl;
    return 0;
}

