    }
    return res;
}

int main() {
    i64 n = read(), m = read(), P = read();

    vector<i64> fac(n + 2), inv(n + 2);
    fac[0] = inv[0] = 1;

    for (i64 i = 1; i <= n + 1; ++i) {
        fac[i] = (fac[i-1] * i) % P;
    }

    for (i64 i = 1; i <= n + 1; ++i) {
        inv[i] = mod_pow(fac[i], P - 2, P);
    }

    auto comb = [&](i64 x, i64 y) -> i64 {
        if (x < y) return 0;
        return (fac[x] * inv[y] % P) * inv[x - y] % P;
    };

    auto tri = [](i64 x) -> i64 {
        return x * (x + 1) / 2;
    };

    vector<i64> f(m + 1, 0), g(m + 1, 0);
    f[0] = 1;

    for (i64 i = 1; i <= m; ++i) {
        for (i64 j = 0; j < i; ++j) {
            i64 term = f[j] * f[i - 1 - j] % P * comb(i - 1, j) % P;
            f[i] = (f[i] + term) % P;

            i64 part1 = (g[j] * f[i - 1 - j] % P + f[j] * g[i - 1 - j] % P) * (i + 1) % P;
            i64 part2 = f[j] * f[i - 1 - j] % P * (tri(j) + tri(i - 1 - j)) % P;
            i64 inner = (part1 + part2) % P * comb(i - 1, j) % P;
            g[i] = (g[i] + inner) % P;
        }
        f[i] = f[i] * (i + 1) % P;
    }

    vector<vector<i64>> F(m + 1, vector<i64>(n + 1, 0));
    vector<vector<i64>> G(m + 1, vector<i64>(n + 1, 0));

    F[0][0] = 1;
    for (i64 j = 0; j <= n; ++j) F[0][j] = 1;

    for (i64 i = 1; i <= m; ++i) {
        F[i][i] = f[i];
        G[i][i] = g[i];
        for (i64 j = i + 1; j <= n; ++j) {
            F[i][j] = F[i][j-1];
            G[i][j] = G[i][j-1];
            for (i64 l = 1; l <= i; ++l) {
                if (j - 1 - l >= 0) {
                    i64 termF = F[i-l][j-1-l] * f[l] % P * comb(i, l) % P;
                    F[i][j] = (F[i][j] + termF) % P;

                    i64 termG = (G[i-l][j-1-l] * f[l] % P + F[i-l][j-1-l] * g[l] % P) % P;
                    termG = termG * comb(i, l) % P;
                    G[i][j] = (G[i][j] + termG) % P;
                }
            }
        }
    }

    cout << G[m][n] << endl;
    return 0;
}

