lint fast_read() {
    lint num = 0;
    int c = getchar_unlocked();
    bool neg = false;
    while (c < '0' || c > '9') {
        if (c == '-') neg = true;
        c = getchar_unlocked();
    }
    while (c >= '0' && c <= '9') {
        num = num * 10 + c - '0';
        c = getchar_unlocked();
    }
    return neg ? -num : num;
}

lint mod_exp(lint base, lint exp, lint mod) {
    lint res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

