        for (int j = 1; j < i; ++j) {
            int k = i - j - 1;
            int comb = (int)mul(C[j + k][j], j + k + 2);
            inc(f[i], (int)mul(comb, (int)mul(f[j], f[k])));
            inc(g[i], (int)mul(comb, (int)mul(f[j], g[k])));
            inc(g[i], (int)mul(comb, (int)mul(g[j], f[k])));
            int w = j * (j + 1) / 2 + k * (k + 1) / 2;
            inc(g[i], (int)mul((int)mul(C[j + k][j], w), (int)mul(f[j], f[k])));
        }
    }

    array<array<array<int, 2>, MAX_N>, MAX_N> dp;
    fill(dp[0][0].begin(), dp[0][0].end(), 0);
    dp[0][0][0] = 1;

    for (int i = 0; i <= m; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int o = 0; o < 2; ++o) {
                int c = dp[i][j][o];
                if (!c) continue;

                if (!o) {
                    for (int k = 1; j + k <= m; ++k) {
                        inc(dp[i+1][j+k][0], (int)mul((int)mul(c, C[j+k][k]), f[k]));
                        inc(dp[i+1][j+k][1], (int)mul((int)mul(c, C[j+k][k]), g[k]));
                    }
                } else {
                    for (int k = 1; j + k <= m; ++k) {
                        inc(dp[i+1][j+k][1], (int)mul((int)mul(c, C[j+k][k]), f[k]));
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int i = 1; i <= m; ++i) {
        inc(ans, (int)mul(dp[i][m][1], C[n - m + 1][i]));
    }

    cout << ans << '\n';
    return 0;
}

