LL dp2[N][N], ways2[N][N];
LL dp0[N][N], ways0[N][N];
void add(LL &x,LL y){
	x=(x+y)%p;
}
LL cal(LL x){
	return 1LL*x*(x-1)/2 % p; 
}
int main() {
    cin>>n>>m>>p;
