#include <bits/stdc++.h>
using namespace std;
using lint = long long;
constexpr int MAX_SIZE = 510;

lint comb[MAX_SIZE][MAX_SIZE];
lint fn[MAX_SIZE], gn[MAX_SIZE];
lint state_dp[MAX_SIZE][MAX_SIZE], state_cnt[MAX_SIZE][MAX_SIZE];
lint temp_dp[MAX_SIZE][MAX_SIZE], temp_cnt[MAX_SIZE][MAX_SIZE];
lint prev_dp0[MAX_SIZE][MAX_SIZE], prev_cnt0[MAX_SIZE][MAX_SIZE];

int N, M, MOD;

void mod_inc(lint &x, lint y) {
    x = ((x + y) % MOD + MOD) % MOD;
}

lint triangle(lint x) {
    return ((x * (x - 1) / 2) % MOD + MOD) % MOD;
}

int main() {
    ios::sync_with_stdio(0); cin.tie(0);
    cin >> N >> M >> MOD;

    for (int i = 0; i < MAX_SIZE; ++i) comb[i][0] = 1;
    for (int i = 1; i < MAX_SIZE; ++i) {
        for (int j = i; j >= 1; --j) {
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD;
        }
    }

    fn[0] = 0; gn[0] = 1;
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= i; ++j) {
            lint contrib = comb[i-1][j-1];
            lint part1 = contrib * fn[j-1] % MOD * gn[i-j] % MOD * (i + 1) % MOD;
            lint part2 = contrib * gn[j-1] % MOD * fn[i-j] % MOD * (i + 1) % MOD;
            lint part3 = contrib * gn[j-1] % MOD * gn[i-j] % MOD * ((triangle(j) + triangle(i - j + 1)) % MOD) % MOD;
            mod_inc(fn[i], part1 + part2 + part3);
            mod_inc(gn[i], contrib * gn[j-1] % MOD * gn[i-j] % MOD * (i + 1) % MOD);
        }
    }

    state_dp[0][0] = 0; state_cnt[0][0] = 1;

    for (int layer = 0; layer < N; ++layer) {
        memset(temp_dp, 0, sizeof(temp_dp));
        memset(temp_cnt, 0, sizeof(temp_cnt));
        for (int j = 0; j <= min(layer, M); ++j) {
            for (int k = 0; k <= min(j, M); ++k) {
                if (k == 0) {
                    prev_dp0[layer][j] = state_dp[j][0];
                    prev_cnt0[layer][j] = state_cnt[j][0];
                }
                mod_inc(temp_dp[j][0], state_dp[j][k]);
                mod_inc(temp_cnt[j][0], state_cnt[j][k]);
                int unused = M - (j - k);
                lint coeff1 = prev_cnt0[layer - k][j - k] * comb[unused][k + 1] % MOD * gn[k + 1] % MOD;
                lint coeff2 = prev_dp0[layer - k][j - k] * comb[unused][k + 1] % MOD * gn[k + 1] % MOD;
                lint coeff3 = prev_cnt0[layer - k][j - k] * comb[unused][k + 1] % MOD * fn[k + 1] % MOD;
                mod_inc(temp_cnt[j + 1][k + 1], coeff1);
                mod_inc(temp_dp[j + 1][k + 1], coeff2 + coeff3);
            }
        }
        memcpy(state_dp, temp_dp, sizeof(state_dp));
        memcpy(state_cnt, temp_cnt, sizeof(state_cnt));
    }

    lint result = 0;
    for (int i = 0; i <= M; ++i) {
        mod_inc(result, state_dp[M][i]);
    }
    cout << result << endl;
    return 0;
}

