        }
    }

    F[0] = 0; G[0] = 1;
    for (int i = 1; i <= M; ++i) {
        for (int j = 1; j <= i; ++j) {
            i64 c = C[i-1][j-1];
            i64 term = c * ((c * G[j-1] % MOD * G[i-j] % MOD * ((tri(j) + tri(i-j+1)) % MOD) % MOD)
                    + (c * F[j-1] % MOD * G[i-j] % MOD * (i+1) % MOD)
                    + (c * G[j-1] % MOD * F[i-j] % MOD * (i+1) % MOD)) % MOD;
            add(F[i], term);
            add(G[i], c * G[j-1] % MOD * G[i-j] % MOD * (i+1) % MOD);
        }
    }

