                    DP0[idx][j] = DP[j][0];
                    W0[idx][j] = W[j][0];
                }
                add(ND[j][0], DP[j][k]);
                add(NW[j][0], W[j][k]);
                int r = M - (j - k);
                i64 coef = W0[idx - k][j - k] * C[r][k+1] % MOD;
                add(NW[j+1][k+1], coef * G[k+1] % MOD);
                add(ND[j+1][k+1], DP0[idx - k][j - k] * coef % MOD * G[k+1] % MOD + W0[idx - k][j - k] * C[r][k+1] % MOD * F[k+1] % MOD);
            }
        }
        memcpy(DP, ND, sizeof(DP));
        memcpy(W, NW, sizeof(W));
    }

    i64 ans = 0;
    for (int i = 0; i <= M; ++i) {
        add(ans, DP[M][i]);
