    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n_in >> m_in >> M_in;

    // Fill binomial coefficients
    for (int i = 0; i < MAX_SIZE; ++i) {
        binom[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            binom[i][j] = (binom[i-1][j] + binom[i-1][j-1]) % M_in;
        }
    }

    // Fill power table
    for (int i = 0; i < MAX_SIZE; ++i) {
        power[i][0] = 1;
        for (int j = 1; j < MAX_SIZE; ++j) {
            power[i][j] = (power[i][j-1] * i) % M_in;
        }
    }

    // Accumulate results
    for (int i = 2; i <= m_in; ++i) {
        for (int d = 1; d < i; ++d) {
            me_term = d * (d + 1) / 2;
            me_term %= M_in;
            me_term = (me_term * binom[i-1][d]) % M_in;
            me_term = (me_term * power[d+1][d-1]) % M_in;
            me_term = (me_term * helper(n_in + 1 - (d + 1) - 1, i - (d + 1))) % M_in;
            me_term = (me_term * power[2][d]) % M_in;
            me_term = (me_term * power[n_in + 1][m_in - i]) % M_in;
            me_term = (me_term * power[2][m_in - i]) % M_in;

            you_term = (you_term + me_term + me_term) % M_in;
        }
    }

    ll residual = (n_in + 1 - m_in) % M_in;
    if (residual < 0) residual += M_in;
    ll output = (you_term * residual) % M_in;
    if (output < 0) output += M_in;

    cout << output << '\n';

    return 0;
}

