int MOD;

int comb(int n, int k, const vector<vector<int>>& C) {
    if (k < 0 || k > n) return 0;
    return C[n][k];
}

int main() {
    int n, m;
    cin >> n >> m >> MOD;

    vector<vector<int>> C(n + 1, vector<int>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i-1][j] + C[i-1][j-1]) % MOD;
        }
    }

    vector<pair<int, int>> dp1(n + 1, {0, 0});
    dp1[0] = {1, 0};

    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int w = (ll)dp1[j-1].first * dp1[i-j].first % MOD * comb(i-1, j-1, C) % MOD;
            int tri_sum = (j-1)*j/2 + (i-j)*(i-j+1)/2;
            int term1 = (ll)tri_sum * w % MOD;
            int term2 = (ll)dp1[j-1].second * dp1[i-j].first % MOD * (i+1) % MOD * comb(i-1, j-1, C) % MOD;
            int term3 = (ll)dp1[j-1].first * dp1[i-j].second % MOD * (i+1) % MOD * comb(i-1, j-1, C) % MOD;

            dp1[i].second = (dp1[i].second + term1 + term2 + term3) % MOD;
            dp1[i].first = (dp1[i].first + (ll)w * (i+1) % MOD) % MOD;
        }
    }

    vector<vector<pair<int, int>>> dp2_cur(n + 1, vector<pair<int, int>>(n + 1, {0, 0}));
    vector<vector<pair<int, int>>> dp2_nxt(n + 1, vector<pair<int, int>>(n + 1, {0, 0}));

    dp2_cur[0][0] = {1, 0};
    dp2_nxt[0][0] = {1, 0};

    for (int i = 0; i < n; ++i) {
        fill(dp2_nxt.begin(), dp2_nxt.end(), vector<pair<int, int>>(n + 1, {0, 0}));

        for (int j = 0; j <= i; ++j) {
            for (int ln = 1; ln <= n - i; ++ln) {
                dp2_nxt[i + ln][j].first = (dp2_nxt[i + ln][j].first + dp2_cur[i][j].first) % MOD;
                dp2_nxt[i + ln][j].second = (dp2_nxt[i + ln][j].second + dp2_cur[i][j].second) % MOD;

                int coef1 = (ll)dp2_nxt[i][j].first * dp1[ln].first % MOD * comb(j + ln, j, C) % MOD;
                dp2_cur[i + ln][j + ln].first = (dp2_cur[i + ln][j + ln].first + coef1) % MOD;

                int coef2 = (ll)dp2_nxt[i][j].first * dp1[ln].second % MOD * comb(j + ln, j, C) % MOD;
                dp2_cur[i + ln][j + ln].second = (dp2_cur[i + ln][j + ln].second + coef2) % MOD;

                int coef3 = (ll)dp2_nxt[i][j].second * dp1[ln].first % MOD * comb(j + ln, j, C) % MOD;
                dp2_cur[i + ln][j + ln].second = (dp2_cur[i + ln][j + ln].second + coef3) % MOD;
            }
        }
        swap(dp2_cur, dp2_nxt);
    }

    int ans = (dp2_cur[n][m].second + dp2_nxt[n][m].second) % MOD;
    cout << ans << endl;
}

