using ll = long long;

int MOD;

int main() {
    int n, m;
    cin >> n >> m >> MOD;

    vector<vector<int>> C(n + 1, vector<int>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i-1][j] + C[i-1][j-1]) % MOD;
        }
    }

    vector<pair<int, int>> dp1(n + 1);
    dp1[0] = make_pair(1, 0);

    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int w = (ll)dp1[j-1].first * dp1[i-j].first % MOD;
            w = (ll)w * C[i-1][j-1] % MOD;
            int tri_sum = (j-1)*j/2 + (i-j)*(i-j+1)/2;
            int term1 = (ll)tri_sum * w % MOD;
            int term2 = (ll)dp1[j-1].second * dp1[i-j].first % MOD;
            term2 = (ll)term2 * (i+1) % MOD;
            term2 = (ll)term2 * C[i-1][j-1] % MOD;
            int term3 = (ll)dp1[j-1].first * dp1[i-j].second % MOD;
            term3 = (ll)term3 * (i+1) % MOD;
            term3 = (ll)term3 * C[i-1][j-1] % MOD;

            dp1[i].second = (dp1[i].second + term1 + term2 + term3) % MOD;
            dp1[i].first = (dp1[i].first + (ll)w * (i+1) % MOD) % MOD;
        }
    }

    vector<vector<pair<int, int>>> dp2_0(n + 1, vector<pair<int, int>>(n + 1, make_pair(0, 0)));
    vector<vector<pair<int, int>>> dp2_1(n + 1, vector<pair<int, int>>(n + 1, make_pair(0, 0)));
    dp2_0[0][0] = dp2_1[0][0] = make_pair(1, 0);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            for (int ln = 1; ln <= n - i; ++ln) {
                dp2_1[i + ln][j].first = (dp2_1[i + ln][j].first + dp2_0[i][j].first) % MOD;
                dp2_1[i + ln][j].second = (dp2_1[i + ln][j].second + dp2_0[i][j].second) % MOD;

                int coef1 = (ll)dp2_1[i][j].first * dp1[ln].first % MOD;
                coef1 = (ll)coef1 * C[j + ln][j] % MOD;
                dp2_0[i + ln][j + ln].first = (dp2_0[i + ln][j + ln].first + coef1) % MOD;

                int coef2 = (ll)dp2_1[i][j].first * dp1[ln].second % MOD;
                coef2 = (ll)coef2 * C[j + ln][j] % MOD;
                dp2_0[i + ln][j + ln].second = (dp2_0[i + ln][j + ln].second + coef2) % MOD;

                int coef3 = (ll)dp2_1[i][j].second * dp1[ln].first % MOD;
                coef3 = (ll)coef3 * C[j + ln][j] % MOD;
                dp2_0[i + ln][j + ln].second = (dp2_0[i + ln][j + ln].second + coef3) % MOD;
            }
        }
    }

    int ans = (dp2_0[n][m].second + dp2_1[n][m].second) % MOD;
    cout << ans << endl;
}

