    for (int i = 0; i <= N; i++) {
        choose[i][0] = choose[i][i] = 1;
        for (int j = 1; j < i; j++) {
            choose[i][j] = (choose[i-1][j-1] + choose[i-1][j]) % P;
        }
    }

    // First DP arrays
    vector<ll> dp1(N+1, 0), dpw(N+1, 0);
    dp1[0] = 0;
    dpw[0] = 1;

    for (int m = 1; m <= M; m++) {
        for (int i = 0; i < m; i++) {
            ll w = dpw[i] * dpw[m-1-i] % P;
            w = w * choose[m-1][i] % P;
            dpw[m] = (dpw[m] + w * (m + 1)) % P;

            ll s1 = dp1[i] * dpw[m-1-i] % P;
            ll s2 = dp1[m-1-i] * dpw[i] % P;
            ll add = ((s1 + s2) % P * (m + 1) % P * choose[m-1][i]) % P;
            add = (add + w * ((i*(i+1) + (m-1-i)*(m-i))/2) % P) % P;
            dp1[m] = (dp1[m] + add) % P;
        }
    }

    // Second DP arrays
    vector<vll> dp(N+1, vll(N+1, 0)), dps(N+1, vll(N+1, 0));
    dps[0][0] = 1;

    for (int i = 1; i <= N; i++) {
