        for (int j = 1; j < i; j++) {
            dp[i][j] = dp[i-1][j];
            dps[i][j] = dps[i-1][j];

            for (int k = 1; k <= j; k++) {
                dps[i][j] = (dps[i][j] + dpw[k] * dps[i-k-1][j-k] % P * choose[j][k]) % P;
                ll add = (dp[i-k-1][j-k] * dpw[k] % P + dps[i-k-1][j-k] * dp1[k] % P) % P;
                dp[i][j] = (dp[i][j] + add * choose[j][k] % P) % P;
            }
        }
    }

    cout << (dp[N][M] % P + P) % P << '\n';
    return 0;
}

