using namespace std;

const int MAX_SIZE = 510;

int M, N, MOD;

inline int add(int x, int y) {
    long long res = (long long)x + y;
    return (int)(res % MOD);
}

inline int subtract(int x, int y) {
    int res = x - y;
    if (res < 0) res += MOD;
    return res;
}

inline int multiply(int x, int y) {
    return (int)((long long)x * y % MOD);
}

int fact[MAX_SIZE], inv_fact[MAX_SIZE], inv[MAX_SIZE];

void init(int n) {
    fact[0] = inv[1] = fact[1] = inv_fact[0] = inv_fact[1] = 1;
    for (int i = 2; i <= n; ++i) {
        inv[i] = multiply(MOD - MOD / i, inv[MOD % i]);
    }
    for (int i = 2; i <= n; ++i) {
        fact[i] = multiply(fact[i - 1], i);
        inv_fact[i] = multiply(inv_fact[i - 1], inv[i]);
    }
}

inline int binomial(int n, int k) {
    if (n < k || k < 0) return 0;
    return multiply(multiply(fact[n], inv_fact[k]), inv_fact[n - k]);
}

inline int combinations_with_repetition(int n, int k) {
    return binomial(n + k - 1, k - 1);
}

int f_arr[MAX_SIZE], g_arr[MAX_SIZE], prefix[MAX_SIZE];
