    g_arr[0] = 0;
    g_arr[1] = 0;

    for (int i = 2; i <= N; ++i) {
        for (int j = 0; j < i; ++j) {
            int temp = multiply(binomial(i - 1, j), multiply(f_arr[j], f_arr[i - 1 - j]));
            f_arr[i] = add(f_arr[i], multiply(temp, i + 1));
            g_arr[i] = add(g_arr[i], multiply(temp, add(prefix[j], prefix[i - 1 - j])));

            temp = multiply(add(multiply(g_arr[j], f_arr[i - 1 - j]), multiply(g_arr[i - 1 - j], f_arr[j])), i + 1);
            g_arr[i] = add(g_arr[i], multiply(temp, binomial(i - 1, j)));
        }
    }

    memset(dp_f, 0, sizeof(dp_f));
    memset(dp_g, 0, sizeof(dp_g));
    dp_f[0][0] = 1;
    dp_g[0][0] = 0;

    for (int i = 0; i <= M; ++i) {
        for (int j = 0; j <= M; ++j) {
            if (!dp_f[i][j]) continue;
            for (int k = 1; j + k <= M; ++k) {
                int c = binomial(j + k, k);
                dp_f[i + 1][j + k] = add(dp_f[i + 1][j + k], multiply(multiply(dp_f[i][j], f_arr[k]), c));
                dp_g[i + 1][j + k] = add(dp_g[i + 1][j + k], multiply(add(multiply(dp_g[i][j], f_arr[k]), multiply(dp_f[i][j], g_arr[k])), c));
            }
        }
    }

    int ans = 0;
    for (int i = 1; i <= M; ++i) {
        if (N + 1 - M >= i) {
            ans = add(ans, multiply(dp_g[i][M], combinations_with_repetition(N + 1 - M - i, i + 1)));
        }
    }

