                gg[i + 1][j + k] = add(gg[i + 1][j + k], mul(add(mul(gg[i][j], f[k]), mul(ff[i][j], g[k])), c));
            }
        }
    }

    int res = 0;
    for (int i = 1; i <= M; ++i) {
        if (N + 1 - M >= i) {
            res = add(res, mul(gg[i][M], P(N + 1 - M - i, i + 1)));
        }
    }

    cout << res << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 510;

int M, N, MOD;

inline int add(int x, int y) {
    return (x + y) % MOD;
}

inline int sub(int x, int y) {
    return (x - y + MOD) % MOD;
}

inline int mul(int x, int y) {
    return (int)((1LL * x * y) % MOD);
}

int fact[MAXN], inv[MAXN], invfact[MAXN];

void precompute(int n) {
    fact[0] = inv[1] = fact[1] = invfact[0] = invfact[1] = 1;
    for (int i = 2; i <= n; ++i) {
        inv[i] = mul(MOD - MOD / i, inv[MOD % i]);
    }
    for (int i = 2; i <= n; ++i) {
        fact[i] = mul(fact[i - 1], i);
        invfact[i] = mul(invfact[i - 1], inv[i]);
    }
}

inline int comb(int n, int k) {
    if (n < k || k < 0) return 0;
    return mul(mul(fact[n], invfact[k]), invfact[n - k]);
}

inline int stars_bars(int n, int k) {
    return comb(n + k - 1, k - 1);
}

int f[MAXN], g[MAXN], prefix[MAXN];
int dp_f[MAXN][MAXN], dp_g[MAXN][MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M >> MOD;
    precompute(500);

    for (int i = 1; i <= N; ++i) {
        prefix[i] = add(prefix[i - 1], i);
    }

    f[0] = 1;
    f[1] = 2;
    g[0] = 0;
    g[1] = 0;

    for (int i = 2; i <= N; ++i) {
        for (int j = 0; j < i; ++j) {
            int temp = mul(comb(i - 1, j), mul(f[j], f[i - 1 - j]));
            f[i] = add(f[i], mul(temp, i + 1));
            g[i] = add(g[i], mul(temp, add(prefix[j], prefix[i - 1 - j])));

            temp = mul(add(mul(g[j], f[i - 1 - j]), mul(g[i - 1 - j], f[j])), i + 1);
            g[i] = add(g[i], mul(temp, comb(i - 1, j)));
        }
    }

    dp_f[0][0] = 1;
    dp_g[0][0] = 0;

    for (int i = 0; i <= M; ++i) {
        for (int j = 0; j <= M; ++j) {
            if (!dp_f[i][j]) continue;
            for (int k = 1; j + k <= M; ++k) {
                int c = comb(j + k, k);
                dp_f[i + 1][j + k] = add(dp_f[i + 1][j + k], mul(mul(dp_f[i][j], f[k]), c));
                dp_g[i + 1][j + k] = add(dp_g[i + 1][j + k], mul(add(mul(dp_g[i][j], f[k]), mul(dp_f[i][j], g[k])), c));
            }
        }
    }

    int result = 0;
    for (int i = 1; i <= M; ++i) {
        if (N + 1 - M >= i) {
            result = add(result, mul(dp_g[i][M], stars_bars(N + 1 - M - i, i + 1)));
        }
    }

    cout << result << '\n';
    return 0;
}

