            cnt[i] = (cnt[i] + tmp * j) % p;
            dp[i] = (dp[i] + tmp * SUM(i - j) % p + zh * (i - j + 1) % p * (dp[j - 1] * cnt[i - j] % p + dp[i - j] * cnt[j - 1] % p) % p) % p;
            cnt[i] = (cnt[i] + tmp * (i - j + 1)) % p;
        }
