using int64 = long long;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, MOD;
    cin >> n >> m >> MOD;

    vector<int64> dp(505, 0), cnt(505, 0), fac(505, 1), invfac(505, 1);
    vector<vector<int64>> dp2(505, vector<int64>(505, 0)), tot(505, vector<int64>(505, 0));

    // Compute factorials and inverse factorials modulo MOD
    for (int i = 1; i <= 500; ++i) {
        fac[i] = fac[i-1] * i % MOD;
    }

    // Modular exponentiation for inverse factorial[500]
    auto binpow = [](int64 base, int64 exp, int mod) -> int64 {
        int64 res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    };

    invfac[500] = binpow(fac[500], MOD - 2, MOD);
    for (int i = 499; i >= 0; --i) {
        invfac[i] = invfac[i+1] * (i + 1) % MOD;
    }

    auto comb = [&](int nn, int mm) -> int64 {
        if (mm < 0 || mm > nn) return 0;
        return fac[nn] * invfac[mm] % MOD * invfac[nn - mm] % MOD;
    };

    auto tri = [&](int x) -> int64 {
        return (int64)x * (x + 1) / 2 % MOD;
    };

    cnt[0] = 1; dp[0] = 0;
    cnt[1] = 2; dp[1] = 0;

    for (int i = 2; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int64 zh = comb(i - 1, j - 1);
            int64 tmp = cnt[j - 1] * cnt[i - j] % MOD * zh % MOD;

            dp[i] = (dp[i] + tmp * tri(j - 1)) % MOD;
            dp[i] = (dp[i] + zh * j % MOD * (dp[j - 1] * cnt[i - j] % MOD + dp[i - j] * cnt[j - 1] % MOD)) % MOD;

            cnt[i] = (cnt[i] + tmp * j) % MOD;

            dp[i] = (dp[i] + tmp * tri(i - j)) % MOD;
            dp[i] = (dp[i] + zh * (i - j + 1) % MOD * (dp[j - 1] * cnt[i - j] % MOD + dp[i - j] * cnt[j - 1] % MOD)) % MOD;

            cnt[i] = (cnt[i] + tmp * (i - j + 1)) % MOD;
        }
    }

    dp2[0][0] = 0; tot[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= min(m, i); ++j) {
            dp2[i][j] = dp2[i-1][j];
            tot[i][j] = tot[i-1][j];

            for (int k = 1; k <= j; ++k) {
                if (k < i) {
                    int64 zh = comb(j, k);
                    dp2[i][j] = (dp2[i][j] + dp[k] * zh % MOD * tot[i - k - 1][j - k]) % MOD;
                    dp2[i][j] = (dp2[i][j] + dp2[i - k - 1][j - k] * zh % MOD * cnt[k]) % MOD;

                    tot[i][j] = (tot[i][j] + cnt[k] * tot[i - k - 1][j - k] % MOD * zh) % MOD;
                } else {
                    dp2[i][j] = (dp2[i][j] + dp[i]) % MOD;
                    tot[i][j] = (tot[i][j] + cnt[i]) % MOD;
                }
            }
        }
    }

    cout << ((dp2[n][m] % MOD) + MOD) % MOD << '\n';
    return 0;
}

