            dp[len] = (dp[len] + dp[i - 1] * 1LL * cnt % Mod * dp[len - i] % Mod * C[i - 1][len - 1]) % Mod;
            dp2[len] = (dp2[len] + sm * 1LL * dp[i - 1] % Mod % Mod * dp[len - i] % Mod * C[i - 1][len - 1]) % Mod;
            dp2[len] = (dp2[len] + dp2[i - 1] * 1LL * cnt % Mod * dp[len - i] % Mod * C[i - 1][len - 1]) % Mod;
