#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 577;
int n, m, MOD;
int dp[MAX_N], dp2[MAX_N];
int comb[MAX_N][MAX_N];
int res[MAX_N][MAX_N], res2[MAX_N][MAX_N];

inline int sumRange(int l, int r) {
    if (l > r) return 0;
    long long t = (long long)(l + r) * (r - l + 1) / 2;
    return (int)(t % MOD);
}

int main() {
    scanf("%d%d%d", &n, &m, &MOD);

    // Precompute binomial coefficients
    for (int i = 0; i < MAX_N; ++i) {
        comb[i][0] = comb[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            comb[j][i] = (comb[j][i-1] + comb[j-1][i-1]) % MOD;
        }
    }

    dp[0] = 1;
    dp2[0] = 0;

    // DP for dp[len] and dp2[len]
    for (int len = 1; len <= n; ++len) {
        for (int i = 1; i <= len; ++i) {
            int leftSum = sumRange(1, i - 1);
            int rightSum = sumRange(1, len - i);
            int totalSum = (leftSum + rightSum) % MOD;
            int count = len + 1;

            long long term1 = (long long)dp[i-1] * count % MOD;
            term1 = term1 * dp[len-i] % MOD;
            term1 = term1 * comb[i-1][len-1] % MOD;
            dp[len] = (dp[len] + (int)term1) % MOD;

            long long term2 = (long long)totalSum * dp[i-1] % MOD;
            term2 = term2 * dp[len-i] % MOD;
            term2 = term2 * comb[i-1][len-1] % MOD;
            dp2[len] = (dp2[len] + (int)term2) % MOD;

            long long term3 = (long long)dp2[i-1] * count % MOD;
            term3 = term3 * dp[len-i] % MOD;
            term3 = term3 * comb[i-1][len-1] % MOD;
            dp2[len] = (dp2[len] + (int)term3) % MOD;

            long long term4 = (long long)dp2[len-i] * count % MOD;
            term4 = term4 * dp[i-1] % MOD;
            term4 = term4 * comb[i-1][len-1] % MOD;
            dp2[len] = (dp2[len] + (int)term4) % MOD;
        }
    }

    // Compute res and res2
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m && j <= i; ++j) {
            res[i][j] = res[i-1][j];
            res2[i][j] = res2[i-1][j];

            for (int h = 1; h < j; ++h) {
                long long term5 = (long long)res[i-h-1][j-h] * dp[h] % MOD;
                term5 = term5 * comb[h][j] % MOD;
                res[i][j] = (res[i][j] + (int)term5) % MOD;

                long long term6 = (long long)res2[i-h-1][j-h] * dp[h] % MOD;
                term6 = term6 * comb[h][j] % MOD;
                res2[i][j] = (res2[i][j] + (int)term6) % MOD;

                long long term7 = (long long)res[i-h-1][j-h] * dp2[h] % MOD;
                term7 = term7 * comb[h][j] % MOD;
                res2[i][j] = (res2[i][j] + (int)term7) % MOD;
            }

            res[i][j] = (res[i][j] + dp[j]) % MOD;
            res2[i][j] = (res2[i][j] + dp2[j]) % MOD;
        }
    }

    printf("%d\n", res2[n][m]);
    return 0;
}

