#include <bits/stdc++.h>
using namespace std;

using i64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, mod;
    cin >> n >> m >> mod;
    int Mod = mod - 2;

    vector<i64> jc(n + 1), Jc(n + 1);
    vector<i64> f(m + 1), g(m + 1);
    vector<vector<i64>> C(n + 1, vector<i64>(n + 1, 0));
    vector<vector<vector<i64>>> h(m + 2, vector<vector<i64>>(m + 1, vector<i64>(2, 0)));

    jc[0] = 1;
    for (int i = 1; i <= n; i++) jc[i] = jc[i-1] * i % mod;

    auto modPow = [&](i64 base, int exp) -> i64 {
        i64 result = 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    };

    Jc[n] = modPow(jc[n], Mod);
    for (int i = n - 1; i >= 0; i--) {
        Jc[i] = Jc[i + 1] * (i + 1) % mod;
    }

    C[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % mod;
        }
    }

    f[0] = 1;
    g[0] = 0;
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= i; j++) {
            i64 s = (i64)j * (j - 1) / 2 + (i64)(i - j + 1) * (i - j) / 2;
            s %= mod;
            f[i] = (f[i] + f[j-1] * f[i-j] % mod * (i + 1) % mod * C[i-1][j-1]) % mod;
            i64 term1 = (g[j-1] * f[i-j] + f[j-1] * g[i-j]) % mod;
            term1 = term1 * (i + 1) % mod;
            i64 term2 = f[j-1] * f[i-j] % mod * s % mod;
            g[i] = (g[i] + (term1 + term2) % mod * C[i-1][j-1]) % mod;
        }
    }

    h[0][0][0] = 1;
    int bound = min(m, n - m + 1);
    for (int i = 0; i < bound; i++) {
        for (int j = 0; j < m; j++) {
            for (int k = 1; k <= m - j; k++) {
                i64 F = f[k] * C[j + k][j] % mod;
                h[i + 1][j + k][0] = (h[i + 1][j + k][0] + h[i][j][0] * F) % mod;
                h[i + 1][j + k][1] = (h[i + 1][j + k][1] + h[i][j][1] * F) % mod;
                h[i + 1][j + k][1] = (h[i + 1][j + k][1] + h[i][j][0] * g[k] % mod * C[j + k][j]) % mod;
            }
        }
    }

    i64 ans = 0;
    for (int i = 1; i <= bound; i++) {
        ans = (ans + h[i][m][1] * C[n - m + 1][i]) % mod;
    }
    ans = (ans % mod + mod) % mod;

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const int MAXN = 505;

int main() {
    int n, m, mod;
    cin >> n >> m >> mod;
    int Mod = mod - 2;

    vector<ll> jc(MAXN), Jc(MAXN);
    vector<ll> f(MAXN), g(MAXN);
    vector<vector<ll>> C(MAXN, vector<ll>(MAXN));
    vector<vector<vector<ll>>> h(MAXN, vector<vector<ll>>(MAXN, vector<ll>(2)));

    // Compute factorials
    jc[0] = 1;
    for (int i = 1; i <= n; ++i) jc[i] = jc[i-1] * i % mod;

    // Compute inverse factorials using binary exponentiation
    ll inv = 1, base = jc[n];
    int exp = Mod;
    while (exp > 0) {
        if (exp & 1) inv = inv * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    Jc[n] = inv;
    for (int i = n-1; i >= 0; --i) {
        Jc[i] = Jc[i+1] * (i+1) % mod;
    }

    // Compute binomial coefficients
    C[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % mod;
        }
    }

    // DP arrays f and g
    f[0] = 1;
    g[0] = 0;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            ll s = (ll)j * (j-1) / 2 + (ll)(i - j + 1) * (i - j) / 2;
            s %= mod;
            f[i] = (f[i] + f[j-1] * f[i-j] % mod * (i+1) % mod * C[i-1][j-1]) % mod;
            ll temp = ((g[j-1] * f[i-j] % mod + f[j-1] * g[i-j]) % mod * (i+1) % mod + f[j-1] * f[i-j] % mod * s) % mod;
            g[i] = (g[i] + temp * C[i-1][j-1]) % mod;
        }
    }

    // 3D DP array h
    h[0][0][0] = 1;
    int lim = min(m, n - m + 1);
    for (int i = 0; i < lim; ++i) {
        for (int j = 0; j < m; ++j) {
            for (int k = 1; k <= m - j; ++k) {
                ll F = f[k] * C[j+k][j] % mod;
                h[i+1][j+k][0] = (h[i+1][j+k][0] + h[i][j][0] * F) % mod;
                h[i+1][j+k][1] = (h[i+1][j+k][1] + h[i][j][1] * F) % mod;
                h[i+1][j+k][1] = (h[i+1][j+k][1] + h[i][j][0] * g[k] % mod * C[j+k][j]) % mod;
            }
        }
    }

    // Compute final answer
    ll ans = 0;
    for (int i = 1; i <= lim; ++i) {
        ans = (ans + h[i][m][1] * C[n-m+1][i]) % mod;
    }
    ans = (ans % mod + mod) % mod;

    cout << ans << '\n';
    return 0;
}

