int M;
int spow(int a, int b) {
  int r = 1;
  while (b) {
    if (b % 2) {
      r = r * a % M;
    }
    a = a * a % M;
    b /= 2;
  }
  return r;
}
int Inv(int a) {
  int b = M - 2;
  int r = 1;
  while (b) {
    if (b % 2) {
      r = r * a % M;
    }
    a = a * a % M;
    b /= 2;
  }
  return r;
}
int f(int c, int p) {
  if (p == 0) { return 1; }
  return spow(c + 1, p - 1) * (c + 1 - p) % M;
}
