int main() {
    scanf("%d %d %d", &n, &m, &M);

    f[0] = 1 % M;

    // Precompute binomial coefficients modulo M
    for (i = 0; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (j = 1; j < i; ++j)
            C[i][j] = (C[i-1][j] + C[i-1][j-1]) % M;
    }

    // Compute f[i] and dp[i]
    for (i = 1; i <= n; ++i) {
        for (j = 1; j <= i; ++j) {
            ll term = f[j-1] * f[i-j] % M;
            term = term * C[i-1][j-1] % M;
            term = term * (i + 1) % M;
            f[i] = (f[i] + term) % M;

            // Compute sum of absolute differences
            int s = 0;
            for (k = 1; k <= i; ++k)
                s += abs(k - j);

            // Update dp[i]
            ll part1 = dp[j-1] * f[i-j] % M * C[i-1][j-1] % M * (i + 1) % M;
            ll part2 = f[j-1] * dp[i-j] % M * C[i-1][j-1] % M * (i + 1) % M;
            ll part3 = (ll)s * f[j-1] % M * f[i-j] % M * C[i-1][j-1] % M;
            dp[i] = (dp[i] + part1 + part2 + part3) % M;
        }
    }

    // Initialize fd table
    fd[0][0] = 1;

    // Fill fd and d tables
    for (i = 1; i <= n; ++i) {
        for (j = 0; j <= min(m, i); ++j) {
            fd[i][j] = fd[i-1][j];
            d[i][j] = d[i-1][j];

            for (k = 1; k <= j; ++k) {
                ll temp_fd = (i - k - 1 >= 0) ? fd[i-k-1][j-k] : 1;
                ll temp_d = (i - k - 1 >= 0) ? d[i-k-1][j-k] : 0;

                ll term_fd = temp_fd * f[k] % M * C[j][k] % M;
                fd[i][j] = (fd[i][j] + term_fd) % M;

                ll term_d = (temp_fd * dp[k] % M + temp_d * f[k] % M) % M * C[j][k] % M;
                d[i][j] = (d[i][j] + term_d) % M;
            }
        }
    }

    ll result = (d[n][m] % M + M) % M;
    cout << result;
}

