    memset(C, 0, sizeof(C));

    f[0] = 1 % M;

    // Pascal's triangle for binomial coefficients
    for (int i = 0; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j)
            C[i][j] = (C[i-1][j] + C[i-1][j-1]) % M;
    }

    // Compute f and dp arrays
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            long long comb = C[i-1][j-1];
            long long f1 = f[j-1], f2 = f[i-j];
            f[i] = (f[i] + f1 * f2 % M * comb % M * (i + 1)) % M;

            int s = 0;
            for (int k = 1; k <= i; ++k) s += abs(k - j);

            long long d1 = dp[j-1], d2 = dp[i-j];
            long long part1 = d1 * f2 % M * comb % M * (i + 1);
            long long part2 = f1 * d2 % M * comb % M * (i + 1);
            long long part3 = (long long)s * f1 % M * f2 % M * comb;

            dp[i] = (dp[i] + part1 + part2 + part3) % M;
        }
    }

    fd[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= min(m, i); ++j) {
            fd[i][j] = fd[i-1][j];
            d[i][j] = d[i-1][j];

