                long long base_fd = (i - k - 1 >= 0) ? fd[i-k-1][j-k] : 1;
                long long base_d = (i - k - 1 >= 0) ? d[i-k-1][j-k] : 0;

                fd[i][j] = (fd[i][j] + base_fd * f[k] % M * C[j][k]) % M;

                long long term = (base_fd * dp[k] % M + base_d * f[k] % M) % M * C[j][k] % M;
                d[i][j] = (d[i][j] + term) % M;
            }
        }
    }

