using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, M;
    cin >> n >> m >> M;

    const int N = 505;
    vector<vector<long long>> C(N, vector<long long>(N, 0));
    vector<long long> f(N, 0), dp(N, 0);
    vector<vector<long long>> fd(N, vector<long long>(N, 0)), d(N, vector<long long>(N, 0));

    f[0] = 1 % M;

    // Precompute binomial coefficients
    for (int i = 0; i <= n; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++) {
            C[i][j] = C[i-1][j] + C[i-1][j-1];
            if (C[i][j] >= M) C[i][j] %= M;
        }
    }

    // Compute f and dp arrays
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            long long comb = C[i-1][j-1];
            long long fprev = f[j-1], fsucc = f[i-j];
            long long add = fprev * fsucc % M;
            add = add * comb % M;
            add = add * (i + 1) % M;
            f[i] = (f[i] + add) % M;

            // Compute sum of distances to pivot j
            int dist_sum = 0;
            for (int k = 1; k <= i; k++) {
                dist_sum += abs(k - j);
            }

            // Update dp[i]
            long long dp_jm1 = dp[j-1], dp_isj = dp[i-j];
            long long part1 = dp_jm1 * fsucc % M * comb % M * (i + 1);
            long long part2 = fprev * dp_isj % M * comb % M * (i + 1);
            long long part3 = (long long)dist_sum * fprev % M * fsucc % M * comb;
            dp[i] = (dp[i] + part1 + part2 + part3) % M;
        }
    }

    // Base case
    fd[0][0] = 1;

    // DP for fd and d tables
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= min(m, i); j++) {
            fd[i][j] = fd[i-1][j];
            d[i][j] = d[i-1][j];

            for (int k = 1; k <= j; k++) {
                long long prev_fd = (i - k - 1 >= 0) ? fd[i-k-1][j-k] : 1;
                long long prev_d = (i - k - 1 >= 0) ? d[i-k-1][j-k] : 0;

                fd[i][j] = (fd[i][j] + prev_fd * f[k] % M * C[j][k]) % M;

                long long contribution = (prev_fd * dp[k] % M + prev_d * f[k] % M) % M;
                contribution = contribution * C[j][k] % M;
                d[i][j] = (d[i][j] + contribution) % M;
            }
        }
    }

    long long res = (d[n][m] % M + M) % M;
    cout << res << '\n';

    return 0;
}

#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

#define mp make_pair
#define pb push_back
#define ll long long

#define maxN 66

int r, c, n, i;
char s[maxN];
ll comb[maxN][maxN];

int cnt_a[maxN], cnt_b[maxN];
vector<ll> partial[maxN], partial_zero[maxN];

void compute_comb() {
    int i, j;

    for (i = 0; i <= n; i++) {
        comb[i][0] = 1;
        for (j = 1; j <= i; j++)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

ll get_difs(int conf, int a_bef, int b_bef) {
    int i;
    ll ans = 0;
    ll aux1, aux2;

    for (i = 0; i < c + 1; i++) {
        if (conf & (1 << i)) {
            //! here comes a B
            b_bef++;

            aux1 = comb[b_bef - 1][r - 1];
            aux2 = comb[n - b_bef][r] - comb[a_bef][r];

            ans -= aux1 * aux2;
        } else {
            //! here comes an A
            a_bef++;

            aux1 = comb[a_bef - 1][r - 1];
            aux2 = comb[n - a_bef][r] - comb[b_bef][r];

            ans += aux1 * aux2;
        }
    }

    return ans;
}

bool check(int conf) {
    int i;

    for (i = 0; i < c + 1; i++) {
        if (s[2 * r + c + i] == 'A' && ( (conf >> i) & 1 ) == 1) return false;
        if (s[2 * r + c + i] == 'B' && ( (conf >> i) & 1 ) == 0) return false;
    }

    return true;
}

void compute_second_part() {
    int i, conf;
    int limit = 1 << (c + 1);
    int a_here, b_here;

    for (conf = 0; conf < limit; conf++) {
        b_here = __builtin_popcount(conf);
        a_here = c + 1 - b_here;

        if (check(conf))
            partial[a_here].pb(get_difs(conf, r + c - a_here, r + c - b_here));
        else
            partial_zero[a_here].pb(get_difs(conf, r + c - a_here, r + c - b_here));
    }

    for (i = 0; i <= c + 1; i++) {
        sort(partial[i].begin(), partial[i].end());
        sort(partial_zero[i].begin(), partial_zero[i].end());
    }
}

ll get_coef(int conf) {
    int i, j;

    for (i = 0; i < c + 1; i++)
        if ( ((conf >> i) & 1) != (conf & 1) )
            break;

    for (j = i; j < c + 1; j++) {
