        if (idxA >= prefixA[totalSteps] && idxB >= prefixB[totalSteps]) {
            int newIdxA = idxA - prefixA[totalSteps];
            int newIdxB = idxB - prefixB[totalSteps];
            return ans = comb[newIdxA + newIdxB][newIdxA];
        }
        return ans = 0;
    }

    ans = 0;
    char ch = inputSeq[idxA + idxB - 1];
    if (ch != 'B') {
        long long addA = comb[idxA][rows] - comb[idxA - 1][rows];
        long long sumB = comb[idxB][rows];
