using lli = long long int;

lli binom[777][777];
int N, M;
lli globalTotal;
lli smallestDifference = (lli)1e18;
lli optimalLeftValue = -1;

void dfs(lli A_sum, lli B_sum, int idxA, int idxB) {
    lli diff = llabs(A_sum - B_sum);
    if (smallestDifference <= 1 || diff - binom[idxA][N] * binom[idxB][N] >= smallestDifference)
        return;

    if (idxA == N - 1 && idxB == N - 1) {
        lli cur_diff = llabs(A_sum - B_sum);
        if (cur_diff < smallestDifference) {
            smallestDifference = cur_diff;
            optimalLeftValue = A_sum;
        }
        return;
    }

    if (idxA >= N) {
        lli deltaA = binom[idxA][N] - binom[idxA-1][N];
        lli sumB = binom[idxB][N];
        dfs(A_sum, B_sum + deltaA * sumB, idxA-1, idxB);
    }

    if (idxB >= N) {
        lli sumA = binom[idxA][N];
        lli deltaB = binom[idxB][N] - binom[idxB-1][N];
        dfs(A_sum + sumA * deltaB, B_sum, idxA, idxB-1);
    }
}

