lli count_valid(lli A_val, lli B_val, int iA, int iB) {
    lli key = (A_val << 20) ^ (iA << 10) ^ iB;
    auto it = dp_cache.find(key);
    if (it != dp_cache.end()) return it->second;

    lli &res = dp_cache[key];
    lli diff = llabs(A_val - B_val);
    if (diff - binom[iA][N] * binom[iB][N] > smallestDifference) {
