        if (iA >= cnt_a[pos] && iB >= cnt_b[pos]) {
            int a_idx = iA - cnt_a[pos];
            int b_idx = iB - cnt_b[pos];
            return res = binom[a_idx + b_idx][a_idx];
        }
        res = 0;
        return res;
